    (5, 12, "ወይትፌሥሑ ፡ ብከ ፡ ኵሎሙ ፡ እለ ፡ ይትዌከሉከ ፡ ለዓለም ፡ ይትሐሠዩ ፡ ወተኀድር ፡ ላዕሌሆሙ ። ወይትሜክሑ ፡ ብከ ፡ ኵሎሙ ፡ እለ ፡ ያፈቅሩ ፡ ስመከ ።"),
    (5, 13, "እስመ ፡ አንተ ፡ ትባርኮ ፡ ለጻድቅ ፤ እግዚኦ ፡ ከመ ፡ ወልታ ፡ ሥሙር ፡ ከለልከነ ።"),
    (6, 1, "ፍጹሜ ፡ ዘስብሐት ፡ በእንተ ፡ ሳምንት ፤ መዝሙር ፡ ዘዳዊት ።"),
    (6, 2, "እግዚኦ ፡ በመዐትከ ፡ ኢትቅሥፈኒ ፤ ወበመቅሠፍትከ ፡ ኢትገሥጸኒ ።"),
    (6, 3, "ትሣሀለኒ ፡ እግዚኦ ፡ እስመ ፡ ድውይ ፡ አነ ፤ ወፈውሰኒ ፡ እስመ ፡ ተሀውከ ፡ አዕጽምትየ ።"),
    (6, 4, "ወነፍስየኒ ፡ ተሀውከት ፡ ፈድፋደ ፤ ወአንተኒ ፡ እግዚኦ ፡ እስከ ፡ ማእዜኑ ።"),
    (6, 5, "ተመየጥ ፡ እግዚኦ ፡ ወባልሓ ፡ ለነፍስየ ፤ ወአድኅነኒ ፡ በእንተ ፡ ምሕረትከ ።"),
    (6, 6, "እስመ ፡ አልቦ ፡ በውስተ ፡ ሞት ፡ ዘይዘከረከ ፤ ወበሲኦልኒ ፡ መኑ ፡ የአምነከ ።"),
    (6, 7, "ሰራሕኩ ፡ በምንዳቤየ ፡ ወአኀፅብ ፡ ኵሎ ፡ ሌሊተ ፡ ዐራትየ ፤ ወበአንብዕየ ፡ አርሐስኩ ፡ ምስካብየ ።"),
    (6, 8, "ወተሀውከት ፡ እመዐት ፡ ዐይንየ ፤ ወበለይኩ ፡ በኀበ ፡ ኵሎሙ ፡ ጸላእትየ ።"),
    (6, 9, "ረሐቁ ፡ እምኔየ ፡ ኵልክሙ ፡ ገበርተ ፡ ዐመፃ ፤ እስመ ፡ ሰምዐኒ ፡ እግዚአብሔር ፡ ቃለ ፡ ብካይየ ።"),
    (6, 10, "ወሰምዐኒ ፡ እግዚአብሔር ፡ ስእለትየ ፤ ወተወክፈ ፡ እግዚአብሔር ፡ ጸሎትየ ።"),
    (6, 11, "ለይትኀፈሩ ፡ ወይኅሰሩ ፡ ኵሎሙ ፡ ጸላእትየ ፤ ለይገብኡ ፡ ድኅሬሆሙ ፡ ወይትኀፈሩ ፡ ፈድፋደ ፡ ወፍጡነ ።"),
    (7, 1, "መዝሙር ፡ ዘዳዊት ፤ ዘዘመረ ፡ ለእግዚአብሔር ፡ በእንተ ፡ ነገረ ፡ ኩዝ ፡ ወልደ ፡ አሚናዳብ ።"),
    (7, 2, "እግዚኦ ፡ አምላክየ ፡ ብከ ፡ ተወከልኩ ፡ ወኢትግድፈኒ ፤ ወአድኅነኒ ፡ እምኵሎሙ ፡ እለ ፡ ሮዱኒ ፡ ወባልሐኒ ።"),
    (7, 3, "ከመ ፡ ኢይምስጥዋ ፡ ከመ ፡ አንበሳ ፡ ለነፍስየ ፤ እንዘ ፡ አልቦ ፡ ዘያድኅን ፡ ወዘይባልሕ ።"),
    (7, 4, "እግዚኦ ፡ አምላክየ ፡ እመሰ ፡ ከመዝ ፡ ገበርኩ ፤ ወእመኒቦ ፡ ዐመፃ ፡ ውስተ ፡ እደውየ ።"),
    (7, 5, "ወእመኒ ፡ ፈደይክዎሙ ፡ ለእለ ፡ ይፈድዩኒ ፡ እኩየ ፤ ለያውድቁኒ ፡ ጸላእትየ ፡ ዕራቅየ ።"),
    (7, 6, "ወይዴግና ፡ ፀራዊ ፡ ለነፍስየ ፡ ወይርከባ ፤ ወይኪዳ ፡ ውስተ ፡ ምድር ፡ ለሕይወትየ ። ወያኅስሮ ፡ ውስተ ፡ መሬት ፡ ለክብርየ ።"),
    (7, 7, "ተንሥእ ፡ እግዚኦ ፡ በመዐትከ ፤ ወተለዐል ፡ መልዕልቶሙ ፡ ለጸላእትየ ።"),
    (7, 8, "ተንሥእ ፡ እግዚኦ ፡ አምላክየ ፡ በሥርዐት ፡ ዘአዘዝከ ። ወማኅበረ ፡ አሕዛብኒ ፡ የዐውደከ ፤ ወበእንተዝ ፡ ተመየጥ ፡ ውስተ ፡ አርያም ።"),
    (7, 9, "እግዚአብሔር ፡ ይኴንኖሙ ፡ ለአሕዛብ ። ፍታሕ ፡ ሊተ ፡ እግዚኦ ፡ በከመ ፡ ጽድቅከ ፤ ወይኩነኒ ፡ በከመ ፡ የዋሃትየ ።"),
    (7, 10, "የኀልቅ ፡ እከዮሙ ፡ ለኃጥኣን ፤ ወታረትዖሙ ፡ ለጻድቃን ፤ ይፈትን ፡ ልበ ፡ ወኵልያተ ፡ እግዚአብሔር ።"),
    (7, 11, "አማን ፡ ይረድአኒ ፡ እግዚአብሔር ፤ ዘያድኅኖሙ ፡ ለርቱዓነ ፡ ልብ ።"),
    (7, 12, "እግዚአብሔር ፡ መኰንነ ፡ ጽድቅ ፡ ኀያል ፡ ወመስተዐግስ ፤ ወኢያምጽእ ፡ መንሱተ ፡ ኵሎ ፡ አሚረ ።"),
    (7, 13, "ወእመሰ ፡ ኢተመየጥክሙ ፡ ሰይፎ ፡ ይመልኅ ፤ ቀስቶኒ ፡ ወተረ ፡ ወአስተዳለወ ።"),
    (7, 14, "ወአስተዳለወ ፡ ቦቱ ፡ ሕምዘ ፡ ዘይቀትል ፤ ወአሕጻሁኒ ፡ ለእለ ፡ ይነዲ ፡ ገብረ ።"),
    (7, 15, "ናሁ ፡ ሐመ ፡ በዐመፃ ፤ ፀንሰ ፡ ጻዕረ ፡ ወወለደ ፡ ኃጢአተ ።"),
    (7, 16, "ግበ ፡ ከረየ ፡ ወደሐየ ፤ ወይወድቅ ፡ ውስተ ፡ ግብ ፡ ዘገብረ ።"),
    (7, 17, "ወይገብእ ፡ ጻማሁ ፡ ዲበ ፡ ርእሱ ፤ ወትወርድ ፡ ዐመፃሁ ፡ ዲበ ፡ ድማሑ ።"),
    (7, 18, "እገኒ ፡ ለእግዚአብሔር ፡ በከመ ፡ ጽድቁ ፤ ወእዜምር ፡ ለስመ ፡ እግዚአብሔር ፡ ልዑል ።"),
    (8, 1, "ፍጻሜ ፡ በእንተ ፡ መክብብት ፤ መዝሙር ፡ ዘዳዊት ።"),
    (8, 2, "እግዚኦ ፡ እግዚእነ ፡ ጥቀ ፡ ተሰብሐ ፡ ስምክ ፡ በኵሉ ፡ ምድር ፤"),
    (8, 3, "እስመ ፡ ተለዐለ ፡ እበየ ፡ ስብሓቲከ ፡ መልዕልተ ፡ ሰማያት ።"),
    (8, 4, "እምአፈ ፡ ደቂቅ ፡ ወሕፃናት ፡ አስተዳሉከ ፡ ስብሐተ ፡ በእንተ ፡ ጸላኢ ፤ ከመ ፡ ትንሥቶ ፡ ለጸላኢ ፡ ወለገፋዒ ።"),
    (8, 5, "እስመ ፡ ንሬኢ ፡ ሰማያተ ፡ ግብረ ፡ አጻብዒከ ፤ ወርኀ ፡ ወከዋክብተ ፡ ዘለሊከ ፡ ሳረርከ ።"),
    (8, 6, "ምንትኑ ፡ ውእቱ ፡ ሰብእ ፡ ከመ ፡ ትዝክሮ ፤ ወምንትኑ ፡ እጓለ ፡ እመሕያው ፡ ከመ ፡ ተሐውጾ ።"),
    (8, 7, "ሕቀ ፡ አሕጸጽኮ ፡ እምላእክቲከ ፤ ክብረ ፡ ወስብሐተ ፡ ከለልኮ ። ወሢምኮ ፡ ዲበ ፡ ኵሉ ፡ ግብረ ፡ እደዊከ ፤"),
    (8, 8, "ወኵሎ ፡ አግረርከ ፡ ሎቱ ፡ ታሕተ ፡ እገሪሁ ። አባግዐኒ ፡ ወኵሎ ፡ አልህምተ ፤ ወዓዲ ፡ እንስሳ ፡ ዘገዳም ።"),
    (8, 9, "አዕዋፈ ፡ ሰማይኒ ፡ ወዐሣተ ፡ ባሕር ፤ ወዘኒ ፡ የሐውር ፡ ውስተ ፡ ፍኖተ ፡ ባሕር ።"),
    (8, 10, "እግዚኦ ፡ እግዚእነ ፡ ጥቀ ፡ ተሰብሐ ፡ ስምከ ፡ በኵሉ ፡ ምድር ።"),
    (9, 1, "ፍጻሜ ፡ በእንተ ፡ ኅቡኣተ ፡ ወልድ ፤ መዝሙር ፡ ዘዳዊት ።"),
    (9, 2, "እገኒ ፡ ለከ ፡ እግዚኦ ፡ በኵሉ ፡ ልብየ ፤ ወእነግር ፡ ኵሎ ፡ ስብሓቲከ ።"),
    (9, 3, "እትፌሣሕ ፡ ወእትሐሠይ ፡ ብከ ፤ ወእዜምር ፡ ለስምከ ፡ ልዑል ።"),
    (9, 4, "ሶበ ፡ ገብኡ ፡ ጸላእትየ ፡ ድኅሬሆሙ ፤ ይድወዩ ፡ ወይትሐጐሉ ፡ እምቅድመ ፡ ገጽከ ።"),
    (9, 5, "እስመ ፡ ገበርከ ፡ ሊተ ፡ ፍትሕየ ፡ ወበቀልየ ፤ ወነበርከ ፡ ዲበ ፡ መንበርከ ፡ መኰንነ ፡ ጽድቅ ።"),
    (9, 6, "ገሠጽኮሙ ፡ ለአሕዛብ ፡ ወተሐጕሉ ፡ ረሲዓን ፤ ወደምሰስከ ፡ ስሞሙ ፡ ለዓለመ ፡ ዓለም ።"),
    (9, 7, "ፀርሰ ፡ ተገምሩ ፡ በኲናት ፡ ለዝሉፍ ። ወአህጒሪሆሙኒ ፡ ነሠትከ ፤ ወትስዕር ፡ ዝክሮሙ ፡ ኅቡረ ።"),
    (9, 8, "ወእግዚአብሔር ፡ ይነብር ፡ ለዓለም ፤ ወአስትዳለወ ፡ መንበሮ ፡ ለኰንኖ ።"),
    (9, 9, "ወውእቱ ፡ ይኴንና ፡ ለዓለም ፡ በጽድቅ ፤ ወይኴንኖሙ ፡ ለአሕዛብ ፡ በርትዕ ።"),
    (9, 10, "ወኮኖሙ ፡ እግዚአብሔር ፡ ምስካዮሙ ፡ ለነዳያን ፤ ወረዳኢሆሙ ፡ ውእቱ ፡ በጊዜ ፡ ምንዳቤሆሙ ።"),
    (9, 11, "ወይትዌከሉ ፡ ብከ ፡ ኵሎሙ ፡ እለ ፡ ያፈቅሩ ፡ ስመከ ፤ እስመ ፡ ኢተኀድጎሙ ፡ ለእለ ፡ የኀሡከ ፡ እግዚኦ ።"),
    (9, 12, "ዘምሩ ፡ ለእግዚአብሔር ፡ ዘየኀድር ፡ ውስተ ፡ ጽዮን ፤ ወንግርዎሙ ፡ ለአሕዛብ ፡ ምግባሮ ።"),
    (9, 13, "እስመ ፡ ተዘክረ ፡ ዘይትኃሠሥ ፡ ደሞሙ ፤ ወኢረስዐ ፡ ዐውያቶሙ ፡ ለነዳያን ።"),
    (9, 14, "ተሣሀለኒ ፡ እግዚኦ ፡ ወርኢ ፡ ዘከመ ፡ ያሐሙኒ ፡ ጸላእትየ ፤"),
    (9, 15, "ዘያሌዕለኒ ፡ እምአናቅጸ ፡ ሞት ። ከመ ፡ እንግር ፡ ኵሎ ፡ ስብሓቲከ ፤ በአናቅጺሃ ፡ ለወለተ ፡ ጽዮን ፤"),
    (9, 16, "ወንትፌሣሕ ፡ በአድኅኖትከ ። ጠግዑ ፡ አሕዛብ ፡ በጌጋዮሙ ፡ ዘገብሩ ፤ ወበይእቲ ፡ መሥገርት ፡ እንተ ፡ ኀብኡ ፡ ተሠግረ ፡ እግሮሙ ።"),
    (9, 17, "ያአምር ፡ እግዚአብሔር ፡ ገቢረ ፡ ፍትሕ ፤ ወበግብረ ፡ እደዊሁ ፡ ተሠግረ ፡ ኃጥእ ።"),
    (9, 18, "ያግብኡ ፡ ኃጥኣን ፡ ውስተ ፡ ሲኦል ፤ ወኵሎሙ ፡ አሕዛብ ፡ እለ ፡ ይረስዕዎ ፡ ለእግዚአብሔር ።"),
    (9, 19, "እስመ ፡ አኮ ፡ ለዝሉፉ ፡ ዘይትረሳዕ ፡ ነዳይ ፤ ወኢያሕጕሉ ፡ ትዕግሥቶሙ ፡ ነዳያን ፡ ለዓለም ።"),
    (9, 20, "ተንሥእ ፡ እግዚኦ ፡ ወኢይጽናዕ ፡ እጓለ ፡ እምሕያው ፤ ወይትኴነኑ ፡ አሕዛብ ፡ በቅድሜከ ።"),
    (9, 21, "ሢም ፡ እግዚኦ ፡ መምህረ ፡ ሕግ ፡ ላዕሌሆሙ ፤ ወያእምሩ ፡ አሕዛብ ፡ ከመ ፡ እጓለ ፡ እመሕያው ፡ እሙንቱ ።"),
    (9, 22, "ለምንት ፡ እግዚኦ ፡ ቆምከ ፡ እምርሑቅ ፤ ወትትዔወር ፡ በጊዜ ፡ ምንዳቤ ።"),
    (9, 23, "በትዕቢቱ ፡ ለኃጥእ ፡ ይውዒ ፡ ነዳይ ፤ ወይሠገሩ ፡ በውዴቶሙ ፡ እንተ ፡ ሐለዩ ።"),
    (9, 24, "እስመ ፡ ይትዌደስ ፡ ኃጥእ ፡ በፍትወተ ፡ ነፍሱ ፤ ወዐማፂኒ ፡ ይትባረክ ፡"),
    (9, 25, "ወሐኮ ፡ ኃጥእ ፡ ለእግዚአብሔር ። ወኢተኃሥሦ ፡ በከመ ፡ ብዝኀ ፡ መዐቱ ፤"),
    (9, 26, "ወአልቦ ፡ እግዚአብሔር ፡ በቅድሜሁ ። ወርኩስ ፡ ኵሉ ፡ ፍናዊሁ ፡ ወንሡት ፡ ኵነኔከ ፡ በቅድሜሁ ፤ ወይቀንዮሙ ፡ ለኵሎሙ ፡ ጸላእቱ ።"),
    (9, 27, "ወይብል ፡ በልቡ ፡ ኢይትሀወክ ፤ ለትውልደ ፡ ትውልድ ፡ ኢይረክበኒ ፡ እኩይ ።"),
    (9, 28, "ምሉእ ፡ አፉሁ ፡ መርገመ ፡ ወጽልሑተ ፤ ወታሕተ ፡ ልሳኑ ፡ ጻማ ፡ ወሕማም ።"),
    (9, 29, "ወይጸንሕ ፡ ወይንዑ ፡ ምስለ ፡ ብዑላን ፡ ከመ ፡ ይቅትሎ ፡ ለንጹሕ ፡ በጽሚት ፤"),
    (
        9,
        30,
        "ወአዕይንቲሁኒ ፡ ኀበ ፡ ነዳይ ፡ ያስትሐይጻ ። ይጸንሕ ፡ ወይትኀባእ ፡ ከመ ፡ አንበሳ ፡ ውስተ ፡ ግብ ፡ ወይጸንሕ ፡ ከመ ፡ ይምስጦ ፡ ለነዳይ ፤ ወይመስጦ ፡ ለነዳይ ፡ ወይስሕቦ ፡",
    ),
    (9, 31, "ወያኀስሮ ፡ በመሥገርቱ ። ይትቀጻዕ ፡ ወይወድቅ ፡ ሶበ ፡ ቀነዮ ፡ ለነዳይ ።"),
    (9, 32, "ወይብል ፡ በልቡ ፡ ይረስዐኒ ፡ እግዚአብሔር ፤ ወሜጠ ፡ ገጾ ፡ ከመ ፡ ኢይርአይ ፡ ለግሙራ ።"),
    (9, 33, "ተንሥእ ፡ እግዚኦ ፡ አምላክየ ፡ ወትትሌዐል ፡ እዴከ ፤ ወኢትርስዖሙ ፡ ለነዳያን ።"),
    (9, 34, "በእንተ ፡ ምንት ፡ አምዕዖ ፡ ኃጥእ ፡ ለእግዚአብሔር ፤ እስመ ፡ ይብል ፡ በልቡ ፡ ኢይትኃሠሠኒ ።"),
    (
        9,
        35,
        "ትሬኢኑ ፡ ከመ ፡ ለሊከ ፡ ትኔጽር ፡ ጻማ ፡ ወመዐተ ፤ ወከመ ፡ ትመጥዎ ፡ ውስተ ፡ እዴከ ፤ ላዕሌከኑ ፡ እንከ ፡ ተገድፈ ፡ ነዳይ ፤ ወአንተኑ ፡ ረዳኢሁ ፡ ለእጓለ ፡ ማውታ ።",
    ),
    (9, 36, "ቀጥቅጥ ፡ መዝራዕቶ ፡ ለኃጥእ ፡ ወለእኩይ ፤ ወትትኀሠሥ ፡ ኀጢአቱ ፡ በእንቲአሁ ፡ ወኢትትረከብ ።"),
    (9, 37, "ይነግሥ ፡ እግዚአብሔር ፡ ለዓለም ፡ ወለዓለመ ፡ ዓለም ፤ ወይትሐጕሉ ፡ አሕዛብ ፡ እምድር ።"),
    (9, 38, "ፍትወቶሙ ፡ ለነዳያን ፡ ሰምዐ ፡ እግዚአብሔር ፤ ወሕሊና ፡ ልቦሙኒ ፡ አፅምአት ፡ እዝኑ ።"),
    (9, 39, "ፍትሑ ፡ ለነዳይ ፡ ወለእጓለ ፡ ማውታ ፤ ከመ ፡ ኢይድግሙ ፡ እንከ ፡ እጓለ ፡ እምሕያው ፡ አዕብዮ ፡ አፉሆሙ ፡ በዲበ ፡ ምድር ።"),
    (10, 1, "ፍጻሜ ፡ መዝሙር ፡ ዘዳዊት ። በእግዚአብሔር ፡ ተወከልኩ ፡ እፎ ፡ ትብልዋ ፡ ለነፍስየ ፤ ተዐይል ፡ ውስተ ፡ አድባር ፡ ከመ ፡ ዖፍ ።"),
    (10, 2, "እስመ ፡ ናሁ ፡ ኃጥኣን ፡ ወሰቁ ፡ ቀስቶሙ ፡ ወአስተዳለው ፡ አሕጻቲሆሙ ፡ ውስተ ፡ ምጕንጳቶሆሙ ፤ ከመ ፡ ይንድፍዎ ፡ ለርቱዕ ፡ ልብ ፡ በጽሚት ።"),
    (10, 3, "እስመ ፡ ናሁ ፡ ዘአንተ ፡ ሠራዕከ ፡ እሙንቱ ፡ ነሠቱ ፤ ወጻድቅሰ ፡ ምንተ ፡ ገብረ ።"),
    (
        10,
        4,
        "እግዚአብሔር ፡ ውስተ ፡ ጽርሐ ፡ መቅድሱ ፡ እግዚአብሔር ፡ ውስተ ፡ ሰማይ ፡ መንብሩ ፤ ወአዕይንቲሁኒ ፡ ኀበ ፡ ነዳይ ፡ ይኔጽራ ፡ ወቀራንብቲሁኒ ፡ የሐቶ ፡ ለእጓለ ፡ እመሕያው ።",
    ),
    (10, 5, "እግዚአብሔር ፡ የሐቶ ፡ ለጻድቅ ፡ ወለኃጥእ ፤ ወዘሰ ፡ አፍቀራ ፡ ለዐመፃ ፡ ጸልአ ፡ ነፍሶ ።"),
    (10, 6, "ይዘንም ፡ መሣግር ፡ ላዕለ ፡ ኃጥኣን ፤ እሳት ፡ ወተይ ፡ መንፈስ ፡ ዐውሎ ፡ መክፈልተ ፡ ጽዋዖሙ ።"),
    (10, 7, "እስመ ፡ ጻድቅ ፡ እግዚአብሔር ፡ ወጽድቀ ፡ አፍቀረ ፤ ወለርትዕሰ ፡ ትሬእዮ ፡ ገጹ ።"),
    (11, 1, "ፍጻሜ ፡ ስብሐት ፡ መዝሙር ፡ ዘዳዊት ፡ በእንተ ሳምንት ።"),
    (11, 2, "አድኅነኒ ፡ እግዚኦ ፡ እስመ ፡ ኀልቀ ፡ ኄር ፤ ወውሕደ ፡ ሀይማኖት ፡ እምአጓለ ፡ እምሕያው ።"),
    (11, 3, "ከንቶ ፡ ይትናገሩ ፡ አሐዱ ፡ ምስለ ፡ ካልኡ ፤ በከናፍረ ፡ ጕሕሉት ፡ በልብ ፡ ወበልብ ፡ ይትናገሩ ።"),
    (11, 4, "ይሤርዎን ፡ እግዚአብሔር ፡ ለከናፍረ ፡ ጕሕሉት ፤ ወለልሳን ፡ እንተ ፡ ታዐቢ ነቢበ ።"),
    (11, 5, "እለ ፡ ይብሉ ፡ ናዐቢ ፡ ልሳናቲነ ፡ ወከናፍሪነኒ ፡ ኀቤነ ፡ እሙንቱ ፤ መኑ ፡ ውእቱ ፡ እግዚእነ ።"),
    (11, 6, "በእንተ ፡ ሕማዎሙ ፡ ለነዳያን ፡ ወበእንተ ፡ ገዐሮሙ ፡ ለሙቁሓን ፤ ይእዜ ፡ እትነሣእ ፡ ይቤ ፡ እግዚአብሔር ፡ እሬሲ ፡ መድኀኒተ ፡ ወእግህድ ፡ ቦቱ ።"),
    (11, 7, "ቃለ ፡ እግዚአብሔር ፡ ቃል ፡ ንጹሕ ፤ ከመ ብሩር ፡ ጽሩይ ፡ ወንጡፍ ፡ ወፍቱን ፡ እምድር ፡ ዘአጽረይዎ ፡ ምስብዒተ ።"),
    (11, 8, "አንተ ፡ እግዚኦ ፡ ዕቀበነ ፤ ወተማኅፀነነ ፡ እምዛቲ ፡ ትውልድ ፡ ወእስከ ፡ ለዓለም ።"),
    (11, 9, "ዐውደ ፡ የሐውሩ ፡ ረሲዓን ፤ ወበከመ ፡ ልዕልናከ ፡ ሠራዕኮሙ ፡ ለደቂቀ ፡ እጓለ ፡ እመሕያው ።"),
    (12, 1, "ፍጻሜ ፡ መዝሙር ፡ ዘዳዊት ። እስከ ፡ ማእዜኑ ፡ እግዚኦ ፡ ትረስዐኒ ፡ ለግሙራ ፡ እስከ ፡ ማእዜኑ ፡ ትመይጥ ፡ ገጸከ ፡ እምኔየ ።"),
    (12, 2, "እስከ ፡ ማእዜኑ ፡ ኣነብር ፡ ሐዘነ ፡ ውስተ ፡ ነፍስየ ፡ ወትጼዕረኒ ፡ ልብየ ፡ ኵሎ ፡ አሚረ ፤"),
    (12, 3, "እስከ ፡ ማእዜኑ ፡ ይትዔበዩ ፡ ጸላእትየ ፡ ላዕሌየ ።"),
    (12, 4, "ነጽረኒ ፡ ወስምዐኒ ፡ እግዚኦ ፡ አምላኪየ ፤ አብርሆን ፡ ለአዕይንትየ ፡ ከመ ፡ ኢይኑማ ፡ ለመዊት ።"),
    (12, 5, "ወከመ ፡ ኢይበሉኒ ፡ ጸላእትየ ፡ ሞእናሁ ፤ ወእለሰ ፡ ይሣቅዩኒ ፡ ይትፌሥሑ ፡ ለእመ ፡ ተሀወኩ ።"),
    (12, 6, "ወአንሰ ፡ በምሕረትከ ፡ ተወከልኩ ፡ ይትፌሥሐኒ ፡ ልብየ ፡ በአድኅኖትከ ፤ እሴብሖ ፡ ለእግዚአብሔር ፡ ዘረድአኒ ፡ ወእዜምር ፡ ለስመ ፡ እግዚአብሔር ፡ ልዑል ።"),
    (
        13,
        1,
        "ፍጻሜ ፡ መዝሙር ፡ ዘዳዊት ። ይብል ፡ አብድ ፡ በልቡ ፡ አልቦ ፡ እግዚአብሔር ፤ ኀስሩ ፡ ወረኵሱ ፡ በምግባሪሆሙ ፤ አልቦ ፡ ዘይገብራ ፡ ለሠናይት ፡ አልቦ ፡ ወኢአሐዱ ።",
    ),
    (13, 2, "እግዚአብሔር ፡ ሐወጸ ፡ እምሰማይ ፡ ላዕለ ፡ እጓለ ፡ እምሕያው ፤ ከመ ፡ ይርአይ ፡ እመቦ ፡ ጠቢበ ፡ ዘየኀሦ ፡ ለእግዚአብሔር ።"),
    (
        13,
        3,
        "ኵሉ ፡ ዐረየ ፡ ወኅቡረ ፡ ዐለወ ፤ አልቦ ፡ ዘይገብራ ፡ ለሠናይት ፡ አልቦ ፡ ወኢአሐዱ ። [-] ከመ ፡ መቃብር ፡ ክሡት ፡ ጐራዒቶሙ ፡ ወጸልሐዉ ፡ በልሳናቲሆሙ ፡ ሕምዘ ፡ አርዌ ፡ ምድር ፡ ታሕተ ፡ ከነፍሪሆሙ ። [-] መሪር ፡ አፋሆሙ ፡ ወምሉእ ፡ መርገም ፤ በሊኅ ፡ እገሪሆሙ ፡ ለክዒወ ፡ ደም ። [-] ኀሳር ፡ ወቅጥቃጤ ፡ ውስተ ፡ ፍኖቶሙ ፤ ወኢያአምርዋ ፡ ለፍኖተ ፡ ሰላም ። ወአልቦ ፡ ፍርሀተ ፡ እግዚአብሔር ፡ ቅድመ ፡ አዕይንቲሆሙ ።",
    ),
    (13, 4, "ወኢያአምሩ ፡ ኵሎሙ ፡ ገበርተ ፡ ዐመፃ ፤ እለ ፡ ይውኅጥዎሙ ፡ ለሕዝብየ ፡ ከመ ፡ በሊዐ ፡ እክል ። ወለእግዚአብሔርሰ ፡ ኢጸውዕዎ ።"),
    (13, 5, "ወበህየ ፡ ፈርሁ ፡ ወገረሞሙ ፡ ዘኢኮነ ፡ ግሩመ ፤ እስመ ፡ እግዚአብሔር ፡ ውስተ ፡ ትውልደ ፡ ጻድቃን ።"),
    (13, 6, "ወአስተኀፈርክሙ ፡ ምክረ ፡ ነዳይ ፤ እስመ ፡ እግዚአብሔር ፡ ተስፋሆሙ ፡ ውእቱ ።"),
    (13, 7, "መኑ ፡ ይሁብ ፡ መድኀኒተ ፡ እምጽዮን ፡ ለእስራኤል ። አመ ፡ ሜጠ ፡ እግዚአብሔር ፡ ፄዋ ፡ ሕዝቡ ፤ ይትፌሣሕ ፡ ያዕቆብ ፡ ወይትሐሠይ ፡ እስራኤል ።"),
    (14, 1, "መዝሙር ፡ ዘዳዊት ። እግዚኦ ፡ መኑ ፡ ይኀድር ፡ ውስተ ፡ ጽላሎትከ ፤ ወመኑ ፡ ያጸልል ፡ ውስተ ፡ ደብረ ፡ መቅድስከ ።"),
    (14, 2, "ዘየሐውር ፡ በንጹሕ ፡ ወይገብር ፡ ጽድቀ ፤ ወዘይነብብ ፡ ጽድቀ ፡ በልቡ ።"),
    (14, 3, "ወዘኢጓሕለወ ፡ በልሳኑ ፡ ወዘኢገብረ ፡ እኩየ ፡ ዲበ ፡ ቢጹ ፤ ወዘኢያጽአለ ፡ አዝማዲሁ ።"),
    (14, 4, "ወዘምኑን ፡ በቅድሜሁ ፡ እኩይ ፡ ወዘያከብሮሙ ፡ ለፈራህያነ ፡ እግዚአብሔር ፤ ዘይምሕል ፡ ለቢጹ ፡ ወኢይሔሱ ።"),
    (14, 5, "ወዘኢለቅሐ ፡ ወርቆ ፡ በርዴ ፡ ወዘኢነሥአ ፡ ሕልያነ ፡ በላዕለ ፡ ንጹሕ ፤ ዘይገብር ፡ ከመዝ ፡ ኢይትሀወክ ፡ ለዓለም ።"),
    (15, 1, "ሥርዐተ ፡ አርአያ ፡ መጽሐፍ ፡ ዘዳዊት ። ዕቀበኒ ፡ እግዚኦ ፡ እስመ ፡ ኪያከ ፡ ተወከልኩ ።"),
    (15, 2, "እብሉ ፡ ለእግዚአብሔር ፡ እግዚእየ ፡ አንተ ፤ እስመ ፡ ኢትፈቅዳ ፡ ለሠናይትየ ፡"),
    (15, 3, "ለቅዱሳን ፡ እለ ፡ ውስተ ፡ ምድር ፤ ተሰብሐ ፡ ኵሉ ፡ ሥምረትከ ፡ በላዕሌሆሙ ።"),
    (15, 4, "በዝኀ ፡ ደዌሆሙ ፡ ወእምዝ ፡ አስፋጠኑ ፤ ወኢይትኃበር ፡ ውስተ ፡ ማኅበሮሙ ፡ ዘደም ፡ ወኢይዜከር ፡ አስማቲሆሙ ፡ በአፉየ ።"),
    (15, 5, "እግዚአብሔር ፡ መክፈልተ ፡ ርስትየ ፡ ወጽዋዕየ ፤ አንተ ፡ ውእቱ ፡ ዘታገብአ ፡ ሊተ ፡ ርስትየ ።"),
    (15, 6, "አሕባለ ፡ ወረው ፡ ሊተ ፡ የአኅዙኒ ፤ ወርስትየሰ ፡ እኁዝ ፡ ውእቱ ፡ ሊተ ።"),
    (15, 7, "እባርኮ ፡ ለእግዚአብሔር ፡ ዘአለበወኒ ፤ ወዐዲ ፡ ሌሊተኒ ፡ ገሠጻኒ ፡ ኵልያትየ ።"),
    (15, 8, "ዘልፈ ፡ እሬእዮ ፡ ለእግዚአብሔር ፡ ቅድሜየ ፡ በኵሉ ፡ ጊዜ ፤ እስመ ፡ በየማንየ ፡ ውእቱ ፡ ከመ ፡ ኢይትሀወክ ።"),
    (15, 9, "በእንተዝ ፡ ተፈሥሐ ፡ ልብየ ፡ ወተሐሥየ ፡ ልሳንየ ፤ ወዐዲ ፡ በተስፋሁ ፡ ኀደረ ፡ ሥጋየ ።"),
    (15, 10, "እስመ ፡ ኢተኀድጋ ፡ ውስተ ፡ ሲኦል ፡ ለነፍስየ ፤ ወኢትሁቦ ፡ ለጻድቅከ ፡ ይርአይ ፡ ሙስና ።"),
    (15, 11, "ወአርአይከኒ ፡ ፍኖተ ፡ ሕይወት ፤ ወአጽገብከኒ ፡ ሐሤተ ፡ ምስለ ፡ ገጽከ ፡ ወትፍሥሕት ፡ ውስተ ፡ የማንከ ፡ ለዝሉፉ ።"),
    (16, 1, "መዝሙር ፡ ዘዳዊት ። እግዚኦ ፡ ስምዐኒ ፡ ጽድቅየ ፡ ወአፅምአኒ ፡ ስእለትየ ። ወአፅምአኒ ፡ ጸሎትየ ፤ ዘኢኮነ ፡ በከናፍረ ፡ ጕሕሉት ።"),
    (16, 2, "እምቅድመ ፡ ገጽከ ፡ ይወፅእ ፡ ፍትሕየ ፤ አዕይንትየኒ ፡ ርእያ ፡ ጽድቅከ ።"),
    (16, 3, "ሐወጽከኒ ፡ ሌሊተ ፡ ወፈተንኮ ፡ ለልብየ ፡ ወአመከርከኒ ፡ ወኢተረክበ ፡ ዐመፃ ፡ በላዕሌየ ።"),
    (16, 4, "ከመ ፡ ኢይንብብ ፡ አፉየ ፡ ግብረ ፡ እጓለ ፡ እመሕያው ፡ በእንተ ፡ ቃለ ፡ ከናፍሪከ ፤"),
    (16, 5, "አነ ፡ ዐቀብኩ ፡ ፍናወ ፡ ዕፁባተ ። አጽንዖን ፡ ለመካይድየ ፡ ውስተ ፡ ፍኖትከ ፤ ከመ ፡ ኢይድኀፃ ፡ ሰኰናየ ።"),
    (16, 6, "አንሰ ፡ ጸራኅኩ ፡ እስመ ፡ ሰምዐኒ ፡ እግዚአብሔር ፤ አፅምእ ፡ እዝነከ ፡ ኀቤየ ፡ ወስምዐኒ ፡ ቃልየ ።"),
    (16, 7, "ሰብሓ ፡ ለምሕረትከ ፡ ዘያድኅኖሙ ፡ ለእለ ፡ ይትዌከሉከ ፤ እምእለ ፡ ይትቃወምዋ ፡ ለየማንከ ።"),
    (16, 8, "ዕቀበኒ ፡ ከመ ፡ ብንተ ፡ ዐይን ፤ ወበጽላሎተ ፡ ክንፊከ ፡ ክድነኒ ።"),
    (16, 9, "እምገጸ ፡ ኃጥኣን ፡ እለ ፡ ያኀስሩኒ ፤ ጸላእትየሰ ፡ አስተሐየጽዋ ፡ ለነፍስየ ።"),
    (16, 10, "ወቈጸሩ ፡ አማዑቶሙ ፤ ወነበበ ፡ ትዕቢተ ፡ አፉሆሙ ።"),
    (16, 11, "ሰደዱኒ ፡ ይእዜኒ ፡ ዐገቱኒ ፤ ወአትሐቱ ፡ አዕይንቲሆሙ ፡ ውስተ ፡ ምድር ።"),
    (16, 12, "ወተመጠዉኒ ፡ ከመ ፡ አንበሳ ፡ ዘጽኑሕ ፡ ለመሲጥ ፤ ወከመ ፡ እጓለ ፡ አንበሳ ፡ ዘይነብር ፡ ተኀቢኦ ።"),
    (16, 13, "ተንሥአ ፡ እግዚኦ ፡ በጽሖሙ ፡ ወአዕቅጾሙ ፤ ወበልሓ ፡ እምኲናት ፡ ለነፍስየ ። ሰይፍከ ፡ ላዕለ ፡ ፀረ ፡ እዴከ ፤"),
    (16, 14, "እግዚኦ ፡ እምውኁዳን ፡ ምድር ፡ ንፍቆሙ ፡ በሕይወቶሙ ፤ እምኅቡኣቲከ ፡ ጸግበት ፡ ከርሦሙ ። ጸግቡ ፡ ደቂቆሙ ፡ ወኀደጉ ፡ ትራፋቲሆሙ ፡ ለሕፃናቲሆሙ ።"),
    (16, 15, "ወአንሰ ፡ በጽድቅከ ፡ እሬኢ ፡ ገጸከ፤ ወእጸግብ ፡ በርእየ ፡ ስብሐቲከ ።"),
    (
        17,
        1,
        "ፍጻሜ ፡ ዘገብረ ፡ እግዚአብሔር ፡ ዘዳዊት ። ዘተናገሮ ፡ ለእግዚአብሔር ፡ በቃለ ፡ ማኅሌት ፤ በዕለተ ፡ አድኅኖ ፡ እግዚአብሔር ፡ እምእደ ፡ ኵሎሙ ፡ ጸላእቱ ፡ ወእምእደ ፡ ሳኦል ፡ 2 ወይቤ ። ኣፈቅረከ ፡ እግዚኦ ፡ በኀይልየ ።",
    ),
    (17, 3, "እግዚአብሔር ፡ ኀይልየ ፡ ወጸወንየ ፡ ወመድኀኒየ ። አምላኪየ ፡ ወረዳኢየ ፡ ወእትዌከል ፡ ቦቱ ፤ ምእመንየ ፡ ወቀርነ ፡ ሕይወትየ ፡ ወምስካይየ ።"),
    (17, 4, "እንተ ፡ ሶበ ፡ ጸዋዕክዎ ፡ ለእግዚአብሔር ፤ እድኅን ፡ እምፀርየ ።"),
    (17, 5, "አኀዘኒ ፡ ጻዕረ ፡ ሞት ፤ ወውሒዘ ፡ ዐመፃ ፡ ሆከኒ ።"),
    (17, 6, "ወዐገተኒ ፡ ጻዕረ ፡ ሲኦል ፤ ወበጽሐኒ ፡ መሣግረ ፡ ሞት ።"),
    (
        17,
        7,
        "ወሶበ ፡ ተመንድብኩ ፡ ጸዋዕክዎ ፡ ለእግዚአብሔር ፡ ወጸራኅኩ ፡ ኀበ ፡ አምላኪየ ። ወሰምዐኒ ፡ በጽርሐ ፡ መቅደሱ ፡ ቃልየ ፤ ወጽራኅየኒ ፡ ቦአ ፡ ቅድሜሁ ፡ ውስተ ፡ እዝኒሁ ።",
    ),
    (17, 8, "ርዕደት ፡ ወአድለቅለቀት ፡ ምድር ፡ ወአንቀልቀሉ ፡ መሰረታተ ፡ አድባር ፤ ወተሀውኩ ፡ እስመ ፡ ተምዖሙ ፡ ለእግዚአብሔር ።"),
    (17, 9, "ዐርገ ፡ ጢስ ፡ እመዐቱ ፡ ወነደ ፡ እሳት ፡ እምቅድመ ፡ ገጹ ፤ ኀተወ ፡ አፍሓም ፡ እምኔሁ ።"),
    (17, 10, "አጽነነ ፡ ሰማያት ፡ ወወረደ ፤ ወቆባር ፡ ታሕተ ፡ እገሪሁ ።"),
    (17, 11, "ተጽእነ ፡ ላዕለ ፡ ኪሩቤል ፡ ወሠረረ ፤ ወሠረረ ፡ በክንፈ ፡ ነፋስ ።"),
    (17, 12, "ወረሰየ ፡ ጽልመት ፡ ምስዋር ፡ ወዐውዶሂ ፡ ጽላሎቱ ፤ ወጸልሙ ፡ ማያት ፡ በውስተ ፡ ደመናት ።"),
    (17, 13, "ወእምብርሃነ ፡ ገጹ ፡ ኀለፋ ፡ ደመናት ፡ ቅድሜሁ ፤ በረድ ፡ ወአፍሓመ ፡ እሳት ።"),
    (17, 14, "ወአንጐድጐደ ፡ እግዚአብሔር ፡ በሰማያት ፡ ወልዑል ፡ ወሀበ ፡ ቃሉ ፤"),
    (17, 15, "ፈነወ ፡ አሕፃሁ ፡ ወዘረዎሙ ፡ አብዝኀ ፡ መባርቅቲሁ ፡ ወሀኮሙ ።"),
    (17, 16, "ወአስተርአየ ፡ አንቅዕተ ፡ ማያት ፡ ወተከሥተ ፡ መሰረታተ ፡ ዓለም ። እምተግሣጽከ ፡ እግዚኦ ፤ ወእምእስትንፋሰ ፡ መንፈሰ ፡ መዐትከ ።"),
    (17, 17, "ፈነወ ፡ እምአርያም ፡ ወነሥአኒ ፤ ወተመጠወኒ ፡ እማይ ፡ ብዙኅ ።"),
    (17, 18, "ወአድኀነኒ ፡ እምፀርየ ፡ ጽኑዓን ፤ ወእምጸላእትየ ፡ እስመ ፡ ይኄይሉኒ ።"),
    (17, 19, "ወበጽሑኒ ፡ በዕለተ ፡ መንዳቤየ ፤ ወኮነኒ ፡ እግዚአብሔር ፡ ምስካይየ ።"),
    (17, 20, "ወአውፅአኒ ፡ ውስተ ፡ መርሕብ ፤ ወአድኀነኒ ፡ እስመ ፡ ይፈቅደኒ ።"),
    (17, 21, "የዐስየኒ ፡ እግዚአብሔር ፡ በከመ ፡ ጽድቅየ ፤ ወይፈድየኒ ፡ በከመ ፡ ንጹሐ ፡ እደውየ ።"),
    (17, 22, "እስመ ፡ ዐቀብኩ ፡ ፍናዊሁ ፡ ለእግዚአብሔር ፤ ወኢአበስኩ ፡ ለአምላኪየ ።"),
    (17, 23, "እስመ ፡ ኵሉ ፡ ኵነኔሁ ፡ ቅድሜየ ፡ ውእቱ ፤ ወጽድቁኒ ፡ ኢርሕቀ ፡ እምኔየ ።"),
    (17, 24, "ወእከውን ፡ ንጹሐ ፡ ምስሌሁ ፤ ወእትዐቀብ ፡ እምኃጢአትየ ።"),
    (17, 25, "የዐስየኒ ፡ እግዚአብሔር ፡ በከመ ፡ ጽድቅየ ፤ ወይፈድየኒ ፡ በከመ ፡ ንጹሐ ፡ እደውየ ፡ በቅድመ ፡ አዕይንቲሁ ።"),
    (17, 26, "ምስለ ፡ ጻድቅ ፡ ትጸድቅ ፤ ወምስለ ፡ ብእሲ ፡ ንጹሕ ፡ ንጹሐ ፡ ትከውን ።"),
    (17, 27, "ወምስለ ፡ ኅሩይ ፡ ኅሩየ ፡ ትከውን ፤ ወምስለ ፡ ጠዋይ ፡ ትጠዊ ።"),
    (17, 28, "እስመ ፡ አንተ ፡ እግዚኦ ፡ ታድኅኖ ፡ ለሕዝብ ፡ ትሑት ፤ ወታኀስሮሙ ፡ ለአዕይንተ ፡ ዕቡያን ።"),
    (17, 29, "እስመ ፡ አንተ ፡ ታብርህ ፡ ማኅቶትየ ፡ እግዚኦ ፡ አምላኪየ ፡ ያበርህ ፡ ጽልመትየ ።"),
    (17, 30, "እስመ ፡ ብከ ፡ እድኅን ፡ እመንሱት ፤ ወበአምላኪየ ፡ እትዐደዋ ፡ ለአረፍት ።"),
    (17, 31, "ለአምላኪየሰ ፡ ንጹሕ ፡ ፍኖቱ ። ቃል ፡ እግዚአብሔር ፡ ርሱን ፤ ወምእመኖሙ ፡ ውእቱ ፡ ለኵሎሙ ፡ እለ ፡ ይትዌከሉ ፡ ቦቱ ።"),
    (17, 32, "ወኑ ፡ ውእቱ ፡ አምላክ ፡ ዘእንበለ ፡ እግዚአብሔር ፤ ወመኑ ፡ እግዚአብሔር ፡ ዘእንበለ ፡ አምላክነ ።"),
    (17, 33, "እግዚአብሔር ፡ ዘያቀንተኒ ፡ ኀይለ ፤ ወረሰያ ፡ ንጹሐ ፡ ለፍኖተየ ።"),
    (17, 34, "ዘያረትዖን ፡ ከመ ፡ ኀየል ፡ ለእገርየ ፤ ወያቀውመኒ ፡ ውስተ ፡ መልዕልት ።"),
    (17, 35, "ዘይሜህሮን ፡ ፀብአ ፡ ለእደውየ ፤ ወረሰየ ፡ ቀስተ ፡ ብርት ፡ ለመዝራዕትየ ።"),
    (17, 36, "ወወሀበኒ ፡ ምእመነ ፡ ለመድኀኒትየ ። ወየማንከ ፡ ተወክፈኒ ፤ ወትምህርትከ ፡ ያጸንዐኒ ፡ ለዝሉፉ ። ወተግሣጽከ ፡ ውእቱ ፡ ዘይሜህረኒ ።"),
    (17, 37, "ወአርሐብከ ፡ መካይድየ ፡ በመትሕቴየ ፤ ወኢደክማ ፡ ሰኩናየ ።"),
    (17, 38, "እዴግኖሙ ፡ ለፀርየ ፡ ወእኅዞሙ ፤ ወኢይትመየጥ ፡ እስከ ፡ ኣጠፍኦሙ ።"),
    (17, 39, "ኣመነድቦሙ ፡ ወኢይድክሉ ፡ ቀዊመ ፤ ወይወድቁ ፡ ታሕተ ፡ እገርየ ።"),
    (17, 40, "ወታቀንተኒ ፡ ኀይለ ፡ በፀብእ ፤ አዕቀጽኮሙ ፡ ለኵሎሙ ፡ እለ ፡ ቆሙ ፡ ላዕሌየ ፡ በመትሕቴየ ።"),
    (17, 41, "ወመጠውከኒ ፡ ዘባኖሙ ፡ ለፀርየ ፤ ወሠረውኮሙ ፡ ለጸላእትየ ።"),
    (17, 42, "ዐውየዉ ፡ ወኀጥኡ ፡ ዘይረድኦሙ ፤ ኀበ ፡ እግዚአብሔር ፡ ወኢሰምዖሙ ።"),
    (17, 43, "አኀርጾሙ ፡ ከመ ፡ ጸበል ፡ ዘቅድመ ፡ ገጸ ፡ ነፋስ ፤ ወእኪይዶሙ ፡ ከመ ፡ ጽንጕነ ፡ መርሕብ ።"),
    (17, 44, "አድኅነኒ ፡ እምነቢበ ፡ አሕዛብ ። ወትሠይመኒ ፡ ውስተ ፡ ርእሰ ፡ ሕዝብ ፤"),
    (17, 45, "ሕዝብ ፡ ዘኢያአምር ፡ ተቀንየ ፡ ሊተ ። ውስተ ፡ ምስማዐ ፡ እዝን ፡ ተሠጥዉኒ ፤"),
    (17, 46, "ውሉደ ፡ ነኪር ፡ ሐሰዉኒ ። ውሉደ ፡ ነኪር ፡ በልዩ ፤ ወሐንከሱ ፡ በፍኖቶሙ ።"),
    (17, 47, "ሕያው ፡ እግዚአብሔር ፡ ወቡሩክ ፡ አምላኪየ ፤ ወተለዐለ ፡ አምላከ ፡ መድኀኒትየ ።"),
    (17, 48, "አምላኪየ ፡ ያገብእ ፡ በቀልየ ፤ ወአግረረ ፡ ሊተ ፡ አሕዛበ ፡ በመትሕቴየ ። ዘይባልሐኒ ፡ እምጸላእትየ ፡ ምንስዋን ፡"),
    (17, 49, "ወዘያሌዕለኒ ፡ እምእለ ፡ ቆሙ ፡ ላዕሌየ ፤ እምብእሲ ፡ ገፋዒ ፡ ባልሐኒ ።"),
    (17, 50, "በእንተዝ ፡ እገኒ ፡ ለከ ፡ በውስተ ፡ አሕዛብ ፡ እግዚኦ ፤ ወእዜምር ፡ ለስምከ ።"),
    (17, 51, "ዘያዐብያ ፡ ለመድኀኒተ ፡ ንጉሥ ። ወይገብር ፡ ምሕረቶ ፡ ለመሲሑ ፡ ለዳዊት ፡ ወለዘርዑ ፡ እስከ ፡ ለዓለም ።"),
    (18, 1, "ፍጽሜ ፡ መዝሙር ፡ ዘዳዊት ።"),
    (18, 2, "ሰማያት ፡ ይነግራ ፡ ስብሐተ ፡ እግዚአብሔር ፤ ወግብረ ፡ እደዊሁ ፡ ያየድዓ ፡ ሰማያት ።"),
    (18, 3, "ዕለት ፡ ለዕለት ፡ ትጐሥዕ ፡ ነቢበ ፤ ወሌሊት ፡ ለሌሊት ፡ ታየድዕ ፡ ጥበበ ።"),
    (18, 4, "አልቦ ፡ ነገረ ፡ ወአልቦ ፡ ነቢበ ፡ ዘኢተሰምዐ ፡ ቃሎሙ ።"),
    (18, 5, "ውስተ ፡ ኵሉ ፡ ምድር ፡ ወፅአ ፡ ነገሮሙ ፡ ወእስከ ፡ አጽናፈ ፡ ዓለም ፡ በጽሐ ፡ ነቢቦሙ ፤ ወውስተ ፡ ፀሓይ ፡ ሤመ ፡ ጽላሎቶ ።"),
    (18, 6, "ወውእቱሰ ፡ ከመ ፡ መርዓዊ ፡ ዘይወፅእ ፡ እምጽርሑ ፤ ይትፌሣሕ ፡ ከመ ፡ ይርባሕ ፡ ዘይሜርድ ፡ ፍኖቶ ።"),
    (18, 7, "እምአጽናፈ ፡ ሰማይ ፡ ሙፅኡ ፡ ወእስከ ፡ አጽናፈ ፡ ሰማይ ፡ ምእታዉ ፤ ወአልቦ ፡ ዘይትኀባእ ፡ እምላህቡ ።"),
    (18, 8, "ሕጉ ፡ ለእግዚአብሔር ፡ ንጹሕ ፡ ወይመይጣ ፡ ለነፍስ ፤ ስምዑ ፡ ለእግዚአብሔር ፡ እሙን ፡ ዘያጠብብ ፡ ሕፃናተ ።"),
    (18, 9, "ኵነኔሁ ፡ ለእግዚአብሔር ፡ ርቱዕ ፡ ወይስተፌሥሕ ፡ ልበ ፤ ትእዛዙ ፡ ለእግዚአብሔር ፡ ብሩህ ፡ ወይበርህ ፡ አዕይንተ ።"),
    (18, 10, "ፈሪሀ ፡ እግዚአብሔር ፡ ንጹሕ ፡ ወየሐዩ ፡ ለዓለም ፤ ፍትሑ ፡ ለእግዚአብሔር ፡ ጽድቅ ፤ ወርትዕ ፡ ኅቡረ ።"),
    (18, 11, "ወይትፈተው ፡ እምወርቅ ፡ ወእምዕንቍ ፡ ክቡር ፤ ወይጥዕም ፡ እመዓር ፡ ወሶከር ።"),
    (18, 12, "ወገብርከሰ ፡ የዐቅቦ ፤ ወበዐቂቦቱ ፡ ይትዐሰይ ፡ ብዙኀ ።"),
    (18, 13, "ለስሒት ፡ መኑ ፡ ይሌብዋ ፤ እምኅቡኣትየ ፡ አንጽሐኒ ። ወእምነኪር ፡ መሐኮ ፡ ለገብርከ ።"),
    (18, 14, "እመሰ ፡ ኢቀነዩኒ ፡ ውእተ ፡ ጊዜ ፡ ንጹሐ ፡ እከውን ፤ ወእነጽሕ ፡ እምዐባይ ፡ ኀጢአትየ ።"),
    (18, 15, "ወይከውን ፡ ሥሙረ ፡ ቃለ ፡ አፉየ ፡ ወሕሊና ፡ ልብየኒ ፡ ቅድሜየ ፡ ውእቱ ፡ በኵሉ ፡ ጊዜ ። እግዚእየ ፡ ረዳኢየ ፡ ወመድኀንየ ።"),
    (19, 1, "ፍጻሜ ፡ መዝሙር ፡ ዘዳዊት ።"),
    (19, 2, "ይስማዕከ ፡ እግዚአብሔር ፡ በዕለተ ፡ ምንዳቤከ ፤ ወይቁም ፡ ለከ ፡ ስሙ ፡ ለአምላከ ፡ ያዕቆብ ።"),
    (19, 3, "ወይፈኑ ፡ ለከ ፡ ረድኤተ ፡ እምቅደሱ ፤ ወእምጽዮን ፡ ይትወከፍከ ።"),
    (19, 4, "ወይዝክር ፡ ለከ ፡ ኵሎ ፡ መሥዋዕተከ ፤ ወያጥልል ፡ ለከ ፡ ቍርባነከ ።"),
    (19, 5, "የሀብክ ፡ እግዚአብሔር ፡ ዘከመ ፡ ልብከ ፤ ወይፈጽም ፡ ለከ ፡ ኵሎ ፡ ሥምረተከ ።"),
    (19, 6, "ወንትፌሣሕ ፡ በአድኅኖትከ ፡ ወነዐቢ ፡ በስመ ፡ እግዚአብሔር ፡ አምላክነ ፤ ወይፈጽም ፡ ለከ ፡ እግዚአብሔር ፡ ኵሎ ፡ ስእለተከ ።"),
    (19, 7, "ይእዜ ፡ ኣእመርኩ ፡ ከመ ፡ አድኀኖ ፡ እግዚአብሔር ፡ ለመሲሑ ። ወይሠጠዎ ፡ እምሰማይ ፡ ወቅደሱ ፤ በኀይለ ፡ አድኅኖተ ፡ የማኑ ።"),
    (19, 8, "እሙንቱሰ ፡ በአፍራስ ፡ ወበሰረገላት ፤ ወንሕነሰ ፡ ነዐቢ ፡ በስመ ፡ እግዚአብሔር ፡ አምላክነ ።"),
    (19, 9, "እሙንቱሰ ፡ ተዐቅጹ ፡ ወወድቁ ፤ ወንሕነሰ ፡ ተንሣእነ ፡ ወረታዕነ ።"),
    (19, 10, "እግዚኦ ፡ አድኅኖ ፡ ለንጉሥ ፡ ወስምዐነ ፡ በዕለተ ፡ ንጼውዐከ ።"),
    (20, 1, "ፍጻሜ ፡ መዝሙር ፡ ዘዳዊት ።"),
    (20, 2, "እግዚኦ ፡ በኀይልከ ፡ ይትፌሣሕ ፡ ንጉሥ ፤ ወብዙኀ ፡ ይትሐሠይ ፡ በአድኅኖትከ ።"),
    (20, 3, "ፍትወተ ፡ ነፍሱ ፡ ወሀብኮ ፤ ወስእለተ ፡ ከናፍሪሁ ፡ ኢከላእኮ ።"),
    (20, 4, "እስመ ፡ በጻሕኮ ፡ በበረከት ፡ ሠናይ ፤ ወአንበርከ ፡ አክሊለ ፡ ዲበ ፡ ርእሱ ፡ ዘእምዕንቍ ፡ ክቡር ።"),
    (20, 5, "ሐይወ ፡ ሰአለከ ፡ ወወሀብኮ ፤ ለነዋኅ ፡ መዋዕል ፡ ለዓለመ ፡ ዓለም ።"),
    (20, 6, "ዐቢይ ፡ ክብሩ ፡ በአድኅኖትከ ፤ ክብረ ፡ ወስብሐተ ፡ ወሰኮ ።"),
    (20, 7, "እስመ ፡ ወሀብኮ ፡ በረከተ ፡ ለዓለመ ፡ ዓለም ፤ ወታስተፌሥሖ ፡ በሐሤተ ፡ ገጽከ ።"),
    (20, 8, "እስመ ፡ ተወከለ ፡ ንጉሥ ፡ በእግዚአብሔር ፤ ወኢይትሀወክ ፡ በምሕረቱ ፡ ለልዑል ።"),
    (20, 9, "ትርከቦሙ ፡ እዴከ ፡ ለኵሎሙ ፡ ፀርከ ፤ ወትትራከቦሙ ፡ እዴከ ፡ ለኵሎሙ ፡ ጸላእትከ ።"),
    (20, 10, "ወትረስዮሙ ፡ ከመ ፡ እቶነ ፡ እሳት ፡ ለጊዜ ፡ ገጽከ ። እግዚኦ ፡ በመዐትከ ፡ ሁኮሙ ፤ ወትብልዖሙ ፡ እሳት ።"),
    (20, 11, "ወፍሬሆሙኒ ፡ ሰዐር ፡ እምድር ፤ ወዘርዖሙኒ ፡ እምእጓለ ፡ እመሕያው ።"),
    (20, 12, "እስመ ፡ ሜጥዋ ፡ ለዐመፃ ፡ ላዕሌከ ፤ ወሐለዩ ፡ ምክረ ፡ እንተ ፡ ኢይክሉ ፡ አቅሞ ።"),
    (20, 13, "ወታገብኦሙ ፡ ድኅሬሆሙ ፤ ወታስተደሉ ፡ ገጾሙ ፡ ለጊዜ ፡ መዐትከ ።"),
    (20, 14, "ተለዐልከ ፡ እግዚኦ ፡ በኀይልከ ፤ ንሴብሕ ፡ ወንዜምር ፡ ለጽንዕከ ።"),
    (21, 1, "ፍጻሜ ፡ በእንተ ፡ ተወክፎ ፡ እንተ ፡ ጸብሐት ፤ መዝሙር ፡ ዘዳዊት ።"),
    (21, 2, "አምላኪየ ፡ አምላኪየ ፡ ነጽረኒ ፡ ወለምንት ፡ ኀደገኒ ፤ ርሑቅ ፡ እምአድኅኖትየ ፡ ቃለ ፡ ኃጢአትየ ።"),
    (21, 3, "አምላኪየ፡ ጸራኅኩ ፡ ኀቤከ ፡ ዕለትየ ፡ ወኢሰማዕከኒ ፤ ወሌሊትየኒ ፡ ቅድሜከ ፡ ወኢሐለይከኒ ።"),
    (21, 4, "ወአንተሰ ፡ ውስተ ፡ ቅዱሳኒከ ፡ ተኀድር ፡ ስቡሐ ፡ እስራኤል ።"),
    (21, 5, "ኪያከ ፡ ተወከሉ ፡ አበዊነ ፤ ተወከሉከኒ ፡ ወአድኀንኮሙ ።"),
    (21, 6, "ኀቤከ ፡ ጸርኁ ፡ ወድኅኑ ፤ ኪያከ ፡ ተወከሉ ፡ ወኢተኀፍሩ ።"),
    (21, 7, "አንሰ ፡ ዕፄ ፡ ወአኮ ፡ ሰብእ ፤ ምኑን ፡ በኀበ ፡ ሰብእ ፡ ወትሑት ፡ በውስተ ፡ ሕዝብ ።"),
    (21, 8, "ኵሎሙ ፡ እለ ፡ ይሬእዩኒ ፡ ይትቃጸቡኒ ፤ ይብሉ ፡ በከናፍሪሆሙ ፡ ወየሐውሱ ፡ ርእሶሙ ።"),
    (21, 9, "ተወከለ ፡ በእግዚአብሔር ፡ ለያድኅኖ ፤ ወያድኅኖ ፡ እመ ፡ ይፈቅዶ ።"),
    (21, 10, "እስመ ፡ እንተ ፡ አውፃእከኒ ፡ እምከርሥ ፤ ወተወከልኩከ ፡ እንዘ ፡ ሀለውኩ ፡ ውስተ ፡ አጥባተ ፡ እምየ ።"),
    (21, 11, "ላዕሌከ ፡ ተገደፍኩ ፡ እማኅፀን ፤ እምከርሠ ፡ እምየ ፡ አንተ ፡ አምላኪየ ።"),
    (21, 12, "ኢትርሐቅ ፡ እምኔየ ፡ እስመ ፡ አልጸቁ ፡ እትመንድብ ፤ እስመ ፡ አልቦ ፡ ዘይረድአኒ ።"),
    (21, 13, "ዐገቱኒ ፡ አልህምት ፡ ብዙኃን ፤ ወአኀዙኒ ፡ አስዋር ፡ ሥቡሓን ፤"),
    (21, 14, "ወአብቀዉ ፡ አፉሆሙ ፡ ላዕሌየ ፤ ከመ ፡ አንበሳ ፡ ዘጽኑሕ ፡ ለመሲጥ ።"),
    (21, 14, "ተከዐውኩ ፡ ከመ ፡ ማይ ፡ ወተዘርወ ፡ ኵሉ ፡ አዕጽምትየ ። ወኮነ ፡ ልብየ ፡ ከመ ፡ ሰምዕ ፡ ዘይትመሰው ፡ በማእከለ ፡ ከርሥየ ።"),
    (21, 16, "ወየብሰ ፡ ከመ ፡ ገልዕ ፡ ኀይልየ ፡ ወጠግዕ ፡ ልሳንየ ፡ በጕርዔየ ፤ ወአውረድከኒ ፡ ውስተ ፡ መሬተ ፡ ሞት ።"),
    (21, 17, "ዐገቱኒ ፡ ከለባት ፡ ብዙኃን ፤ ወአኀዙኒ ፡ ማኅበሮሙ ፡ ለእኩያን ። ቀነዉኒ ፡ እደውየ ፡ ወእገርየ ።"),
    (21, 18, "ወኈለቁ ፡ ኵሎ ፡ አዕጽምትየ ። እሙንተሰ ፡ ጠይቆሙ ፡ ተዐወሩኒ ።"),
    (21, 19, "ወተካፈሉ ፡ አልባስየ ፡ ለርእሶሙ ፤ ወተዓፀዉ ፡ ዲበ ፡ ዐራዝየ ።"),
    (21, 20, "አንተ ፡ እግዚኦ ፡ ኢትርሐቅ ፡ እምኔየ ፤ ወነጽር ፡ ውስተ ፡ ረዱኦትየ ።"),
    (21, 21, "አድኅና ፡ አምኲናት ፡ ለነፍስየ ። ወእምእደ ፡ ከለባት ፡ ለብሕቱትየ ።"),
    (21, 22, "አድኅነኒ ፡ እምአፈ ፡ አንበሳ ፤ ወእምአቅርንት ፡ ዘአሐዱ ፡ ቀርኑ ፡ ለብሕቱትየ ።"),
    (21, 23, "እነግሮሙ ፡ ስምከ ፡ ለአኀውየ ፤ ወበማእከለ ፡ ማኅበር ፡ እሴብሐከ ።"),
    (21, 24, "እለ ፡ ትፈርህዎ ፡ ልእግዚአብሔር ፡ ሰብሕዎ ፤ ኵልክሙ ፡ ዘርዐ ፡ ያዕቆብ ፡ አክብርዎ ፤ ወፍርህዎ ፡ ኵልክሙ ፡ ዘርዕ ፡ እስራኤል ።"),
    (21, 25, "እስመ ፡ ኢመነነ ፡ ወኢተቈጥዐ ፡ ስእለተ ፡ ነዳይ ፤ ወኢሜጠ ፡ ገጾ ፡ እምኔየ ፤ ሶበ ፡ ጸራኅኩ ፡ ኀቤሁ ፡ ይሰምዐኒ ።"),
    (21, 26, "እምኀቤከ ፡ ክብርየ ፡ በማኅበር ፡ ዐቢይ ፤ ወእሁብ ፡ ብፅአትየ ፡ በቅድመ ፡ እለ ፡ ይፈርህዎ ።"),
    (21, 27, "ይብልዑ ፡ ነዳያን ፡ ወይጽገቡ ፡ ወይሴብሕዎ ፡ ለእግዚአብሔር ፡ ኵሎሙ ፡ እለ ፡ የኀሥዎ ፤ ወየሐዩ ፡ ልቦሙ ፡ ለዓለመ ፡ ዓለም ።"),
    (21, 28, "ወይዝክሩ ፡ ወይትመየጡ ፡ ኀበ ፡ እግዚአብሔር ፡ ኵሎሙ ፡ አጽናፈ ፡ ምድር ፤ ወይስግዱ ፡ ቅድሜሁ ፡ ኵሎሙ፡ በሐውርተ ፡ አሕዛብ ።"),
    (21, 29, "እስመ ፡ ለእግዚአብሔር ፡ መንግሥት ፤ ወውእቱ ፡ ይኴንኖሙ ፡ ለአሕዛብ ።"),
    (21, 30, "ብልዑ ፡ ወስግዱ ፡ ኵልክሙ ፡ ጥሉላነ ፡ ምድር ፡ ቅድሜሁ ፡ ይወድቁ ፡ ኵሎሙ ፡ እለ ፡ ይወርዱ ፡ ውስተ ፡ ምድር ፤ ወነፍስየኒ ፡ ሎቱ ፡ ተሐዩ ።"),
    (21, 31, "ወዘርዕየኒ ፡ ሎቱ ፡ ይትቀነይ ፤ ትዜንዎ ፡ ለእግዚአብሔር ፡ ትውልድ ፡ እንተ ፡ ትመጽእ ።"),
    (21, 32, "ወይዜንዉ ፡ ጽድቀ ፡ ዚአሁ ፤ ሕዝብ ፡ ዘይትወለድ ፡ ዘገብረ ፡ እግዚአብሔር ።"),
    (22, 1, "መዝሙር ፡ ዘዳዊት ። እግዚአብሔር ፡ ይሬዕየኒ ፡ ወአልቦ ፡ ዘየኀጥአኒ ።"),
    (22, 2, "ውስተ ፡ ብሔር ፡ ሥዑር ፡ ህየ ፡ ያኀድረኒ ፤ ወኀበ ፡ ማየ ፡ ዕረፍት ፡ ሐፀነኒ ።"),
    (22, 3, "ሜጣ ፡ ለነፍስየ ፤ ወመርሐኒ ፡ ፍኖተ ፡ ጽድቅ ፡ በእንተ ፡ ስመ ፡ ዚአሁ ።"),
    (22, 4, "እመኒ ፡ ሖርኩ ፡ ማእከለ ፡ ጽላሎተ ፡ ሞት ፡ ኢይፈርሆ ፡ ለእኩይ ፡ እስመ ፡ አንተ ፡ ምስሌየ ፤ በትርከ ፡ ወቀስታምከ ፡ እማንቱ ፡ ገሠጻኒ ።"),
    (22, 5, "ወሠራዕከ ፡ ማእደ ፡ በቅድሜየ ፡ በአንጻሪሆሙ ፡ ለእለ ፡ ይሣቅዩኒ ፤ ወአጽሐድከ ፡ በቅብእ ፡ ርእስየ ፡ ጽዋዕከኒ ፡ ጽኑዕ ፡ ያረዊ ።"),
    (22, 6, "ምሕረትከ ፡ ይትልወኒ ፡ በኵሉ ፡ መዋዕለ ፡ ሕይወትየ ፤ ከመ ፡ ታንብረኒ ፡ ቤቶ ፡ ለእግዚአብሔር ፡ ለነዋኅ ፡ መዋዕል ።"),
    (23, 1, "መዝሙር ፡ ዘዳዊት ፡ ዘቀዳሚተ ሰንበት ። ለእግዚአብሔር ፡ ምድር ፡ በምልኣ ፤ ወዓለምኒ ፡ ወኵሎሙ ፡ እለ ፡ ይነብሩ ፡ ውስቴታ ።"),
    (23, 2, "ወውእቱ ፡ በባሕር ፡ ሳረራ ፤ ወበአፍላግኒ ፡ ውእቱ ፡ አጽንዓ ።"),
    (23, 3, "መኑ ፡ የዐርግ ፡ ውስተ ፡ ደብረ ፡ እግዚአብሔር ፤ ወመኑ ፡ ይቀውም ፡ ውስተ ፡ መካነ ፡ መቅደሱ ።"),
    (23, 4, "ዘንጹሕ ፡ ልቡ ፡ ወንጹሕ ፡ እደዊሁ ። ወዘኢነሥአ ፡ ከንቶ ፡ ላዕለ ፡ ነፍሱ ፤ ወዘኢመሐለ ፡ በጕሕሉት ፡ ለቢጹ ።"),
    (23, 5, "ውእቱ ፡ ይነሥእ ፡ በረከተ ፡ እምኀበ ፡ እግዚአብሔር ፤ ወሣህሉኒ ፡ እምኀበ ፡ እግዚአብሔር ፡ አምላኩ ።"),
    (23, 6, "ዛቲ ፡ ትውልድ ፡ ተኀሦ ፡ ሎቱ ፤ ወተኀሥሥ ፡ ገጾ ፡ ለአምላከ ፡ ያዕቆብ ።"),
    (23, 7, "አርኅው ፡ ኆኃተ ፡ መኳንንት ፡ ወይትረኀዋ ፡ ኆኃት ፡ እለ ፡ እምፍጥረት ፤ ወይባእ ፡ ንጉሠ ፡ ስብሐት ።"),
    (23, 8, "መኑ ፡ ውእቱ ፡ ዝንቱ ፡ ንጉሠ ፡ ስብሐት ። እግዚአብሔር ፡ ኀያል ፡ ወጽኑዕ ፤ እግዚአብሔር ፡ ኀያል ፡ በውስተ ፡ ፀብእ ።"),
    (23, 9, "አርኅው ፡ ኆኃተ ፡ መኳንንት ፡ ወይትረኀዋ ፡ ኆኃት ፡ እለ ፡ እምፍጥረት ፤ ወይባእ ፡ ንጉሠ ፡ ስብሐት ።"),
    (23, 10, "መኑ ፡ ውእቱ ፡ ዝንቱ ፡ ንጉሠ ፡ ስብሐት ፤ እግዚአብሔር ፡ አምላከ ፡ ኀያላን ፡ ውእቱ ፡ ዝንቱ ፡ ንጉሠ ፡ ስብሐት ።"),
    (24, 1, "መዝሙር ፡ ዘዳዊት ። ኀቤከ ፡ እግዚኦ ፡ አንቃዕደውኩ ፡ ነፍስየ ፡"),
    (24, 2, "አምላኪየ ፡ ኪያከ ፡ ተወከልኩ ፡ ኢይትኀፈር ፡ ለዓለም ፤ ወኢይስሐቁኒ ፡ ጸላእትየ ።"),
    (24, 3, "እስመ ፡ ኵሎሙ ፡ እለ ፡ ይሴፈዉከ ፡ ኢይትኀፈሩ ፤ ለይትኀፈሩ ፡ ኵሎሙ ፡ እለ ፡ ይኤብሱ ፡ ዘልፈ ።"),
    (24, 4, "ፍኖተከ ፡ እግዚኦ ፡ አምረኒ ፤ ወአሰረ ፡ ዚአከ ፡ ምህረኒ ።"),
    (24, 5, "ወምርሐኒ ፡ በጽድቅከ ፡ ወምህረኒ ፡ እስመ ፡ አንተ ፡ አምላኪየ ፡ ወመድኀኒየ ፤ ወኪየከ ፡ እሴፎ ፡ ኵሎ ፡ አሚረ ።"),
    (24, 6, "ተዘከር ፡ ሣህለከ ፡ እግዚኦ ፡ ወምሕረተከኒ ፤ እስመ ፡ ለዓለም ፡ ውእቱ ።"),
    (24, 7, "ኃጢአትየ ፡ ዘበንእስየ ፡ ወእበድየ ፡ ኢተዝክር ፡ ሊተ ። ወበከመ ፡ ሣህልከ ፡ ተዘከረኒ ፤ በእንተ ፡ ምሕረትከ ፡ እግዚኦ ።"),
    (24, 8, "ኄርኒ ፡ ወጻድቅኒ ፡ እግዚአብሔር ፤ በእንተዝ ፡ ይመርሖሙ ፡ ፍኖተ ፡ ለእለ ፡ ይስሕቱ ።"),
    (24, 9, "ወይሜህሮሙ ፡ ፍትሐ ፡ ለየዋሃን ፤ ወይኤምሮሙ ፡ ፍኖቶ ፡ ለልቡባን ።"),
    (24, 10, "ኵሉ ፡ ፍኖቱ ፡ ለእግዚአብሔር ፡ ሣህል ፡ ወጽድቅ ፤ ለእለ ፡ የኀሡ ፡ ሕጎ ፡ ወስምዖ ።"),
    (24, 11, "በእንተ ፡ ስምከ ፡ እግዚኦ ፤ ወስረይ ፡ ሊተ ፡ ኵሎ ፡ ኃጢአትየ ፡ እስመ ፡ ብዙኅ ፡ ውእቱ ።"),
    (24, 12, "መኑ ፡ ውእቱ ፡ ብእሲ ፡ ዘይፈርሆ ፡ ለእግዚአብሔር ፤ ወይመርሖ ፡ ፍኖተ ፡ እንተ ፡ ኀርየ ።"),
    (24, 13, "ወነፍሱሂ ፡ ውስተ ፡ ሠናይ ፡ ተኀድር ፤ ወዘርዑሂ ፡ ይወርስዋ ፡ ለምድር ።"),
    (24, 14, "ኀይሎሙ ፡ ውእቱ ፡ እግዚአብሔር ፡ ለእለ ፡ ይፈርህዎ ፤ ወስሙሂ ፡ ለእግዚአብሔር ፡ ለእለ ፡ ይጼውዕዎ ። ወሕጎሂ ፡ ይሜህሮሙ ።"),
    (24, 15, "አዕይንትየሰ ፡ ዘልፈ ፡ ኀበ ፡ እግዚአብሔር ፤ እስመ ፡ ውእቱ ፡ ይባልሖን ፡ እመሥገርት ፡ ለእገርየ ።"),
    (24, 16, "ነጽር ፡ ላዕሌየ ፡ ወተሣሀለኒ ፤ እስመ ፡ ባሕታዊ ፡ ወነዳይ ፡ አነ ።"),
    (24, 17, "ወብዙኅ ፡ ሐዘኑ ፡ ለልብየ ፤ አድኅነኒ ፡ እምንዳቤየ ።"),
    (24, 18, "ርኢ ፡ ሕማምየ ፡ ወስራሕየ ፤ ወኅድግ ፡ ሊተ ፡ ኵሎ ፡ ኃጢአትየ ።"),
    (24, 19, "ወርኢ ፡ ከመ ፡ በዝኁ ፡ ጸላእትየ ፤ ጽልአ ፡ በዐመፃ ፡ ይጸልኡኒ ።"),
    (24, 20, "ዕቀባ ፡ ለነፍስየ ፡ ወአድኅና ፤ ወኢይትኀፈር ፡ እስመ ፡ ኪየከ ፡ ተወከልኩ ።"),
    (24, 21, "የዋሃን ፡ ወራትዓን ፡ ተለዉኒ ፤ እስመ ፡ ተሰፈውኩከ ፡ እግዚኦ ።"),
    (24, 22, "ያድኅኖ ፡ እግዚአብሔር ፡ ለእስራኤል ፡ እምኵሉ ፡ ምንዳቤሁ ።"),
    (25, 1, "መዝሙር ፡ ዘዳዊት ። ፍታሕ ፡ ሊተ ፡ እግዚኦ ፡ እስመ ፡ አንሰ ፡ በየዋሃትየ ፡ አሐውር ፤ ወተወከልኩ ፡ በእግዚአብሔር ፡ ከመ ፡ ኢይድክም ።"),
    (25, 2, "ፍትነኒ ፡ እግዚኦ ፡ ወአመክረኒ ፤ ፍትን ፡ ልብየ ፡ ወኵልያትየ ።"),
    (25, 3, "ከመ ፡ ምሕረትከ ፡ ቅድመ ፡ አዕይንትየ ፡ ውእቱ ፤ ወተፈሣሕኩ ፡ በአድኅኖትከ ።"),
    (25, 4, "ወኢነበርኩ ፡ ውስተ ፡ ዐውደ ፡ ከንቱ ፤ ወኢቦእኩ ፡ ምስለ ፡ ዐማፂያን ።"),
    (25, 5, "ጸላእኩ ፡ ማኅበረ ፡ እኩያን ፤ ወኢይነብር ፡ ምስለ ፡ ጽልሕዋን ።"),
    (25, 6, "ወአሐጽብ ፡ በንጹሕ ፡ እደውየ ፤ ወአዐውድ ፡ ምሥዋዒከ ፡ እግዚኦ ።"),
    (25, 7, "ከመ ፡ እስማዕ ፡ ቃለ ፡ ስብሐቲከ ፤ ወከመ ፡ እንግር ፡ ኵሎ ፡ መንክረከ ።"),
    (25, 8, "እግዚኦ ፡ አፍቀርኩ ፡ ሥነ ፡ ቤትከ ፤ ወመካነ ፡ ማኅደረ ፡ ስብሐቲከ ።"),
    (25, 9, "ኢትግድፋ ፡ ምስለ ፡ ኃጥኣን ፡ ለነፍስየ ፤ ወኢምስለ ፡ ዕድወ ፡ ደም ፡ ለሕይወትየ ።"),
    (25, 10, "እለ ፡ ዐመፃ ፡ ውስተ ፡ እደዊሆሙ ፤ ወምልእት ፡ ሕልያነ ፡ የምኖሙ ።"),
    (25, 11, "ወአንሰ ፡ በየዋሃትየ ፡ አሐውር ፤ አድኅነኒ ፡ እግዚኦ ፡ ወተሣሀለኒ ።"),
    (25, 12, "እስመ ፡ በርቱዕ ፡ ቆማ ፡ እገሪየ ፤ በማኅበር ፡ እባርከከ ፡ እግዚኦ ።"),
    (
        26,
        1,
        "መዝሙር ፡ ዘዳዊት ፡ ዘእንበለ ፡ ይትቀባእ ። እግዚአብሔር ፡ ያበርህ ፡ ሊተ ፡ ወያድኅነኒ ፡ ምንትኑ ፡ ያፈርሀኒ ፤ እግዚአብሔር ፡ ምእመና ፡ ለሕይወትየ ፡ ምንትኑ ፡ ያደነግፀኒ ።",
    ),
    (26, 2, "ሶበ ፡ ይቀርቡኒ ፡ እኩያን ፡ ይብልዑኒ ፡ ሥጋየ ፤ ጸላእትየሰ ፡ እለ ፡ ይሣቅዩኒ ፡ እሙንቱ ፡ ደክሙ ፡ ወወድቁ ።"),
    (26, 3, "እመኒ ፡ ፀብአኒ ፡ ተዓይን ፡ ኢይፈርሀኒ ፡ ልብየ ፤ ወእመኒ ፡ ሮዱኒ ፡ ፀባኢት ፡ አንሰ ፡ ቦቱ ፡ ተወከልኩ ።"),
    (
        26,
        4,
        "አሐተ ፡ ሰአልክዎ ፡ ለእግዚአብሔር ፡ ወኪያሃ ፡ አኀሥሥ ፤ ከመ ፡ እኅድር ፡ ቤቶ ፡ ለእግዚአብሔር ፡ በኵሉ ፡ መዋዕለ ፡ ሕይወትየ ፤ ከመ ፡ ያርእየኒ ፡ ዘያሠምሮ ፡ ለእግዚአብሔር ፡ ወከመ ፡ እፀመድ ፡ ውስተ ፡ ቤተ ፡ መቅደሱ ።",
    ),
    (26, 5, "እስመ ፡ ኀብአኒ ፡ ውስተ ፡ ጽላሎቱ ፡ በዕለተ ፡ ምንዳቤየ ። ወሰወረኒ ፡ በምኅባአ ፡ ጽላሎቱ ፤ ወዲበ ፡ ኰኵሕ ፡ አልዐለኒ ።"),
    (
        26,
        6,
        "ናሁ ፡ ይእዜ ፡ አልዐለ ፡ እግዚአብሔር ፡ ርእስየ ፡ ዲበ ፡ ጸላእትየ ። ዖድኩ ፡ ወሦዕኩ ፡ ውስተ ፡ ደብተራሁ ፡ መሥዋዕተ ፤ ወየበብኩ ፡ ሎቱ ። እሴብሕ ፡ ወእዜምር ፡ ለእግዚአብሔር ።",
    ),
    (26, 7, "ስምዐኒ ፡ እግዚኦ ፡ ቃልየ ፡ ዘሰአልኩ ፡ ኀቤከ ። ተሣሀለኒ ፡ ወስምዐኒ ፡"),
    (26, 8, "ለከ ፡ ይብለከ ፡ ልብየ ፡ ወኀሠሥኩ ፡ ገጸከ ፤ ገጸ ፡ ዚአከ ፡ አኀሥሥ ፡ እግዚኦ ።"),
    (26, 9, "ወኢትሚጥ ፡ ገጸከ ፡ እምኔየ ፡ ወኢትትገሐስ ፡ እምገብርከ ፡ ተምዒዐከ ። ረዳኤ ፡ ኩነኒ ፡ ወኢትግድፈኒ ፡ ወኢትትሀየየኒ ፡ አምላኪየ ፡ ወመድኀኒየ ።"),
    (26, 10, "እስመ ፡ አቡየ ፡ ወእምየ ፡ ገደፉኒ ፤ ወእግዚአብሔር ፡ ተወክፈኒ ።"),
    (26, 11, "ምህረኒ ፡ እግዚኦ ፡ ፍኖትከ ፤ ወምርሐኒ ፡ ፍኖተ ፡ ርትዕከ ፡ በእንተ ፡ ጸላእትየ ።"),
    (26, 12, "ወኢትመጥወኒ ፡ ለነፍስ ፡ ለእለ ፡ ይሣቅዩኒ ፤ እስመ ፡ ቆሙ ፡ ላእሌየ ፡ ሰምዕተ ፡ ዐመፃ ፡ ወሐሰወት ፡ ርእሳ ፡ ዐመፃ ።"),
    (26, 13, "እትአመን ፡ ከመ ፡ እርአይ ፡ ሠናይቶ ፡ ለእግዚአብሔር ፡ በብሔረ ፡ ሕያዋን ።"),
    (26, 14, "ወተሰፈዎ ፡ ለእግዚአብሔር ። ተዐገሥ ፡ ወአጽንዕ ፡ ልበከ ፡ ወተሰፈዎ ፡ ለእግዚአብሔር ።"),
    (27, 1, "መዝሙር ፡ ዘዳዊት ። ኀቤከ ፡ እግዚኦ ፡ ጸራኅኩ ፡ አምላኪየ ፡ ወኢተጸመመኒ ፤ ወእመሰ ፡ ተጸመመከኒ ፡ እከውን ፡ ከመ ፡ እለ ፡ የወርዱ ፡ ውስተ ፡ ግብ ።"),
    (27, 2, "ስምዐኒ ፡ እግዚኦ ፡ ቃለ ፡ ስእለትየ ፡ ዘጸራኅኩ ፡ ኀቤከ ፡ ሶበ ፡ ኣንሥእ ፡ እደውየ ፡ በጽርሐ ፡ መቅደስከ ።"),
    (
        27,
        3,
        "ኢትስሐባ ፡ ምስለ ፡ ኃጥኣን ፡ ለነፍስየ ፡ ወኢትግድፈኒ ፡ ምስለ ፡ ገበርተ ፡ ዐመፃ ። እለ ፡ ይትናገሩ ፡ ሰላመ ፡ ምስለ ፡ ቢጾሙ ፤ ወእኩይ ፡ ውስተ ፡ ልቦሙ ።",
    ),
    (27, 4, "ሀቦሙ ፡ በከመ ፡ ምግባሮሙ ፡ ወበከመ ፡ እከየ ፡ ሕሊናሆሙ ። ፍድዮሙ ፡ በከመ ፡ ግብረ ፡ እደዊሆሙ ፤ ፍድዮሙ ፡ ፍዳሆሙ ፡ ላዕለ ፡ ርእሶሙ ።"),
    (27, 5, "እስመ ፡ ኢሐለዩ ፡ ውስተ ፡ ግብረ ፡ እግዚአብሔር ፡ ወኢውስተ ፡ ግብረ ፡ እደዊሁ ፤ ንሥቶሙ ፡ ወኢትሕንጾሙ ።"),
    (27, 6, "ይትባረክ ፡ እግዚአብሔር ፡ እስመ ፡ ሰምዐኒ ፡ ቃለ ፡ ስእለትየ ።"),
    (27, 7, "እግዚአብሔር ፡ ረዳእየ ፡ ወምእመንየ ፡ ቦቱ ፡ ተወከለ ፡ ልብየ ፡ ወይረድአኒ ። ወሠረጸ ፡ ሥጋየ ፤ ወእምፈቃድየ ፡ አአምኖ ።"),
    (27, 8, "እግዚአብሔር ፡ ኀይሎሙ ፡ ውእቱ ፡ ለሕዝቡ ፤ ወምእመነ ፡ መድኀኒተ ፡ መሲሑ ፡ ውእቱ ።"),
    (27, 9, "አድኅን ፡ ሕዝበከ ፡ ወባርክ ፡ ርስተከ ፤ ረዐዮሙ ፡ ወአልዕሎሙ ፡ እስከ ፡ ለዓለም ።"),
    (28, 1, "መዝሙር ፡ ዘዳዊት ፡ ዘበፀአተ ፡ ትዕይንት ። አምጽኡ ፡ ለእግዚአብሔር ፡ ውሉደ ፡ አማልክት ፤ አምጽኡ ፡ ለእግዚአብሔር ፡ እጓለ ፡ ሐራጊት ፤"),
    (28, 2, "አምጽኡ ፡ ለእግዚአብሔር ፡ ክብረ ፡ ወስብሐተ ። አምጽኡ ፡ ለእግዚአብሔር ፡ ስብሐተ ፡ ለስሙ ፤ ስግዱ ፡ ለእግዚአብሔር ፡ በዐጸደ ፡ መቅደሱ ።"),
    (28, 3, "ቃለ ፡ እግዚአብሔር ፡ ላዕለ ፡ መየት ። አምላከ ፡ ስብሐት ፡ አንጐድጐደ ፤ እግዚአብሔር ፡ ላዕለ ፡ ማያት ፡ ብዙኅ ።"),
    (28, 4, "ቃለ ፡ እግዚአብሔር ፡ በኀይል ፤ ቃለ ፡ እግዚአብሔር ፡ በዐቢይ ፡ ስብሐት ።"),
    (28, 5, "ቃለ ፡ እግዚአብሔር ፡ ይቀጠቅጥ ፡ አርዘ ፤ ወይቀጠቅጦ ፡ እግዚአብሔር ፡ ለአርዘ ፡ ሊባኖስ ።"),
    (28, 6, "ወያደገድጎ ፡ ከመ ፡ ላህመ ፡ ለሊባኖስ ፤ ወፍቁርሰ ፡ ከመ ፡ ወልድ ፡ ዘአሐዱ ፡ ቀርኑ ።"),
    (28, 7, "ቃለ ፡ እግዚአብሔር ፡ ይመትር ፡ ነደ ፡ እሳት ።"),
    (28, 8, "ቃለ ፡ እግዚአብሔር ፡ ያድለቀልቆ ፡ ለገዳም ፤ ወያድለቀልቆ ፡ እግዚአብሔር ፡ ለሐቅለ ፡ ቃዴስ ።"),
    (28, 9, "ቃለ ፡ እግዚአብሔር ፡ ያጸንዖሙ ፡ ለኀየላት ፤ ወይከሥት ፡ አዕዋመ ፤ ወበጽርሑ ፡ ኵሉ ፡ ይብል ፡ ስብሐት ።"),
    (28, 10, "እግዚአብሔር ፡ ያስተጋብኦ ፡ ለማየ ፡ አይኅ ፤ ወይነብር ፡ እግዚአብሔር ፡ ወይነግሥ ፡ ለዓለም ።"),
    (28, 11, "ወይሁቦሙ ፡ እግዚአብሔር ፡ ኀይል ፡ ለሕዝቡ ፤ እግዚአብሔር ፡ ይባርኮሙ ፡ ለሕዝቡ ፡ በሰላም ።"),
    (29, 1, "ፍጻሜ ፡ መዝሙር ፡ ማኅሌት ፡ ለተሐድሶ ፡ ቤቱ ፡ ለዳዊት ።"),
    (29, 2, "ኣአኵተከ ፡ እግዚኦ ፡ እስመ ፡ ተወከፍክኒ ፤ ወስላተ ፡ ጸላኢየ ፡ ኢረሰይከኒ ።"),
    (29, 3, "እግዚኦ ፡ አምላኪየ ፡ ጸራኅኩ ፡ ኀቤከ ፡ ወተሣሀልከኒ ።"),
    (29, 4, "እግዚኦ ፡ አውፃእካ ፡ እምሲኦል ፡ ለነፍስየ ፤ ወአድኀንከኒ ፡ እምእለ ፡ ይወርዱ ፡ ውስተ ፡ ግብ ።"),
    (29, 5, "ዘምሩ ፡ ለእግዚአብሔር ፡ ጻድቃኑ ፤ ወግነዩ ፡ ለዝክረ ፡ ቅድሳቱ ።"),
    (29, 6, "እስመ ፡ መቅሠፍት ፡ እመዐቱ ፡ ወሐይው ፡ እምፈቅዱ ፤ በምሴት ፡ ይደምፅ ፡ ብካይ ፡ ወበጽባሕ ፡ ፍሥሓ ።"),
    (29, 7, "አንሰ ፡ እቤ ፡ በትድላየ ፤ ኢይትሀወክ ፡ ለዓለም ።"),
    (29, 8, "እግዚኦ ፡ በሥምረትከ ፡ ሀባ ፡ ኀይለ ፡ ለሕይወትየ ፤ ሜጥከሰ ፡ ገጸከ ፡ ወኮንኩ ፡ ድንጉፀ ።"),
    (29, 9, "ኀቤከ ፡ እግዚኦ ፡ ጸራኅኩ ፡ ኀበ ፡ አምላኪየ ፡ እስእል ።"),
    (29, 10, "ምንተ ፡ ያሰልጥ ፡ ደምየ ፡ ለእመ ፡ ወረድኩ ፡ ውስተ ፡ ሙስና ፤ መሬትኑ ፡ የአምነከ ፡ ወይነግር ፡ ጽድቀከ ።"),
    (29, 11, "ሰምዐ ፡ እግዚአብሔር ፡ ወተሠሀለኒ ፤ ወኮነኒ ፡ እግዚአብሔር ፡ ረዳኢየ ።"),
    (29, 12, "ሜትከ ፡ ላሕየ ፡ ወአስተፈሣሕከኒ ፤ ሰጠጥከ ፡ ሠቅየ ፡ ወሐሤተ ፡ አቅነትከኒ ።"),
    (29, 13, "ከመዝ ፡ እዜምር ፡ ለከ ፡ ክብርየ ፡ ወኢይደንግፅ ፤ እግዚኦ ፡ አምላኪየ ፡ እገኒ ፡ ለከ ፡ ለዓለም ።"),
    (30, 1, "መዝሙር ፡ ዘዳዊት ፡ ዘበተደሞ ፡ ከመዘ ፡ ውእቱ ፡ በካልእ ።"),
    (30, 2, "ኪየከ ፡ ተወከልኩ ፡ እግዚኦ ፡ ወኢይትኀፈር ፡ ለዓለም ፤ ወበጽድቅከ ፡ አንግፈኒ ፡ ወባልሐኒ ።"),
    (30, 3, "አፅምእ ፡ እዝነከ ፡ ኀቤየ ፡ ወፍጡነ ፡ አድኅነኒ ። ኩነኒ ፡ አምላኪየ ፡ ወመድኀንየ ፤ ወቤተ ፡ ጸወንየ ፡ ከመ ፡ ታድኅነኒ ፡"),
    (30, 4, "እስመ ፡ ኀይልየ ፡ ወጸወንየ ፡ አንተ ፤ ወበእንተ ፡ ስምከ ፡ ምርሐኒ ፡ ወሴስየኒ ።"),
    (30, 5, "ወአውፅእኒ ፡ እምዛቲ ፡ መሥገርት ፡ እንተ ፡ ኀብኡ ፡ ሊተ ፤ እስመ ፡ አንተ ፡ ረዳእየ ፡ እግዚኦ ።"),
    (30, 6, "ውስተ ፡ እዴከ ፡ ኣምኀፅን ፡ ነፍስየ ፤ ቤዝወኒ ፡ እግዚአብሔር ፡ አምላከ ፡ ጽድቅ ።"),
    (30, 7, "ጸላእከ ፡ እግዚኦ ፡ ኵሎ ፡ ዘየዐቅብ ፡ ከንቶ ፡ ለዝሉፉ ፤ ወአንሰ ፡ በእግዚአብሔር ፡ እወከልኩ ።"),
    (30, 8, "እትፌሣሕ ፡ ወእትሐሠይ ፡ በአድኅኖትከ ። እስመ ፡ ርኢከኒ ፡ በሕማምየ ፤ ወአድኀንካ ፡ እምንዳቤሃ ፡ ለነፍስየ ።"),
    (30, 9, "ወኢዘጋሕከኒ ፡ ውስተ ፡ እደ ፡ ፀርየ ። ወአቀምኮን ፡ ውስተ ፡ መርሕብ ፡ ለእገርየ ።"),
    (30, 10, "ተሣሀለኒ ፡ እግዚኦ ፡ እስመ ፡ ሐመምኩ ፤ ወተሀውከት ፡ እመዐት ፡ ዐይንየ ፡ ነፍስየኒ ፡ ወከርሥየኒ ።"),
    (30, 11, "እስመ ፡ ኀልቀ ፡ በሕማም ፡ ሕይወትየ ፤ ወዐመትየኒ ፡ በገዐር ። ደክመ ፡ በተጽናስ ፡ ኀይልየ ፤ ወአንቀልቀለ ፡ ኵሉ ፡ አዕጽምትየ ።"),
    (30, 12, "ተጸአልኩ ፡ በኀበ ፡ ኵሎሙ ፡ ጸላእትየ ፤ ወፈድፋደሰ ፡ በኀበ ፡ ጎርየ ፡ ግሩም ፡ ኮንክዎሙ ፡ ለአዝማድየ ።"),
    (30, 13, "ወእለኒ ፡ ይሬእዩኒ ፡ አፍአ ፡ ይጐዩ ፡ እምኔየ ። ቀብጹኒ ፡ እምልብ ፡ ከመ ፡ ዘሞተ ፤ ወኮንኩ ፡ ከመ ፡ ንዋይ ፡ ዘተሐጕለ ።"),
    (30, 14, "እስመ ፡ ሰማዕኩ ፡ ድምፀ ፡ ብዙኃን ፡ እለ ፡ ዐገቱኒ ፡ ዐውድየ ። ሶበ ፡ ተጋብኡ ፡ ኅቡረ ፡ ላዕሌየ ፤ ወተማከሩ ፡ ይምስጥዋ ፡ ለነፍስየ ።"),
    (30, 15, "ወአንሰ ፡ ብከ ፡ ተወከልኩ ፡ እግዚኦ ፤ ወእቤለከ ፡ አምላኪየ ፡ አንተ ።"),
    (30, 16, "ውስተ ፡ እዴከ ፡ ርስትየ ፤ አድኅነኒ ፡ እንእደ ፡ ፀርየ ፡ ወእምእለ ፡ ሮዱኒ ።"),
    (30, 17, "አብርህ ፡ ገጸከ ፡ ላዕለ ፡ ገብርከ ፤ ወአድኅነኒ ፡ በእንተ ፡ ምሕረትከ ።"),
    (30, 18, "ወኢይትኀፈር ፡ እግዚኦ ፡ እስመ ፡ ጸዋዕኩከ ፤ ለይትኀፈሩ ፡ ጽልሕዋን ፡ ወይረዱ ፡ ውስተ ፡ ሲኦል ።"),
    (30, 19, "አሌሎን ፡ ለከናፍረ ፡ ጕሕሉት ፤ እለ ፡ ይነባ ፡ ዐመፃ ፡ ላዕለ ፡ ጻድቅ ፡ በትዕቢት ፡ ወበመንኖ ።"),
    (
        30,
        20,
        "ወበከመ ፡ ብዝኀ ፡ ምሕረትከ ፡ እግዚኦ ፡ ሰወርኮሙ ፡ ለእለ ፡ ይፈርሁከ ። ወአድኀንኮሙ ፡ ለእለ ፡ ይትዌከሉ ፡ ብከ ፤ በቅድመ ፡ ደቂቀ ፡ እጓለ ፡ እምሕያው ።",
    ),
    (30, 21, "ወተኀብኦሙ ፡ በጽላሎትከ ፡ እምሀከከ ፡ ሰብእ ፤ ወትከድኖሙ ፡ በመንጦላዕትከ ፡ እምባህለ ፡ ልሳን ።"),
    (30, 22, "ይትባረክ ፡ እግዚአብሔር ፡ ዘሰብሐ ፡ ምሕረቶ ፡ ላዕሌየ ፡ በብዝኀ ፡ ምንዳቤየ ።"),
    (30, 23, "አንሰ ፡ እቤ ፡ ተገደፍኩኒ ፡ እንጋ ፡ እምቅድመ ፡ አዕይንቲከ ። በእንተዝ ፡ ሰምዐኒ ፡ እግዚአብሔር ፡ ቃለ ፡ ስእለትየ ፡ ዘጸራኅኩ ፡ ኀቤሁ ።"),
    (30, 24, "አፍቅርዎ ፡ ለእግዚአብሔር ፡ ኵልክሙ ፡ ጻድቃኑ ። እስመ ፡ ጽድቀ ፡ የኀሥሥ ፡ እግዚአብሔር ፤ ወይትቤቀሎሙ ፡ ለእለ ፡ የኀሥሡ ፡ ትዕቢተ ፡ ፈድፋደ ።"),
    (30, 25, "ተዐገሡ ፡ ወአጽንዑ ፡ ልበክሙ ፤ ኵልክሙ ፡ እለ ፡ ተወከልክሙ ፡ በእግዚአብሔር ።"),
    (31, 1, "መዝሙር ፡ ዘዳዊት ፡ ዘበኣእምሮ ። ብፁዓን ፡ እለ ፡ ተኀድገ ፡ ሎሙ ፡ ኀጢአቶሙ ፤ ወለእለ ፡ ኢሐሰበ ፡ ሎሙ ፡ ኵሎ ፡ ገጋዮሙ ።"),
    (31, 2, "ብፁዕ ፡ ብእሲ ፡ ዘኢኈለቈ ፡ ሎቱ ፡ እግዚአብሔር ፡ ኃጢአቶ ፤ ወዘአልቦ ፡ ጽልሑተ ፡ ውስተ ፡ ልቡ ።"),
    (31, 3, "እስመ ፡ አርመምኩ ፡ በልብየ ፡ አዕጽምትየ ፤ እምኀበ ፡ እጸርኅ ፡ ኵሎ ፡ አሚረ ።"),
    (31, 4, "እስመ ፡ መዐልተ ፡ ወሌሊተ ፡ ከብደት ፡ እዴከ ፡ ላዕሌየ ፤ ወተመየጥኩ ፡ ለሕርትምና ፡ ሶበ ፡ ወግዐኒ ፡ ሦክ ።"),
    (
        31,
        5,
        "ኃጢአትየ ፡ ነገርኩ ፡ ወአበሳየ ፡ ኢኀባእኩ ፤ ወእቤ ፡ ኣስተዋዳ ፡ ርእስየ ፡ ኀበ ፡ እግዚአብሔር ፡ በእንተ ፡ ኀጢአትየ ፤ ወአንተ ፡ ኅድግ ፡ ጽልሑቶ ፡ ለልብየ ።",
    ),
    (31, 6, "በእንተዝ ፡ ይጼሊ ፡ ኀቤከ ፡ ኵሉ ፡ ጻድቅ ፡ በጊዜ ፡ ርቱዕ ፤ ወባሕቱ ፡ ማየ ፡ አይኅ ፡ ብዙኅ ፡ ኢይቀርብ ፡ ኀቤከ ።"),
    (31, 7, "አንተ ፡ ምስካይየ ፡ እምዛቲ ፡ ምንዳቤየ ፡ እንተ ፡ ረከበትኒ ፤ ወትፍሥሕትየኒ ፡ ከመ ፡ ታድኅነኒ ፡ እምእለ ፡ ሮዱኒ ።"),
    (31, 8, "ኣሌብወከ ፡ ወኣጸንዐከ ፡ በዛቲ ፡ ፍኖት ፡ እንተ ፡ ሖርከ ፤ ወኣጸንዕ ፡ አዕይንትየ ፡ ላዕሌከ ።"),
    (31, 9, "ኢትኩኒ ፡ ከመ ፡ ፈረስ ፡ ወበቅል ፡ እለ ፡ አልቦሙ ፡ ልበ ፤ እለ ፡ በሕሳል ፡ ወበልጓም ፡ ይመይጥዎሙ ፡ መላትሒሆሙ ፡ ከመ ፡ ኢይቅረቡ ፡ ኀቤከ ።"),
    (31, 10, "ብዙኅ ፡ መቅሠፍቶሙ ፡ ለኃጥኣን ፤ ወእለሰ ፡ ይትዌከሉ ፡ በእግዚአብሔር ፡ ሣህል ፡ ይሜግቦሙ ።"),
    (31, 11, "ተፈሥሑ ፡ በእግዚአብሔር ፡ ወተሐሠዩ ፡ ጻድቃኑ ፤ ወተመክሑ ፡ ኵልክሙ ፡ ርቱዓነ ፡ ልብ ።"),
    (32, 1, "መዝሙር ፡ ዘዳዊት ። ተፈሥሑ ፡ ጻድቃን ፡ በእግዚአብሔር ፤ ወለራትዓን ፡ ይደልዎሙ ፡ ክብር ።"),
    (32, 2, "ግነዩ ፡ ለእግዚአብሔር ፡ በመሰንቆ ፤ ወበመዝሙር ፡ ዘዐሠርቱ ፡ አውታሪሁ ፡ ዘምሩ ፡ ሎቱ ።"),
    (32, 3, "ወሰብሐዎ ፡ ስብሐተ ፡ ሐዲሰ ፤ ሠናየ ፡ ዘምሩ ፡ ወየብቡ ፡ ሎቱ ።"),
    (32, 4, "እስመ ፡ ጽድቅ ፡ ቃሉ ፡ ለእግዚአብሔር ፤ ውኵሉ ፡ ግብሩ ፡ በሀይማኖት ።"),
    (32, 5, "ያፈቅር ፡ እግዚአብሔር ፡ ጽድቀ ፡ ወምጽዋተ ፤ ሣህሉ ፡ ለእግዚአብሔር ፡ መልአ ፡ ምድረ ።"),
    (32, 6, "ወበቃለ ፡ እግዚአብሔር ፡ ጸንዓ ፡ ሰማያት ፤ ወበእስትንፋሰ ፡ አፉሁ ፡ ኵሉ ፡ ኀይሎሙ ።"),
    (32, 7, "ዘያስተጋብኦ ፡ ከመ ፡ ዝቅ ፡ ለማየ ፡ ባሕር ፤ ወይሠይሞሙ ፡ ውስተ ፡ መዛግብተ ፡ ቀላያት ።"),
    (32, 8, "ትፍርሆ ፡ ለእግዚአብሔር ፡ ኵላ ፡ ምድር ፤ ወእምኔሁ ፡ ይደንግፁ ፡ ኵሎሙ ፡ እለ ፡ ይነብሩ ፡ ውስተ ፡ ዓለም ።"),
    (32, 9, "እስመ ፡ ውእቱ ፡ ይቤ ፡ ወኮኑ ፤ ወውእቱ ፡ አዘዘ ፡ ወተፈጥሩ ።"),
    (32, 10, "እግዚአብሔር ፡ ይመይጥ ፡ ምክሮሙ ፡ ለአሕዛብ ፤ ወይመይጥ ፡ ሕሊናሆሙ ፡ ለሕዝብ ፤ ወያረስዖሙ ፡ ምክሮሙ ፡ ለመላእክት ።"),
    (32, 11, "ወምክሩሰ ፡ ለእግዚአብሔር ፡ ይሄሉ ፡ ለዓለም ፤ ወሕሊና ፡ ልቡኒ ፡ ለትውልደ ፡ ትውልድ ።"),
    (32, 12, "ብፁዕ ፡ ሕዝብ ፡ ዘእግዚአብሔር ፡ አምላኩ ፤ ሕዝብ ፡ ዘኀረየ ፡ ሎቱ ፡ ለርስቱ ።"),
    (32, 13, "እምሰማይ ፡ ሐወጸ ፡ እግዚአብሔር ፤ ወርእየ ፡ ኵሎ ፡ ደቂቀ ፡ እጓለ ፡ እምሕያው ።"),
    (32, 14, "ወእምድልው ፡ ጽርሐ ፡ መቅደሱ ፤ ወርእየ ፡ ላዕለ ፡ ኵሎሙ ፡ እለ ፡ ኅዱራን ፡ ዲበ ፡ ምድር ።"),
    (32, 15, "ዘውእቱ ፡ ባሕቲቱ ፡ ፈጠረ ፡ ልኮሙ ፤ ዘያአምር ፡ ኵሎ ፡ ምግባሮሙ ።"),
    (32, 16, "ኢይድኅን ፡ ንጉሥ ፡ በብዝኀ ፡ ሰራዊቱ ፤ ወያርብኅኒ ፡ ኢደኅነ ፡ በብዙኀ ፡ ኀይሉ ።"),
    (32, 17, "ወፈረስኒ ፡ ሐሳዊ ፡ ኢያድኅን ፤ ወኢያመስጥ ፡ በብዝኀ ፡ ጽንዑ ።"),
    (32, 18, "ናሁ ፡ አዕይንቲሁ ፡ ለእግዚአብሔር ፡ ኀበ ፡ እለ ፡ ይፈርህዎ ፤ ወእለሰ ፡ ይትዌከሉ ፡ በምሕረቱ ።"),
    (32, 19, "ያድኅና ፡ እሞት ፡ ለነፍሶሙ ፤ ወይሴስዮሙ ፡ አመ ፡ ረኃብ ።"),
    (32, 20, "ነፍስነሰ ፡ ትሴፈዎ ፡ ለእግዚአብሔር ፤ እስመ ፡ ረዳኢነ ፡ ወምስካይነ ፡ ውእቱ ።"),
    (32, 21, "እስመ ፡ ቦቱ ፡ ይትፌሣሕ ፡ ልብነ ፤ ወተወከልነ ፡ በስሙ ፡ ቅዱስ ።"),
    (32, 22, "ለትኩን ፡ እግዚኦ ፡ ምሕረትከ ፡ ላዕሌነ ፤ በከመ ፡ ላዕሌከ ፡ ተወከልነ ።"),
    (33, 1, "መዝሙር ፡ ዘዳዊት ፤ ዘአመ ፡ በዐደ ፡ ገጾ ፡ እምቅድሜሁ ፡ ለአቢሜሌክ ።"),
    (33, 2, "እባርኮ ፡ ለእግዚአብሔር ፡ በኵሉ ፡ ጊዜ ፤ ወዘልፈ ፡ ስብሓቲሁ ፡ ውስተ ፡ አፉየ ።"),
    (33, 3, "በእግዚአብሔር ፡ ትከብር ፡ ነፍስየ ፤ ይስምዑ ፡ የዋሃን ፡ ወይትፈሥሑ ።"),
    (33, 4, "አዕብይዎ ፡ ለእግዚአብሔር ፡ ምስሌየ ፤ ወናልዕል ፡ ስሞ ፡ ኅቡረ ።"),
    (33, 5, "ኀሠሥክዎ ፡ ለእግዚአብሔር ፡ ወተሠጥወኒ ፤ ወእምኵሉ ፡ ምንዳቤየ ፡ አድኀነኒ ።"),
    (33, 6, "ቅረቡ ፡ ኀቤሁ ፡ ወያበርህ ፡ ለክሙ ፤ ወኢይትኀፈር ፡ ገጽክሙ ።"),
    (33, 7, "ዝንቱ ፡ ነዳይ ፡ ጸርኀ ፡ ወእግዚአብሔር ፡ ሰምዖ ፤ ወእምኵሉ ፡ ምንዳቤሁ ፡ አድኀኖ ።"),
    (33, 8, "ይትዐየን ፡ መልአከ ፡ እግዚአብሔር ፡ ዐውዶሙ ፡ ለእለ ፡ ይፈርህዎ ፡ ወያድኅኖሙ ።"),
    (33, 9, "ጠዐሙ ፡ ወታእምሩ ፡ ከመ ፡ ኄር ፡ እግዚአብሔር ፤ ብፁዕ ፡ ብእሲ ፡ ዘተወከለ ፡ ቦቱ ።"),
    (33, 10, "ፍርህዎ ፡ ለእግዚአብሔር ፡ ኵልክሙ ፡ ቅዱሳኑ ፤ እስመ ፡ አልቦሙ ፡ ተፅናሰ ፡ ለእለ ፡ ይፈርህዎ ።"),
    (33, 11, "ብዑላንሰ ፡ ነድዩ ፡ ወርኅቡ ፤ ወእለሰ ፡ ይኀሥዎ ፡ ለእግዚአብሔር ፡ ኢተጸነሱ ፡ እምኵሎ ፡ ሠናይ ።"),
    (33, 12, "ንዑ ፡ ደቂቅየ ፡ ወስምዑኒ ፤ ፈሪሀ ፡ እግዚአብሔር ፡ እምህርክሙ ።"),
    (33, 13, "መኑ ፡ ውእቱ ፡ ብእሲ ፡ ዘይፈቅዱ ፡ ሐይወ ፤ ወያፍቅር ፡ ይርእይ ፡ መዋዕለ ፡ ሠናያተ ።"),
    (33, 14, "ክላእ ፡ ልሳነከ ፡ እምእኩይ ፤ ወከናፍሪከኒ ፡ ከመ ፡ ኢይንብባ ፡ ጕሕሉተ ።"),
    (33, 15, "ተገሐሥ ፡ እምእኩይ ፡ ወግበር ፡ ሠናየ ፤ ኅሥሣ ፡ ለሰላም ፡ ወዴግና ።"),
    (33, 16, "እስመ ፡ አዕይንቲሁ ፡ ለእግዚአብሔር ፡ ኀበ ፡ ጻድቃኑ ፤ ወእዝኑሂ ፡ ኀበ ፡ ስእለቶሙ ።"),
    (33, 17, "ገጹ ፡ ለእግዚአብሔር ፡ ኀበ ፡ እለ ፡ ይገብሩ ፡ እኩየ ፤ ከመ ፡ ይሠረው ፡ እምድር ፡ ዝክሮሙ ።"),
    (33, 18, "ጸርኁ ፡ ጻድቃን ፡ ወእግዚአብሔር ፡ ሰምዖሙ ፤ ወእምኵሉ ፡ ምንዳቤሆሙ ፡ አድኀኖሙ ።"),
    (33, 19, "ቅሩብ ፡ እግዚአብሔር ፡ ለየዋሃነ ፡ ልብ ፤ ወያድኅኖሙ ፡ ለትሑታነ ፡ መንፈስ ።"),
    (33, 20, "ብዙኅ ፡ ሕማሞሙ ፡ ለጻድቃን ፤ ወእምኵሉ ፡ ያድኅኖሙ ፡ እግዚአብሔር ።"),
    (33, 21, "እግዚአብሔር ፡ የዐቅብ ፡ ኵሎ ፡ አዕጽምቲሆሙ ፤ ወኢይትቀጠቀጥ ፡ አሐዱ ፡ እምውስቴቶሙ ።"),
    (33, 22, "ሞቱ ፡ ለኃጥእ ፡ ፀዋግ ፤ ወእለሰ ፡ ይጸልእዎ ፡ ለጻድቅ ፡ ይኔስሑ ።"),
    (33, 23, "ይቤዙ ፡ እግዚአብሔር ፡ ነፍሰ ፡ አግብርቲሁ ፤ ወኢይኔስሑ ፡ ኵሎሙ ፡ እለ ፡ ይትዌከሉ ፡ ቦቱ ።"),
    (34, 1, "መዝሙር ፡ ዘዳዊት ። ግፍዖሙ ፡ እግዚኦ ፡ ለእለ ፡ ይገፍዑኒ ፤ ፅብኦሙ ፡ እግዚኦ ፡ ለእለ ፡ ይፀብኡኒ ።"),
    (34, 2, "ንሥእ ፡ ወልታ ፡ ወኲናተ ፤ ወተንሥእ ፡ ውስተ ፡ ረዲኦትየ ።"),
    (34, 3, "ምላኅ ፡ ሰይፈከ ፡ ወዕግቶሙ ፡ ለእለ ፡ ሮዱኒ ፤ በላ ፡ ለነፍስየ ፡ አነ ፡ ውእቱ ፡ ረዳኢኪ ።"),
    (34, 4, "ለይትኀፈሩ ፡ ወይኅሰሩ ፡ ኵሎሙ ፡ እለ ፡ የኀሥዋ ፡ ለነፍስየ ፤ ለይግብኡ ፡ ድኅሬሆሙ ፡ ወይትኀፈሩ ፡ እለ ፡ መከሩ ፡ እኩየ ፡ ላዕሌየ ።"),
    (34, 5, "ለይኩኑ ፡ ከመ ፡ ጸበል ፡ ዘቅድመ ፡ ገጸ ፡ ነፋስ ፤ ወመልአከ ፡ እግዚአብሔር ፡ ለይሣቅዮሙ ።"),
    (34, 6, "ለትኩን ፡ ፍኖቶሙ ፡ ዳኅፀ ፡ ወጽልመተ ፤ ወመልአከ ፡ እግዚአብሔር ፡ ለይስድዶሙ ።"),
    (34, 7, "እስመ ፡ በከንቱ ፡ ኀብኡ ፡ ሊተ ፡ መሥገርተ ፡ ያጥፍኡኒ ፤ ወበከንቱ ፡ አምንዘዝዋ ፡ ለነፍስየ ።"),
    (34, 8, "ለትምጽኦሙ ፡ መሥገርት ፡ እንተ ፡ ኢያእመሩ ። ወተአኅዞሙ ፡ መሥገርት ፡ እንተ ፡ ኀብኡ ፤ ወይደቁ ፡ ውስተ ፡ ይእቲ ፡ መሥገርት ።"),
    (34, 9, "ወነፍስየሰ ፡ ትትፌሣሕ ፡ በእግዚአብሔር ፤ ወትትሐሠይ ፡ በአድኅኖቱ ።"),
    (34, 10, "ኵሉ ፡ አዕጽምትየ ፡ ይብሉከ ፤ እግዚኦ ፡ መኑ ፡ ከማከ ፡ ታድኅኖ ፡ ለነዳይ ፡ እምእደ ፡ ዘይትዔገሎ ፤ ለነዳይ ፡ ወለምስኪን ፡ እምእደ ፡ ዘይመስጦ ።"),
    (34, 11, "ተንሥኡ ፡ ላዕሌየ ፡ ሰማዕተ ፡ ዐመፃ ፤ ወዘኢያአምር ፡ ነበቡ ፡ ላዕሌየ ።"),
    (34, 12, "ፈደዩኒ ፡ እኪተ ፡ ህየንተ ፡ ሠናይት ፤ ወአኅጥእዋ ፡ ውሉደ ፡ ለነፍስየ ።"),
    (34, 13, "ወአንሰ ፡ ሶበ ፡ አስርሑኒ ፡ ለበስኩ ፡ ሠቀ ፡ ወአሕመምክዋ ፡ በጾም ፡ ለነፍስየ፤ ወጸሎትየኒ ፡ ገብአ ፡ ውስተ ፡ ሕፅንየ ።"),
    (34, 14, "ከመ ፡ ዘለአኀውየ ፡ ወለቢጽየ ፡ ከማሁ ፡ አድሎኩ ፤ ከመ ፡ ዘይላሑ ፡ ወይቴክዝ ፡ ከማሁ ፡ አትሐትኩ ፡ ርእስየ ።"),
    (34, 15, "ተጋብኡ ፡ ላዕሌየ ፡ ወተፈሥሑ ፤ ተማከሩ ፡ ይቅሥፉኒ ፡ ወኢያእመርኩ ።"),
    (34, 16, "ተሰብሩሂ ፡ ወኢደንገፁ ። ፈተኑኒ ፡ ወተሳለቁ ፡ ላዕሌየ ፡ ወሠሐቁኒ ፤ ወሐቀዩ ፡ ስነኒሆሙ ፡ ላዕሌየ ።"),
    (34, 17, "እግዚኦ ፡ ማእዜኑ ፡ ትፈትሕ ፡ ሊተ ። አድኅና ፡ ለነፍስየ ፡ እምእከየ ፡ ምግባሮሙ ፤ ወእምአናብስት ፡ ለብሕቱትየ ።"),
    (34, 18, "እገኒ ፡ ለከ ፡ እግዚኦ ፡ በውስተ ፡ ማኅበር ፡ ዐቢይ ፤ ወእሴብሐከ ፡ በውስተ ፡ ሕዝብ ፡ ክቡድ ፡"),
    (34, 19, "ወኢይትፌሥሑ ፡ ላዕሌየ ፡ እለ ፡ ይጸልኡኒ ፡ በዐመፃ ፤ እለ ፡ ይፃረሩኒ ፡ በከንቱ ፡ ወይትቃጸቡኒ ፡ በአዕይንቲሆሙ ።"),
    (34, 20, "እስመ ፡ ሊተሰ ፡ ሰላመ ፡ ይትናገሩኒ ፤ ወይመክሩ ፡ በቍፅር ፡ ያመንስዉኒ ።"),
    (34, 21, "ወአብቀዉ ፡ አፉሆሙ ፡ ላዕሌየ ፤ ወይቤሉ ፡ እንቋዕ ፡ እንቋዕ ፤ ርኢናሁ ፡ በአዕይንቲነ ።"),
    (34, 22, "ርኢ ፡ እግዚኦ ፡ ወኢታርምም ፤ እግዚኦ ፡ ኢትርሐቅ ፡ እምኔየ ።"),
    (34, 23, "ተንሥእ ፡ እግዚኦ ፡ አፅምእ ፡ ፍትሕየ ፤ አምላኪየ ፡ ወእግዚእየ ፡ ውስተ ፡ ቅሥትየ ።"),
    (34, 24, "ፍታሕ ፡ ሊተ ፡ እግዚኦ ፡ አምላኪየ ፡ በከመ ፡ ጽድቅከ ፤ ወኢይትፌሥሑ ፡ ላእሌየ ።"),
    (34, 25, "ወኢይበሉ ፡ በልቦሙ ፡ እንቋዕ ፡ እንቋዕ ፡ ላዕለ ፡ ነፍስየ ፤ ወኢይበሉ ፡ ውኅጥናሁ ።"),
    (34, 26, "ለይትኀፈሩ ፡ ወይኅሰሩ ፡ እለ ፡ ይትፌሥሑ ፡ በሕማምየ ፤ ወይልበሱ ፡ ኀፍረተ ፡ ወኀሳረ ፡ እለ ፡ ያዐብዩ ፡ አፉሆሙ ፡ ላዕሌየ ።"),
    (34, 27, "ለይትፌሥሑ ፡ ወይትሐሠዩ ፡ እለ ፡ ይፈቅድዋ ፡ ለጽድቅየ ፤ ወይበሉ ፡ በኵሉ ፡ ጊዜ ፡ ዐቢይ ፡ እግዚአብሔር ፡ እለ ፡ ይፈቅዱ ፡ ሰላመ ፡ ገብርከ ።"),
    (34, 28, "ልሳንየ ፡ ያነብብ ፡ ጽድቀከ ፤ ወኵሎ ፡ አሚረ ፡ ስብሐቲከ ።"),
    (35, 1, "ፍጻሜ ፡ ዘገብረ ፡ እግዚአብሔር ፤ መዝሙር ፡ ዘዳዊት ።"),
    (35, 2, "ይነብብ ፡ ኃጥእ ፡ በዘ ፡ ያስሕት ፡ ርእሶ ፤ ወአልቦ ፡ ፍርሀተ ፡ እግዚአብሔር ፡ ቅድመ ፡ አዕይንቲሁ ።"),
    (35, 3, "እስመ ፡ ጸልሐወ ፡ በልሳኑ ፤ ሶበ ፡ ትረክቦ ፡ ኀጢአቱ ፡ ይጸልኦ ።"),
    (35, 4, "ቃለ ፡ አፉሁ ፡ ዐመፃ ፡ ወጕሕሉት ፤ ወኢፈቀደ ፡ ይለቡ ፡ ከመ ፡ ያሠኒ ።"),
    (35, 5, "ወሐለየ ፡ ዐመፃ ፡ በውስተ ፡ ምስካቡ ፤ ወቆመ ፡ በፍኖት ፡ እንተ ፡ በኵሉ ፡ ኢኮነት ፡ ሠናይተ ፡ ወኢተሀከያ ፡ ለእኪት ።"),
    (35, 6, "እግዚኦ ፡ በሰማይ ፡ ሣህልከ ፤ ወጽድቅከኒ ፡ እስከ ፡ ደመናት ።"),
    (35, 7, "ወርትዕከኒ ፡ ከመ ፡ አድባረ ፡ እግዚአብሔር ፤ ኵነኔከ ፡ ዕሙቅ ፡ ጥቀ ፤ ሰብአ ፡ ወእንስሳ ፡ ታድኅን ፡ እግዚኦ ።"),
    (35, 8, "በከመ ፡ አብዛኅከ ፡ ምሕረተከ ፡ እግዚኦ ፤ ደቂቀ ፡ እጓለ ፡ እመሕያው ፡ ይትዌከሉ ፡ በታሕተ ፡ ክነፊከ ።"),
    (35, 9, "ወይረውዩ ፡ እምጠለ ፡ ቤትከ ፤ ወትሰቅዮሙ ፡ ፈለገ ፡ ትፍሥሕትከ ።"),
    (35, 10, "እስመ ፡ እምኀቤከ ፡ ነቅዐ ፡ ሕይወት ፤ በብርሃንከ ፡ ንሬኢ ፡ ብርሃነ ።"),
    (35, 11, "ስፋሕ ፡ ምሕረተከ ፡ እግዚኦ ፡ ላዕለ ፡ እለ ፡ ያአምሩከ ፤ ወጽድቀከኒ ፡ ለርቱዓነ ፡ ልብ ።"),
    (35, 12, "ኢይምጽአኒ ፡ እግረ ፡ ትዕቢት ፤ ወእደ ፡ ኃጥእ ፡ ኢይሁከኒ ።"),
    (35, 13, "ህየ ፡ ወድቁ ፡ ኵሎሙ ፡ ገበርተ ፡ ዐመፃ ፤ ይሰደዱ ፡ ወኢይክሉ ፡ ቀዊመ ።"),
    (36, 1, "መዝሙር ፡ ዘዳዊት ። ኢትቅናእ ፡ ላዕለ ፡ እኩያን ፤ ወኢትቅናእ ፡ ላዕለ ፡ ገበርተ ፡ ዐመፃ ።"),
    (36, 2, "እስመ ፡ ከመ ፡ ሣዕር ፡ ፍጡነ ፡ ይየብሱ ፤ ወከመ ፡ ኀመልማል ፡ ኀምል ፡ ፍጡነ ፡ ይወድቁ ።"),
    (36, 3, "ተወከል ፡ በእግዚአብሔር ፡ ወግበር ፡ ሠናየ ፤ ወያኀድረከ ፡ ዲበ ፡ ምድር ፡ ወይሬዕየከ ፡ ዲበ ፡ ብዕላ ።"),
    (36, 4, "ተፈሣሕ ፡ በእግዚአብሔር ፡ ወይሁበከ ፡ ስእለተ ፡ ልብከ ።"),
    (36, 5, "ክሥት ፡ ለእግዚአብሔር ፡ ፍኖተከ ፤ ወተወከል ፡ ቦቱ ፡ ወውእቱ ፡ ይገብር ፡ ለከ ።"),
    (36, 6, "ወያመጽኣ ፡ ከመ ፡ ብርሃን ፡ ለጽድቅከ ፤ ወፍትሕከኒ ፡ ከመ ፡ መዐልት ። ግነይ ፡ ለእግዚአብሔር ፡ ወተፀመዶ ፤"),
    (36, 7, "ወኢትቅናእ ፡ ላዕለ ፡ ዘይዴሎ ፡ በሕይወቱ ፤ ላዕለ፡ ሰብእ ፡ ዘይገብር ፡ ዐመፃ ።"),
    (36, 8, "ኅድጋ ፡ ለመዐት ፡ ወግድፋ ፡ ለቍጥዓ ፤ ወኢትቅናእ ፡ ከመ ፡ ታሕሥም ።"),
    (36, 9, "እስመ ፡ እለ ፡ ያሕሥሙ ፡ ይሤረዉ ፤ ወእለሰ ፡ ይትዔገሥዎ ፡ ለእግዚአብሔር ፡ እሙንቱ ፡ ይወርስዋ ፡ ለምድር ፤"),
    (36, 10, "ወዓዲ ፡ ኅዳጠ ፡ ወኢይሄሉ ፡ እንከ ፡ ኃጥእ ፤ ተኀሥሥ ፡ ወኢትረክብ ፡ መካኖ ።"),
    (36, 11, "ወየዋሃንሰ ፡ ይወርስዋ ፡ ለምድር ፤ ወይትፌሥሑ ፡ በብዙኅ ፡ ሰላም ።"),
    (36, 12, "ያስትሐይጾ ፡ ኃጥእ ፡ ለጻድቅ ፡ ወየሐቂ ፡ ስነኒሁ ፡ ላዕሌሁ ።"),
    (36, 13, "ወእግዚአብሔርሰ ፡ ይስሕቆ ። እስመ፡ ያቀድም ፡ አእምሮ ፡ ከመ ፡ በጽሐ ፡ ዕለቱ ።"),
    (36, 14, "ሰይፎሙ ፡ መልኁ ፡ ኃጥኣን ፡ ወወሰቁ ፡ ቀስቶሙ ፤ ከመ ፡ ይቅትልዎ ፡ ለነዳይ ፡ ወለምስኪን ፡ ወከመ ፡ ይርግዝዎሙ ፡ ለርቱዓነ ፡ ልብ ።"),
    (36, 15, "ሰይፎሙ ፡ ይባእ ፡ ውስተ ፡ ልቦሙ ፤ ወይትቀጥቀጥ ፡ አቅስቲሆሙ ።"),
    (36, 16, "ይኄይስ ፡ ኅዳጥ ፡ ዘበጽድቅ ፤ እምብዙኅ ፡ ብዕለ ፡ ኃጥኣን ።"),
    (36, 17, "እስመ ፡ ይትቀጠቀጥ ፡ ኀይሎሙ ፡ ለኃጥኣን ፤ ያጸንዖሙ ፡ እግዚአብሔር ፡ ለጻድቃን ።"),
    (36, 18, "ወያአምር ፡ እግዚአብሔር ፡ ፍኖተ ፡ ንጹሓን ፤ ወለዓለም ፡ ውእቱ ፡ ርስቶሙ ።"),
    (36, 19, "ወኢይትኀፈሩ ፡ በመዋዕለ ፡ እኩያት ፤ ወይጸግቡ ፡ በመዋዕለ ፡ ረኃብ ።"),
    (36, 20, "ወኃጥኣንሰ ፡ ይትሐጐሉ ፡ ወጸላእቱሰ ፡ ለእግዚአብሔር ፡ ሶበ ፡ ከብሩ ፡ ወተለዐሉ ፤ የኀልቁ ፡ ወይጠፍኡ ፡ ከመ ፡ ጢስ ።"),
    (36, 22, "ይትሌቃሕ ፡ ኃጥእ ፡ ወኢይፈዲ ፡ ወጻድቅሰ ፡ ይምሕር ፡ ወይሁብ ።"),
    (36, 24, "እስመ ፡ እለ ፡ ይባርክዎ ፡ ይወርስዋ ፡ ለምድር ፤ ወእለሰ ፡ ይረግምዎ ፡ ይሤረዉ ።"),
    (36, 25, "እምኀበ ፡ እግዚአብሔር ፡ ይጸንዕ ፡ ሑረቱ ፡ ለሰብእ ፤ ለዘይፈቅድ ፡ ፍኖቶ ፡ ፈድፋደ ።"),
    (36, 24, "እመኒ ፡ ወድቀ ፡ ኢይደነግፅ ፤ እስመ ፡ እግዚአብሔር ፡ ይሰውቆ ፡ እዴሁ ።"),
    (36, 25, "ወርዘውኩሂ ፡ ወረሳእኩ ፤ ወጻድቅሰ ፡ ዘይትገደፍ ፡ ኢርኢኩ ፤ ወዘርዑኒ ፡ ኢይጼነስ ፡ እክለ ።"),
    (36, 26, "ወኵሎ ፡ አሚረ ፡ ይምሕር ፡ ወይሌቅሕ ፤ ወዘርዑሂ ፡ ውስተ ፡ በረከት ፡ ይሄሉ ።"),
    (36, 27, "ተገሕስ ፡ እምእኩይ ፡ ወግበር ፡ ሠናየ ፤ ወትነብር ፡ ለዓለመ ፡ ዓለም ።"),
    (36, 28, "እስመ ፡ ጽድቀ ፡ ያፈቅር ፡ እግዚአብሔር ፡ ወኢይገድፎሙ ፡ ለጻድቃን ፤ ወለዓለም ፡ የዐቅቦሙ ፤ ወይትቤቀሎሙ ፡ ለንጹሓን ፤ ወይሤሩ ፡ ዘርዖሙ ፡ ለኃጥኣን ።"),
    (36, 29, "ወጻድቃንሰ ፡ ይወርስዋ ፡ ለምድር ፤ ወይነብሩ ፡ ውስቴታ ፡ ለዓለመ ፡ ዓለም ።"),
    (36, 30, "አፉሁ ፡ ለጻድቅ ፡ ይትሜሀር ፡ ጥበበ ፤ ወልሳኑ ፡ ይነብብ ፡ ጽድቀ ።"),
    (36, 31, "ሕገ ፡ አምላኩ ፡ ውስተ ፡ ልቡ ፤ ወኢይድኅፅ ፡ ሰኰናሁ ።"),
    (36, 32, "ያስተሓይጾ ፡ ኃጥእ ፡ ለጻድቅ ፤ ወይፈቅድ ፡ ይቅትሎ ።"),
    (36, 33, "ወኢየኀድጎ ፡ እግዚአብሔር ፡ ውስተ ፡ እዴሁ ፤ ወኢይመውኦ ፡ ሶበ ፡ ይትዋቀሡ ።"),
    (36, 34, "ተዐገሶ ፡ ለእግዚአብሔር ፡ ወዕቀብ ፡ ፍኖቶ ፡ ወያዐብየከ ፡ ከመ ፡ ትረሳ ፡ ለምድር ፤ ወትሬኢ ፡ ከመ ፡ ይሠረዉ ፡ ኃጥኣን ።"),
    (36, 35, "ርኢክዎ ፡ ለኃጥእ ፡ ዐቢየ ፤ ወተለዐለ ፡ ከመ ፡ አርዘ ፡ ሊባኖስ ።"),
    (36, 36, "ወሶበ ፡ እገብእ ፡ ኀጣእክዎ ፤ ኀሠሥኩ ፡ ወኢረከብኩ ፡ መካኖ ።"),
    (36, 37, "ዕቀብ ፡ የውሀተ ፡ ወትሬኢ ፡ ጽድቀ ፤ እስመ ፡ ቦቱ ፡ ተረፈ ፡ ብእሴ ፡ ሰላም ።"),
    (36, 38, "ወዐማፂያንሰ ፡ ይሤረዉ ፤ ወይሤረዉ ፡ ትራፋቲሆሙ ፡ ለኃጥኣን ።"),
    (36, 39, "መድኀኒቶሙ ፡ ለጻድቃን ፡ እምኀበ ፡ እግዚአብሔር ፤ ወቀዋሚሆሙ ፡ ውእቱ ፡ በጊዜ ፡ መንዳቤሆሙ ።"),
    (36, 40, "ይረድኦሙ ፡ እግዚአብሔር ፡ ወያድኅኖሙ ፤ ወያነግፎሙ ፡ እምእደ ፡ ኃጥኣን ፡ ወያድኅኖሙ ፤ እስመ ፡ ተወከሉ ፡ ቦቱ ።"),
    (37, 1, "መዝሙር ፡ ዘዳዊት ፡ ለተዝካረ ሰንበት ።"),
    (37, 2, "እግዚኦ ፡ በመዐትከ ፡ ኢትቅሥፈኒ ፤ ወበመቅሠፍትከ ፡ ኢትገሥጸኒ ።"),
    (37, 3, "እስመ ፡ አሕጻከ ፡ ደጐጻኒ ፤ ወአጽናዕከ ፡ እዴከ ፡ ላዕሌየ ።"),
    (37, 4, "ወአልቦ ፡ ፈውሰ ፡ ለሥጋየ ፡ እምገጸ ፡ መዐትከ ፤ ወአልቦ ፡ ሰላመ ፡ ለአዕጽምትየ ፡ እምገጸ ፡ ኀጢአትየ ።"),
    (37, 5, "እስመ ፡ ኖኀ ፡ እምሥዕርትየ ፡ ጌጋይየ ፤ ከመ ፡ ጾር ፡ ክብድ ፡ ከብደ ፡ ላዕሌየ ።"),
    (37, 6, "ጼአ ፡ ወባኍብኈ ፡ አዕጽምትየ ፡ እምገጸ ፡ እበድየ ።"),
    (37, 7, "ሐርተምኩ ፡ ወተቀጻዕኩ ፡ ለዝሉፉ ፤ ወኵሎ ፡ አሚረ ፡ ትኩዝየ ፡ ኣንሶሱ ።"),
    (37, 8, "እስመ ፡ ጸግበት ፡ ጽእለተ ፡ ነፍስየ ፤ ወኀጣእኩ ፡ ፈውሰ ፡ ለሥጋየ ።"),
    (37, 9, "ደወይኩ ፡ ወሐመምኩ ፡ ፈድፋደ ፤ ወእጐሥዕ ፡ እምሐዘነ ፡ ልብየ ።"),
    (37, 10, "በቅድሜከ ፡ ኵሉ ፡ ፍትወትየ ፤ ወገዓርየኒ ፡ ኢይትኀባእ ፡ እምኔከ ።"),
    (37, 11, "ልብየኒ ፡ ደንገፀኒ ፡ ወኀይልየኒ ፡ ኀደገኒ ፤ ወብርሃነ ፡ አዕይንትየኒ ፡ ለከወኒ ።"),
    (37, 12, "አዕርክትየኒ ፡ ወቢጽየኒ ፡ ዕድወ ፡ ኮኑኒ ፡ ሮዱኒ ፡ ወደበዩኒ ፤"),
    (
        37,
        13,
        "ወአዝማድየኒ ፡ ቀብፁኒ ፡ ወተናከሩኒ ። ወተኀየሉኒ ፡ እለ ፡ የኀሥሥዋ ፡ ለነፍስየ ፤ ወእለኒ ፡ ይፈቅዱ ፡ ሕማምየ ፡ ነበቡ ፡ ከንቶ ፤ ወኵሎ ፡ አሚረ ፡ ይመክሩ ፡ በቍፅር ፡ ያመነስዉኒ ።",
    ),
    (37, 14, "ወአንሰ ፡ ከመ ፡ ጽሙም ፡ ዘኢይሰምዕ ፤ ወከመ ፡ በሃም ፡ ዘኢይከሥት ፡ አፉሁ ።"),
    (37, 15, "ወኮንኩ ፡ ከመ ፡ ብእሲ ፡ ዘኢይሰምዕ ፤ ወከመ ፡ ዘኢይክል ፡ ተናግሮ ፡ በአፉሁ ።"),
    (37, 16, "እስመ ፡ ኪያከ ፡ ተወከልኩ ፡ እግዚኦ ፤ አንተ ፡ ስምዐኒ ፡ እግዚኦ ፡ አምላኪየ ።"),
    (37, 17, "እስመ ፡ እቤ ፡ ኢትረስየኒ ፡ ስላተ ፡ ጸላእየ ፤ ወእመኒ ፡ ድኅፀ ፡ ሰኰናየ ፡ ያዐብዩ ፡ አፉሆሙ ፡ ላዕሌየ ።"),
    (37, 18, "እስመ ፡ ሊተሰ ፡ አጽንሑኒ ፡ ይቅሥፉኒ ፤ ወቍስልየኒ ፡ ቅድሜየ ፡ ውእቱ ፡ በኵሉ ፡ ጊዜ ።"),
    (37, 19, "ወእነግር ፡ ጌጋይየ ፤ ወእቴክዝ ፡ በእንተ ፡ ኀጢአትየ ።"),
    (37, 20, "ጸላእትየሰ ፡ ሕያዋን ፡ ወይኄይሉኒ ፤ ወበዝኁ ፡ እለ ፡ በዐመፃ ፡ ይጸልኡኒ ።"),
    (37, 21, "እለ ፡ ይፈድዩኒ ፡ እኪተ ፡ ህየንተ ፡ ሠናይት ፡ ወያስተዋድዩኒ ፡ በተሊወ ፡ ጽድቅ ። ወገደፉ ፡ እኅዋሆሙ ፡ ከመ ፡ በድን ፡ ርኩስ ።"),
    (37, 22, "አንተ ፡ ኢትግድፈኒ ፡ እግዚኦ ፡ አምላኪየ ፡ ወኢትርሕቅ ፡ እምኔየ ።"),
    (37, 23, "ወነጽር ፡ ውስተ ፡ ረዱኦትየ ፤ እግዚኦ ፡ አምላከ ፡ መድኀኒትየ ።"),
    (38, 1, "ፍጻሜ ፡ ዘኢዶቱም ፡ ማኅሌት ፡ ዘዳዊት ።"),
    (38, 2, "እቤ ፡ አዐቅብ ፡ አፉየ ፡ ከመ ፡ ኢይስሐት ፡ በልሳንየ ፤ ወአንበርኩ ፡ ዐቃቤ ፡ ለአፉየ ፤ ሶበ ፡ ይትቃወሙኒ ፡ ኃጥኣን ፡ ቅድሜየ ።"),
    (38, 3, "ተጸመምኩ ፡ ወአትሐትኩ ፡ ርእስየ ፡ ወአርመምኩ ፡ ለሠናይ ፤ ወተሕደሰኒ ፡ ቍስልየ ።"),
    (38, 4, "ወሞቀኒ ፡ ልብየ ፡ በውስጤየ ፡ ወነደ ፡ እሳት ፡ እምአንብቦትየ ፤ ወእቤ ፡ በልሳንየ ።"),
    (38, 5, "ንግረኒ ፡ እግዚኦ ፡ ደኃሪትየ ፡ ምንት ፡ እማንቱ ፡ ኈልቆን ፡ ለመዋዕልየ ፡ ከመ ፡ ኣእምር ፡ ለምንት ፡ እዴኀር ፡ አነ ።"),
    (38, 6, "ናሁ ፡ ብሉያተ ፡ረሰይኮነ ፡ ለመዋዕልየ ፡ ወአካልየኒ ፡ ወኢከመ ፡ ምንት ፡ በቅድሜከ ፤ ወባሕቱ ፡ ከንቱ ፡ ኵሉ ፡ ደቂቀ ፡ እጓለ ፡ እመሕያው ።"),
    (38, 7, "ወከመ ፡ ጽላሎት ፡ ያንሶሱ ፡ ኵሉ ፡ ሰብእ ፡ ወባሕቱ ፡ ከንቶ ፡ ይትሀወኩ ፤ ይዘግቡ ፡ ወኢያአምሩ ፡ ለዘ ፡ ያስተጋብኡ ።"),
    (38, 8, "ወይእዜኒ ፡ መኑ ፡ ተስፋየ ፡ አኮኑ ፡ እግዚአብሔር ፤ ወትዕግስትየኒ ፡ እምኅቤከ ፡ ውእቱ ።"),
    (38, 9, "ወእምኵሉ ፡ ኀጢአትየ ፡ አድኅነኒ ፤ ወረሰይከኒ ፡ ጽእለተ ፡ ለአብዳን ።"),
    (38, 10, "ተጸመምኩ ፡ ወኢከሠትኩ ፡ አፉየ ፤ እስመ ፡ አንተ ፡ ፈጠርከኒ ።"),
    (38, 11, "አርሕቅ ፡ እምኔከ ፡ መቅሠፍተከ ፤ እስመ ፡ እምጽንዐ ፡ እዴከ ፡ ኀለቁ ፡ አነ ።"),
    (38, 12, "በተግሣጽከ ፡ በእንተ ፡ ኀጢአቱ ፡ ተዛለፍኮ ፡ ለሰብእ ፡ ወመሰውካ ፡ ከመ ፡ ሳሬት ፡ ለነፍሱ ፤ ወባሕቱ ፡ ከንቶ ፡ ይትሀወኩ ፡ ኵሉ ፡ ሰብእ ።"),
    (
        38,
        13,
        "ስምዐኒ ፡ እግዚኦ ፡ ጸሎትየ ፡ ወስእለትየ ፡ ወአፅምአኒ ፡ አንብዕየ ፡ ወኢትጸመመኒ ፤ እስመ ፡ ፈላሲ ፡ አነ ፡ ውስተ ፡ ምድር ፤ ወነግድ ፡ ከመ ፡ ኵሉ ፡ አበውየ ።",
    ),
    (38, 14, "ሥኅተኒ ፡ ከመ ፡ ኣዕርፍ ፤ ዘእንበለ ፡ እሖር ፡ ኀበ ፡ ኢይገብእ ።"),
    (39, 1, "ፍጻሜ ፡ መዝሙር ፡ ዘዳዊት ።"),
    (39, 2, "ጸኒሐ ፡ ጸናሕክዎ ፡ ለእግዚአብሔር ፤ ሰምዐኒ ፡ ወተመይጠኒ ፡ ወሰምዐኒ ፡ ቃለ ፡ ስእለትየ ።"),
    (39, 3, "ወአውፅአኒ ፡ እምዐዘቅተ ፡ ሕርትምና ፡ ወእምጽብረ ፡ ዐምዓም ፤ ወአቀሞኒ ፡ ውስተ ፡ ኰኵሕ ፡ ለእገርየ ፡ ወአጽንዖኒ ፡ ለመካይድየ ።"),
    (39, 4, "ወወደየ ፡ ውስተ ፡ አፉየ ፡ ስብሓተ ፡ ሐዲሰ ፡ ስብሓቲሁ ፡ ለአምላክነ ፤ ይርአዩ ፡ ብዙኃን ፡ ወይፍርሁ ፤ ወይትወከሉ ፡ በእግዚአብሔር ።"),
    (39, 5, "ብፁዕ ፡ ብእሲ ፡ ዘስመ ፡ እግዚአብሔር ፡ ትውክልቱ ፤ ወዘኢነጸረ ፡ ውስተ ፡ ከንቱ ፡ ውስተ ፡ መዐት ፡ ወሐሰት ።"),
    (39, 6, "ብዙኀ ፡ ገበርከ ፡ እግዚኦ ፡ አምላኪየ ፡ መንክረከ ፡ ወአልቦ ፡ ዘይመስሎ ፡ ለሕሊናከ ፤ አይደዕኩ ፡ ወነገርኩ ፡ ወበዝኃ ፡ እምኈልቍ ።"),
    (39, 7, "መሥዋዕተ ፡ ወቍርባነ ፡ ኢፈቀድከ ፡ ሥጋሰ ፡ አንጽሕ ፡ ሊተ ፤ መሥዋዕተ ፡ ዘበእንተ ፡ ኃጢአት ፡ ኢሠመርከ ።"),
    (39, 8, "ውእቱ ፡ ጊዜ ፡ እቤ ፡ ነየ ፡ መጻእኩ ፤ ውስተ ፡ ርእሰ ፡ መጽሐፍ ፡ ተጽሕፈ ፡ በእንቲአየ ።"),
    (39, 9, "ከመ ፡ እንግር ፡ ፈቃደከ ፡ መከርኩ ፡ አምላኪየ ፤ ወሕግከኒ ፡ በማእከለ ፡ ከርሥየ ።"),
    (39, 10, "ዜነውኩ ፡ ጽድቀ ፡ በማኅበር ፡ ዐቢይ ፡ ናሁ ፡ ኢከላእኩ ፡ ከናፍርየ ፤ እግዚኦ ፡ ለሊከ ፡ ታአምር ፡ ጽድቅየ ።"),
    (39, 11, "ኢኀባእኩ ፡ ውስተ ፡ ልብየ ፡ ርትዐከ ፤ ወነገርኩ ፡ አድኅኖተከ ፤ ወኢሰወርኩ ፡ ሣህለከ ፡ ወምሕረትከ ፡ እማኅበር ፡ ዐቢይ ።"),
    (39, 12, "አንተ ፡ እግዚኦ ፡ ኢታርሕቅ ፡ ሣህለከ ፡ እምኔየ ፤ ምሕረትከ ፡ ወጽድቅከ ፡ ዘልፈ ፡ ይርከባኒ ።"),
    (
        39,
        13,
        "እስመ ፡ ረከበተኒ ፡ እኪት ፡ እንተ ፡ አልባቲ ፡ ኈልቈ ፡ ወተራከባኒ ፡ ኃጣውእየ ፡ ወስእንኩ ፡ ነጽሮ ፤ ወበዝኃ ፡ እምሥዕርተ ፡ ርእስየ ፤ ልብየኒ ፡ ኀደገኒ ።",
    ),
    (39, 14, "ሥመር ፡ እግዚኦ ፡ ከመ ፡ ታድኅነኒ ፤ እግዚኦ ፡ ነጽር ፡ ውስተ ፡ ረዲኦትየ ።"),
    (39, 15, "ይትኀፈሩ ፡ ወይኅሰሩ ፡ ኅቡረ ፡ እለ ፡ ይፈቅዱ ፡ ያእትትዋ ፡ ለነፍስየ ፡ ለይግብኡ ፡ ድኅሬሆሙ ፡ ወይትኀፈሩ ፡ እለ ፡ ይፈቅዱ ፡ ሊተ ፡ እኩየ ።"),
    (39, 16, "ወይትፈደዩ ፡ በጊዜሃ ፡ ኀሳሮሙ ፤ እለ ፡ ይብሉኒ ፡ እንቋዕ ፡ እንቋዕ ።"),
    (
        39,
        17,
        "ለይትፈሥሑ ፡ ወይትሐሰዩ ፡ ብከ ፡ ኵሎሙ ፡ እለ ፡ የኀሡከ ፡ እግዚኦ ። ወይበሉ ፡ ዘልፈ ፡ ዐቢይ ፡ እግዚአብሔር ፤ እለ ፡ ይፈቅዱ ፡ አድኀኖተከ ፡ በኵሉ ፡ ጊዜ ።",
    ),
    (39, 18, "አንሰ ፡ ነዳይ ፡ ወምስኪን ፡ አነ ፡ ወእግዚአብሔር ፡ ይሔሊ ፡ ሊተ ፤ ረዳእየ ፡ ወመድኀንየ ፡ አንተ ፡ አምላኪየ ፡ ወኢትጐንዲ ።"),
    (40, 1, "ፍጻሜ ፡ መዝሙር ፡ ዘዳዊት ።"),
    (40, 2, "ብፁዕ ፡ ዘይሌቡ ፡ ላዕለ ፡ ነዳይ ፡ ወምስኪን ፤ እምዕለት ፡ እኪተ ፡ ያድኅኖ ፡ እግዚአብሔር ።"),
    (40, 3, "እግዚአብሔር ፡ ያዐቅቦ ፡ ወያሐይዎ ፡ ወያበጽዖ ፡ ዲበ ፡ ምድር ፤ ወኢያገብኦ ፡ ውስተ ፡ እደ ፡ ጸላኢሁ ።"),
    (40, 4, "እግዚአብሔር ፡ ይረድኦ ፡ ውስተ ፡ ዐራተ ፡ ሕማሙ ፤ ወይመይጥ ፡ ሎቱ ፡ ኵሎ ፡ ምስካቤሁ ፡ እምደዌሁ ።"),
    (40, 5, "አንሰ ፡ እቤ ፡ እግዚኦ ፡ ተሣሀለኒ ፤ ወስረይ ፡ ላቲ ፡ ለነፍስየ ፡ እስመ ፡ አበስኩ ፡ ለከ ።"),
    (40, 6, "ጸላእትየሰ ፡ እኩየ ፡ ይቤሉ ፡ ላዕሌየ ፤ ማእዜ ፡ ይመውት ፡ ወይሰዐር ፡ ስሙ ።"),
    (40, 7, "ወይባእ ፡ ወይርአይ ፡ ዘከንቶ ፡ ይነብብ ፡ ልቡ ፡ አስተጋብአ ፡ ኃጢአተ ፡ ላዕሌሁ ፤ ይወፅእ ፡ አፍአ ፡ ወይትናገር ።"),
    (40, 8, "ወየኀብር ፡ ላዕሌየ ፡ ወይትቃጸቡኒ ፡ ኵሎሙ ፡ ጸላእትየ ፤ ወይመክሩ ፡ እኩየ ፡ ላዕሌየ ፤"),
    (40, 9, "ነገረ ፡ ጌጋየ ፡ አውፅኡ ፡ ላዕሌየ ፤ ዘኖመሰ ፡ ኢይነቅህኑ ፡ እንከ ።"),
    (40, 10, "ብእሴ ፡ ሰላምየ ፡ ዘኪያሁ ፡ እትአመን ፡ ዘይሴስይ ፡ እክልየ ፤ አንሥአ ፡ ሰኰናሁ ፡ ላዕሌየ ።"),
    (40, 11, "እንተ ፡ እግዚኦ ፡ ተሣሀለኒ ፡ ወአንሥአኒ ፡ እፍድዮሙ ።"),
    (40, 12, "ወበእንተዝ ፡ አእመርኩ ፡ ከመ ፡ ሠመርከኒ ፤ ወኢተፈሥሑ ፡ ጸላእትየ ፡ ላዕሌየ ።"),
    (40, 13, "ወሊተሰ ፡ በእንተ ፡ የዋሀትየ ፡ ተወከፍከኒ ፤ ወአጽናዕከኒ ፡ ቅድሜከ ፡ ለዓለም ።"),
    (40, 14, "ይትባረክ ፡ እግዚአብሔር ፡ አምላከ ፡ እስራኤል ፡ እምይእዜ ፡ ወእስከ ፡ ለዓለም ፤ ለይኩን ፡ ለይኩን ።"),
    (41, 1, "መዝሙር ፡ ዘበአእምሮ ፡ ዘደቂቀ ፡ ቆሬ ።"),
    (41, 2, "ከመ ፡ ያፈቅር ፡ ኀየል ፡ ኀበ ፡ አንቅዕተ ፡ ማያት ፤ ከማሁ ፡ ታፈቅር ፡ ነፍስየ ፡ ኀበ ፡ እግዚአብሔር ።"),
    (41, 3, "ጸምአት ፡ ነፍስይ ፡ ኀበ ፡ አምላኪየ ፡ ሕያው ፤ ማእዜ ፡ እበጽሕ ፡ ወእሬኢ ፡ ገጾ ፡ ለአምላኪየ ።"),
    (
        41,
        4,
        "ሲሳየ ፡ ኮነኒ ፡ አንብዕየ ፡ መዐልተ ፡ ወሌሊተ ፤ እስመ ፡ ይብሉኒ ፡ ኵሎ ፡ አሚረ ፡ አይቴ ፡ ውእቱ ፡ አምላክከ ። ዘንተ ፡ ተዘኪርየ ፡ ተክዕወት ፡ ነፍስየ ፡ በላዕሌየ ፡ እስመ ፡ እበውእ ፡ ውስተ ፡ መካነ ፡ ማኅደረ ፡ ስብሐት ፡ ቤተ ፡ እግዚአብሔር ፤ በቃለ ፡ አሚን ፡ ወትፍሥሕት ፡ ደምፁ ፡ እለ ፡ ይገብሩ ፡ በዓለ ።",
    ),
    (41, 5, "ለምንት ፡ ትቴክዚ ፡ ነፍስየ ፡ ወለምንት ፡ ተሀውክኒ ፤ እመኒ ፡ በእግዚአብሔር ፡ ከመ ፡ እገኒ ፡ ሎቱ ፤ መድኀኔ ፡ ገጽየ ፡ አምላኪየ ።"),
    (41, 7, "ተሀውከት ፡ ነፍስየ ፡ በላዕሌየ ፤ በእንተዝ ፡ እዜከረከ ፡ እግዚኦ ፡ በምድረ ፡ ዮርዳኖስ ፡ በአርሞንኤም ፡ በደብር ፡ ንኡስ ።"),
    (41, 8, "ቀላይ ፡ ለቀላይ ፡ ትጼውዓ ፡ በቃለ ፡ አስራቢከ ፤ ኵሉ ፡ ማዕበልከ ፡ ወሞገድከ ፡ እንተ ፡ ላዕሌየ ፡ ኀለፈ ።"),
    (41, 9, "መዐልተ ፡ ይኤዝዝ ፡ እግዚአብሔር ፡ ሣህሎ ፡ ወሌሊተ ፡ ይነብር ፤ እምኀቤየ ፡ ብፅአተ ፡ ሕይወትየ ፡ ለእግዚአብሔር ።"),
    (41, 10, "እብሎ ፡ ለእግዚአብሔር ፡ አምላኪየ ፡ አንተ ፡ ለምንት ፡ ትረስዐኒ ፤ ለምንት ፡ ተኀድገኒ ፡ ወለምንት ፡ ትኩዝየ ፡ አንሶሱ ፡ ሶበ ፡ ያመነድቡኒ ፡ ፀርየ ።"),
    (41, 11, "ወያጸንጵዉኒ ፡ አዕጽምትየ ፡ ወይጼእሉኒ ፡ ኵሎሙ ፡ ጸላእትየ ፤ እስመ ፡ ይብሉኒ ፡ ኵሎ ፡ አሚረ ፡ አይቴ ፡ ውእቱ ፡ አምላክከ ።"),
    (41, 12, "ለምንት ፡ ትቴክዚ ፡ ነፍስየ ፡ ወለምንት ፡ ተሀውክኒ ፤ እመኒ ፡ በእግዚአብሔር ፡ ከመ ፡ እገኒ ፡ ሎቱ ፤ መድኀኔ ፡ ገጽየ ፡ አምላኪየ ።"),
    (42, 1, "መዝሙር ፡ ዘዳዊት ። ፍታሕ ፡ ሊተ ፡ እግዚኦ ፡ ወተበቀል ፡ በቀልየ ፡ እምሕዝብ ፡ ውፁኣን ፡ እምጽድቅ ፤ እምብእሲ ፡ ዐማፂ ፡ ወጽልሕው ፡ ባልሐኒ ፡"),
    (42, 2, "እስመ ፡ አንተ ፡ አምላኪየ ፡ ወኀይልየ ፡ ለምንት ፡ ተኀድገኒ ፤ ወለምንት ፡ ትኩዝየ ፡ ኣንሶሱ ፡ ሶበ ፡ ያመነድቡኒ ፡ ፀርየ ።"),
    (42, 3, "ፈኑ ፡ ብርሃነከ ፡ ወጽድቀከ ፡ እማንቱ ፡ ይምርሓኒ ፤ ወይስዳኒ ፡ ደብረ ፡ መቅደስከ ፡ ወውስተ ፡ አብያቲከ ፡ እግዚኦ ።"),
    (42, 4, "ወእበውእ ፡ ኀበ ፡ ምሥዋዒሁ ፡ ለእግዚአብሔር ፡ ኀበ ፡ አምላኪየ ፡ ዘአስተፈሥሓ ፡ ለውርዙትየ ፤"),
    (
        42,
        5,
        "እገኒ ፡ ለከ ፡ አምላኪየ ፡ በመሰንቆ ። ለምንት ፡ ትቴክዚ ፡ ነፍስየ ፡ ወለምንት ፡ ተሀውክኒ ፤ እመኒ ፡ በእግዚአብሔር ፡ ከመ ፡ እገኒ ፡ ሎቱ ፡ ወድኀኔ ፡ ገጽየ ፡ አምላኪየ ።",
    ),
    (43, 1, "ፍጻሜ ፡ ዘደቂቀ ፡ ቆሬ ፡ ዘበኣእምሮ ፡ መዝሙር ።"),
    (43, 2, "እግዚኦ ፡ ሰማዕነ ፡ በእዘኒነ ፡ ወአበዊነሂ ፡ ዜነዉነ ። ግብረ ፡ ዘገበርከ ፡ በመዋዕሊሆሙ ፡ በመዋዕለ ፡ ትካት ።"),
    (43, 3, "እዴከ ፡ ሠረወቶሙ ፡ ለፀር ፡ ወተከልከ ፡ ኪያሆሙ ፤ ሣቀይኮሙ ፡ ለአሕዛብ ፡ ወሰደድኮሙ ።"),
    (43, 4, "ዘአኮ ፡ በኲናቶሙ ፡ ወረስዋ ፡ ለምድር ፡ ወመዝራዕቶሙ ፡ ኢያድኀኖሙ ፤ ዘእንበለ ፡ የማንከ ፡ ወመዝራዕትከ ፡ ወብርሃነ ፡ ገጽከ ፡ እስመ ፡ ተሣሀልኮሙ ።"),
    (43, 5, "አንተ ፡ ውእቱ ፡ ንጉሥየ ፡ ወአምላኪየ ፤ ዘአዘዝከ ፡ መድኀኒቶ ፡ ለያዕቆብ ።"),
    (43, 6, "ብከ ፡ ንወግኦሙ ፡ ለኵሎሙ ፡ ፀርነ ፤ ወበስምከ ፡ ናኀስሮሙ ፡ ለእለ ፡ ቆሙ ፡ ላዕሌነ ።"),
    (43, 7, "ዘአኮ ፡ በቀስትየ ፡ እትአመን ፤ ወኲናትየኒ ፡ ኢይድኀነኒ ።"),
    (43, 8, "ወአድኀንከነ ፡ እምእለ ፡ ሮዱነ ፤ ወአስተኀፈርኮሙ ፡ ለኵሎሙ ፡ ጸላእትነ ።"),
    (43, 9, "በእግዚአብሔር ፡ ንከብር ፡ ኵሎ ፡ አሚረ ፤ ወለስምከ ፡ ንገኒ ፡ ለዓለም ።"),
    (43, 10, "ይእዜሰ ፡ ገደፍከነ ፡ ወአስተኀፈርከነ ፤ ወኢትወፅእ ፡ አምላክነ ፡ ምስለ ፡ ኀይልነ ፡"),
    (43, 11, "ወአግባእከነ ፡ ድኅሬነ ፡ ኀበ ፡ ፀርነ ፤ ወተማሰጡነ ፡ ጸላእትነ ።"),
    (43, 12, "ወወሀብከነ ፡ ይብልዑነ ፡ ከመ ፡ አባግዕ ፤ ወዘረውከነ ፡ ውስተ ፡ አሕዛብ ።"),
    (43, 13, "መጦከ ፡ ሕዝበከ ፡ ዘእንበለ ፡ ሤጥ ፤ ወአልቦ ፡ ብዝኀ ፡ ለይባቤነ ።"),
    (43, 14, "ረሰይከነ ፡ ጽእለተ ፡ ለጎርነ ፤ ሠሓቀ ፡ ወሥላቀ ፡ ለአድያሚነ ።"),
    (43, 15, "ወረሰይከነ ፡ አምሳለ ፡ ለአሕዛብ ፤ ወሑስተ ፡ ርእስ ፡ ለሕዝብ ።"),
    (43, 16, "ኵሎ ፡ አሚረ ፡ ቅድሜየ ፡ ውእቱ ፡ ኀፍረትየ ፤ ወከደነኒ ፡ ኀፍረተ ፡ ገጽየ ።"),
    (43, 17, "እምቃለ ፡ ዘይጽእል ፡ ወይዘረኪ ፤ እምገጸ ፡ ፀራዊ ፡ ዘይረውድ ።"),
    (43, 18, "ዝንቱ ፡ ኵሉ ፡ በጽሐ ፡ ላዕሌነ ፡ ወኢረሳዕናከ ፡ ወኢዐመፅነ ፡ ኪዳነከ ።"),
    (43, 19, "ወኢገብአ ፡ ድኀሬሁ ፡ ልብነ ፤ ወኢተግሕሠ ፡ አሰርነ ፡ እምፍኖትከ ።"),
    (43, 20, "እስመ ፡ አሕመምከነ ፡ በብሔር ፡ እኩይ ፤ ወደፈነነ ፡ ጽላሎተ ፡ ሞት ።"),
    (43, 21, "ሶበሁ ፡ ረሳዕነ ፡ ስሞ ፡ ለአምላክነ ፤ ወሶበሁ ፡ አንሣእነ ፡ እደዊነ ፡ ኀበ ፡ አምላክ ፡ ነኪር ።"),
    (43, 22, "አኮኑ ፡ እግዚአብሔር ፡ እምተኃሠሦ ፡ ለዝንቱ ፤ እስመ ፡ ውእቱ ፡ ያአምር ፡ ኀቡኣተ ፡ ልብ ።"),
    (43, 23, "እስመ ፡ በእንቲአከ ፡ ይቀትሉነ ፡ ኵሎ ፡ አሚረ ፡ ወኮነ ፡ ከመ ፡ አባግዕ ፡ ዘይጠብሑ ።"),
    (43, 24, "ንቃህ ፡ እግዚኦ ፡ ለምንት ፡ ትነውም ፡ ተንሥእ ፡ ወኢትግድፈነ ፡ ለዝሉፉ ።"),
    (43, 25, "ወለምንት ፡ ትመይጥ ፡ ገጸከ ፡ እምኔነ ፤ ወትረስዐነ ፡ ሕማመነ ፡ ወተጽናሰነ ።"),
    (43, 26, "እስመ ፡ ኀስረት ፡ ውስተ ፡ ምድር ፡ ነፍስነ ፤ ወጠግዐት ፡ በምድር ፡ ከርሥነ ።"),
    (43, 27, "ተንሥእ ፡ እግዚኦ ፡ ርድአነ ፤ ወአድኅነነ ፡ በእንተ ፡ ስምከ ።"),
    (44, 1, "ፍጻሜ ፡ በእንተ ፡ እለ ፡ ተበዐዱ ፡ ዘውሉደ ፡ ቆሬ ፤ መዝሙር ፡ ዘዳዊት ፡ ዘበኣእምሮ ።"),
    (44, 2, "ጐሥዐ ፡ ልብየ ፡ ቃለ ፡ ሠናየ ፡ አነ ፡ ኣየድዕ ፡ ግብርየ ፡ ለንጉሥ ፤ ከመ ፡ ቀለመ ፡ ጸሓፊ ፡ ዘጠበጠበ ፡ ይጽሕፍ ፡ ልሳንየ ።"),
    (44, 3, "ይሤኒ ፡ ላሕዩ ፡ እምውሉደ ፡ እጓለ ፡ እመሕያው ፡ ተክዕወ ፡ ሞገስ ፡ እምከናፍሪከ ፤ በእንተዝ ፡ ባረከከ ፡ እግዚአብሔር ፡ ለዓለም ።"),
    (44, 4, "ቅንት ፡ ሰይፈከ ፡ ኀይል ፡ ውስተ ፡ ሐቌከ ፤ በሥንከ ፡ ወበላሕይከ ።"),
    (44, 5, "አርትዕ ፡ ተሠራሕ ፡ ወንገሥ ፡ በእንተ ፡ ጽድቅ ፡ ወርትዕ ፡ ወየዋሃት ፤ ወይመርሐከ ፡ ስብሐተ ፡ የማንከ ።"),
    (44, 6, "አሕጻከ ፡ ስሑል ፡ ኀያል ፡ አሕዛብ ፡ ይወድቁ ፡ ታሕቴከ ፤ ውስተ ፡ ልቦሙ ፡ ለጸላእተ ፡ ንጉሥ ።"),
    (44, 7, "ወንበርከ ፡ እግዚኦ ፡ ለዓለመ ፡ ዓለም ፤ በትረ ፡ ጽድቅ ፡ በትረ ፡ መንግሥትከ ።"),
    (44, 8, "አፍቀርከ ፡ ጽድቀ ፡ ወዐመፃ ፡ ጸላእከ ፡ በእንተዝ ፡ ቀብአከ ፡ እግዚአብሔር ፡ አምላክከ ፤ ቅብአ ፡ ትፍሥሕት ፡ እምእለ ፡ ከማከ ።"),
    (44, 9, "ከርቤ ፡ ወቀንአተ ፡ ወሰሊኆት ፡ እምነ ፡ አልባሲከ ፤ እምክቡዳነ ፡ አቅርንት ፡ ዘእምኔሆሙ ፡ አስተፈሥሓከ ፡ አዋልደ ፡ ነገሥት ፡ ለክብርከ ፤"),
    (44, 10, "ወትቀውም ፡ ንግሥት ፡ በየማንከ ፡ በአልባሰ ፡ ወርቅ ፡ ዑጽፍት ፡ ወሑብርት ።"),
    (44, 11, "ስምዒ ፡ ወለትየ ፡ ወርእዪ ፡ ወአፅምዒ ፡ እዝነኪ ፤ ወርስዒ ፡ ሕዝበኪ ፡ ወቤተ ፡ አቡኪ ።"),
    (44, 12, "እስመ ፡ ፈተወ ፡ ንጉሥ ፡ ሥነኪ ፤ እስመ ፡ ውእቱ ፡ እግዚእኪ ።"),
    (44, 13, "ወይሰግዳ ፡ ሎቱ ፡ አዋልደ ፡ ጠሮስ ፡ በአምኃ ፡ ወለገጽኪ ፡ ይትመሀለሉ ፡ ኵሎሙ ፡ አሕዛብ ፡ ብዑላነ ፡ ምድር ።"),
    (44, 14, "ኵሉ ፡ ክብራ ፡ ለወለተ ፡ ንጉሥ ፡ ሐሴቦን ፤ በዘአዝፋረ ፡ ወርቅ ፡ ዑጽፍት ፡ ወሑብርት ።"),
    (44, 15, "ወይወስዱ ፡ ለንጉሥ ፡ ደናግለ ፡ ድኅሬሃ ፤ ወቢጻሂ ፡ ይወስዱ ፡ ለከ ።"),
    (44, 16, "ወይወስድዎን ፡ በትፍሥሕት ፡ ወበሐሤት ፤ ወያበውእዎን ፡ ውስተ ፡ ጽርሕ ፡ ንጉሥ ።"),
    (44, 17, "ህየንተ ፡ አበዊኪ ፡ ተወልዱ ፡ ለኪ ፡ ደቂቅ ፤ ወትሠይምዮሙ ፡ መላእክተ ፡ ለኵሉ ፡ ምድር ።"),
    (44, 18, "ወይዘከሩ ፡ ስመኪ ፡ በኵሉ ፡ ትውልደ ፡ ትውልድ ፤ በእንተዝ ፡ ይገንዩ ፡ ለከ ፡ አሕዛብ ፡ እግዚኦ ፡ ለዓለም ፡ ወለዓለመ ፡ ዓለም ።"),
    (45, 1, "ፍጻሜ ፡ ዘደቂቀ ፡ ቆሬ ፡ በእንተ ፡ ኅቡኣት ፡ መዝሙር ፡ ዘዳዊት ።"),
    (45, 2, "አምላክነሰ ፡ ኀይልነ ፡ ወጸወንነ ፤ ወረዳኢነ ፡ ውእቱ ፡ በምንዳቤነ ፡ ዘረከበነ ፡ ፈድፋደ ።"),
    (45, 3, "በእንተዝ ፡ ኢንፈርህ ፡ ለእመ ፡ አድለቅለቀት ፡ ምድር ፤ ወእመኒ ፡ ፈለሱ ፡ አድባር ፡ ውስተ ፡ ልብ ፡ ባሕር ።"),
    (45, 4, "ደምፁ ፡ ወተሐመጉ ፡ ማያቲሆሙ ፤ ወአድለቅለቁ ፡ አድባር ፡ እምኀይሉ ።"),
    (45, 5, "ፈለግ ፡ ዘይውሕዝ ፡ ያስተፌሥሕ ፡ ሀገረ ፡ እግዚአብሔር ፤ ቀደሰ ፡ ማኅድሮ ፡ ልዑል ።"),
    (45, 6, "እግዚአብሔር ፡ ውስተ ፡ ማእከላ ፡ ኢትትሀወክ ፤ ወይረድኣ ፡ እግዚአብሔር ፡ ፍጹመ ።"),
    (45, 7, "ደንገፁ ፡ አሕዛብ ፡ ወተመይጡ ፡ ነገሥት ፤ ወሀበ ፡ ቃሎ ፡ ልዑል ፡ ወአድለቅለቀት ፡ ምድር ።"),
    (45, 8, "እግዚኦ ፡ ኀያላን ፡ ምስሌነ ፤ ወምስካይነ ፡ አምላኩ ፡ ለያዕቆብ ።"),
    (45, 9, "ንዑ ፡ ወትርአዩ ፡ ገብሮ ፡ ለእግዚአብሔር ፤ ዘገብረ ፡ መንክረ ፡ በዲበ ፡ ምድር ።"),
    (45, 10, "ይስዕር ፡ ፀብአ ፡ እስከ ፡ አጽናፈ ፡ ምድር ፤ ይሰብር ፡ ቀስተ ፡ ወይቀጠቅጥ ፡ ወልታ ፡ ወያውዒ ፡ በእሳት ፡ ንዋየ ፡ ሐቅል ።"),
    (45, 11, "አስተርክቡ ፡ ወአእምሩ ፡ ከመ ፡ አነ ፡ ውእቱ ፡ እግዚአብሔር ፤ ተለዐልኩ ፡ እምአሕዛብ ፡ ወተለዐልኩ ፡ እምድር ።"),
    (45, 12, "እግዚአ ፡ ኀያላን ፡ ምስሌነ ፤ ወምስካይነ ፡ አምላኩ ፡ ለያዕቆብ ።"),
    (46, 1, "ፍጻሜ ፡ ዘበእንተ ፡ ውሉደ ፡ ቆሬ ፡ መዝሙር ።"),
    (46, 2, "ኵልክሙ ፡ አሕዛብ ፡ ጥፍሑ ፡ እደዊክሙ ፤ ወየብቡ ፡ ለእግዚአብሔር ፡ በቃለ ፡ ትፍሥሕት ።"),
    (46, 3, "እስመ ፡ ልዑል ፡ ወግሩም ፡ እግዚአብሔር ፤ ወንጉሥ ፡ ዐቢይ ፡ ውእቱ ፡ ዲበ ፡ ኵሉ ፡ ምድር ።"),
    (46, 4, "አግረረ ፡ ለነ ፡ አሕዛብ ፡ ወሕዘበ ፡ ታሕተ ፡ እገሪነ ፡"),
    (46, 5, "ወኀረየነ ፡ ሎቱ ፡ ለርስቱ ፤ ሥኖ ፡ ለያዕቆብ ፡ ዘአፍቀረ ።"),
    (46, 6, "ዐርገ ፡ እግዚአብሔር ፡ በይባቤ ፤ ወእግዚእነ ፡ በቃለ ፡ ቀርን ።"),
    (46, 7, "ዘምሩ ፡ ለአምላክነ ፡ ዘምሩ ፤ ዘምሩ ፡ ለንጉሥነ ፡ ዘምሩ ።"),
    (46, 8, "እስመ ፡ ንጉሥ ፡ እግዚአብሔር ፡ ለኵሉ ፡ ምድር ፡ ዘምሩ ፡ ልብወ ።"),
    (46, 9, "ነግሠ ፡ እግዚአብሔር ፡ ላዕለ ፡ ኵሉ ፡ አሕዛብ ፤ እግዚአብሔርሰ ፡ ይነብር ፡ ዲበ ፡ መንበሩ ፡ ቅዱስ ።"),
    (46, 9, "መላእክተ ፡ አሕዛብ ፡ ተጋብኡ ፡ ምስለ ፡ አምላከ ፡ አብርሃም ፤ እስመ ፡ ለእግዚአብሔር ፡ ጽኑዓነ ፡ ምድር ፡ ፈድፋደ ፡ ተለዐሉ ።"),
    (47, 1, "ማኅሌት ፡ መዝሙር ፡ ዘደቂቀ ፡ ቆሬ ፡ በሳኒታ ፡ ሰንበት ።"),
    (47, 2, "ዐቢይ ፡ እግዚአብሔር ፡ ወብዙኅ ፡ አኰቴቱ ፤ በሀገረ ፡ አምላክነ ፡ በደብረ ፡ መቅደሱ ።"),
    (47, 3, "ዘይዔዝዝ ፡ ትፍሥሕተ ፡ ለኰሉ ፡ ምድር ፤ አድባረ ፡ ጽዮን ፡ በገቦ ፡ መስዕ ፡ ሀገሩ ፡ ለንጉሥ ፡ ዐቢይ ።"),
    (47, 4, "እግዚአብሔር ፡ ያአምር ፡ ክበዲሃ ፡ ሶበ ፡ ተመጠውዋ ።"),
    (47, 5, "እስመ ፡ ናሁ ፡ ነገሥተ ፡ ምድር ፡ ተጋብኡ ፤ ወመጽኡ ፡ ኅቡረ ።"),
    (47, 6, "እሙንቱሰ ፡ ዝንተ ፡ ርእዮሙ ፡ አንከሩ ፤ ደንገፁ ፡ ወፈርሁ ።"),
    (47, 7, "ወአኀዞሙ ፡ ረዐድ ፡ ወሐሙ ፡ በህየ ፡ ከመ ፡ እንተ ፡ ትወልድ ።"),
    (47, 8, "በነፋስ ፡ ኀያል ፡ ትቀጠቅጦን ፡ ለአሕማረ ፡ ተርሴስ ።"),
    (47, 9, "በከመ ፡ ሰማዕነ ፡ ከማሁ ፡ ርኢነ ፡ በሀገረ ፡ እግዚአ ፡ ኀያላን ፡ በሀገረ ፡ አምላክነ ፤ እግዚአብሔር ፡ ሳረራ ፡ ለዓለም ።"),
    (47, 10, "ተወከፍነ ፡ እግዚኦ ፡ ሣህለከ ፡ በማእከለ ፡ ሕዝብከ ።"),
    (47, 11, "ወበከመ ፡ ስምከ ፡ ከማሁ ፡ ስብሐቲከ ፡ በኵሉ ፡ አጽናፈ ፡ ምድር ፤ ጽድቅ ፡ ምሉእ ፡ የማንከ ።"),
    (47, 12, "ይትፌሥሓ ፡ አድባረ ፡ ጽዮን ፡ ወይትሐሠያ ፡ አዋልደ ፡ ይሁዳ ፤ በእንተ ፡ ፍትሕከ ፡ እግዚኦ ።"),
    (47, 13, "ዕግትዋ ፡ ለጽዮን ፡ ወሕቀፍዋ ፤ ወተናገሩ ፡ በውስተ ፡ መኃፍዲሃ ።"),
    (47, 14, "ደዩ ፡ ልበክሙ ፡ ውስተ ፡ ኀይላ ፤ ወትትካፈልዎ ፡ ለክበዲሃ ፤ ከመ ፡ ትንግሩ ፡ ለካልእ ፡ ትውልድ ።"),
    (47, 15, "ከመ ፡ ዝንቱ ፡ ውእቱ ፡ አምላክነ ፡ ለዓለም ፡ ወለዓለመ ፡ ዓለም ፤ ወውእቱ ፡ ይሬዕየነ ፡ እስከ ፡ ለዓለም ።"),
    (48, 1, "ፍጻሜ ፡ ዘደቂቀ ፡ ቆሬ ፡ መዝሙር ፡ ዘዳዊት ።"),
    (48, 2, "ስምዑ ፡ ዝንተ ፡ ኵልክሙ ፡ አሕዛብ ፤ ወአፅምኡ ፡ ኵልክሙ ፡ እለ ፡ ትነብሩ ፡ ውስተ ፡ ዓለም ።"),
    (48, 3, "በበ ፡ በሐውርቲክሙ ፡ ደቂቀ ፡ እጓለ ፡ እመሕያው ፤ አብዕልትኒ ፡ ወነዳይኒ ።"),
    (48, 4, "አፉየ ፡ ይነግር ፡ ጥበበ ፤ ወሕሊና ፡ ልብየ ፡ ምክረ ።"),
    (48, 5, "ኣፀምእ ፡ ምሳሌ ፡ በእዘንየ ፤ ወእከሥት ፡ በመዝሙር ፡ ነገርየ ።"),
    (48, 6, "ለምንት ፡ እፈርህ ፡ እምዕለት ፡ እኪት ፤ ኃጢአተ ፡ ሰኰናየ ፡ ዐገተኒ ።"),
    (48, 7, "እለ ፡ ይትአመኑ ፡ በኀይሎሙ ፤ ወይዜሀሩ ፡ በብዝኀ ፡ ብዕሎሙ ።"),
    (48, 8, "እኍኒ ፡ ኢያድኅን ፡ እኅዋሁ ፡ ወኢያድኅን ፡ ሰብእ ፤ ወኢይሁብ ፡ ለእግዚአብሔር ፡ ቤዛሁ ።"),
    (48, 9, "ወኢተውላጠ ፡ ሤጠ ፡ ነፍሱ ፡ ዘጻመወ ፡ ለዓለም ፡"),
    (48, 10, "የሐዩ ፡ ለዝሉፉ ፤ እስመ ፡ ኢይሬኢ ፡ መስና ። ሶበ ፡ ትሬእዮሙ ፡ ለጠቢባን ፡ ይመውቱ ፡"),
    (48, 11, "መከማሁ ፡ ይትሐጐሉ ፡ አብዳን ፡ እለ ፡ አልቦሙ ፡ ልበ ፤ ወየኀድጉ ፡ ለባዕድ ፡ ብዕሎሙ ።"),
    (48, 12, "ወመቃብሪሆሙ ፡ አብያቲሆሙ ፡ ለዓለም ፡ ወማኅደሪሆሙ ፡ ለትውልደ ፡ ትውልድ ፤ ወይሰምዩ ፡ አስማቲሆሙ ፡ በበ ፡ በሐውርቲሆሙ ።"),
    (48, 13, "ወሰብእሰ ፡ እንዘ ፡ ክቡር ፡ ውእቱ ፡ ኢያእመረ ፤ ወኮነ ፡ ከመ ፡ እንስሳ ፡ ዘአልቦ ፡ ልበ ፡ ወተመሰሎሙ ።"),
    (48, 14, "ለሊሃ ፡ ፍኖቶሙ ፡ ዕቅፍቶሙ ፡ ወእንዘ ፡ ይሠምሩ ፡ በአፉሆሙ ።TABULAA"),
    (48, 15, "ከመ ፡ አባግዕ ፡ ሞት ፡ ይሬዕዮሙ ፡ በሲኦል ፤ ወይቀንይዎሙ ፡ ራትዓን ፡ በጽባሕ ፡ ወትበሊ ፡ ረድኤቶሙ ፡ በሲኦል ፡ እምክብሮሙ ።"),
    (48, 16, "ወባሕቱ ፡ እግዚአብሔር ፡ ያድኅና ፡ ለነፍስየ ፡ እምእደ ፡ ሲኦል ፤ ሶበ ይነሥኡኒ ።"),
    (48, 17, "ኢትፍርሆ ፡ ለሰብእ ፡ ሶበ ፡ ይብዕል ፤ ወሶበ ፡ ይበዝኅ ፡ ክብረ ፡ ቤቱ ።"),
    (48, 18, "እስመ ፡ ኢይነሥእ ፡ መስሌሁ ፡ ኵሎ ፡ እመ ፡ ይመውት ፤ ወኢይወርድ ፡ መስሌሁ ፡ ክብረ ፡ ቤቱ ።"),
    (48, 19, "እስመ ፡ ፈግዐት ፡ ነፍሱ ፡ በሕይወቱ ፤ የአምነከ ፡ ሰብእ ፡ ሶበ ፡ ታሤኒ ፡ ሎቱ ።"),
    (48, 20, "ወይወርድ ፡ ውስተ ፡ ዓለመ ፡ አበዊሁ ፤ ወኢይሬኢ ፡ እንከ ፡ ብርሃነ ፡ እስከ ፡ ለዓለም ።"),
    (48, 21, "ወእጓለ ፡ እመሕያውሰ ፡ እንዘ ፡ ክቡር ፡ ውእቱ ፡ ኢያእምረ ፤ ወኮነ ፡ ከመ ፡ እንስሳ ፡ ዘአልቦ ፡ ልበ ፡ ወተመሰሎሙ ።"),
    (49, 1, "ፍጻሜ ፡ ዘደቂቀ ፡ ቆሬ ፡ መዝሙር ፡ ዘአሳፍ ። አምላከ ፡ አማልክት ፡ እግዚአብሔር ፡ ነበበ ፡ ወጸውዓ ፡ ለምድር ፤ እምሥራቀ ፡ ፀሓይ ፡ እስከነ ፡ ዐረብ ።"),
    (49, 2, "ወእምጽዮን ፡ ሥነ ፡ ስብሐቲሁ ፡ እግዚአብሔርሰ ፡ ገሀደ ፡ ይመጽእ ፡"),
    (49, 3, "ወአምላክነሂ ፡ ኢያረምም ፤ እሳት ፡ ይነድድ ፡ ቅድሜሁ ፡ ወዐውድዶሂ ፡ ዐውሎ ፡ ብዙኅ ።"),
    (49, 4, "ይጼውዓ ፡ ለሰማይ ፡ በላዕሉ ፤ ወለምድርኒ ፡ ከመ ፡ ይኰንን ፡ ሕዝቦ ።"),
    (49, 5, "አስተጋብኡ ፡ ሎቱ ፡ ጻድቃኑ ፤ እለ ፡ ይገብሩ ፡ መሥዋዕተ ፡ ዘበሕጉ ።"),
    (49, 6, "ይነግራ ፡ ሰማያት ፡ ጽድቀ ፡ ዚአሁ ፤ እስመ ፡ እግዚአብሔር ፡ መኰንን ፡ ውእቱ ።"),
    (49, 7, "ስምዐኒ ፡ ሕዝብየ ፡ ወእንግርከ ፡ እስራኤል ፡ ወኣሰምዕ ፡ ለከ ፤ አምላክከሰ ፡ አምላክ ፡ አነ ፡ ውእቱ ።"),
    (49, 8, "አኮ ፡ በእንተ ፡ መሥዋዕትከ ፡ ዘእዛለፈከ ፤ ወቍርባንከኒ ፡ ቅድሜየ ፡ ውእቱ ፡ በኵሉ ፡ ጊዜ ።"),
    (49, 9, "ኢይነሥእ ፡ አልህምተ ፡ እምቤትከ ፤ ወኢሐራጊት ፡ እመርዔትከ ።"),
    (49, 10, "እስመ ፡ ዚአየ ፡ ውእቱ ፡ ኵሉ ፡ አራዊት ፡ ዘገዳም ፤ እንስሳ ፡ ገዳምኒ ፡ ወአልህምት ።"),
    (49, 11, "ወኣአምር ፡ ኵሎ ፡ አዕዋፈ ፡ ሰማይ ፤ ወሥነ ፡ ገዳምኒ ፡ ኀቤየ ፡ ሀሎ ።"),
    (49, 12, "እመኒ ፡ ርኀብኩ ፡ ኢይስእለከ ፤ እስመ ፡ ዚአየ ፡ ውእቱ ፡ ኵሉ ፡ ዓለም ፡ በምልኡ ።"),
    (49, 13, "ኢይበልዕ ፡ ሥጋ ፡ ላህም ፤ ወኢይሰቲ ፡ ደመ ፡ ጠሊ ።"),
    (49, 14, "ሡዕ ፡ ለእግዚአብሔር ፡ መሥዋዕተ ፡ ስብሐት ፤ ወሀቦ ፡ ለልዑል ፡ ጸሎተከ ።"),
    (49, 15, "ትጼውዐኒ ፡ በዕለተ ፡ መንዳቤከ ፡ ኣድኅነከ ፡ ወታአኵተኒ ።"),
    (49, 16, "ወለኃጥእሰ ፡ ይቤሎ ፡ እግዚአብሔር ፡ ለምንት ፡ ለከ ፡ ትነግር ፡ ሕግየ ፤ ወትነሥእ ፡ በአፉከ ፡ ሥርዕትየ ።"),
    (49, 17, "ወአንተሰ ፡ ጸላእከ ፡ ተግሣጽየ ፤ ወአግባእከ ፡ ድኅሬከ ፡ ቃልየ ።"),
    (49, 18, "እመኒ ፡ ርኢከ ፡ ሰራቄ ፡ ትረውጽ ፡ ምስሌሁ ፤ ወረሰይከ ፡ መክፈልተከ ፡ ምስለ ፡ ዘማውያን ።"),
    (49, 19, "አፉከ ፡ አብዝኃ ፡ ለእኪት ፤ ወልሳንከ ፡ ፀፈራ ፡ ለሕብል ።"),
    (49, 20, "ትነብር ፡ ወተሐምዮ ፡ ለእኁከ ፤ ወአንበርከ ፡ ዕቅፍተ ፡ ለወልደ ፡ እምከ ።"),
    (49, 21, "ዝንተ ፡ ገቢረክ ፡ አርመምኩ ፡ ለከ ፡ አደመተከኒ ፡ ኀጢአት ፡ ሐዘብከኑ ፡ እኩን ፡ ከማከ ፤ እዛለፍከኑ ፡ ወእቁም ፡ ቅድመ ፡ ገጽከ ።"),
    (49, 22, "ለብዉ ፡ ዘንተ ፤ ኵልክሙ ፡ እለ ፡ ትረስዕዎ ፡ ለእግዚአብሔር ፤ ወእመአኮሰ ፡ ይመስጥ ፡ ወአልቦ ፡ ዘያድኅን ።"),
    (49, 23, "መሥዋዕት ፡ ክብርት ፡ ትሴብሐኒ ፤ ህየ ፡ ፍኖት ፡ እንተ ፡ ባቲ ፡ አርአየ ፡ እግዚአብሔር ፡ አድኅኖቶ ።"),
    (50, 1, "ፍጻሜ ፡ መዝሙር ፡ ዘዳዊት ።"),
    (50, 2, "አመ ፡ መጽአ ፡ ኀቤሁ ፡ ናታን ፡ ነቢይ ፤ ዘአመ ፡ ቦአ ፡ ኀቤሃ ፡ ለአበሳቢ ።"),
    (50, 3, "ተሣሀለኒ ፡ እግዚኦ ፡ በከመ ፡ ዕበየ ፡ ሣህልከ ፤ ወበከመ ፡ ብዙኀ ፡ መሕረትከ ፡ ደምስስ ፡ ኃጢአትየ ።"),
    (50, 4, "ኅፅበኒ ፡ ወአንጽሐኒ ፡ እምኀጢአትየ ፤ ወእምአበሳየኒ ፡ አንጽሐኒ ።"),
    (50, 5, "እስመ ፡ ለልየ ፡ ኣአምር ፡ ጌጋይየ ፤ ወኀጢአትየኒ ፡ ቅድሜከ ፡ ውእቱ ፡ በኵሉ ፡ ጊዜ ።"),
    (50, 6, "ለከ ፡ ለባሕቲትከ ፡ አበስኩ ፡ ወእኩየኒ ፡ በቅድሜከ ፡ ገበርኩ ፤ ከመ ፡ ትጽደቅ ፡ በነቢብከ ፡ ወትማእ ፡ በኵነኔከ ።"),
    (50, 7, "እስመ ፡ ናሁ ፡ በኀጢአት ፡ ተፀነስኩ ፤ ወበዐመፃ ፡ ወለደተኒ ፡ እምየ ።"),
    (50, 8, "እስመ ፡ ናሁ ፡ ጽድቀ ፡ አፍቀርከ ፤ ዘኢይትነበብ ፡ ኅቡአ ፡ ጥበብከ ፡ አይዳዕከኒ ።"),
    (50, 9, "ትነዝኀኒ ፡ በአዛብ ፡ ወእነጽሕ ፤ ተኀፅበኒ ፡ እምበረድ ፡ እጸዐዱ ።"),
    (50, 10, "ታሰምዐኒ ፡ ትፍሥሕተ ፡ ወሐሤተ ፤ ወይትፌሥሑ ፡ አዕጽምተ ፡ ጻድቃን ።"),
    (50, 11, "ሚጥ ፡ ገጸከ ፡ እምኀጢአትየ ፤ ወደምስስ ፡ ሊተ ፡ ኵሎ ፡ አበሳየ ።"),
    (50, 12, "ልበ ፡ ንጹሐ ፡ ፍጥር ፡ ሊተ ፡ እግዚኦ ፤ ወመንፈሰ ፡ ርቱዐ ፡ ሐድስ ፡ ውስተ ፡ ከርሥየ ።"),
    (50, 13, "ኢትግድፈኒ ፡ እምቅድመ ፡ ገጽከ ፤ ወመንፈሰከ ፡ ቅዱሰ ፡ ኢታውፅእ ፡ እምላዕሌየ ።"),
    (50, 14, "ዕስየኒ ፡ ፍሥሓ ፡ በአድኅኖትከ ፤ ወበመንፈስ ፡ ዐዚዝ ፡ አጽንዐኒ ።"),
    (50, 15, "ከመ ፡ እምሀሮሙ ፡ ለኃጥኣን ፡ ፈኖተከ ፤ ወረሲዓን ፡ ይትመየጡ ፡ ኀቤከ ።"),
    (50, 16, "አድኅነኒ ፡ እምደም ፡ እግዚአብሔር ፡ አምላከ ፡ መድኀኒትየ ፤ ይትፌሣሕ ፡ ልሳንየ ፡ በጽድቀ ፡ ዚአከ ።"),
    (50, 17, "እግዚኦ ፡ ትከሥት ፡ ከናፍርየ ፤ ወአፉየ ፡ ያየድዕ ፡ ስብሐቲከ ።"),
    (50, 18, "ሶበሰ ፡ ፈቀድከ ፡ መሥዋዕተኒ ፡ እምወሀብኩ ፤ ወጽንሓሕኒ ፡ ኢትሠምር ።"),
    (50, 19, "መሥዋዕቱ ፡ ለእግዚአብሔር ፡ መንፈስ ፡ የዋህ ፤ ልበ ፡ ትሑተ ፡ ወየዋሀ ፡ ኢይሜንን ፡ እግዚአብሔር ።"),
    (50, 20, "አሠንያ ፡ እግዚኦ ፡ በሥምረትከ ፡ ለጽዮን ፤ ወይትሐንጻ ፡ አረፋቲሃ ፡ ለኢየሩሳሌም ።"),
    (50, 21, "አመ ፡ ትሠምር ፡ መሥዋዕተ ፡ ጽድቅ ፡ መባአኒ ፡ ወቍርባነኒ ፤ አሜሃ ፡ ያዐርጉ ፡ ውስተ ፡ ምሥዋዒከ ፡ አልህምተ ።"),
    (51, 1, "ፍጻሜ ፡ ዘበአእምሮ ፡ ዘዳዊት ።"),
    (51, 2, "ዘአመ ፡ መጽአ ፡ ዶይቅ ፡ ኤዶማዊ ፡ ወነገሮ ፡ ለሳኦል ፤ ወይቤሎ ፡ መጽአ ፡ ዳዊት ፡ ቤቶ ፡ ለአቤሜሌክ ።"),
    (51, 3, "ለምንት ፡ ይዜሀር ፡ ኀያል ፡ በእከዩ ፤ ወይዔምፅ ፡ ኵሎ ፡ አሚረ ።"),
    (51, 4, "ኀጢአተ ፡ ሐለየ ፡ ልብከ ፤ ከመ ፡ መላፄ ፡ በሊኅ ፡ ገበርከ ፡ ሕብለ ።"),
    (51, 5, "አብደርከ ፡ እኪተ ፡ እምሠናይት ፤ ወትዔምፅ ፡ እምትንብብ ፡ ጽድቀ ።"),
    (51, 6, "ወአፍቀርከ ፡ ኵሎ ፡ ነገረ ፡ ልሳን ፡ መስጥም ።"),
    (51, 7, "በእንተዝ ፡ ይነሥተከ ፡ እግዚአብሔር ፡ ለዝሉፉ ፤ ይመልሐከ ፡ ወያፈልሰከ ፡ እምቤትከ ፡ ወሥርወከኒ ፡ እምድረ ፡ ሕያዋን ።"),
    (51, 8, "ይርአዩ ፡ ጻድቃን ፡ ወይፍርሁ ፡ ወይስሐቁ ፡ ላዕሌሁ ፡ ወይበሉ ። ነዋ ፡ ብእሲ ፡ ዘኢረሰዮ ፡ ለእግዚአብሔር ፡ ረዳኢሁ ፤"),
    (51, 9, "ወተአመነ ፡ በብዝኀ ፡ ብዑሉ ፤ ወተኀየለ ፡ በከንቱ ።"),
    (51, 10, "ወአንሰ ፡ ከመ ፡ ዕፀ ፡ ዘይት ፡ ስሙር ፡ ውስተ ፡ ቤተ ፡ እግዚአብሔር ፤ ወተወከልኩ ፡ በምሕረቱ ፡ ለእግዚአብሔር ፡ ለዓለም ፡ ወለዓለመ ፡ ዓለም ።"),
    (51, 11, "እገኒ ፡ ለከ ፡ ለዓለም ፡ እስመ ፡ ገበርከ ፡ ሊተ ፤ ወእሴፈዋ ፡ ለምሕረትከ ፡ እስመ ፡ ሠናያቲከ ፡ ኀበ ፡ ጻድቃኒከ ።"),
    (52, 1, "ፍጻሜ ፡ ዘአመ ፡ መጽአ ፡ ዘበኣእምሮ ፡ ዘዳዊት ።"),
    (52, 2, "ይብል ፡ አብድ ፡ በልቡ ፡ አልቦ ፡ እግዚአብሔር ፤ ኀስሩ ፡ ወረኵሱ ፡ በጌጋዮሙ አልቦ ፡ ዘይገብራ ፡ ለሠናይት ።"),
    (52, 3, "እግዚአብሔር ፡ ሐወጸ ፡ እምሰማይ ፡ ዲበ ፡ እጓለ ፡ እምሕያው ፤ ከመ ፡ ይርአይ ፡ እመቦ ፡ ጠቢበ ፤ ዘየኀሦ ፡ ለእግዚአብሔር ።"),
    (52, 4, "ኵሉ ፡ ዐረየ ፡ ወኅቡረ ፡ ዐለወ ፤ አልቦ ፡ ዘይገብራ ፡ ለሠናይት ፤ አልቦ ፡ ወኢአሐዱ ።"),
    (52, 5, "ወኢያአምሩ ፡ ኵሎሙ ፡ ገበርተ ፡ ዐመፃ ፤ እለ ፡ ይውኅጥዎሙ ፡ ለሕዝብየ ፡ ከመ ፡ በሊዐ ፡ እክል ፤ ወለእግዚአብሔር ፡ ኢጸውዕዎ ።"),
    (
        52,
        6,
        "ወበህየ ፡ ፈርሁ ፡ ወገረሞሙ ፡ ዘኢኮነ ፡ ግሩመ ፤ እስመ ፡ እግዚአብሔር ፡ ዘረወ ፡ አዕጽምቲሆሙ ፡ ለመዳልዋን ፡ ወተኀፍሩ ፡ እስመ ፡ እግዚአብሔር ፡ አኅሰሮሙ ።",
    ),
    (52, 7, "መኑ ፡ ይሁብ ፡ እምጽዮን ፡ መድኀኒተ ፡ ልእስራኤል ፤ አመ ፡ ሜጠ ፡ እግዚአብሔር ፡ ፄዋ ፡ ሕዝቡ ፡ ይትፌሣሕ ፡ ያዕቆብ ፡ ወይትሐሠይ ፡ እስራኤል ።"),
    (53, 1, "ፍጻሜ ፡ ስብሐት ፡ ዘበኣእምሮ ፡ ዘዳዊት ፡"),
    (53, 2, "ዘአመ ፡ መጽኡ ፡ ዜፌዊያን ፡ ወይቤልዎ ፡ ለሳኦል ፤ ናሁ ፡ ዳዊት ፡ ይትኀባእ ፡ ኀቤነ ።"),
    (53, 3, "እግዚኦ ፡ በስምከ ፡ አድኅነኒ ፤ ወበኀይልከ ፡ ፍታሕ ፡ ሊተ ።"),
    (53, 4, "እግዚኦ ፡ ስምዐኒ ፡ ጸሎትየ ፤ ወአፅምእ ፡ ቃለ ፡ አፉየ ።"),
    (53, 5, "እስመ ፡ ነኪራን ፡ ቆሙ ፡ ላዕሌየ ፡ ወኀያላን ፡ ኀሠሥዋ ፡ ለነፍስየ ፤ ወኢረሰይዎ ፡ ለእግዚአብሔር ፡ ቅድሜሆሙ ።"),
    (53, 6, "ናሁ ፡ እግዚአብሔር ፡ ይረድአኒ ፤ ወእግዚእየ ፡ ያድኅና ፡ ለነፍስየ ።"),
    (53, 7, "ወይመይጣ ፡ ለእኪት ፡ ዲበ ፡ ጸላእትየ ፤ ወበጽድቅከ ፡ ሠርዎሙ ።"),
    (53, 8, "ዘእምፈቃድየ ፡ እሠውዕ ፡ ለከ ፤ እገኒ ፡ ለስምከ ፡ እግዚኦ ፡ እስመ ፡ ሠናይ ።"),
    (53, 9, "እስመ ፡ እምኵሎ ፡ ምንዳቤየ ፡ አድኀንከኒ ፤ ወርእየት ፡ ዐይንየ ፡ በጸላእትየ ።"),
    (54, 1, "ፍጻሜ ፡ ስብሐት ፡ ዘበኣእምሮ ፡ ዘዳዊት ።"),
    (54, 2, "አፅምአኒ ፡ እግዚኦ ፡ ጸሎትየ ፤ ወኢትትሀየየኒ ፡ ስእለትየ ።"),
    (54, 3, "ነጽረኒ ፡ ወስምዐኒ ፤ ተከዝኩ ፡ ወደንገፅኩ ፡ ወተዛዋዕኩ ። እምቃለ ፡ ጸላኢ ፡ ወእምሥቃየ ፡ ኃጥእ ፤"),
    (54, 4, "እስመ ፡ ሜጥዋ ፡ ለዐመፃ ፡ ላዕሌየ ፡ ወቆሙ ፡ ላዕሌየ ፡ ያመንስዉኒ ።"),
    (54, 5, "ወደንገፀኒ ፡ ልብየ ፡ በላዕሌየ ፤ ወመጽአኒ ፡ ድንጋፄ ፡ ሞት ።"),
    (54, 6, "ፍርሀት ፡ ወረዐድ ፡ አኀዘኒ ፤ ወደፈነኒ ፡ ጽልመት ።"),
    (54, 7, "ወእቤ ፡ መኑ ፡ ይሁበኒ ፡ ክንፈ ፡ ከመ ፡ ርጌብ ፤ እሥርር ፡ ወኣዕርፍ ።"),
    (54, 8, "ናሁ ፡ አርሐቁ ፡ ተኀጥኦ ፤ ወቤትኩ ፡ ውስተ ፡ በድው ።"),
    (54, 9, "እሴፈዎ ፡ ለዘ ፡ ያድኅነኒ ፤ እምዕንባዜ ፡ ነፍስየ ፡ ከመ ፡ ዐውሎ ።"),
    (54, 10, "አስጥሞሙ ፡ እግዚኦ ፡ ወምትር ፡ ልሳናቲሆሙ ፤ እስመ ፡ ርኢኩ ፡ ዐመፃ ፡ ወቅሥተ ፡ ውስተ ፡ ሀገር ።"),
    (54, 11, "እስመ ፡ መዐልተ ፡ ወሌሊተ ፡ ዕጉት ፡ ውስተ ፡ አረፋቲሃ ፤ ዐመፃ ፡ ወስራሕ ፡ ወኀጢአት ፡ ማእከላ ።"),
    (54, 12, "ወኢይርሕቅ ፡ እመርሕባ ፡ ጕሕሉት ።"),
    (54, 13, "ሶበሰ ፡ ጸላኢ ፡ ጸአለኒ ፡ እምተዐገሥኩ ፤ ውሶበሂ ፡ ጸላኢ ፡ አዕበየ ፡ አፉሁ ፡ ላዕሌየ ፡ እምተኀባእክዎ ።"),
    (54, 14, "ወአንተሰ ፡ ብእሲ ፡ ዘከመ ፡ ነፍስየ ፤ ማእምርየ ፡ ወዐውቅየ ።"),
    (54, 15, "ዘኅቡረ ፡ አስተጠዐምከ ፡ ሊተ ፡ መባልዕተ ፤ ወነሐውር ፡ ቤተ ፡ እግዚአብሔር ፡ በአሐዱ ፡ ልብ ።"),
    (54, 16, "ይምጽኦሙ ፡ ሞት ፡ ወይረዱ ፡ ውስተ ፡ ሲኦል ፡ ሕያዋኒሆሙ ፤ እስመ ፡ እኩይ ፡ ማእከሎሙ ፡ ውስተ ፡ አብያቲሆሙ ።"),
    (54, 17, "ወአንሰ ፡ ጸራኅኩ ፡ ኀበ ፡ እግዚአብሔር ፤ ወአምላኪየ ፡ ሰምዐኒ ።"),
    (54, 18, "ሰርከ ፡ ወነግሀ ፡ ወመዐልተ ፡ እነግር ፡ ወኣየድዕ ፤ ወይሰምዐኒ ፡ ቃልየ ።"),
    (54, 19, "አድኅና ፡ በሰላም ፡ ለነፍስየ ፡ እምእለ ፡ ይትቃረቡኒ ፤ እስመ ፡ ይበዝኁ ፡ እምእለ ፡ ምስሌየ ።"),
    (54, 20, "ይስማዕ ፡ እግዚአብሔር ፡ ወያኅስሮሙ ፤ ዘሀሎ ፡ እምቅድመ ፡ ይትፈጠር ፡ ዓለም ። እስመ ፡ አልቦሙ ፡ ቤዛ ፡ ወኢፈርህዎ ፡ ለእግዚአብሔር ።"),
    (54, 21, "ወሰፍሐ ፡ እዴሁ ፡ ለፍድይ ። ወአርኰሱ ፡ ሥርዐቶ ።"),
    (54, 22, "ወተናፈቁ ፡ እምዐተ ፡ ገጹ ፡ ወቀርበ ፡ ልቡ ። ወጽሕደ ፡ እምቅብእ ፡ ነገሩ ፡ እሙንቱሰ ፡ ማዕበል ፡ ያስጥሙ ።"),
    (54, 23, "ግድፍ ፡ ላዕለ ፡ እግዚአብሔር ፡ ሕሊናከ ፡ ወውእቱ ፡ ይሴስየከ ፤ ወኢይሁቦ ፡ ሁከተ ፡ ለጻድቅ ፡ ለዓለም ።"),
    (54, 24, "አንተ ፡ እግዚኦ ፡ አጽድፎሙ ፡ ውስተ ፡ ዐዘቅተ ፡ ሞት ፡ ዕድው ፡ ደም ፡ ወጽልሕዋን ፡ ኢይነፍቁ ፡ መዋዕሊሆሙ ፤ ወአንሰ ፡ ተወከልኩከ ፡ እግዚኦ ።"),
    (55, 1, "ፍጻሜ ፡ ዘበእንተ ፡ ሕዝብ ፡ እለ ፡ እምቅዱሳን ፡ ርሕቁ ፡ ዘዳዊት ፡ አርአያ ፡ መጽሐፍ ፤ ዘአመ ፡ አኀዝዎ ፡ ኢሎፍሊ ፡ በጌት ።"),
    (55, 2, "ተሣሀለኒ ፡ እግዚኦ ፡ እስመ ፡ ኬደኒ ፡ ሰብእ ፤ ወኵሎ ፡ አሚረ ፡ አስርሐኒ ፡ ቀትል ።"),
    (55, 3, "ወኬዱኒ ፡ ፀርየ ፡ ኵሎ ፡ አሚረ ፡ በኑኀ ፡ ዕለት ፤ እስመ ፡ ብዙኃን ፡ እለ ፡ ፀብኡኒ ፡ ወፈራህኩ ።"),
    (55, 4, "ወአንሰ ፡ ኪያከ ፡ ተወከልኩ ፡ እግዚኦ ።"),
    (55, 5, "በእግዚአብሔር ፡ እሴብሕ ፡ ቃልየ ፤ ወበእግዚአብሔር ፡ ተወከልኩ ፡ ኢይፈርህ ፤ ምንተ ፡ ይሬስየኒ ፡ ዘሥጋ ።"),
    (55, 6, "ወኵሎ ፡ አሚረ ፡ ያስቆርሩኒ ፡ ዘነበብኩ ። ወላዕሌየ ፡ ይመክሩ ፡ ኵሎ ፡ እኩየ ።"),
    (55, 7, "ይጸንሑኒ ፡ ወይትኀብኡኒ ። ወእሙንቱሰ ፡ ሰኰናየ ፡ ያስተሓይጹኒ ፤ ወዘልፈ ፡ ይጸንሕዋ ፡ ለነፍስየ ።"),
    (55, 8, "ወኢታድኅኖሙ ፡ ወኢበምንትኒ ፤ ወታጸድፎሙ ፡ ለአሕዛብ ፡ በመዐትከ ።"),
    (55, 9, "አምላኪየ ፡ እነግረከ ፡ ሕይወትየ ፤ ወአንበርኩ ፡ አንብዕየ ፡ ቅድሜከ ፡ በከመ ፡ አዘዝከ ።"),
    (55, 10, "ለይግብኡ ፡ ፀርየ ፡ ድኅሬሆሙ ፡ አመ ፡ ዕለተ ፡ እጼውዐከ ፤ ናሁ ፡ ኣእመርኩ ፡ ከመ ፡ አምላኪየ ፡ አንተ ።"),
    (55, 11, "በእግዚአብሔር ፡ እሴብሕ ፡ ቃልየ ፤ በእግዚአብሔር ፡ ይከብር ፡ ዘነበብኩ ።"),
    (55, 12, "ወበእግዚአብሔር ፡ ተወከልኩ ፡ ኢይፈርህ ፤ ምንተ ፡ ይሬስየኒ ፡ ሰብእ ።"),
    (55, 13, "እምኀቤይ ፡ እሁብ ፡ ብፅአትየ ፡ ለስብሓቲከ ።"),
    (55, 14, "እስመ ፡ አድኀንካ ፡ እሞት ፡ ለነፍስየ ፡ ወለአዕይንትየኒ ፡ እምአንብዕ ፤ ወለእገርየኒ ፡ እምዳኅፅ ። ከመ ፡ ኣሥምሮ ፡ ለእግዚአብሔር ፡ በብሔረ ፡ ሕያዋን ።"),
    (56, 1, "ፍጻሜ ፡ ኢታማስን ፡ ዘዳዊት ፡ አርአያ ፡ መጽሐፍ ፤ ዘአመ ፡ ጐየ ፡ እምቅድመ ፡ ገጸ ፡ ሳኦል ፡ ውስተ ፡ በአት ።"),
    (56, 2, "ተሣሀለኒ ፡ እግዚኦ ፡ ተሣሀለኒ ። እስመ ፡ ኪያከ ፡ ተወከለት ፡ ነፍስየ ፤ ወተወከልኩ ፡ በጽላሎተ ፡ ክንፊከ ፤ እስከ ፡ ተኀልፍ ፡ ኀጢአት ።"),
    (56, 3, "እጸርኅ ፡ ኀበ ፡ እግዚአብሔር ፡ ልዑል ፤ ኀበ ፡ እግዚአብሔር ፡ ዘረድአኒ ።"),
    (56, 4, "ፈነወ ፡ እምሰማይ ፡ ወአድኀነኒ ፡ ወወሀቦሙ ፡ ኀሳረ ፡ ለእለ ፡ ኬዱኒ ፤ ገነወ ፡ እግዚአብሔር ፡ ሣህሎ ፡ ወጽድቆ ።"),
    (
        56,
        5,
        "ወአድኀና ፡ ለነፍስየ ፡ እምእከለ ፡ አናብስት ፡ ወኖምኩ ፡ ድንጉፅየ ፤ ደቂቀ ፡ እጓለ ፡ እምሕያው ፡ ስነኒሆሙ ፡ ሐጽ ፡ ወኲናት ፡ ወልሳኖሙኒ ፡ በሊኅ ፡ መጥባሕት ።",
    ),
    (56, 6, "ተለዐለ ፡ እግዚአብሔር ፡ መልዕልተ ፡ ሰማያት ፤ ወበኵሉ ፡ ምድር ፡ ስብሐቲሁ ።"),
    (56, 7, "መሥገርተ ፡ አስተዳለዉ ፡ ለእገርየ ፡ ወቀጽዕዋ ፡ ለነፍስየ ፤ ከሩዩ ፡ ግበ ፡ ቅድሜየ ፡ ወወድቁ ፡ ውስቴቱ ።"),
    (56, 8, "ጥቡዕ ፡ ልብየ ፡ እግዚኦ ፡ ጥቡዕ ፡ ልብየ ፤ እሴብሕ ፡ ወእዜምር ።"),
    (56, 9, "ወይትንሣእ ፡ ክብርየ ፤ ወይትንሣእ ፡ በመዝሙር ፡ ወበመሰንቆ ፤ ወእትንሣእ ፡ በጽባሕ ።"),
    (56, 10, "እገኒ ፡ ለከ ፡ በውስተ ፡ አሕዛብ ፡ እግዚኦ ፤ ወእዜምር ፡ ለከ ፡ በውስተ ፡ ሕዝብ ።"),
    (56, 11, "እስመ ፡ ዐብየት ፡ እስከ ፡ ሰማያት ፡ ምሕረትከ ፤ ወእስከ ፡ ደመናት ፡ ጽድቅከ ።"),
    (56, 12, "ተለዐለ ፡ እግዚአብሔር ፡ መልዕልተ ፡ ሰማያት ፤ ወበኵሉ ፡ ምድር ፡ ስብሓቲሁ ።"),
    (57, 1, "ፍጻሜ ፡ ኢታማስን ፡ ዘዳዊት ፡ አርአያ ፡ መጽሐፍ ።"),
    (57, 2, "እመሰ ፡ አማን ፡ ጽድቀ ፡ ትነቡ ፤ ወርትዐ ፡ ትኴንኑ ፡ ደቂቀ ፡ እጓለ ፡ እምሕያው ።"),
    (57, 3, "እስመ ፡ በልብክሙ ፡ ኃጢአተ ፡ ትገብሩ ፡ በዲበ ፡ ምድር ፤ ወጽልሑተ ፡ ይፀፍራ ፡ እደዊክሙ ።"),
    (57, 4, "ተነክሩ ፡ ኃጥኣን ፡ እማሕፀን ፤ እምከርሥ ፡ ስሕቱ ፡ ወነበቡ ፡ ሐሰተ ።"),
    (57, 5, "ወመዐቶሙኒ ፡ ከመ ፡ ሕምዘ ፡ አርዌ ፡ ምድር ፤ ከመ ፡ አርዌ ፡ ምድር ፡ ጽምምት ፡ እዘኒሃ ።"),
    (57, 6, "እንት ፡ ኢትሰምዕ ፡ ቃለ ፡ ዘይሬቅያ ፤ እንዘ ፡ ይሠርያ ፡ መሠርይ ፡ ጠቢብ ።"),
    (57, 7, "እግዚአብሔር ፡ ይሰብር ፡ ስነኒሆሙ ፡ በውስተ ፡ አፉሆሙ ፤ ወይሰብር ፡ እግዚአብሔር ፡ ጥረሲሆሙ ፡ ለአናብስት ።"),
    (57, 8, "ወየኀስሩ ፡ ከመ ፡ ማይ ፡ ዘይትከዐው ፤ ወይዌስቅ ፡ ቀስቶ ፡ እስከ ፡ ያደክዎሙ ።"),
    (57, 9, "ወየኀልቁ ፡ ከመ ፡ ሰምዕ ፡ ዘይትመሰው ፤ ወድቀት ፡ እሳት ፡ ወኢርኢክዋ ፡ ለፀሐይ ።"),
    (57, 10, "ዘእንበለ ፡ ይትዐወቅ ፡ ሦክክሙ ፡ ሕለተ ፡ ኮነ ፡ ከመ ፡ ሕያዋን ፡ በመዐቱ ፡ ይውኅጠክሙ ።"),
    (57, 11, "ይትፌሣሕ ፡ ጻድቅ ፡ ሶበ ፡ ይሬኢ ፡ በቀለ ፤ ወይትኀፀብ ፡ እዴሁ ፡ በደመ ፡ ኃጥእ ።"),
    (57, 12, "ወይብል ፡ ሰብእ ፡ ቦኑ ፡ እንጋ ፡ ፍሬ ፡ ለጻድቅ ፤ ወቦኑ ፡ እንጋ ፡ እግዚአብሔር ፡ ይፈትሕ ፡ ሎሙ ፡ በዲበ ፡ ምድር ።"),
    (58, 1, "ፍጻሜ ፡ ኢታማስን ፡ ዘዳዊት ፡ አርአየ ፡ ምስሐፍ ፤ አመ ፡ ፈነወ ፡ ሳኦል ፡ ይዕቀቡ ፡ ቤቶ ፡ ከመ ፡ ይቅትሎ ።"),
    (58, 2, "አድኅነኒ ፡ እግዚኦ ፡ እምፀርየ ፤ ወአንግፈኒ ፡ እምእለ ፡ ቆሙ ፡ ላዕሌየ ።"),
    (58, 3, "ወባልሐኒ ፡ እምገበርተ ፡ ዐመፃ ፤ ወአድኅነኒ ፡ እምዕድወ ፡ ደም ።"),
    (58, 4, "እስመ ፡ ናሁ ፡ ናዐውዋ ፡ ለነፍስየ ፤ ወቆሙ ፡ ላዕሌየ ፡ ኀያላን ፤ አኮ ፡ በአበሳየ ፡ ወአኮ ፡ በጌጋይየ ፡ እግዚኦ ።"),
    (58, 5, "ዘእንበለ ፡ ዐመፃ ፡ ሮጽኩ ፡ ወአርታዕኩ ፤ ተንሥእ ፡ ተቀበለኒ ፡ ወርኢ ።"),
    (58, 6, "አንተ ፡ እግዚኦ ፡ አምላከ ፡ ኀያላን ፡ ንጉሠ ፡ እስራኤል ፡ ሐውጾሙ ፡ ለኵሎሙ ፡ አሕዛብ ፡ ወተሣሀሎሙ ፤ ወኢትሣሀሎሙ ፡ ለኵሎሙ ፡ ገበርተ ፡ ዐመፃ ።"),
    (58, 7, "ይትመየጡ ፡ ሰርከ ፡ ወይርኀቡ ፡ ከመ ፡ ከልብ ፤ ወይዑዱ ፡ ሀገር ።"),
    (58, 8, "ናሁ ፡ ይነቡ ፡ በአፉሆሙ ፡ ወሰይፍ ፡ ውስተ ፡ ከናፍሪሆሙ ፤ ወዘሂ ፡ ይሰምዖሙ ።"),
    (58, 9, "ወአንተ ፡ እግዚኦ ፡ ትስሕቆሙ ፤ ወነንኮሙ ፡ ለኵሎሙ ፡ አሕዛብ ።"),
    (58, 10, "ኣምኀፅን ፡ ኀቤከ ፡ ኀይልየ ፤ እስመ ፡ አምላኪየ ፡ ወምስካይየ ፡ አንተ ።"),
    (58, 11, "ይብጽሐኒ ፡ ሣህሉ ፡ ለአምላኪየ ፤ አምላኪየ ፡ አርእየኒ ፡ በጸላእትየ ።"),
    (58, 12, "ኢትቅትሎሙ ፡ ከመ ፡ ኢይርስዑ ፡ ሕገከ ፡ ዘርዎሙ ፡ በኀይልከ ፡ ወአጽድፎሙ ፡ አምላኪየ ፡ ወረዳእየ ።"),
    (58, 13, "ኀጢአተ ፡ አፉሆሙ ፡ ቃለ ፡ ከናፍሪሆሙ ፤ ወይሠገሩ ፡ በትዕቢቶሙ ። ወበመርገሞሙ ፡ ወእምሐሰቶሙ ፡ ይትዐወቅ ፡ ደኃሪቶሙ ።"),
    (58, 14, "ወየኀልቁ ፡ በደኃሪ ፡ መቅሠፍት ፤ ወያእምሩ ፡ ከመ ፡ አምላከ ፡ ያዕቆብ ፡ ይኴንን ፡ እስከ ፡ አጽናፈ ፡ ምድር ።"),
    (58, 15, "ይትመየጡ ፡ ሰርከ ፡ ወይርኀቡ ፡ ከመ ፡ ከልብ ፡ ወይዑዱ ፡ ሀገረ ።"),
    (58, 16, "እሙንቱሰ ፡ ይዘረዉ ፡ ለበሊዕ ፤ ወእስመ ፡ ኢጸግቡ ፡ ወአንጐርጐሩ ።"),
    (58, 17, "ወአንሰ ፡ እሴብሕ ፡ ለኀይልከ ፡ ወእትፌሣሕ ፡ በጽባሕ ፡ በምሕረትከ ፤ እስመ ፡ ኮንከኒ ፡ ምስካይየ ፡ ወጸወንየ ፡ በዕለተ ፡ ምንዳቤየ ።"),
    (58, 18, "ረዳእየ ፡ አንተ ፡ ወለከ ፡ እዜምር ፡ አምላኪየ ፤ እስመ ፡ አምላኪየ ፡ ወምስካይየ ፡ አንተ ፡ አምላኪየ ፡ ውእቱ ፡ ሣህልየ ።"),
    (
        59,
        1,
        "ፍጻሜ ፡ ዘእለ ፡ ተበዐዱ ፡ ዓዲ ፤ አርአየ ፡ መጽሐፍ ፡ ዘዳዊት ፡ ለትምህርት ። 2 ዘአመ ፡ አውዐየ ፡ መስጴጦምየ ፡ ዘሶርያ ፡ ወሶርያ ፡ ዘሶበል ፡ ወተመይጠ ፡ ዮአብ ፡ ወቀተለ ፡ በቈላቲሆም ፡ ካልኣን ፡ ዐሠርተ ፡ ወ ፪ ፻ ።",
    ),
    (59, 3, "እግዚኦ ፡ ገደፍከነ ፡ ወነሠትከነ ፤ ቀሠፍከነሂ ፡ ወተሣሀልከነ ።"),
    (59, 4, "አድለቅለቃ ፡ ለምድር ፡ ወሆካ ፤ ወፈወስከ ፡ ቍስላ ፡ እስመ ፡ ምንቀልቀለት ።"),
    (59, 5, "ወአርአይኮሙ ፡ ዕፁባተ ፡ ለሕዝብከ ፤ ወአስተይከነ ፡ ወይነ ፡ መደንግፀ ።"),
    (59, 6, "ወወሀብኮሙ ፡ ትእምርተ ፡ ለእለ ፡ ይፈርሁከ ፤ ከመ ፡ ያምስጡ ፡ እምገጸ ፡ ቀስት ።"),
    (59, 7, "ወይድኀኑ ፡ ፍቁራኒከ ፤ አድኅን ፡ በየማንከ ፡ ወስምዐኒ ።"),
    (59, 8, "እግዚአብሔር ፡ ነበበ ፡ በመቅደሱ ፡ እትፌሣሕ ፡ ወእትካፈል ፡ ምህርካ ፤ ወእሳፈር ፡ አዕጻደተ ፡ ቈላት ።"),
    (59, 9, "ዚአየ ፡ ውእቱ ፡ ገላዐድ ፡ ወዚአየ ፡ ምናሴ ፤ ወኤፍሬም ፡ ምስማከ ፡ ርእስየ ፤ ወይሁዳ ፡ ንጉሥየ ።"),
    (59, 10, "ወሞአብ ፡ ካህን ፡ ተስፋየ ፡ ዲበ ፡ አደምያስ ፡ እሰፍሕ ፡ መካይድየ ፤ ሊተ ፡ ይገንዩ ፡ ኢሎፍሊ ።"),
    (59, 11, "መኑ ፡ ይወስደኒ ፡ ሀገረ ፡ ጥቅም ፤ ወመኑ ፡ ይመርሐኒ ፡ እስከ ፡ ኢዶምያስ ።"),
    (59, 12, "አኮኑ ፡ አንተ ፡ እግዚኦ ፡ ዘገደፍከነ ፤ ወኢትወፅእ ፡ አምላክነ ፡ ምስለ ፡ ኀይልን ።"),
    (59, 13, "ሀበነ ፡ ረድኤተ ፡ በምንዳቤነ ፤ ወከንቱ ፡ ተአምኖ ፡ በሰብእ ።"),
    (59, 14, "በእግዚአብሔር ፡ ንገብር ፡ ኀይለ ፤ ወውእቱ ፡ ያኀስሮሙ ፡ ለእለ ፡ ይሣቅዩነ ።"),
    (60, 1, "ፍጻሜ ፡ ማኅሌት ፡ ዘዳዊት ።"),
    (60, 2, "ስምዐኒ ፡ አምላኪየ ፡ ስእለትየ ፤ ወአፅምአኒ ፡ ጸሎትየ ።"),
    (60, 3, "እምአጽናፈ ፡ ምድር ፡ ጸራኅኩ ፡ ኀቤከ ፡ ሶበ ፡ ቀብጸኒ ፡ ልብየ ፤ ወእምእብን ፡ አልዐልከኒ ፡ ወመራሕከኒ ።"),
    (60, 4, "እስመ ፡ ተስፋየ ፡ ኮንከኒ ፤ ማኅፈድ ፡ ጽኑዕ ፡ ቅድመ ፡ ገጸ ፡ ጸላኢ ።"),
    (60, 5, "እነብር ፡ ቤተከ ፡ ለዓለም ፤ ወእትከደን ፡ በጽላሎተ ፡ ክነፊከ ።"),
    (60, 6, "እስመ ፡ አንተ ፡ አምላኪየ ፡ ሰማዕከኒ ፡ ጸሎትየ ፤ ወወሀብኮሙ ፡ ርስተ ፡ ለእለ ፡ ይፈርሁከ ።"),
    (60, 7, "እምዕለት ፡ ዕለተ ፡ ይዌስክ ፡ ንጉሥ ፤ ዐመቲሁ ፡ እስከ ፡ መዋዕለ ፡ ትውለደ ፡ ትውለድ ።"),
    (60, 8, "ወይነብር ፡ ለዓለም ፡ ቅድመ ፡ እግዚአብሔር ፤ መኑ ፡ የኀሥሥ ፡ ሣህሎ ፡ ወጽድቆ ።"),
    (60, 9, "ከመዝ ፡ እዜምር ፡ ለስምከ ፡ ለዓለም ፤ ከመ ፡ ተሀበኒ ፡ ተምኔትየ ፡ ኵሎ ፡ አሚረ ።"),
    (61, 1, "ፍጻሜ ፡ ዝበእንተ ፡ ኢዶቱም ፡ መዝሙር ፡ ዘዳዊት ።"),
    (61, 2, "አኮኑ ፡ ለእግዚአብሔር ፡ ትገኒ ፡ ነፍስየ ፤ እስመ ፡ ኀቤሁ ፡ መድኀነትየ ።"),
    (61, 3, "እስመ ፡ ውእቱ ፡ አምላኪየ ፡ ወመድኀኒየ ፤ ወውእቱ ፡ ርዳእየ ፡ ወኢይትሀወክ ፡ ለዝሉፉ ።"),
    (61, 4, "እስከ ፡ ማእዜኑ ፡ ትቀውሙ ፡ ላዕለ ፡ ብእሲ ፡ ወትቀትልዎ ፡ ኵልክሙ ፤ ከመ ፡ አረፍት ፡ ጽንንት ፡ ወከመ ፡ ጥቅም ፡ ንሑል ።"),
    (61, 5, "ወባሕቱ ፡ መከሩ ፡ ይስዐሩ ፡ ክብርየ ፡ ወሮጽኩ ፡ በጽምእየ ፤ በአፉሆሙ ፡ ይድሕሩ ፡ ወበልቦሙ ፡ ይረግሙ ።"),
    (61, 6, "ወባሕቱ ፡ ለእግዚአብሔር ፡ ትገኒ ፡ ነፍስየ ፤ እስመ ፡ ኀቤሁ ፡ ተስፋየ ።"),
    (61, 7, "እስመ ፡ ውእቱ ፡ አምላኪየ ፡ ወመድኀኒየ ፤ ወርዳእየ ፡ ውእቱ ፡ ኢይትሀወክ ።"),
    (61, 8, "በእግዚአብሔር ፡ መድኀነትየ ፡ ወበእግዚአብሔር ፡ ክብርየ ፤ አምላከ ፡ ረድኤትየ ፡ ወተስፋየ ፡ እግዚአብሔር ።"),
    (61, 9, "ተወከሉ ፡ ቦቱ ፡ ኵልክሙ ፡ ማኅበሩ ፡ አሕዛብ ፡ ወከዐዉ ፡ ልበክሙ ፡ ቅድሜሁ ፤ ወእግዚአብሔር ፡ ውእቱ ፡ ርዳኢነ ።"),
    (
        61,
        10,
        "ወባሕቱ ፡ ከንቱ ፡ ኵሉ ፡ ደቂቀ ፡ እጓለ ፡ እመሕያው፡ ሐሳውያን ፡ ደቂቀ ፡እጓለ ፡ እመሕያው፡ ወይዔምፁ ፡ መዳልወ ፤ እሙንቱሰ ፡ እምከንቱ ፡ ውስተ ፡ ከንቱ ፡ ክመ ።",
    ),
    (61, 11, "ከመ ፡ ኢትሰፈዉዋ ፡ ለዓመፃ ። ወኢትትአመንዎ ፡ ለሀይድ ፤ ብዕል ፡ ለእመ ፡ በዝኀ ፡ ኢታዕብዮ ፡ ልበክሙ ።"),
    (61, 12, "ምዕረ ፡ ነበበ ፡ እግዚአብሔር ፡ ወዘንተ ፡ ከመ ፡ ሰማዕኩ ፤"),
    (61, 13, "እስመ ፡ ዘእግዚአብሔር ፡ ሣህል ። ወዚአከ ፡ እግዚኦ ፡ ኀይል ፤ እስመ ፡ አንተ ፡ ትፈድዮ ፡ ለኵሉ ፡ በከመ ፡ ምግባሩ ።"),
    (62, 1, "መዝሙር ፡ ዘዳዊት ፤ አመ ፡ ሀሎ ፡ ውስተ ፡ ገዳመ ፡ ኢዶምያስ ።"),
    (
        62,
        2,
        "አምላኪየ ፡ አምላኪየ ፡ እገይስ ፡ ኀቤከ ፤ ጸምአት ፡ ነፍስየ ፡ ለከ ፤ እፎ ፡ እስፋሕ ፡ ለከ ፡ ሥጋየ ፡ በምደረ ፡ በድው ፡ ኀበ ፡ አልቦ ፡ ዕፀ ፡ ወማየ ።",
    ),
    (62, 3, "ከመዝ ፡ በመቅደስከ ፡ አስተርአይኩከ ፤ ከመ ፡ ኣእምር ፡ ኀይለከ ፡ ወስብሐቲከ ።"),
    (62, 4, "እስመ ፡ ይኄይስ ፡ እምሐይው ፡ ሣህልከ ፤ ከናፍሪየ ፡ ይሴብሓከ ።"),
    (62, 5, "ከመዝ ፡ እባርከከ ፡ በሕይወትየ ፤ ወበስመ ፡ ዚአከ ፡ ኣነሥእ ፡ እደውየ ።"),
    (62, 6, "ከመ ፡ ዘእምሥቡሕ ፡ ወእምአንጕዕ ፡ ጸግበት ፡ ነፍስይ ፤ ከናፍርየ ፡ ፍሡሓት ፡ ይሴብሓ ፡ ለስምከ ።"),
    (62, 7, "ወበምስካብየኒ ፡ እዜክረከ ፤ ወጽባሕ ፡ ኣነብብ ፡ ለከ ።"),
    (62, 8, "እስመ ፡ ኮንከኒ ፡ ረዳእየ ፤ ወእትዌከል ፡ በጽላሎተ ፡ ክነፊከ ።"),
    (62, 9, "ተለወት ፡ ነፍስየ ፡ ድኅሬከ ፤ ሊተሰ ፡ ተወክፈተኒ ፡ የማንከ ።"),
    (62, 10, "እሙንቱሰ ፡ ለከንተ ፡ ኀሠሥዌ ፡ ለነፍስየ ፤ ለይባኡ ፡ ውስተ ፡ መዓምቅቲሃ ፡ ለምድር ።"),
    (62, 11, "ወይግብኡ ፡ ውስተ ፡ እደ ፡ ሰይፍ ፤ ክፍለ ፡ ቈናጽል ፡ ለይኩኑ ።"),
    (62, 12, "ወንጉሥሰ ፡ ይትፌሣሕ ፡ በእግዚአብሔር ፤ ወይከብር ፡ ኵሉ ዘይምሕል ፡ ኪያሁ ። እስመ ፡ ይትፈፀም ፡ አፍ ፡ ዘይነብብ ፡ ዐመፃ ።"),
    (63, 1, "ፍጻሜ ፡ መዝሙር ፡ ዘዳዊት ።"),
    (63, 2, "ስምዐኒ ፡ እግዚኦ ፡ ጸሎትየ ፡ ዘሰአልኩ ፡ ኀቤከ ፤ እምትሕዝብተ ፡ ጽላኢ ፡ አድኅና ፡ ለነፍስይ ።"),
    (63, 3, "ወሰውረኒ ፡ እምዕሌቶሙ ፡ ለእኩያን ፤ ወእምብዝኆሙ ፡ ለገበርተ ፡ ዐመፃ ።"),
    (63, 4, "እለ ፡ አብልኁ ፡ ልሳኖሙ ፡ ከመ ፡ አርዌ ፡ ምድር ፤ ወወሰቁ ፡ ቀስቶሙ ፡ ለገቢረ ፡ መሪር ።"),
    (63, 5, "ከመ ፡ ይቅትልዎ ፡ ለንጹሕ ፡ በጽሚት ፤ ግብተ ፡ ይነድፍዎሙ ፡ ወኢይፈርሁ ።"),
    (63, 6, "ወአጽንዑ ፡ ሎሙ ፡ ነገረ ፡ እኩየ ፡ ወተማከሩ ፡ ይኅብኡ ፡ ሎሙ ፡ መሥገርተ ፤ ወይቤሉ ፡ አልቦ ፡ ዘይሬእየነ ።"),
    (63, 7, "ወኀሠሥዋ ፡ ለዐመፃ ፡ ወኀልቁ ፡ እዝነ ፡ ይፈትኑ ፡ ወይወጥኑ ፤ ወይበውእ ፡ ሰብእ ፡ በልብ ፡ ዕሙቅ ፤"),
    (63, 8, "ወይትሌዐል ፡ እግዚአብሔር ። ከመ ፡ ሐጸ ፡ ደቂቅ ፡ ኮነ ፡ መቅሠፍቶሙ ።"),
    (63, 9, "ወደክመ ፡ ለሳኖሙ ፡ በላዕሌሆሙ ፡ ወደንገፁ ፡ ኵሎሙ ፡ እለ ፡ ርእይዎሙ ።"),
    (63, 10, "ወፈርሁ ፡ ኵሉ ፡ ሰብእ ፡ ወነገሩ ፡ ግብረ ፡ እግዚአብሔር ፤ ወአእመሩ ፡ ምግባሮ ።"),
    (63, 11, "ይትፌሣሕ ፡ ጻድቅ ፡ በእግዚአብሔር ፡ ወይትዌከል ፡ ቦቱ ፤ ወይከብሩ ፡ ኵሎሙ ፡ ርቱዓነ ፡ ልብ ።"),
    (64, 1, "ፍጻሜ ፡ ማኅሌት ፡ መዝሙር ፡ ዘዳዊት ።"),
    (64, 2, "ለከ ፡ ይደሉ ፡ እግዚኦ ፡ ስብሐት ፡ በጽዮን ፤ ወለከ ፡ ይትፌነው ፡ ጸሎት ፡ በኢየሩሳሌም ።"),
    (64, 3, "ስማዕ ፡ ጸሎተ ፡ ኵሉ ፡ ዘሥጋ ፡ ዘመጽአ ፡ ኀቤከ ።"),
    (64, 4, "ነገረ ፡ ዐማፂያን ፡ ኀየለነ ፡ ወኀጢአትነሰ ፡ አንተ ፡ ትሰሪ ፡ ለነ ።"),
    (64, 5, "ብፁዕ ፡ ዘኀረይኮ ፡ ወዘተወከፍኮ ፡ ወዘኣኅደርኮ ፡ ውስተ ፡ አዕጻዲከ ። ጸገብነ ፡ እምበረከተ ፡ ቤትከ ፡ ቅዱስ ፡ ጽርሕከ ፡ ወመንክር ፡ በጽዱቅ ።"),
    (64, 6, "ስምዐነ ፡ አምላክነ ፡ ወመድኀኒነ ፤ ተስፋሆሙ ፡ ለኵሎሙ ፡ አጽናፈ ፡ ምድር ፡ ወለእለሂ ፡ ውስተ ፡ ባሕር ፡ ርሑቅ ።"),
    (64, 7, "አጽናዕኮሙ ፡ ለአድባር ፡ በኀይልከ ፤ ወቅኑታን ፡ እሙንቱ ፡ በኀይል ።"),
    (64, 8, "ዘየሀውኮ ፡ ለዐንበረ ፡ ባሕር ፤ ወመኑ ፡ ይትቃወሞ ፡ ለድምፀ ፡ ማዕበላ ። ይደነግፁ ፡ አሕዛብ ፡ ወይፈርሁ ፡"),
    (64, 9, "እለ ፡ ይነብሩ ፡ ውስተ ፡ አጽናፍ ፡ እምተአምሪከ ፤ ይወፅኡ ፡ በጽባሕ ፡ ወሰርከ ፡ ይትፌሥሑ ።"),
    (64, 10, "ሐወጽካ ፡ ለምድር ፡ ወአርወይካ ፡ ወአብዛኅኮ ፡ ለብዕላ ፡ ፈለገ ፡ እግዚአብሔር ፡ ምሉእ ፡ ማያት ፤ አስተዳሎከ ፡ ሲሳዮሙ ፡ እስመ ፡ ከማሁ ፡ ታስተዴሉ ።"),
    (64, 11, "አርውዮ ፡ ለትሌሚሃ ፡ ወአስምር ፡ ለማእረራ ፤ ወበነጠብጣብከ ፡ ትበቍል ፡ ትፈሢሓ ።"),
    (64, 12, "ወትባርክ ፡ አክሊለ ፡ ዓመተ ፡ ምሕረትከ ፤ ወይጸግቡ ፡ ጠላተ ፡ ገዳማት ።"),
    (64, 13, "ወይረውዩ ፡ አድባረ ፡ በድው ፤ ወይትሐሠዩ ፡ አውግር ፡ ወይቀንቱ ።"),
    (64, 14, "ወይለብሱ ፡ አብሐኰ ፡ አባግዕ ፡ ወቈላትኒ ፡ ይመልኡ ፡ ስርናየ ፤ ይጸርኁ ፡ እንዘ ፡ ይሴብሑ ።"),
    (65, 1, "ፍጻሜ ፡ ማኅሌት ፡ መዝሙር ፡ ዘትንሣኤ ። የብቡ ፡ ለእግዚአብሔር ፡ በኵሉ ፡ ምድር ።"),
    (65, 2, "ወዘምሩ ፡ ለስሙ ፤ ሀቡ ፡ አኰቴተ ፡ ለስብሐቲሁ ።"),
    (65, 3, "በልዎ ፡ ለእግዚአብሔር ፡ ግሩም ፡ ግብርከ ፡ እንዘ ፡ ብዙኅ ፡ ኀይልከ ፡ ሐሰዉክ ፡ ጸላእቲከ ።"),
    (65, 4, "ኵላ ፡ ምድር ፡ ትሰግድ ፡ ወትገኒ ፡ ለከ ፡ ወትዜምር ፡ ለስምከ ፡ ልዑል ።"),
    (65, 5, "ንዑ ፡ ወትርአዩ ፡ ግብሮ ፡ ለእግዚአብሔር ፤ ግሩም ፡ ምክሩ ፡ እምእጓለ ፡ እመሕያው ።"),
    (65, 6, "ዘይሬስያ ፡ ለባሕር ፡ የብሰ ፡ ወበተከዚ ፡ የኀልፉ ፡ በእግር ፤ ወበህየ ፡ ንትፌሣሕ ፡ ኅቡረ ።"),
    (65, 7, "ዘይኴንን ፡ በኀይሉ ፡ ዘለዓለም ፡ ወአዕይንቲሁኒ ፡ ኀበ ፡ አሕዛብ ፡ ይኔጽራ ፤ እለ ፡ ታአምሩ ፡ ኢታዕብዩ ፡ ርእሰክሙ ።"),
    (65, 8, "ባርክዎ ፡ አሕዛብ ፡ ለአምላክነ ፤ ወአፅምኡ ፡ ቃለ ፡ ስብሐቲሁ ።"),
    (65, 9, "ዘአንበራ ፡ ለነፍስየ ፡ ውስተ ፡ ሕይወት ፤ ወኢይሁቦን ፡ ሁከተ ፡ ለእግርየ ።"),
    (65, 10, "እስመ ፡ አምከርከነ ፡ እግዚኦ ፤ ወፈተንከነ ፡ ከመ ፡ ይፈትንዎ ፡ ለብሩር ።"),
    (65, 11, "ወአባእከነ ፡ ውስተ ፡ መሥገርት ፤ ወአምጻእከ ፡ ሕማመ ፡ ቅድሜነ ። ወአጽአንከ ፡ ስብአ ፡ ዲበ ፡ አርእስቲነ ፤"),
    (65, 12, "አኅለፍከነ ፡ ማእከለ ፡ እሳት ፡ ወማይ ፡ ወአውፃእከነ ፡ ውስተ ፡ ዕረፍት ።"),
    (65, 13, "እበውእ ፡ ቤተከ ፡ ምስለ ፡ መባእየ ፤ ወእሁብ ፡ ብፅአትየ ።"),
    (65, 14, "ዘነበብኩ ፡ በአፉየ ፤ ዘእቤ ፡ በከናፍርየ ፡ አመ ፡ ምንዳቤየ ።"),
    (65, 15, "መሥዋዕተ ፡ ንጹሐ ፡ ዘአልቦ ፡ ነውረ ፡ ኣበውእ ፡ ለከ ፡ ዕጣነ ፡ ምስለ ፡ ሕራጊት ፤ እሠውዕ ፡ ለከ ፡ አልህምተ ፡ ወአጣሌ ።"),
    (65, 16, "ንዑ ፡ ስምዑኒ ፡ ወእንግርክሙ ፡ ኵልክሙ ፡ እለ ፡ ትፈርህዎ ፡ ለእግዚአብሔር ፤ መጠነ ፡ ገብረ ፡ ላቲ ፡ ለነፍስየ ።"),
    (65, 17, "ዘጸራኅኩ ፡ ኀቤሁ ፡ በአፉየ ፤ ወከላሕኩ ፡ በልሳንየ ።"),
    (65, 18, "እስመ ፡ ዐመፃ ፡ ይሬኢ ፡ ውስተ ፡ ልብየ ፤ ኢይሰምዐኒ ፡ እግዚአብሔር ።"),
    (65, 19, "ወበእንተዝ ፡ ሰምዐኒ ፡ እግዚአብሔር ፤ ወአፅምአኒ ፡ ቃለ ፡ ስእለትየ ።"),
    (65, 20, "ይትባረክ ፡ እግዚአብሔር ፡ ዘኢከልአኒ ፡ ጸሎትየ ፡ ወኢያርሐቀ ፡ ሣህሎ ፡ እምኔየ ።"),
    (66, 1, "ፍጻሜ ፡ ስብሐት ፡ መዝሙር ፡ ማኅሌት ፡ዘዳዊት ።"),
    (66, 2, "እግዚአብሔር ፡ ይባርከነ ፡ ወይሣሀለነ ፤ ወያርኡ ፡ ገጾ ፡ ላዕሌነ ፡ ወንሕዩ ።"),
    (66, 3, "ከመ ፡ ናእምር ፡ በምድር ፡ ፍኖተከ ፤ ወበኵሉ ፡ አሕዛብ ፡ አድኅኖተከ ።"),
    (66, 4, "ይገንዩ ፡ ለከ ፡ አሕዛብ ፡ እግዚኦ ፤ ይገንዩ ፡ ለከ ፡ አሕዛብ ፡ ኵሎሙ ።"),
    (66, 5, "ይትፌሥሑ ፡ ወይትሐሠዩ ፡ አሕዛብ ፤ እስመ ፡ ትኴንኖሙ ፡ ለአሕዛብ ፡ በርትዕ ፡ ወትመርሖሙ ፡ ለአሕዛብ ፡ በምድር ።"),
    (66, 6, "ይገንዩ ፡ ለከ ፡ አሕዛብ ፡ እግዚኦ ፤ ይገንዩ ፡ ለከ ፡ አሕዛብ ፡ ኵሎሙ ።"),
    (66, 7, "ምድርኒ ፡ ወሀበት ፡ ፍሬሃ ፤ ወይባርከነ ፡ እግዚአብሔር ፡ አምላክነ ።"),
    (66, 8, "ወይባርከነ ፡ እግዚአብሔር ፤ ወይፍርህዎ ፡ ኵሎሙ ፡ አጽናፈ ፡ ምድር ።"),
    (67, 1, "ፍጻሜ ፡ ዘዳዊት ፡ መዝሙር ፡ ማኅሌት ።"),
    (67, 2, "ይትነሣእ ፡ እግዚአብሔር ፡ ወይዘረዉ ፡ ፀሩ ፤ ወይጕየዩ ፡ ጸላእቱ ፡ እምቅድመ ፡ ገጹ ።"),
    (
        67,
        3,
        "ከመ ፡ የኀልቅ ፡ ጢስ ፡ ከማሁ ፡ የኀልቁ ፤ ወከመ ፡ ይትመሰው ፡ ሰምዕ ፡ እምቅድመ ፡ ገጸ ፡ እሳት ፡ ከማሁ ፡ ይትሐጐሉ ፡ ኃጥኣን ፡ እምቅድመ ፡ ገጹ ፡ ለእግዚአብሔር ።",
    ),
    (67, 4, "ወጻድቃንሰ ፡ ይትፌሥሑ ፡ ወይትሐሠዩ ፡ በቅድመ ፡ እግዚአብሔር ፤ ወይትፌሥሑ ፡ በሐሤት ።"),
    (
        67,
        5,
        "ሰብሕዎ ፡ ለእግዚአብሔር ፡ ወዘምሩ ፡ ለስሙ ፤ ፍኖተ ፡ ግብሩ ፡ ለዘ ፡ ዐርገ ፡ እንተ ፡ ዐረብ ፤ እግዚአብሔር ፡ ስሙ ፡ ወተፈሥሑ ፡ በቅድሜሁ ። ወይደነግፁ ፡ እምቅድመ ፡ ገጹ ።",
    ),
    (67, 6, "አብ ፡ ለእጓለ ፡ ማውታ ፡ ወመኰንኖን ፡ ለአቤራት ፤ እግዚአብሔር ፡ ውስተ ፡ ቤተ ፡ መቅደሱ ።"),
    (67, 7, "እግዚአብሔር ፡ ያኀድሮሙ ፡ ለባሕታዊያን ፡ ውስተ ፡ ቤቱ ፡ ወያወፅኦሙ ፡ ለሙቁሓን ፡ በኀይሉ ፤ ከማሁ ፡ ለምሩራን ፡ እለ ፡ ይነብሩ ፡ ውስተ ፡ መቃብር ።"),
    (67, 8, "እግዚኦ ፡ አመሰ ፡ ወፃእከ ፡ ቅድመ ፡ ሕዝብከ ፤ ወአመኒ ፡ እንተ ፡ ገዳም ፡ ኀለፍከ ።"),
    (67, 9, "ምድርኒ ፡ አድለቅለቀት ፡ ወሰማይኒ ፡ አንጠብጠበ ፡ እምቅድመ ፡ ገጹ ፡ ለአምላከ ፡ ሲና ፤ እምቅድመ ፡ ገጹ ፡ ለአምላከ ፡ እስራኤል ።"),
    (67, 10, "ዝናመ ፡ ፈቃዱ ፡ ዘፈለጠ ፡ እግዚአብሔር ፡ ለርስትከ ፤ እመኒ ፡ ደክመ ፡ አንተ ፡ ታጸንዖ ።"),
    (67, 11, "እንስሳከ ፡ የኀድር ፡ ውስቴቱ ፤ አስተዳሎከ ፡ ለነዳያን ፡ በኂሩትከ ፡ እግዚኦ ።"),
    (67, 12, "እግዚአብሔር ፡ ይሁቦሙ ፡ ቃለ ፡ ለእለ ፡ ይዜንዉ ፡ ኀይለ ፡ ብዙኀ ።"),
    (67, 13, "ንጉሠ ፡ ኀያለን ፡ ለፍቁሩ ፡ ለፍቁሩ ፡ ወለሥነ ፡ ቤትከ ፡ ተካፈልነ ፡ ምህርካ ።"),
    (67, 14, "እመኒ ፡ ቤትክሙ ፡ ማእከለ ፡ መዋርስት ፤ ክነፈ ፡ ርግብ ፡ በብሩር ፡ ዘግቡር ፡ ወገበዋቲሃኒ ፡ በኀመልማለ ፡ ወርቅ ።"),
    (67, 15, "አመ ፡ አዘዘ ፡ ሰማያዊ ፡ ንጉሥ ፡ ላዕሌሃ ፤ በረድ ፡ ይዘንም ፡ ላዕለ ፡ ሰልሞን ።"),
    (67, 16, "ደብረ ፡ እግዚአብሔር ፡ ደብር ፡ ጥሉል ፤ ደብር ፡ ርጉዕ ፡ ወደብረ ፡ ጥሉል ።"),
    (67, 17, "ለምንት ፡ ይትነሥኡ ፡ አድባር ፡ ርጉዓን ፤ ደብረ ፡ ዘሠምሮ ፡ እግዚአብሔር ፡ ይኀድር ፡ ውስቴቱ ፡ እስመ ፡ ይኀድሮ ፡ እግዚአብሔር ፡ ለዝሉፉ ።"),
    (67, 18, "ሰረገላቲሁ ፡ ለእግዚአብሔር ፡ ምእልፊተ ፡ አእላፍ ፡ ፍሡሓን ፤ እግዚአብሔር ፡ ውስቴቶሙ ፡ በሲና ፡ መቅደሱ ።"),
    (
        67,
        19,
        "ዐረገ ፡ ውስተ ፡ አርያም ፡ ፄዊወከ ፡ ፄዋ ፡ ወወሀብከ ፡ ጸጋከ ፡ ለእጓለ ፡ እምሕያው፤ እስመ ፡ ይክሕዱ ፡ ከመ ፡ ይኅድሩ ። እግዚአብሔር ፡ አምላክ ፡ ቡሩክ ።",
    ),
    (67, 20, "ይትባረክ ፡ እግዚአብሔር ፡ በኵሉ ፡ መዋዕል ፤ ይረድአነ ፡ አምላክነ ፡ ወመድኀኒነ ።"),
    (67, 21, "አምላክነሰ ፡ አምላከ ፡ አድኅኖ ፤ ወፍናዊሁኒ ፡ ለሞት ፡ ዘእግዚአብሔር ፡ ውእቱ ።"),
    (67, 22, "ወባሕቱ ፡ እግዚአብሔር ፡ ይሰብር ፡ አርእስተ ፡ ጸላእቱ ፤ ወበከተማ ፡ ሥዕርቶሙ ፡ የሐውር ፡ ጌጋዮሙ ።"),
    (67, 23, "ይቤ ፡ እግዚአብሔር ፡ ወፂእየ ፡ እገብእ ፤ ወእትመየጥ ፡ እንተ ፡ ቀላየ ፡ ባሕር ።"),
    (67, 24, "ከመ ፡ ይሠረያ ፡ እገሪከ ፡ በደም ፡ ልሳነ ፡ ከለባቲከ ፡ ላዕለ ፡ ጸላእቱ ።"),
    (67, 25, "አስተርአየ ፡ ፍናዊከ ፡ እግዚኦ ፤ ፍናዊሁ ፡ ለአምላኪየ ፡ ለንጉሥ ፡ ዘውስተ ፡ መቅደስ ።"),
    (67, 26, "በጽሑ ፡ መላእክት ፡ ወቦሙ ፡ መዘምራነ ፤ ማእከለ ፡ ደናግል ፡ ዘባጥያተ ፡ ከበሮ ።"),
    (67, 27, "በማኅበር ፡ ባርክዎ ፡ ለእግዚአብሔር ፤ ወለአማላክነ ፡ በአንቅዕተ ፡ እስራኤል ።"),
    (67, 28, "ህየ ፡ ብንያም ፡ ወሬዛ ፡ በኀይሉ ፡ መላእክተ ፡ ይሁዳ ፡ ወመሳፍንቲሆሙ ፤ መላእክተ ፡ ዛብሉን ፡ መላእክተ ፡ ንፍታሌም ።"),
    (67, 29, "አዝዝ ፡ እግዚኦ ፡ በኀይልከ ፤ ወአጽንዖ ፡ እግዚኦ ፡ ለዝንቱ ፡ ዘሠራዕከ ፡ ለነ ።"),
    (67, 30, "ውስተ ፡ ጽርሕከ ፡ ዘኢየሩሳሌም ፤ ለከ ፡ ያምጽኡ ፡ ነገሥት ፡ አምኃ ።"),
    (
        67,
        31,
        "ገሥጾሙ ፡ ለአራዊተ ፡ ሕለት ፡ ማኅበረ ፡ አልህምት ፡ ውስተ ፡ እጓላተ ፡ ሕዝብ ፡ ከመ ፡ ኢይትዐጸዉ ፡ እለ ፡ ፍቱናን ፡ ከመ ፡ ብሩር ፤ ዝርዎሙ ፡ ለአሕዛብ ፡ እለ ፡ ይፈቅዱ ፡ ቀትለ ።",
    ),
    (67, 32, "ይመጽኡ ፡ ተናብልት ፡ እምግብጽ ፤ ኢትዮጵያ ፡ ታበጽሕ ፡ እደዊሃ ፡ ኀበ ፡ እግዚአብሔር ።"),
    (67, 33, "ነገሥተ ፡ ምድር ፡ ሰብሕዎ ፡ ለእግዚአብሔር ፤ ወዘምሩ ፡ ለአምላክነ ።"),
    (
        67,
        34,
        "ዘምሩ ፡ ለእግዚአብሔር ፡ ዘዐርገ ፡ ውስተ ፡ ሰማይ ፤ ሰማይ ፡ ዘመንገለ ፡ ጽባሕ ፤ ናሁ ፡ ይሁብ ፡ ቃሎ ፡ ቃለ ፡ ኀይል ። ሀቡ ፡ አኰቴተ ፡ ለእግዚአብሔር ፡",
    ),
    (67, 35, "ላዕለ ፡ እስራኤል ፡ ዐቢይ ፡ ስብሐቲሁ ፤ ወኀይሉሂ ፡ እስከ ፡ ደመናት ።"),
    (67, 36, "መንክር ፡ እግዚአብሔር ፡ በላዕለ ፡ ቅዱሳኒሁ ። አምላከ ፡ እስራኤል ፡ ውእቱ ፡ ይሁብ ፡ ኀይለ ፡ ወጽንዐ ፡ ለሕዝቡ ፤ ወይትባረክ ፡ እግዚአብሔር ።"),
    (68, 1, "ፍጻሜ ፡ በእንተ ፡ እለ ፡ ተበዐዱ ፡ ዘዳዊት ።"),
    (68, 2, "አድኅነኒ ፡ እግዚኦ ፤ እስመ ፡ በጽሐኒ ፡ ማይ ፡ እስከ ፡ ነፍስየ ።"),
    (68, 2, "ወጠጋዕኩ ፡ ውስተ ፡ ዕሙቅ ፡ ቀላይ ፡ ወኀይል ፡ አልብየ ፤ sበጻሕኩ ፡ ውስተ ፡ ማዕምቀ ፡ ባሕር ፡ ወዐውሎ ፡ አስጠመኒ ።"),
    (68, 4, "ሰራሕኩ ፡ በከልሖ ፡ ወስሕከኒ ፡ ጕርዔየ ፤ ደክማ ፡ አዕይንትየ ፡ እንዘ ፡ እሴፈዎ ፡ ለአምላኪየ ።"),
    (68, 5, "በዝኁ ፡ እምስዕርተ ፡ ርእስየ ፡ እለ ፡ ይጸልኡኒ ፡ በከንቱ ፤ ጸንዑ ፡ ፀርየ ፡ እለ ፡ ይረውዱኒ ፡ በዐመፃ ፡ ወዘኢነሣእኩ ፡ ይትፈደዩኒ ።"),
    (68, 6, "ለሊከ ፡ እግዚኦ ፡ ታአምር ፡ እበድየ ፤ ወኢይትኀባእ ፡ እምኔከ ፡ ኃጢአትየ ።"),
    (68, 7, "ወኢይትኀፈሩ ፡ ብየ ፡ እለ ፡ የኀሡከ ፡ እግዚኦ ፡ እግዚአ ፡ ኀያላን ፤ ወኢይኀሰሩ ፡ ብየ ፡ እለ ፡ ይሴፈዉከ ፤ አምላከ ፡ እስራኤል ።"),
    (68, 8, "እስመ ፡ በእንቲአከ ፡ ተዐገሥኩ ፡ ፅእለተ ፤ ወከደነኒ ፡ ኀፍረት ፡ ገጽየ ።"),
    (68, 9, "ከመ ፡ ነኪር ፡ ኮንክዎሙ ፡ ለአኀውየ ፤ ወነግድ ፡ ለደቂቀ ፡ አቡየ ፡ ወእምየ ።"),
    (68, 10, "እስመ ፡ ቅንአተ ፡ ኬትከ ፡ በልዐኒ ፤ ተዕይርቶሙ ፡ ለእለ ፡ ይትዔየሩከ ፡ ወድቀ ፡ ላዕሌየ ።"),
    (68, 11, "ወቀጻእክዋ ፡ በጾም ፡ ለነፍስየ ። ወኮነኒ ፡ ፅእለተ ።"),
    (68, 12, "ወለበስኩ ፡ ሠቀ ፡ ወኮንክዎሙ ፡ ነገረ ።"),
    (68, 13, "ላዕሌየ ፡ ይዛውዑ ፡ እለ ፡ ይነብሩ ፡ ውስተ ፡ አናቅጽ ፤ ወኪያየ ፡ የኀልዩ ፡ እለ ፡ ይሰትዩ ፡ ወይነ ።"),
    (68, 14, "ወአንሰ ፡ በጸሎትየ ፡ ኀበ ፡ እግዚአብሔር ፡ ሣህሉ ፡ ለእግዚአብሔር ፡ በጊዜሁ ፤ እንዘ ፡ ብዙኅ ፡ ሣህልከ ፡ ስምዐኒ ፡ ዘበአማን ፡ መድኀንየ ።"),
    (68, 15, "ወአድኅነኒ ፡ እምዐምዓም ፡ ከመ ፡ ኢየኀጠኒ ፤ ወአንግፈኒ ፡ እምጸላእትየ ፡ ወእምቀላየ ፡ ማይ ። ወኢያስጥመኒ ፡ ዐውሎ ፡ ማይ ፡"),
    (68, 16, "ወኢየኀጠኒ ፡ ቀላይ ፤ ወኢያብቁ ፡ አፉሁ ፡ ዐዘቅት ፡ ላዕሌየ ።"),
    (68, 17, "ስምዐኒ ፡ እግዚኦ ፡ እስመ ፡ ሠናይ ፡ ምሕረትከ ፤ ወበከመ ፡ ብዝኀ ፡ ሣህልከ ፡ ነጽር ፡ ላዕሌየ ።"),
    (68, 18, "ወኢትሚጥ ፡ ገጸከ ፡ እምገብርከ ፤ እስመ ፡ ተመንደብኩ ፡ ፍጡነ ፡ ስምዐኒ ።"),
    (68, 19, "ነጽራ ፡ ለነፍስየ ፡ ወአድኅና ፤ ወአድኅነኒ ፡ በእንተ ፡ ጽእለትየ ።"),
    (68, 20, "ለሊከ ፡ ታአምር ፡ ጸላእትየ ፤ ኀፍረትየ ፡ ወኀሳርየ ፤ በቅድመ ፡ ኵሎሙ ፡ እለ ፡ ይሣቅዩኒ ።"),
    (68, 21, "ተዐገሠት ፡ ነፍስየ ፡ ጽእለተ ፡ ወኀሳረ ፤ ወነበርኩ ፡ ትኩዝየ ፡ ወኀጣእኩ ፡ ዘይናዝዘኒ ።"),
    (68, 22, "ወወደዩ ፡ ሐሞተ ፡ ውስተ ፡ መብልዕየ ፤ ወአስተዩኒ ፡ ብሒአ ፡ ለጽምእየ ።"),
    (68, 23, "ለትኩኖሙ ፡ ማእዶሙ ፡ መሥገርተ ፡ በቅድሜሆሙ ፤ ወማዕገተ ፡ ዕቅፍት ፡ ለፍዳሆሙ ።"),
    (68, 24, "ይጽለማ ፡ አዕይንቲሆሙ ፡ ወኢይርአያ ፤ ወይትቀጻዕ ፡ ዘባናቲሆሙ ፡ በኵሉ ፡ ጊዜ ።"),
    (68, 25, "ከዐው ፡ መዐተከ ፡ ላዕሌሆሙ ፤ ወይርከቦሙ ፡ መቅሠፍተ ፡ መዐትከ ።"),
    (68, 26, "ለትኩን ፡ ሀገሮሙ ፡ በድወ ፤ ወአልቦ ፡ ዘይንበር ፡ ውስተ ፡ አብያቲሆሙ ።"),
    (68, 27, "እስመ ፡ ዘአንተ ፡ ቀሠፍከ ፡ እሙንቱ ፡ ተለዉ ፤ ወወሰኩኒ ፡ ዲበ ፡ ጸልዕየ ፡ ቍስለ ።"),
    (68, 28, "ወስኮሙ ፡ ጌጋየ ፡ በዲበ ፡ ጌጋዮሙ ፤ ወኢይባኡ ፡ በጽድቅከ ።"),
    (68, 29, "ወይደምሰሱ ፡ እመጽሐፈ ፡ ሕያዋን ፤ ወኢይጸሐፉ ፡ ምስለ ፡ ጻድቃን ።"),
    (68, 30, "ነዳይ ፡ ወቍሱል ፡ አነ ፤ መድኀኔ ፡ ገጽየ ፡ እግዚአብሔር ፡ ተወክፈኒ ።"),
    (68, 31, "እሴብሕ ፡ ለስመ ፡ አምላኪየ ፡ በማኅሌት ፤ ወኣዐብዮ ፡ በስብሓት ።"),
    (68, 32, "ወአሠምሮ ፡ ለእግዚአብሔር ፡ እምላህም ፡ ጣዕዋ ፤ ዘአብቈለ ፡ ቀርነ ፡ ወጽፍረ ።"),
    (68, 33, "ይርአዩ ፡ ነዳያን ፡ ወይትፌሥሑ ፤ ኅሥዎ ፡ ለእግዚአብሔር ፡ ወተሐዩ ፡ ነፍስክሙ ።"),
    (68, 34, "እስመ ፡ ሰምዖሙ ፡ እግዚአብሔር ፡ ለነዳያን ፤ ወኢመነኖሙ ፡ ለሙቁሓን ።"),
    (68, 35, "ይሴብሕዎ ፡ ሰማያት ፡ ወምድር ፤ ወባሕርኒ ፡ ወኵሉ ፡ ዘይትሐወሥ ፡ ውስቴታ ።"),
    (68, 36, "እስመ ፡ አድኀና ፡ እግዚአብሔር ፡ ለጽዮን ፡ ወይትሐነጻ ፡ አህጉረ ፡ ይሁዳ ፤ ወይነብሩ ፡ ህየ ፡ ወይወርስዋ ።"),
    (68, 37, "ወዘርዐ ፡ አግብርቲከ ፡ ይነብርዋ ፤ ወእለ ፡ ያፍቅሩ ፡ ስመከ ፡ የኀድሩ ፡ ውስቴታ ።"),
    (69, 1, "ፍጻሜ ፡ ዘዳዊት ፡ በእንተ ፡ ተዝካረ ፡"),
    (69, 2, "አድኅነኒ ፡ እግዚኦ ። እግዚኦ ፡ ነጽር ፡ ውስተ ፡ ረዲኦትየ ፤ እግዚኦ፡ አፍጥን ፡ ረዳኦትየ ።"),
    (69, 3, "ይትኀፈሩ ፡ ወይኅሰሩ ፡ እለ ፡ የኀሥዎ ፡ ለነፍስየ ፤ ወይግብኡ ፡ ድኅሬሆሙ ፡ ወይትኀፈሩ ፡ እለ ፡ መከሩ ፡ እኩየ ፡ ላዕሌየ ።"),
    (69, 4, "ለይግብኡ ፡ ድኅሬሆሙ ፡ በጊዜሃ ፡ ተኀፊሮሙ ፡ እለ ፡ ይብሉኒ ፡ አንቋዕ ፡ አንቋዕ ።"),
    (69, 5, "ለይትፌሥሑ ፡ ወይትሐሠዩ ፡ ኵሎሙ ፡ እለ ፡ የኀሡከ ፡ እግዚኦ ፤ ወይበሉ ፡ ዘልፈ ፡ ዐቢይ ፡ እግዚአብሔር ፡ እለ ፡ ይፈቅዱ ፡ አድኅኖተከ ፡ በኵሉ ፡ ጊዜ ።"),
    (69, 6, "አንሰ ፡ ነዳይ ፡ ወምስኪን ፡ አነ ፡ ወእግዚአብሔር ፡ ይረድአኒ ። ረዳእየ ፡ ወምስካይየ ፡ አንተ ፡ እግዚኦ ፡ አምላኪየ ፡ ወኢትጐንዲ ።"),
    (70, 1, "ዘዳዊት ፡ ዘወልደ ፡ አሚናዳብ ፡ ለእለ ፡ አቅደሙ ፡ ተፄውዎ ። ኪያከ ፡ ተወከልኩ ፡ እግዚኦ ፡ ወኢይትኀፈር ፡ ለዓለም ።"),
    (70, 2, "ወበጽድቅከ ፡ አንግፈኒ ፡ ወባልሐኒ ፤ አፅምእ ፡ እዝነከ ፡ ኀቤየ ፡ ወፍጡነ ፡ አድኅነኒ ።"),
    (70, 3, "ኩነኒ ፡ አምላኪየ ፡ ወመድኀንየ ፡ ውስተ ፡ ብሔር ፡ ጽኑዕ ፡ ከመ ፡ ታድኅነኒ ፤ እስመ ፡ ኀይልየ ፡ ወጸወንየ ፡ አንተ ።"),
    (70, 4, "አምላኪየ ፡ አድኅነኒ ፡ እምእደ ፡ ኃጥኣን ፤ ወእምእደ ፡ ዐመፂ ፡ ወገፋዒ ።"),
    (70, 5, "እስመ ፡ አንተ ፡ ተስፋየ ፡ እግዚኦ ፤ እግዚእየ ፡ ተሰፈውኩከ ፡ እምንእስየ ።"),
    (70, 6, "ወብከ ፡ ጸናዕኩ ፡ በውስተ ፡ ከርሠ ፡ እምየ ። ወበውስተ ፡ ማኅፀን ፡ እንተ ፡ ከደንከኒ ።"),
    (70, 7, "ወአንተ ፡ ዝክርየ ፡ በኵሉ ፡ ጊዜ ። ከመ ፡ ኳሄላ ፡ ኮንክዎሙ ፡ ለብዙኃን ። ወአንተ ፡ ረዳእየ ፡ ወኀይልየ ።"),
    (70, 8, "ምላእ ፡ አፉየ ፡ ስብሐቲከ ፤ ከመ ፡ እሴብሕ ፡ አኰቴተከ ፡ ወኵሎ ፡ አሚረ ፡ ዕበየ ፡ ስብሐቲከ ።"),
    (70, 9, "ኢትግድገኒ ፡ በመዋዕለ ፡ ርሥእየ ፤ ወአመሂ ፡ ኀልቀ ፡ ኀይልየ ፡ ኢትኅድገኒ ፡ አምላኪየ ።"),
    (70, 10, "እስመ ፡ ነበቡ ፡ ላዕሌየ ፡ ጸላእትየ ፤ ወእለሂ ፡ የኀሥዋ ፡ ለነፍስየ ፡ ተማከሩ ፡ ኅቡረ ፡"),
    (70, 11, "ወይቤሉ ፡ ኀደጎ ፡ እግዚአብሔር ፤ ዴግንዎ ፡ ወትእኅዝዎ ፤ እስመ ፡ አልቦ ፡ ዘያድኅኖ ።"),
    (70, 12, "አምላኪየ ፡ ኢትርሐቅ ፡ እምኔየ ፤ አምላኪየ ፡ ነጽር ፡ ውስተ ፡ ረዲኦትየ ።"),
    (70, 13, "ይትኀፈሩ ፡ ወይኅሰሩ ፡ እለ ፡ ያስተዋድይዋ ፡ ለነፍስየ ፤ ወይልበሱ ፡ ኀፍረተ ፡ ወኀሳረ ፡ እለ ፡ ይፈቅዱ ፡ ሊተ ፡ ሕማመ ።"),
    (70, 14, "ወአንሰ ፡ ዘልፈ ፡ እሴፈወከ ፡ እግዚኦ ፤ ወእዌስክ ፡ ዲበ ፡ ኵሉ ፡ ስብሐቲከ ።"),
    (70, 15, "አፉየ ፡ ይነግር ፡ ጽድቀከ ፡ ወኵሎ ፡ አሚረ ፡ አድኅኖተከ ፤ እስመ ፡ ኢያአምር ፡ ተግባረ ።"),
    (70, 16, "እበውእ ፡ በኀይለ ፡ እግዚአብሔር ፤ እግዚኦ ፡ እዜከር ፡ ጽድቀከ ፡ ባሕቲቶ ።"),
    (70, 17, "ወመሀርከኒ ፡ አምላኪየ ፡ እምንእስየ ፤ እስከ ፡ ይእዜ ፡ እነግር ፡ ስብሐቲከ ።"),
    (70, 18, "ወእስከ ፡ እልህቅ ፡ ወእረሥእ ፡ ኢትኅድገኒ ፡ አምላኪየ ፤ እስከ ፡ እነግረ ፡ መዝራዕተከ ፡ ለትውልድ ፡ ዘይመጽእ ። ኀይለከኒ ፡ ወጽድቀከኒ ።"),
    (70, 19, "እግዚኦ ፡ እስከ ፡ አርያም ፡ ገበርከ ፡ ዐቢያተ ። እግዚኦ ፡ መኑ ፡ ከማከ ።"),
    (70, 20, "እስመ ፡ አርአይከኒ ፡ ሕማመ ፡ ወምንዳቤ ፡ ብዙኀ ፤ ወተመየጥከኒ ፡ ወአሕየውከኒ ፤ ወእምቀላየ ፡ ምድር ፡ ካዕበ ፡ አውፃእከኒ ።"),
    (70, 21, "ወአብዛኅኮ ፡ ለጽድቅከ ፡ ወገባእከ ፡ ታስተፌሥሐኒ ፤ ወእምቀላየ ፡ ምድር ፡ ካዕበ ፡ አውፃእከኒ ።"),
    (70, 22, "ወአነሂ ፡ እገኒ ፡ ለከ ፡ በንዋየ ፡ መዝሙር ፡ ለጽድቅከ ፤ እዜምር ፡ ለከ ፡ አምላኪየ ፡ በመሰንቆ ፡ ቅዱሰ ፡ እስራኤል ።"),
    (70, 23, "ይትፌሥሓኒ ፡ ከናፍርየ ፡ ሶበ ፡ እዜምር ፡ ለከ ፤ ወለነፍስየኒ ፡ አንተ ፡ አድኀንካ ።"),
    (70, 24, "ወዓዲ ፡ ልሳንየ ፡ ያነብብ ፡ ጽድቀከ ፡ ኵሎ ፡ አሚረ ፤ ሶበ ፡ ተኀፍሩ ፡ ወኀስሩ ፡ እለ ፡ የኀሡ ፡ ሊተ ፡ እኩየ ።"),
    (71, 1, "በእንተ ፡ ሰሎሞን ። እግዚኦ ፡ ኵነኔከ ፡ ሀቦ ፡ ለንጉሥ ፤ ወጽድቅከኒ ፡ ለወልደ ፡ ንጉሥ ።"),
    (71, 2, "ከመ ፡ ይኰንኖሙ ፡ ለሕዝብከ ፡ በጽድቅ ፤ ወለነዳያኒከ ፡ በፍትሕ ።"),
    (71, 3, "ይትወከፉ ፡ አድባር ፡ ወአውግር ፡ ሰላመ ፡ ሕዝብከ ።"),
    (71, 4, "ኰንን ፡ በጽድቅ ፡ ነዳያነ ፡ ሕዝብከ ፡ ወአድኅኖሙ ፡ ለደቂቀ ፡ ምስኪናኒከ ፤ ወአኅስሮ ፡ ለዕቡይ ።"),
    (71, 5, "ወይጽናሕ ፡ ምስለ ፡ ፀሐይ ፤ እምቅድመ ፡ ወርኅ ፡ ለትውልደ ፡ ትውልድ ።"),
    (71, 6, "ወይወርድ ፡ ከመ ፡ ጠል ፡ ውስተ ፡ ፀምር ፤ ወከመ ፡ ነጠብጣብ ፡ ዘያንጠበጥብ ፡ ዲበ ፡ ምድር ።"),
    (71, 7, "ወይሠርጽ ፡ ጽድቅ ፡ በመዋዕሊሁ ፤ ወብዙኅ ፡ ሰላመ ፡ እስከ ፡ ይኀልፍ ፡ ወርኅ ።"),
    (71, 8, "ወይኴንን ፡ እምባሕር ፡ እስከ ፡ ባሕር ፤ ወእምአፍላግ ፡ እስከ ፡ አጽናፈ ፡ ዓለም ።"),
    (71, 9, "ይገንዩ ፡ ቅድሜሁ ፡ ኢትዮጵያ ፤ ወጸላእቲሁ ፡ ሐመደ ፡ ይቀምሑ ።"),
    (71, 10, "ነገሥተ ፡ ተርሴስ ፡ ወደሰያት ፡ አምኃ ፡ ያበውኡ ፤ ነገሥተ ፡ ሳባ ፡ ወዐረብ ፡ ጋዳ ፡ ያመጽኡ ።"),
    (71, 11, "ወይሰግዱ ፡ ሎቱ ፡ ኵሎሙ ፡ ነገሥተ ፡ ምድር ፤ ወይትቀነዩ ፡ ሎቱ ፡ ኵሎሙ ፡ አሕዛብ ።"),
    (71, 12, "እስመ ፡ አድኀኖ ፡ ለነዳይ ፡ እምእደ ፡ ዘይትዔገሎ ፤ ለምስኪን ፡ ዘአልቦ ፡ ረዳኤ ።"),
    (71, 13, "ወይምሕክ ፡ ነዳየ ፡ ወምስኪነ ፤ ወያድኅን ፡ ነፍሰ ፡ ነዳያን ።"),
    (71, 14, "እምርዴ ፡ ወእምትዕግልት ፡ ያድኅና ፡ ለነፍሶሙ ፤ ወክቡር ፡ ስሙ ፡ በቅድሜሆሙ ።"),
    (71, 15, "ወየሐዩ ፡ ወይሁብዎ ፡ እምወርቀ ፡ ዐረብ ፤ ወዘልፈ ፡ ይጼልዩ ፡ በእንቲአሁ ፡ ወኵሎ ፡ አሚረ ፡ ይድሕርዎ ።"),
    (
        71,
        16,
        "ወይከውን ፡ ምስማከ ፡ ለኵሉ ፡ ምድር ፡ ውስተ ፡ አርእስተ ፡ አድባር ፤ ወኡነውኅ ፡ እምአርህ ፡ ፍሬሁ ፡ ወይበቍል ፡ ውስተ ፡ ሀገር ፡ ከመ ፡ ሣዕረ ፡ ምድር ።",
    ),
    (
        71,
        17,
        "ወይከውን ፡ ቡሩከ ፡ ስሙ ፡ ለዓለም ፡ እምቅድመ ፡ ፀሐይ ፡ ሀሎ ፡ ስሙ ፤ ወይትባረኩ ፡ ቦቱ ፡ ኵሎሙ ፡ አሕዛበ ፡ ምድር ፡ ወያስተበፅእዎ ፡ ኵሎሙ ፡ ሕዝብ ።",
    ),
    (71, 18, "ይትባረክ ፡ እግዚአብሔር ፡ አምላከ ፡ እስራኤል ፤ ዘገብረ ፡ መንክረ ፡ ባሕቲቱ ።"),
    (71, 19, "ወይትባረክ ፡ ስመ ፡ ስብሓቲሁ ፡ ልዓለም ፡ ወለዓለመ ፡ ዓለም ፤ ወይምላእ ፡ ስብሐቲሁ ፡ ኵሎ ፡ ምድር ፤ ለይኩን ፡ ለይኩን ።"),
    (71, 19, "ኀልቀ ፡ መኅልይ ፡ ዘዳዊት ፡ ዘወልደ ፡ ኤሳይ ።"),
    (72, 1, "መዝሙር ፡ ዘአሳፍ ። ጥቀ ፡ ኄር ፡ እግዚአብሔር ፡ ለእስራኤል ፡ ለርቱዓነ ፡ ልብ ።"),
    (72, 2, "ሊተሰ ፡ ሕቀ ፡ ክመ ፡ ዘእምተንተና ፡ እገርየ ፤ ወሕቀ ፡ ክመ ፡ ዘእምድኅፀ ፡ ሰኰናየ ።"),
    (72, 3, "እስመ ፡ ቀናእኩ ፡ ላዕለ ፡ ኃጥኣን ፤ ሰላሞሙ ፡ ርእይየ ፡ ለዐማፅያን ።"),
    (72, 4, "እስመ ፡ አልቦሙ ፡ ሣኅተ ፡ ለሞቶሙ ፤ ወኢኀይለ ፡ ለመቅሠፍቶሙ ።"),
    (72, 5, "ወበጻማሂ ፡ ኢኮኑ ፡ ከመ ፡ ሰብእ ፤ ወኢተቀሥፉ ፡ ምስለ ፡ ሰብእ ።"),
    (72, 6, "ወበእንተዝ ፡ አኀዞሙ ፡ ትዕቢት ፤ ወተዐጸፍዋ ፡ ለኀጢአቶሙ ፡ ወለዐመፃሆሙ ።"),
    (72, 7, "ወይወፅእ ፡ ከመ ፡ እምአንጕዕ ፡ ኀጢአቶሙ ፤ ወኀለፈ ፡ እምትዕቢተ ፡ ልቦሙ ።"),
    (72, 8, "ወሐለዩ ፡ ወነበቡ ፡ ከንቶ ፤ ወነበቡ ፡ ዐመፃ ፡ ውስተ ፡ አርያም ።"),
    (72, 9, "ወአንበሩ ፡ ውስተ ፡ ሰማይ ፡ አፉሆሙ ፤ ወአንሶሰው ፡ ውስተ ፡ ምድር ፡ ልሳኖሙ ።"),
    (72, 10, "ወበእንተዝ ፡ ይትመየጡ ፡ ሕዝብየ ፡ እምዝየ ፤ ወይትረከብ ፡ ፍጹም ፡ መዋዕል ፡ በላዕሌሆሙ ።"),
    (72, 11, "ወይብሉ ፡ እፎ ፡ ያአምር ፡ እግዚአብሔር ፤ ወቦኑ ፡ ዘያአምር ፡ በአርያም ።"),
    (72, 12, "ናሁ ፡ እሉ ፡ ኃጥኣን ፡ ይትፈግዑ ፡ ወለዓለም ፡ ያጸንዕዋ ፡ ለብዕሎሙ ።"),
    (72, 13, "ወእቤ ፡ ከንቶሁ ፡ እንጋ ፡ አጽደቅዋ ፡ ለልብየ ፤ ወኀፀብኩ ፡ በንጹሕ ፡ እደውየ ።"),
    (72, 14, "ወኮንኩ ፡ ቅሡፈ ፡ ኵሎ ፡ አሚረ ፤ ወዘለፋየኒ ፡ በጽባሕ ።"),
    (72, 15, "ሶበ ፡ እቤሁ ፡ ነበብኩ ፡ ከመዝ ፤ ናሁ ፡ ሠራዕኩ ፡ ለትውልደ ፡ ደቂቅከ ።"),
    (72, 16, "ወተወከፍኩ ፡ ከመ ፡ ኣእምር ፤ ወዝንቱሰ ፡ ጻማ ፡ ውእቱ ፡ በቅድሜየ ።"),
    (72, 17, "እስከ ፡ እበውእ ፡ ውስተ ፡ መቅደሱ ፡ ለእግዚአብሔር ፤ ከመ ፡ ኣእምር ፡ ደኃሪቶሙ ።"),
    (72, 18, "ወባሕቱ ፡ በእንተ ፡ ጽልሑቶሙ ፡ አጽናሕኮሙ ፤ ወነፃኅኮሙ ፡ በተንሥኦቶሙ ።"),
    (72, 19, "እፎ ፡ ኮኑ ፡ ለሙስና ፡ ግብተ ፡ ኀልቁ ፡ ወተሐጕሉ ፡ በእንተ ፡ ኀጢአቶሙ ።"),
    (72, 20, "ከመ ፡ ዘንቃህ ፡ እምንዋም ፡ እግዚኦ ፡ በሀገርከ ፡ አኅስር ፡ ራእዮሙ ።"),
    (72, 21, "እስመ ፡ ውዕየ ፡ ልብየ ፡ ወተመስወ ፡ ኵልያትየ ። ወአንሰ ፡ ምኑን ፡ ወኢያእምርኩ ፤"),
    (72, 22, "ወኮንኩ ፡ ከመ ፡ እንስሳ ፡ በኀቤከ ።"),
    (72, 23, "ወአንሰ ፡ ዘልፈ ፡ ምስሌከ ፤ አኀዝከኒ ፡ እዴየ ፡ ዘየማን ።"),
    (72, 24, "ወበምክረ ፡ ዚአከ ፡ መራሕከኒ ፤ ወምስለ ፡ ስብሐት ፡ ተወከፍከኒ ፤"),
    (72, 25, "ምንተ ፡ ብየ ፡ ተሀሉ ፡ ውስተ ፡ ሰማይ ፤ ወምንተ ፡ እፈቅድ ፡ ኀቤከ ፡ ውስተ ፡ ምድር ።"),
    (72, 26, "ኀልቀ ፡ ልብየ ፡ ወሥጋየ ፡ በአምላከ ፡ መድኀኒትየ ፡ እግዚአብሔር ፡ መክፈልትየ ፡ ለዓለም ።"),
    (72, 27, "እስመ ፡ ናሁ ፡ እለ ፡ ይርሕቁ ፡ እምኔከ ፡ ይትሐጐሉ ፤ ወሠረውኮሙ ፡ ለኵሎሙ ፡ እለ ፡ ይዜምዉ ፡ እምኔከ ።"),
    (72, 28, "ሊተሰ ፡ ተሊወ ፡ እግዚአብሔር ፡ ይኄይሰኒ ፤ ወትውክልትየኒ ፡ ላዕለ ፡ እግዚአብሔር ፤ ከመ ፡ እንግር ፡ ኵሎ ፡ ስብሐቲሁ ። በአናቅጺሃ ፡ ለወለተ ፡ ጽዮን ።"),
    (73, 1, "ዘበኣእምሮ ፡ ዘአሳፍ ። ለምንት ፡ ገደፍከኒ ፡ እግዚኦ ፡ ለዝሉፉ ፤ ወተመዓዕከ ፡ መዐተከ ፡ ላዕለ ፡ አባግዐ ፡ መርዔትከ ።"),
    (73, 2, "ተዘከር ፡ ማኅበረከ ፡ ዘአቅደምከ ፡ ፈጢረ ፡ ወአድኀንከ ፡ በትረ ፡ ርስትከ ፤ ደብረ ፡ ጽዮን ፡ ዘኀደርከ ፡ ውስቴታ ።"),
    (73, 3, "አንሥእ ፡ እዴከ ፡ ዲበ ፡ ትዕቢቶሙ ፡ ለዝሉፉ ፤ መጠነከ ፡ አሕሠመ ፡ ፀራዊ ፡ ዲበ ፡ ቅዱሳኒከ ።"),
    (73, 4, "ወተዘሀሩ ፡ ጸላእትከ ፡ በማእከለ ፡ በዓልከ ፤ ወረሰዩ ፡ ትእምርቶሙ ፡ ትእምርተ ፡ ዘኢያአምሩ ።"),
    (73, 5, "ከመ ፡ ዘውስተ ፡ ላዕላይ ፡ ፍኖት ፤"),
    (73, 6, "ወከመ ፡ ዕፀወ ፡ ገዳም ፡ በጕድብ ፡ ሰበሩ ፡ ኆኃቲሃ ። ከማሁ ፡ በማሕፄ ፡ ወበመፍጽሕ ፡ ሰበርዋ ።"),
    (73, 7, "ወአውዐዩ ፡ በእሳት ፡ መቅደሰከ ፤ ወአርኰሱ ፡ ማኅደረ ፡ ስምከ ፡ ውስተ ፡ ምድር ።"),
    (73, 8, "ወይቤሉ ፡ በልቦሙ ፡ ኀቢሮሙ ፡ በበሕዘቢሆሙ ፤ ንዑ ፡ ንስዐር ፡ ኵሎ ፡ በዓላቲሁ ፡ ለእግዚአብሔር ፡ እምድር ።"),
    (73, 9, "ወትእምርቶሂ ፡ ኢናአምር ፤ ወአልቦ ፡ እንከ ፡ ነቢየ ፤ ወንሕነሂ ፡ ኢናአምር ፡ እንከ ።"),
    (73, 10, "እስከ ፡ ማእዜኑ ፡ እንከ ፡ እግዚኦ ፡ ይጼእል ፡ ፀራዊ ፤ ወዘልፈ ፡ ያምዕዖ ፡ ለስምከ ፡ ጸላኢ ።"),
    (73, 11, "ለምንት ፡ እግዚኦ ፡ ትመይጥ ፡ እዴከ ፤ ወየማንከ ፡ ማእከለ ፡ ሕፅንከ ፡ ለግሙራ ።"),
    (73, 12, "ወእግዚአብሔር ፡ ንጉሥ ፡ ውእቱ ፡ እምቅድመ ፡ ዓለም ፤ ወገብረ ፡ መድኀኒተ ፡ በማእከለ ፡ ምድር ።"),
    (73, 13, "አንተ ፡ አጽናዕካ ፡ ለባሕር ፡ በኀይልከ ፤ አንተ ፡ ሰበርከ ፡ ርእሰ ፡ ከይሲ ፡ በውስተ ፡ ማይ ።"),
    (73, 14, "ወአንተ ፡ ቀጥቀጥከ ፡ አርእስቲሁ ፡ ለከይሲ ፤ ወወሀብኮሙ ፡ ሲሳዮሙ ፡ ለሕዝበ ፡ ኢትዮጵያ ።"),
    (73, 15, "አንተ ፡ ሰጠቀ ፡ አፍላገ ፡ ወአንቅዕት ፤ [አንተ ፡ ኢይበስኮሙ ፡ ለአፍላገ ፡ ኤታም ።]"),
    (73, 16, "ለከ ፡ ውእቱ ፡ መዐልት ፡ ወዚአከ ፡ ይእቲ ፡ ሌሊት ፤ አንተ ፡ ፈጠርከ ፡ ፀሐየ ፡ ወወርኀ ።"),
    (73, 17, "ወአንተ ፡ ገበርከ ፡ አድባረ ፡ ወምድረ ፡ ኵሎ ፤ ክረምተ ፡ ወሐጋየ ፡ አንተ ፡ ፈጠርከ ።"),
    (73, 18, "ወተዘከር ፡ ዘንተ ፡ ተግባረከ ፤ ፀራዊ ፡ ተዐየሮ ፡ ለእግዚአብሔር ፤ ወሕዝብ ፡ አብድ ፡ አምዕዖ ፡ ለስሙ ።"),
    (73, 19, "ኢትመጥዋ ፡ ለአራዊት ፡ ነፍሰ ፡ እንተ ፡ ትገኒ ፡ ለከ ፤ ወኢትርሳዕ ፡ ነፍሰ ፡ ነዳያኒከ ፡ ለዝሉፉ ።"),
    (73, 20, "ወነጽር ፡ ውስተ ፡ ሥርዐትከ ፤ እስመ ፡ በዝኁ ፡ ጽሉማነ ፡ ምድር ፡ አብያተ ፡ ኃጥኣን ።"),
    (73, 21, "ወኢይግባእ ፡ ነዳይ ፡ ተኀፊሮ ፤ ንዳይ ፡ ወምስኪን ፡ ይሴብሑ ፡ ለስምከ ።"),
    (73, 22, "ተንሥእ ፡ እግዚኦ ፡ ወተበቀል ፡ በቀልየ ፤ ወተዘከር ፡ ዘተዐየሩከ ፡ አብዳን ፡ ኵሎ ፡ አሚረ ።"),
    (73, 23, "ወኢትርሳዕ ፡ ቃለ ፡ አግብርቲከ ፤ ትዝህርቶሙ ፡ ለጸላእትከ ፡ ይዕረግ ፡ ኀቤከ ፡ በኵሉ ፡ ጊዜ ።"),
    (74, 1, "ፍጹሜ ፡ ኢታማስን ፡ መዝሙር ፡ ዘአሳፍ ፡ ማኅሌት ።"),
    (74, 2, "እገኒ ፡ ለከ ፡ እግዚኦ እገኒ ፡ ለከ ፡ ወእጼውዕ ፡ ስመከ ፤"),
    (74, 3, "ወእነግር ፡ ኵሎ ፡ ስብሐቲከ ። ሶበ ፡ ረከብኩ ፡ ጊዜሁ ፤ ወአንሰ ፡ ጽድቀ ፡ እኴንን ።"),
    (74, 4, "ተመስወት ፡ ምድር ፡ ወኵሎሙ ፡ እለ ፡ ይነብሩ ፡ ውስቴታ ፤ ወአነ ፡ አጽናዕኩ ፡ አዕማዲሃ ።"),
    (74, 5, "ወእቤሎሙ ፡ ላኃጥኣን ፡ ኢየአብሱ ፤ ወእለሂ ፡ ይኤብሱ ፡ ኢያንሥኡ ፡ ቀርኖሙ ።"),
    (74, 6, "ወኢያንሥኡ ፤ ቀርኖሙ ፡ ውስተ ፡ አርያም ፤ ወኢይንብቡ ፡ ዐመፃ ፡ ላዕለ ፡ እግዚአብሔር ።"),
    (74, 7, "እስመ ፡ ኢእምጽባሕ ፡ ወኢእምዐረብ ፡ ወኢእምአድባረ ፡ ገዳም ፡ እስመ ፡ እግዚአብሔር ፡ መኰንን ፡ ውእቱ ፤"),
    (74, 8, "ዘንተ ፡ ያኀስር ፡ ወዘንተ ፡ ያከብር ። እስመ ፡ ጽዋዕ ፡ ውስተ ፡ እደ ፡ እግዚአብሔር ፡ ወይን ፡ ዘኢኮነ ፡ ቱሱሐ ፡ ዘምሉእ ፡ ቅድሐቱ ፤"),
    (74, 9, "ወሶጦ ፡ እምዝንቱ ፡ ውስተ ፡ ዝንቱ ፤ ወባሕቱ ፡ ጣሕሉኒ ፡ ኢይትከዐው ፡ ወይሰትይዎ ፡ ኵሎሙ ፡ ኃጥኣነ ፡ ምድር ።"),
    (74, 10, "ወአንሰ ፡ እትፌሣሕ ፡ ለዓለም ፤ ወእዜምር ፡ ለአምላከ ፡ ያዕቆብ ።"),
    (74, 11, "ወእሰብር ፡ አቅርንተ ፡ ኃጥኣን ፤ ወይትሌዐል ፡ አቅርንተ ፡ ጻድቃን ።"),
    (75, 1, "ፍጻሜ ፡ ዘስብሐት ፡ መዝሙር ፡ ዘአሳፍ ፡ ማኅሌት ፡ ዘበእንተ ፡ አሶርዮን ።"),
    (75, 2, "ተዐውቀ ፡ እግዚአብሔር ፡ በይሁዳ ፤ ወዐቢይ ፡ ስሙ ፡ በእስራኤል ።"),
    (75, 3, "ወነበረ ፡ በሰላም ፡ ብሔሩ ፤ ወማኅደሩሂ ፡ ውስተ ፡ ጽዮን ።"),
    (75, 4, "ወበህየ ፡ ሰበረ ፡ ኀይለ ፡ ቀስት ፤ ወልታ ፡ ወኲናተ ፡ ወፀባኢተ ። [ወብህየ ፡ ሰበረ ፡ አቅርንተ ።]"),
    (75, 5, "አንተ ፡ ታበርህ ፡ ምንክረ ፤ እምአድባር ፡ ዘለዓለም ። ደንገፁ ፡ ኵሎሙ ፡ አብዳነ ፡ ልብ ፡"),
    (75, 6, "ሐለሙ ፡ ሕልመ ፡ ወአልቦ ፡ ዘረከቡ ፡ ኵሉ ፡ ሰብእ ፡ ለብዕለ ፡ እደዊሁ ።"),
    (75, 7, "እምተግሣጽከ ፡ አምላከ ፡ ያዕቆብ ፤ ደቀሱ ፡ ኵሎሙ ፡ እለ ፡ ይጼአኑ ፡ አፍራሰ ።"),
    (75, 8, "ወአንተሰ ፡ ግሩም ፡ አንተ ፤ ወመኑ ፡ ይትቃወሞ ፡ ለመዐትከ ።"),
    (75, 9, "እምሰማይ ፡ ታፀምእ ፡ ፍትሐ ፡ ምድርኒ ፡ ፈርሀት ፡ ወአርመመት ።"),
    (75, 10, "ሶበ ፡ ተንሥአ ፡ እግዚአብሔር ፡ ለኰንኖ ፤ ከመ ፡ ያድኅኖሙ ፡ ለኵሎሙ ፡ የዋሀነ ፡ ልብ ።"),
    (75, 11, "እስመ ፡ እምፈቃዱ ፡ የአምነከ ፡ ሰብእ ፤ ወእምተረፈ ፡ ሕሊናሁ ፡ ይገብር ፡ በዓለከ ።"),
    (75, 12, "ብፅኡ ፡ ወሀቡ ፡ ለእግዚአብሔር ፡ አምላክነ ፡ ወኵሎሙ ፡ እለ ፡ ፀውዱ ፡ ያበውኡ ፡ አምኃ ፡ ለግሩም ።"),
    (75, 13, "ዘያወፅእ ፡ ነፍሶሙ ፡ ለመላእክት ፤ ወይገርም ፡ እምነገሥተ ፡ ምድር ።"),
    (76, 1, "ፍጻሜ ፡ በእንተ ፡ ኢዶቱም ፡ መዝሙር ፡ ዘአሳፍ ።"),
    (76, 2, "ቃልየ ፡ ኀበ ፡ እግዚአብሔር ፡ ጸራኅኩ ፤ ቃልየ ፡ ኀበ ፡ እግዚአብሔር ፡ ወአፅምአኒ ።"),
    (76, 3, "በዕለተ ፡ ምንደቤየ ፡ ኀሠሥክዎ ፡ ለእግዚአብሔር ፤ እደውየ ፡ ሌሊተ ፡ ቅድሜሁ ፡ ወኢኬዱኒ ፤"),
    (76, 4, "ቀብጸት ፡ ነፍስየ ፡ ትፍሥሕተ ። ተዘከርክዎ ፡ ለእግዚአብሔር ፡ ወተፈሣሕኩ ፤ ተዛዋዕኩሂ ፡ ወዐንበዘት ፡ ነፍስየ ።"),
    (76, 5, "ተራከብክዎን ፡ ለሰዓታተ ፡ ኵሎሙ ፡ ጸላእትየ ፤ ደንገፅኩሂ ፡ ወኢነበብኩ ።"),
    (76, 6, "ወሐለይኩ ፡ መዋዕለ ፡ ትካት ፤ ወተዘከርኩ ፡ ዐመተ ፡ ዓለም ፡ ወአንበብኩ ።"),
    (76, 7, "ሌሊተ ፡ ተዛዋዕኩ ፡ ምስለ ፡ ልብየ ፡ ወአንቃክህዋ ፡ ለነፍስየ ።"),
    (76, 8, "ቦኑ ፡ ለዓለም ፡ ይገድፍ ፡ እግዚአብሔር ፤ ወኢይደግምኑ ፡ እንከ ፡ ተሣህሎ ።"),
    (76, 9, "ቦኑ ፡ ለግሙራ ፡ ይመትር ፡ ምሕረቶ ፡ ለትውልደ ፡ ትውልድ ።"),
    (76, 10, "ወይረስዕኑ ፡ እግዚአብሔር ፡ ተሣህሎ ፤ ወይደፍንኑ ፡ ምሕረቶ ፡ በመዐቱ ።"),
    (76, 11, "ወእቤ ፡ እምይእዜ ፡ ወጠንኩ ፤ ከመዝ ፡ ያስተባሪ ፡ የማኖ ፡ ልዑል ።"),
    (76, 12, "ወተዘከርኩ ፡ ግብሮ ፡ ለእግዚአብሔር ፤ እስመ ፡ እዜከር ፡ ዘትካት ፡ ምሕረትከ ።"),
    (76, 13, "ወኣነብብ ፡ በኵሉ ፡ ምግባሪከ ፤ ወእዛዋዕ ፡ በግብርከ ።"),
    (76, 14, "እግዚኦ ፡ ውስተ ፡ መቅደስ ፡ ፍኖትከ ፤ መኑ ፡ አምላክ ፡ ዐቢይ ፡ ከመ ፡ አምላክነ ።"),
    (76, 15, "አንተ ፡ እግዚአብሔር ፡ ባሕቲትከ ፡ ዘትገብር ፡ መንክረ ፤ አርአይኮሙ ፡ ለሕዝብከ ፡ ኀያለከ ።"),
    (76, 16, "ወአድኀንኮሙ ፡ ለሕዝብከ ፡ በመዝራዕትከ ፤ ለደቂቀ ፡ ያዕቆብ ፡ ወዮሴፍ ።"),
    (76, 17, "ርእዩከ ፡ ማያት ፡ እግዚኦ ፤ ርእዩከ ፡ ማያት ፡ ወፈርሁ ። ደንገፁ ፡ ቀላያት ፡ ማያት ፡ ወደምፁ ፡ ማያቲሆሙ ።"),
    (76, 18, "ቃለ ፡ ወሀቡ ፡ ደመናት ፡ ወአሕፃከ ፡ ያወፅኡ ።"),
    (76, 19, "ቃለ ፡ ነጐድጓድከ ፡ በሰረገላት ፤ አስተርአየ ፡ መባርቅቲሁ ፡ ለዓለም ፤ ርዕደት ፡ ወአድለቅለቀት ፡ ምድር ።"),
    (76, 20, "ውስተ ፡ ባሕር ፡ ፍኖትከ ፡ ወአሰርከኒ ፡ ውስተ ፡ ማይ ፡ ብዙኅ ፤ ወኢይትዐወቅ ፡ አሰርከ ።"),
    (76, 21, "ወመራሕኮሙ ፡ ከመ ፡ አባግዕ ፡ ለሕዝብከ ፤ በእደ ፡ ሙሴ ፡ ወአሮን ።"),
    (77, 1, "ዘበኣእምሮ ፡ ዘአሳፍ ። አፅምኡ ፡ ሕዝብየ ፡ ሕግየ ፤ ወጽልዉ ፡ እዝነክሙ ፡ ኀበ ፡ ቃለ ፡ አፉየ ።"),
    (77, 2, "እከሥት ፡ በምሳሌ ፡ አፉየ ፤ ወእነግር ፡ አምሳለ ፡ ዘእምትካት ።"),
    (77, 3, "ኵሎ ፡ ዘሰማዕነ ፡ ወዘርኢነ ፤ ወዘነገሩነ ፡ አበዊነ ።"),
    (77, 4, "ወኢኀብኡ ፡ እምደቂቆሙ ፡ ለካልእ ፡ ትውልድ ፡ ወነገሩ ፡ ስብሐቲሁ ፡ ለእግዚአብሔር ፤ ኀይሎሂ ፡ ወመንክሮሂ ፡ ዘገብረ ።"),
    (77, 5, "ዘአቀመ ፡ ስምዐ ፡ ለያዕቆብ ፡ ወሠርዐ ፡ ሕገ ፡ ለእስራኤል ፤ ዘአዘዞሙ ፡ ለአበዊነ ፡ ከመ ፡ ይንግሩ ፡ ለደቂቆሙ ።"),
    (77, 6, "ከመ ፡ ያእምር ፡ ካልእ ፡ ትውልድ ፤ ደቂቅ ፡ እለ ፡ ይትወለዱ ፡ ወይትነሥኡ ፡ ወይዜንዉ ፡ ለደቂቆሙ ።"),
    (77, 7, "ከመ ፡ ይረስዩ ፡ ትውክልቶሙ ፡ ላዕለ ፡ እግዚአብሔር ፤ ወከመ ፡ ኢይርስዑ ፡ ግብረ ፡ እግዚአብሔር ፡ ወይኅሥሡ ፡ ትእዛዞ ።"),
    (77, 8, "ከመ ፡ ኢይኩኑ ፡ ከመ ፡ አበዊሆሙ ፤ ትውልድ ፡ ዕሉት ፡ ወመራር ። ትውልድ ፡ እንተ ፡ ኢያርትዐት ፡ ልባ ፤ ወኢተአምነት ፡ መንፈሳ ፡ በእግዚአብሔር ።"),
    (77, 9, "ደቂቀ ፡ ኤፍሬም ፡ ይወስቁ ፡ ወይነድፉ ፤ ወተገፍትኡ ፡ አመ ፡ ዕለተ ፡ ቀትል ።"),
    (77, 10, "እስመ ፡ ኢዐቀቡ ፡ ኪዳኖ ፡ ለእግዚአብሔር ፤ ወአበዩ ፡ ሐዊረ ፡ በሕጉ ።"),
    (77, 11, "ወረስዑ ፡ ረድኤቶ ። ወመንክሮሂ ፡ ዘአርአዮሙ ።"),
    (77, 12, "ዘገብረ ፡ መንክረ ፡ በቅድመ ፡ አባዊሆሙ ፤ በምድረ ፡ ግብጽ ፡ ወበሐቀለ ፡ ጣኔዎስ ።"),
    (77, 13, "ሰጠቀ ፡ ባሕረ ፡ ወአኅለፎሙ ፤ ወአቀመ ፡ ማየ ፡ ከመ ፡ ዝቅ ።"),
    (77, 14, "ወመርሖሙ ፡ መዐልተ ፡ በደመና ፤ ወኵሎ ፡ ሌሊተ ፡ በብርሃነ ፡ እሳት ።"),
    (77, 15, "ወአንቅዐ ፡ ኰኵሐ ፡ በበድው ፤ ወአስተዮሙ ፡ ከመ ፡ ዘእምቀላይ ፡ ብዙኅ ።"),
    (77, 16, "ወአውፅአ ፡ ማየ ፡ እምእብን ፤ ወአውሐዘ ፡ ማየ ፡ ከመ ፡ ዘአፍላግ ።"),
    (77, 17, "ወደገሙ ፡ ዓዲ ፡ ወአበሱ ፡ ሎቱ ፤ ወአምረርዎ ፡ ለልዑል ፡ በበድው ።"),
    (77, 18, "ወአመከርዎ ፡ ለእግዚአብሔር ፡ በልቦሙ ፤ ከመ ፡ ይስአሉ ፡ መብልዐ ፡ ለነፍሶሙ ።"),
    (77, 19, "ሐመይዎ ፡ ለእግዚአብሔር ፡ ወይቤሉ ፤ ይክልኑ ፡ እግዚአብሔር ፡ ሠሪዐ ፡ ማእድ ፡ በገዳም ።"),
    (77, 20, "ይዝብጥ ፡ ኰኵሐ ፡ ወያውሕዝ ፡ ማየ ፤ ወይክልኑ ፡ ውሂበ ፡ ኅብስት ፡ ወይሥራዕ ፡ ማዕደ ፡ ለሕዝቡ ።"),
    (77, 21, "ወሰምዐ ፡ ዘንተ ፡ እግዚአብሔር ፡ ወአናሕሰየ ፤ ወነደ ፡ እሳት ፡ ላዕለ ፡ ያዕቆብ ፡ ወመጽአ ፡ መቅሠፍት ፡ ላዕለ ፡ እስራኤል ።"),
    (77, 22, "እስመ ፡ ኢተአመንዎ ፡ ለእግዚአብሔር ፤ ወኢተወከሉ ፡ በአድኅኖቱ ።"),
    (77, 23, "ወአዘዘ ፡ ደመና ፡ በላዕሉ ፤ ወአርኀወ ፡ ኆኃተ ፡ ሰማይ ።"),
    (77, 24, "ወአዝነመ ፡ ሎሙ ፡ መና ፡ ይብልዑ ፤ ወወሀቦሙ ፡ ኅብስተ ፡ ሰማይ ።"),
    (77, 25, "ወኅብስተ ፡ መላእክቲሁ ፡ በልዑ ፡ እጓለ ፡ እመሕያው ፤ ወፈነወ ፡ ሎሙ ፡ ሥንቆሙ ፡ ዘየአክሎሙ ።"),
    (77, 26, "ወአንሥአ ፡ አዜበ ፡ እምሰማይ ፤ ወአምጽአ ፡ መስዐ ፡ በኀይሉ ።"),
    (77, 27, "ወአዝነመ ፡ ላዕሌሆሙ ፡ ሥጋ ፡ ከመ ፡ መሬት ፤ ወከመ ፡ ኆጻ ፡ ባሕር ፡ አዕዋፈ ፡ ዘይሠርር ።"),
    (77, 28, "ወወድቀ ፡ ማእከለ ፡ ተዓይኒሆሙ ፤ ወዐውደ ፡ ደባትሪሆሙ ።"),
    (77, 29, "በልዑ ፡ ወጸግቡ ፡ ጥቀ ፤ ወወሀቦሙ ፡ ለፍትወቶሙ ።"),
    (77, 30, "ወኢያኅጥኦሙ ፡ እምዘ ፡ ፈቀዱ ። ወእንዘ ፡ ዓዲ ፡ መብልዖሙ ፡ ውስተ ፡ አፉሆሙ ፤"),
    (77, 31, "ወመጽአ ፡ መቅሠፍተ ፡ እግዚአብሔር ፡ ላዕሌሆሙ ፡ ወቀተሎሙ ፡ መብዝኅቶሙ ፤ ወአዕቀጾሙ ፡ ለኅሩያነ ፡ እስራኤል ።"),
    (77, 32, "ወምስለ ፡ ዝኒ ፡ ዓዲ ፡ አበሱ ፡ ሎቱ ፤ ወኢተአመንዎ ፡ በተአምሪሁ ።"),
    (77, 33, "ወኀልቀ ፡ በከንቱ ፡ መዋዕሊሆሙ ፤ ወኀለፈ ፡ በጕጕኣ ፡ ዐመቲሆሙ ።"),
    (77, 34, "ወአመ ፡ ይቀትሎሙ ፡ ውእተ ፡ አሚረ ፡ ይኀሥዎ ፤ ወይትመየጡ ፡ ወይገይሱ ፡ ኀበ ፡ እግዚአብሔር ።"),
    (77, 35, "ወተዘከሩ ፡ ከመ ፡ እግዚአብሔር ፡ ውእቱ ፡ ረዳኢሆሙ ፤ ወእግዚአብሔር ፡ ልዑል ፡ መድኀኒሆሙ ።"),
    (77, 36, "ወአፍቀረዎ ፡ በአፉሆሙ ፤ ወሐሰውዎ ፡ በልሳኖሙ ።"),
    (77, 37, "ወኢኮነ ፡ ርቱዐ ፡ ልቦሙ ፡ በላዕሌሆሙ ፤ ወኢተአመንዎ ፡ በኪዳኑ ።"),
    (77, 38, "ወውእቱሰ ፡ መሓሪ ፡ ውእቱ ፡ ወይሰሪ ፡ ሎሙ ፡ ኵሎ ፡ ኃጢአቶሙ ፡ ወኢያጠፍኦሙ ። ወያበዝኅ ፡ መዪጠ ፡ መዐቱ ፡ ወኢያነድድ ፡ በኵሉ ፡ መቅሠፍቱ ።"),
    (77, 39, "ወተዘከረ ፡ ከመ ፡ ሥጋ ፡ እሙንቱ ፤ መንፈስ ፡ እምከመ ፡ ወፅአ ፡ ኢይገብእ ።"),
    (77, 40, "ሚመጠነ ፡ አምዕዕዎ ፡ በገዳም ፡ ወወሐክዎ ፡ በበድው ።"),
    (77, 41, "ወተመይጡ ፡ ወአመከርዎ ፡ ለእግዚአብሔር ፤ ወወሐክዎ ፡ ለቅዱሰ ፡ እስራኤል ።"),
    (77, 42, "ወኢተዘከሩ ፡ እዴሁ ፤ ዘአድኀኖሙ ፡ እምእደ ፡ ፀሮሙ ።"),
    (77, 43, "ዘገብረ ፡ ተአምረ ፡ በግብጽ ፤ ወመንክረ ፡ በሐቅለ ፡ ጣኔዎስ ።"),
    (77, 44, "ወረሰየ ፡ ደመ ፡ ለአፍላጊሆሙ ፤ ወለአንቅዕቲሆሙኒ ፡ ከመ ፡ ኢይስተዩ ።"),
    (77, 45, "ፈነወ ፡ ላዕሌሆሙ ፡ አኮተ ፡ ወበልዖሙ ፤ ወቈርነነዓተ ፡ ወአርኰሶሙ ።"),
    (77, 46, "ወወሀበ ፡ ለአናኵዕ ፡ ፍሬሆሙ ፤ ወተግባሮሙኒ ፡ ለአንበጣ ።"),
    (77, 47, "ወቀተለ ፡ ወይኖሙ ፡ በበረድ ፤ ወበለሶሙኒ ፡ በአስሐትያ ።"),
    (77, 48, "ወወሀበ ፡ ለበረድ ፡ እንስሳሆሙ ፤ ወንዋዮሙኒ ፡ ለእሳት ።"),
    (77, 49, "ፈነወ ፡ ላዕሌሆሙ ፡ መቅሠፍተ ፡ መዐቱ ፤ መቅሠፍተ ፡ ወመንሱተ ፡ ወሕማመ ፤ ወፈነወ ፡ ምስለ ፡ መላእክት ፡ እኩያን ።"),
    (77, 50, "ወጼሐ ፡ ፍኖተ ፡ ለመዐቱ ፤ ወኢመሐካ ፡ እሞት ፡ ለነፍሶሙ ፤ ወዐጸወ ፡ ውስተ ፡ ሞት ፡ እንስሳሆሙ ።"),
    (77, 51, "ወቀተለ ፡ ኵሎ ፡ በኵሮሙ ፡ በምድረ ፡ ግብጽ ፤ ወቀዳሜ ፡ ኵሎ ፡ ጻማሆሙ ፡ በውስተ ፡ አብያቲሆሙ ።"),
    (77, 52, "ወአውፈሮሙ ፡ ከመ ፡ አባግዕ ፡ ለሕዝቡ ፤ ወአውፅኦሙ ፡ ገዳመ ፡ ከመ ፡ መርዔት ።"),
    (77, 53, "ወመርሖሙ ፡ በተስፋሁ ፡ ወኢፈርሁ ፤ ወደፈኖሙ ፡ ባሕር ፡ ለፀሮሙ ።"),
    (77, 54, "ወወሰዶሙ ፡ ደብረ ፡ መቅደሱ ፤ ደብረ ፡ ዘፈጠረት ፡ የማኑ ።"),
    (77, 55, "ወሰደደ ፡ አሕዛበ ፡ እምቅድመ ፡ ገጾሙ ፡ ወአውረሶሙ ፡ በሐብለ ፡ ርስቱ ፤ ወአንበረ ፡ ውስተ ፡ አብያቲሆሙ ፡ ሕዝበ ፡ እስራኤል ።"),
    (77, 56, "ወአመከርዎ ፡ ወአምዕዕዎ ፡ ለእግዚአብሔር ፡ ልዑል ፤ ወኢዐቀቡ ፡ ስምዖ ።"),
    (77, 57, "ወተመይጡ ፡ ወዐለዉ ፡ ከመ ፡ አበዊሆሙ ፤ ወኮኑ ፡ ከመ ፡ ቀስት ፡ ጠዋይ ።"),
    (77, 58, "ወአምዕዕዎ ፡ በአውገሪሆሙ ፤ ወኣቅንእዎ ፡ በግልፎሆሙ ።"),
    (77, 59, "ወሰምዐ ፡ እግዚአብሔር ፡ ወአናሕሰየ ፤ ወመነኖሙ ፡ ለእስራኤል ፡ ፈድፋደ ።"),
    (77, 60, "ወኀደጋ ፡ ለደብተራ ፡ ሴሎም ፤ ደብተራሁ ፡ እንተ ፡ ባቲ ፡ ኀደረ ፡ ምስለ ፡ ሰብእ ።"),
    (77, 61, "ወወሀበ ፡ ኀይሎሙ ፡ ለተፄውዎ ፤ ወሥኖሙኒ ፡ ውስተ ፡ እደ ፡ ፀሮሙ ።"),
    (77, 62, "ወዐጸዎሙ ፡ ውስተ ፡ ኲናት ፡ ለሕዝቡ ፤ ወተሀየዮሙ ፡ ለርስቱ ።"),
    (77, 63, "ወበልዐቶሙ ፡ እሳት ፡ ለወራዙቶሙ ፤ ወኢላሐዋ ፡ ደናግሊሆሙ ።"),
    (77, 64, "ወካህናቲሆሙኒ ፡ ወድቁ ፡ በኲናት ፤ ወኢበከያ ፡ አቤራቲሆሙ ።"),
    (77, 65, "ወተንሥአ ፡ እግዚአብሔር ፡ ከመ ፡ ዘንቃህ ፡ እምንዋም ፤ ወከመ ፡ ኀያል ፡ ወኅዳገ ፡ ወይን ።"),
    (77, 66, "ወቀተለ ፡ ፀሮሙ ፡ በዳኅሬሆሙ ፤ ወወሀቦሙ ፡ ኀሳረ ፡ ዘለዓለም ።"),
    (77, 67, "ወኀደጋ ፡ ለደብተራ ፡ ዮሴፍ ፤ ወኢኀረዮሙ ፡ ለሕዝበ ፡ ኤፍሬም ።"),
    (77, 68, "ወኀረየ ፡ ለሕዝበ ፡ ይሁዳ ፤ ደብረ ፡ ጽዮን ፡ ዘአፍቀረ ።"),
    (77, 69, "ሐነጸ ፡ መቅደሶ ፡ በአርያም ፤ ወሳረራ ፡ ውስተ ፡ ምድር ፡ ለዓለም ።"),
    (77, 70, "ወኀረዮ ፡ ለዳዊት ፡ ገብሩ ፤ ወነሥኦ ፡ እመርዔተ ፡ አባግዒሁ ። ወተመጠዎ ፡ እምድኅረ ፡ ሐራሣት ፤"),
    (77, 71, "ከመ ፡ ይርዐዮ ፡ ለያዕቆብ ፡ ገብሩ ፤ ወለእስራኤል ፡ ርስቱ ።"),
    (77, 72, "ወርዕዮሙ ፡ በየዋሃተ ፡ ልቡ ፤ ወመርሖሙ ፡ በጥበበ ፡ እደዊሁ ።"),
    (
        78,
        1,
        "መዝሙር ፡ ዘአሳፍ ። እግዚኦ ፡ ቦኡ ፡ አሕዛብ ፡ ውስተ ፡ ርስትከ ፡ ወአርኰሱ ፡ ጽርሐ ፡ መቅደስከ ፤ ወረሰይዋ ፡ ለኢየሩሳሌም ፡ ከመ ፡ ልገተ ፡ ዐቃቤ ፡ ቀምሕ ።",
    ),
    (78, 2, "ወረሰዩ ፡ አብድንቲሆሙ ፡ ለአግብርቲከ ፡ መብልዖሙ ፡ ለአዕዋፈ ፡ ሰማይ ፤ ወሥጋሆሙኒ ፡ ለጻድቃኒከ ፡ ለአረዊተ ፡ ገዳም ።"),
    (78, 3, "ከዐዉ ፡ ደሞሙ ፡ ከመ ፡ ማይ ፡ ዐውዳ ፡ ለኢየሩሳሌም ፤ ወኀጥኡ ፡ ዘይቀብሮሙ ።"),
    (78, 4, "ወኮነ ፡ ጽእለተ ፡ ለጎርነ ፤ ሣሕቀ ፡ ወስላቀ ፡ ለአድያሚነ ።"),
    (78, 5, "እስከ ፡ ማእዜኑ ፡ እግዚኦ ፡ ትትመዓዕ ፡ ለዝሉፉ ፤ ወይነድድ ፡ ከመ ፡ እሳት ፡ ቅንአትከ ።"),
    (78, 6, "ከዐው ፡ መዐተከ ፡ ላዕለ ፡ አሕዛብ ፡ እለ ፡ ኢያአምሩከ ፤ ወላዕለ ፡ መንግሥት ፡ እንተ ፡ ኢጸውዐት ፡ ስመከ ።"),
    (78, 7, "እስመ ፡ በልዕዎ ፡ ለያዕቆብ ፤ ወአማሰኑ ፡ ብሔሮ ።"),
    (78, 8, "ኢትዝክር ፡ ለነ ፡ አበሳነ ፡ ዘትካት ፤ ፍጡነ ፡ ይርከበነ ፡ ሣህልከ ፡ እግዚኦ ፤ እስመ ፡ ተመንደብነ ፡ ፈድፋደ ።"),
    (78, 9, "ርድአነ ፡ አምላክነ ፡ ወመድኀኒነ ፡ በእንተ ፡ ስብሐተ ፡ ስምከ ፤ እግዚኦ ፡ ባልሐነ ፡ ወስረይ ፡ ኀጢአተነ ፡ በእንተ ፡ ስምከ ።"),
    (78, 10, "ከመ ፡ ኢይበሉነ ፡ አሕዛብ ፡ አይቴ ፡ ውእቱ ፡ አምላኮሙ ። ወይርአዩ ፡ አሕዛብ ፡ በቅድመ ፡ አዕይንቲነ ፡ በቀለ ፡ ደሞሙ ፡ ለአግብርቲከ ፡ ዘተክዕወ ።"),
    (78, 11, "ይባእ ፡ ቅድሜከ ፡ ገዐሮሙ ፡ ለሙቁሓን ፤ ወበከመ ፡ ዕበየ ፡ መዝራዕትከ ፡ ተሣሀሎሙ ፡ ለደቂቀ ፡ ቅቱላን ።"),
    (78, 12, "ፍድዮሙ ፡ ለጎርነ ፡ ምስብዒተ ፡ ውስተ ፡ ሕፅኖሙ ፤ ትዕይርቶሙ ፡ ዘተዐየሩከ ፡ እግዚኦ ።"),
    (78, 13, "ወንሕነሰ ፡ ሕዝብከ ፡ ወአባግዐ ፡ መርዔትከ ፡ ንገኒ ፡ ለከ ፡ ለዓለም ። ወንነግር ፡ ስብሐቲከ ፡ ለትውልደ ፡ ትውልድ ።"),
    (79, 1, "ፍጻሜ ፡ ዘበእንተ ፡ እለ ፡ ተበዐዱ ፤ ስምዕ ፡ ዘአሳፍ ፡ መዝሙር ፡ ዘበእንተ ፡ አሶርዮን ።"),
    (79, 2, "ኖላዊሆሙ ፡ ለእስራኤል ፡ አፅምእ ፤ ዘይርዕዮሙ ፡ ከመ ፡ አባግዕ ፡ ለዮሴፍ ። ዘይነብር ፡ ላዕለ ፡ ኪሩቤል ፡ አስተርአየ ።"),
    (79, 3, "በቅድመ ፡ ኤፍሬም ፡ ወብንያም ፡ ወምናሴ ፡ አንሥእ ፡ ኀይለከ ፤ ወነዐ ፡ አድኅነነ ።"),
    (79, 4, "አምላከ ፡ ኀያላን ፡ ሚጠነ ፤ አብርህ ፡ ገጸከ ፡ ላዕሌነ ፡ ወንድኀን ።"),
    (79, 5, "እግዚኦ ፡ አምላከ ፡ ኀያላን ፡ እስከ ፡ ማእዜኑ ፡ ትትመዓዕ ፡ ላዕለ ፡ ጸሎተ ፡ ገብርከ ።"),
    (79, 6, "ወትሴስየነ ፡ እክለ ፡ እንብዕነ ፤ ወታሰትየነ ፡ አንብዐነ ፡ በመስፈርት ።"),
    (79, 7, "ወረሰይከነ ፡ ነገሩ ፡ ለጎርነ ፤ ወተሳለቁ ፡ ላዕሌነ ፡ ጸላእትነ ።"),
    (79, 8, "እግዚኦ ፡ አምላከ ፡ ኀያላን ፡ ሚጠነ ፤ አብርህ ፡ ገጸከ ፡ ላዕሌነ ፡ ወንድኀን ።"),
    (79, 9, "ዐጸደ ፡ ወይን ፡ አፍለስከ ፡ እምግብጽ ፤ ሰደድከ ፡ አሕዛብ ፡ ወተከልከ ፡ ኪያሃ ።"),
    (79, 10, "ወጼሕከ ፡ ፍኖተ ፡ ቅድሜሃ ፤ ወተከልከ፡ ሥረዊሃ ፡ ወመልአት ፡ ምድረ ።"),
    (79, 11, "ወከደነ ፡ አድባረ ፡ ጽላሎታ ፤ ወአዕጹቂሃኒ ፡ ከመ ፡ አርዘ ፡ እግዚአብሔር ።"),
    (79, 12, "ወሰፍሐ ፡ አዕጹቂሃ ፡ እስከ ፡ ባሕር ፤ ወእስከ ፡ አፍላግ ፡ ሠርፃ ።"),
    (79, 13, "ለምንት ፡ ትነሥት ፡ ፀቈና ፤ ወይበልዓ ፡ ኵሉ ፡ ኀላፌ ፡ ፍኖት ።"),
    (79, 14, "ወአርኰሳ ፡ ሐራውያ ፡ ሐቅል ፤ ወተርዕያ ፡ እንስሳ ፡ ገዳም ።"),
    (79, 15, "አምላከ ፡ ኀያላን ፡ ተመየጥሶ ፤ ሐውጽ ፡ እምሰማይ ፡ ወርኢ ፡ ወተሣሀላ ፡ ለዛ ፡ ዐጸደ ፡ ወይን ።"),
    (79, 16, "ወአስተናሥኣ ፡ ወአጽንዓ ፡ ዘተከለት ፡ የማንከ ፤ በወልደ ፡ እጓለ ፡ እመሕያው ፡ ዘአጽናዕከ ፡ ለከ ።"),
    (79, 17, "ለውዒት ፡ በእሳት ፡ ወምልኅት ፤ ወእምተግሣጸ ፡ ገጽከ ፡ ይትሐጐሉ ።"),
    (79, 18, "ለይኩን ፡ እዴከ ፡ ላዕለ ፡ ብእሴ ፡ የማንከ ፤ በወልደ ፡ እጓለ ፡ እመሕያው ፡ ዘአጽናዕከ ፡ ለከ ።"),
    (79, 19, "ወኢንርሐቅ ፡ እምኔከ ፤ ኣሕይወነ ፡ ወንጼውዕ ፡ ስመከ ።"),
    (79, 20, "እግዚኦ ፡ አምላከ ፡ ኀያላን ፡ ሚጠነ ፤ አብርህ ፡ ገጸከ ፡ ላዕሌነ ፡ ወንድኀን ።"),
    (80, 1, "ፍጻሜ ፡ ዘበእንተ ፡ ማኅበብት ፡ ዘአሳፍ ፡ መዝሙር ፡ ዘኃምስቱ ፡ ሰንበት ።"),
    (80, 2, "ተፈሥሑ ፡ ለእግዚአብሔር ፡ ዘረድአነ ፤ ወየብቡ ፡ ለአምላከ ፡ ያዕቆብ ።"),
    (80, 3, "ንሥኡ ፡ መዝሙር ፡ ወሀቡ ፡ ከበሮ ፤ መዝሙር፡ ሐዋዝ ፡ ምስለ ፡ መሰንቆ ።"),
    (80, 4, "ንፍኁ ፡ ቀርነ ፡ በዕለተ ፡ ሠርቅ ፤ በእምርት ፡ ዕለት ፡ በዓልነ ።"),
    (80, 5, "እስመ ፡ ሥርዐቱ ፡ ለእስራኤል ፡ ውእቱ ፤ ወፍትሑ ፡ ለአምላከ ፡ ያዕቆብ ።"),
    (80, 6, "ወአቀመ ፡ ስምዐ ፡ ለዮሴፍ ፡ አመ ፡ የሐውር ፡ ብሔረ ፡ ግብጽ ፤ ወሰምዐ ፡ ልሳነ ፡ ዘኢያአምር ።"),
    (80, 7, "ወሜጠ ፡ ዘባኖ ፡ እምሕራማቲሆሙ ፤ ወተቀንያ ፡ እደዊሁ ፡ ውስተ ፡ አክፋር ።"),
    (80, 8, "ወምንዳቤከ ፡ ጸዋዕከኒ ፡ ወአድኀንኩከ ፤ ወተሰጠውኩከ ፡ በዐውሎ ፡ ኅቡእ ፡ ወአመከርኩከ ፡ በኀበ ፡ ማየ ፡ ቅሥት ።"),
    (80, 9, "ስምዐኒ ፡ ሕዝብየ ፡ ወእንግርከ ፤ እስራኤል ፡ ወኣስምዕ ፡ ለከ ።"),
    (80, 10, "እመሰ ፡ ሰማዕከኒ ፡ ኢይከውነከ ፡ አምላከ ፡ ግብት ፤ ወኢትስግድ ፡ ለአምላክ ፡ ነኪር ።"),
    (80, 11, "እስመ ፡ አነ ፡ ውእቱ ፡ እግዚአብሔር ፡ አምላክከ ፡ ዘአውፃእኩከ ፡ እምድረ ፡ ግብጽ ፤ አርሕብ ፡ አፉከ ፡ ወእነልኦ ፡ ለከ ።"),
    (80, 12, "ወኢሰምዑኒ ፡ ሕዝብየ ፡ ቃልየ ፤ ወእስራኤልኒ ፡ ኢያፅምኡኒ ።"),
    (80, 13, "ወፈነውኩ ፡ ሎሙ ፡ በከመ ፡ ምግባሮሙ ፤ ወሖሩ ፡ በሕሊና ፡ ልቦመ ።"),
    (80, 14, "ሶበሰ ፡ ሰምዑኒ ፡ ሕዝብየ ፡ ቃልየ ፤ ወእስራኤልኒ ፡ ሶበ ፡ ሖሩ ፡ በፍኖትየ ።"),
    (80, 15, "እምአኅሰርክዎሙ ፡ በኵሉ ፡ ለጸላእቶሙ ፤ ወእምወደይኩ ፡ እዴየ ፡ ዲበ ፡ እለ ፡ ይሣቅይዎሙ ።"),
    (80, 16, "ጸላእቱሰ ፡ ለእግዚአብሔር ፡ ሐሰውዎ ፤ ወይከውን ፡ ጊዜሆሙ ፡ እስከ ፡ ለዓለም ።"),
    (80, 17, "ወሴሰዮሙ ፡ ሥብሐ ፡ ስርናይ ፤ ወአጽገቦሙ ፡ መዓረ ፡ እምኰኵሕ ።"),
    (81, 1, "መዝሙር ፡ ዘአሳፍ ። እግዚአብሔር ፡ ቆመ ፡ ውስተ ፡ ማኅበረ ፡ አማልክት ፤ ወይኴንን ፡ በማእከለ ፡ አማልክት ።"),
    (81, 2, "እስከ ፡ ማእዜኑ ፡ ትኴንኑ ፡ ዐመፃ ፤ ወታደልዉ ፡ ለገጸ ፡ ኃጥአን ።"),
    (81, 3, "ፍትሑ ፡ ለነዳይ ፡ ወለእጓለ ፡ ማውታ ፤ ወአጽድቁ ፡ ግፉዐ ፡ ወምስኪነ ።"),
    (81, 4, "ወአድኅኑ ፡ ባሕታዌ ፡ ወጽኑሰ ፤ ወአንግፍዎሙ ፡ እምእደ ፡ ኃጥአን ።"),
    (81, 5, "ኢያእመሩ ፡ ወኢለበዉ ፡ ውስተ ፡ ጽልመት ፡ የሐውሩ ፤ ወያድለቀልቁ ፡ ኵሉ ፡ መሰረታተ ፡ አድባር ።"),
    (81, 6, "አንሰ ፡ እቤ ፡ አማልክት ፡ አንትሙ ፤ ወደቂቀ ፡ ልዑል ፡ ኵልክሙ ፡"),
    (81, 7, "አንትሙሰ ፡ ከመ ፡ ሰብእ ፡ ትመውቱ ፤ ወከመ ፡ አሐዱ ፡ እመላእክት ፡ ትወድቁ ።"),
    (81, 8, "ተንሥእ ፡ እግዚኦ ፡ ወኰንና ፡ ለምድር ፤ እስመ ፡ እንተ ፡ ትወርስ ፡ በኵሉ ፡ አሕዛብ ።"),
    (82, 1, "ማኅሌት ፡ መዝሙር ፡ ዘአሳፍ ።"),
    (82, 2, "እግዚኦ ፡ መኑ ፡ ከማከ ፤ ኢታርምም ፡ ወኢትጸመም ፡ እግዚኦ ።"),
    (82, 3, "እስመ ፡ ናሁ ፡ ወውዑ ፡ ፀርከ ፤ ወአንሥኡ ፡ ርእሶሙ ፡ ጸላእትከ ።"),
    (82, 4, "ወተጓሕለውዎሙ ፡ ምክረ ፡ ለሕዝብከ ፤ ወተማከሩ ፡ ዲበ ፡ ቅዱሳኒከ ።"),
    (82, 5, "ወይቤሉ ፡ ንዑ ፡ ንሥርዎሙ ፡ እምአሕዛብ ፤ ወኢይዝክሩ ፡ እንከ ፡ ስመ ፡ እስራኤል ።"),
    (82, 6, "እስመ ፡ ተማከሩ ፡ ኅቡረ ፡ ወዐረዩ ፤ ላዕሌከ ፡ ተሰካተዩ ፡ ወተካየዱ ።"),
    (82, 7, "ተዓይኒሆሙ ፡ ለኢዶምያስ ፡ ወለእስማኤላውያን ፤ ሞአብ ፡ ወአጋራውያን ።"),
    (82, 8, "ጌባል ፡ ወአሞን ፡ ወአማሌቅ ፤ ወአሎፍሊ ፡ ምስለ ፡ ሰብአ ፡ ጢሮስ ።"),
    (82, 9, "ወአሶርሂ ፡ ኀበረ ፡ ምስሌሆሙ ፤ ወኮንዎሙ ፡ ረድኤተ ፡ ለደቂቀ ፡ ሎጥ ።"),
    (82, 10, "ረስዮሙ ፡ ከመ ፡ ምድያም ፡ ወሲሳራ ፤ ወከመ ፡ ኢያቤስ ፡ በፈለገ ፡ ቂሶን ።"),
    (82, 11, "ወይሠረዉ ፡ ከመ ፡ እለ ፡ እንዶር ፤ ወይኩኑ ፡ ከመ ፡ መሬተ ፡ ምድር ።"),
    (82, 12, "ረስዮሙ ፡ ለመላእክቲሆሙ ፡ ከመ ፡ ሆሬብ ፡ ወዜብ ፤ ወዜብሄል ፡ ወሰልማና ፡ ወኵሎሙ ፡ መላእክቲሆሙ ።"),
    (82, 13, "እለ ፡ ይብሉ ፡ ንወርስ ፡ ምስዋዒሁ ፡ ለእግዚአብሔር ።"),
    (82, 14, "አምላኪየ ፡ ረስዮሙ ፡ ከመ ፡ መንኰራኵር ፤ ወከመ ፡ ሣዕር ፡ ዘቅድመ ፡ ገጸ ፡ እሳት ።"),
    (82, 15, "ወከመ ፡ እሳት ፡ ዘያውዒ ፡ ገዳመ ፤ ወከመ ፡ ነበልባል ፡ ዘያነድድ ፡ አድባረ ።"),
    (82, 16, "ከማሁ ፡ ስድዶሙ ፡ በዐውሎከ ፤ ወሁኮሙ ፡ በመቅሠፍትከ ።"),
    (82, 17, "ምላእ ፡ ውስተ ፡ ገጾሙ ፡ ኀሳረ ፤ ወያእምሩ ፡ ስመከ ፡ እግዚኦ ።"),
    (82, 18, "ይትኀፈሩ ፡ ወይትሀወኩ ፡ ለዓለመ ፡ ዓለም ፤ ወይኅሰሩ ፡ ወይትሐጐሉ ።"),
    (82, 19, "ወያእምሩ ፡ ስመከ ፡ እግዚኦ ፤ ከመ ፡ አንተ ፡ ባሕቲትከ ፡ ልዑል ፡ ዲበ ፡ ኵሉ ፡ ምድር ።"),
    (83, 1, "ፍጻሜ ፡ ዘበእንተ ፡ ማኅበብት ፤ ዘደቂቀ ፡ ቆሬ ፡ መዝሙር ።"),
    (83, 2, "ጥቅ ፡ ፍቁር ፡ አብያቲከ ፡ እግዚአ ፡ ኀያላን ።"),
    (83, 3, "ተፈሥሐት ፡ ነፍስየ ፡ በአፍቅሮ ፡ አዕጻዲከ ፡ እግዚኦ ። ልብየኒ ፡ ወሥጋየኒ ፡ ተፈሥሐ ፡ በእግዚአብሔር ፡ ሕያው ።"),
    (83, 4, "ዖፍኒ ፡ ረከበት ፡ ላቲ ፡ ቤተ ፡ ወማዕነቅኒ ፡ ኀበ ፡ ታነብር ፡ እጐሊሃ ፤ ምሥዋዒከ ፡ እግዚአ ፡ ኀያላን ፡ ንጉሥየኒ ፡ ወአምላኪየኒ ።"),
    (83, 5, "ብፁዓን ፡ ኵሎሙ ፡ እለ ፡ ይነብሩ ፡ ውስተ ፡ ቤትከ ፤ ወለዓለመ ፡ ዓለም ፡ ይሴብሑከ ።"),
    (83, 6, "ብፁዕ ፡ ብእሲ ፡ ዘእምኀቤከ ፡ ረድኤቱ ፡ እግዚኦ ፤ ወዘይሔሊ ፡ በልቡ ፡ ዘበላዕሉ ።"),
    (83, 7, "ውስተ ፡ ቈላተ ፡ ብካይ ፡ ብሔር ፡ ኀበ ፡ ሠራዕኮሙ ፤ እስመ ፡ መምህረ ፡ ሕግ ፡ ይሁብ ፡ በረከተ ።"),
    (83, 8, "ወይሐውር ፡ እምኀይል ፡ ውስተ ፡ ኀይል ፤ ወያስተርኢ ፡ አምላከ ፡ አማልክት ፡ በጽዮን ።"),
    (83, 9, "እግዚኦ ፡ አምላከ ፡ ኀያላን ፡ ስምዐኒ ፡ ጸሎትየ ፤ ወአፅምአኒ ፡ አምላኩ ፡ ለያዕቆብ ።"),
    (83, 10, "ወርእየኒ ፡ እግዚኦ ፡ ተአምኖትየ ፤ ወነጽር ፡ ኀበ ፡ ገጸ ፡ መሲሕከ ።"),
    (
        83,
        11,
        "እስመ ፡ ትኄይስ ፡ አሐቲ ፡ ዕለት ፡ ውስተ ፡ አዕጻዲከ ፡ እምአእላፍ ፤ አብደርኩ ፡ እትገደፍ ፡ ውስተ ፡ በተ ፡ እግዚአብሔር ፡ እምእንበር ፡ ውስተ ፡ ቤተ ፡ ኃጥኣን ።",
    ),
    (
        83,
        12,
        "እስመ ፡ ጽድቀ ፡ ወምጽዋተ ፡ ያበድር ፡ እግዚአብሔር ፤ እግዚአብሔር ፡ ይሁብ ፡ ክብረ ፡ ወሞገሰ ፤ እግዚአብሔር ፡ ኢያስተጼንሶሙ ፡ እምበረከቱ ፡ ለእለ ፡ ይሐውሩ ፡ በየዋሃት ።",
    ),
    (83, 13, "እግዚኦ ፡ አምላከ ፡ ኀያለን ፤ ብፁዕ ፡ ብእሲ ፡ ዘተወከለ ፡ ኪያከ ።"),
    (84, 1, "ፍጻሜ ፡ ዘደቂቀ ፡ ቆሬ ፡ መዝሙር ፡ ጸሎት ፡ ዘዳዊት ።"),
    (84, 2, "ተሣሀልከ ፡ እግዚኦ ፡ ምድረከ ፤ ወሜጥከ ፡ ፄዋሁ ፡ ለያዕቆብ ።"),
    (84, 3, "ወኀደገ ፡ ኃጢአቶሙ ፡ ለሕዝብከ ፤ ወከደንከ ፡ ኵሎ ፡ አበሳሆሙ ።"),
    (84, 4, "ወኀደገ ፡ ኵሎ ፡ መዐትከ ። ወሜጥከ ፡ መቅሠፍተ ፡ መዐተከ ።"),
    (84, 5, "ሚጠነ ፡ አምላክነ ፡ ወመድኀኒነ ፤ ወሚጥ ፡ መዐተከ ፡ እምኔነ ።"),
    (84, 6, "ወለዓለምሰ ፡ ኢትትመዐዐነ ። ወኢታኑኅ ፡ መዐተከ ፡ ላዕለ ፡ ትውልደ ፡ ትውልድ ።"),
    (84, 7, "አንተ ፡ አምላክነ ፡ ተመየጠነ ፡ ወኣሕይወነ ፤ ወሕዝብከኒ ፡ ይትፌሥሑ ፡ ብከ ።"),
    (84, 8, "አርእየነ ፡ እግዚኦ ፡ ሣህለከ ፤ ወሀበነ ፡ አምላክነ ፡ አድኅኖተከ ።"),
    (
        84,
        9,
        "ኣፀምእ ፡ ዘይነበኒ ፡ እግዚአብሔር ፡ አምላኪየ ፤ እስመ ፡ ይነብብ ፡ ሰላመ ፡ ላዕለ ፡ ሕዝቡ ፡ ላዕለ ፡ ጻድቃኑ ፡ ወላዕለ ፡ እለ ፡ ይመይጡ ፡ ልቦሙ ፡ ኀቤሁ ።",
    ),
    (84, 10, "ወባሕቱ ፡ ቅሩብ ፡ አድኅኖቱ ፡ ለእለ ፡ ይፈርህዎ ፤ ከመ ፡ ይኅድር ፡ ስብሐቲሁ ፡ ውስተ ፡ ምድርነ ።"),
    (84, 11, "ሣህል ፡ ወርትዕ ፡ ተራከባ ፤ ጽድቅ ፡ ወሰላም ፡ ተሳዐማ ።"),
    (84, 12, "ርትዕሰ ፡ እምድር ፡ ሠረጸት ፤ ወጽድቅኒ ፡ እምሰማይ ፡ ሐወጸ ።"),
    (84, 13, "ወእግዚአብሔርኒ ፡ ይሁብ ፡ ምሕረቶ ፤ ወምድርኒ ፡ ትሁብ ፡ ፍሬሃ ።"),
    (84, 14, "ጽድቅ ፡ የሐውር ፡ ቅድሜሁ ፤ ወየኀድግ ፡ ውስተ ፡ ፍኖት ፡ አሰሮ ።"),
    (85, 1, "ጸሎት ፡ ዘዳዊት ። አፅምእ ፡ እግዚኦ ፡ እዝነከ ፡ ኀቤየ ፡ ወስምዐኒ ፤ እስመ ፡ ነዳይ ፡ ወምስኪን ፡ አነ ።"),
    (85, 2, "ዕቀባ ፡ ለነፍስየ ፡ እስመ ፡ የዋህ ፡ አን ፤ አድኅኖ ፡ ለገብርከ ፡ አምላኪየ ፡ ዘተወከለ ፡ ኪያከ ።"),
    (85, 3, "ተሣሀለኒ ፡ እግዚኦ ፡ እስመ ፡ ኀቤከ ፡ እጸርኅ ፡ ኵሎ ፡ አሚረ ።"),
    (85, 4, "ወአስተፈሥሓ ፡ ለነፍሰ ፡ ገብርከ ፤ እስመ ፡ ኀቤከ ፡ አንቃዕደውኩ ፡ ነፍስየ ።"),
    (85, 5, "እስመ ፡ መሓሪ ፡ አንተ ፡ እግዚኦ ፡ ወመስተሣህል ፤ ወብዙኅ ፡ ሣህልከ ፡ ለኵሎሙ ፡ እለ ፡ ይጼውዑከ ።"),
    (85, 6, "አፅምእ ፡ እግዚኦ ፡ ጸሎትየ ፤ ወነጽር ፡ ቃለ ፡ ስእለትየ ።"),
    (85, 7, "በዕለተ ፡ ምንዳቤየ ፡ ጸራኅኩ ፡ እስመ ፡ ሰማዕከኒ ።"),
    (85, 8, "አልቦ ፡ ዘይመስለከ ፡ እምነ ፡ አማልክት ፡ እግዚኦ ፤ ወአልቦ ፡ ዘከመ ፡ ምግባሪከ ።"),
    (85, 9, "ኵሎሙ ፡ አሕዛብ ፡ እለ ፡ ገበርከ ፡ ይምጽኡ ፡ ወይስግዱ ፡ ቅድሜከ ፡ እግዚኦ ፤ ወይሰብሑ ፡ ለስምከ ።"),
    (85, 10, "እስመ ፡ ዐቢይ ፡ አንተ ፡ እግዚኦ ፡ ወትገብር ፡ መንክረ ፤ አንተ ፡ እግዚአብሔር ፡ ባሕቲትከ ፡ ዐቢይ ።"),
    (85, 11, "ምርሐኒ ፡ እግዚኦ ፡ ፍኖተከ ፡ ወእሖር ፡ በጽድቅከ ፤ ይትፌሣሕኒ ፡ ልብየ ፡ ለፈሪሀ ፡ ስምከ ።"),
    (85, 12, "እገኒ ፡ ለከ ፡ እግዚኦ ፡ በኵሉ ፡ ልብየ ፡ አምላኪየ ፤ ወእሴብሕ ፡ ለስምከ ፡ ለዓለም ።"),
    (85, 13, "እስመ ፡ ዐብየት ፡ ምሕረትከ ፡ ላዕሌየ ፤ ወአድኀንካ ፡ ለነፍስየ ፡ እምሲኦል ፡ ታሕቲት ።"),
    (85, 14, "አምላኪየ ፡ ዐማፅያን ፡ ቆሙ ፡ ላዕሌየ ፡ ወማኅበረ ፡ እኩያን ፡ ኀሠሥዋ ፡ ለነፍስየ ፤ ወኢረሰዩከ ፡ ቅድሜሆሙ ።"),
    (85, 15, "ወአንተሰ ፡ እግዚኦ ፡ መሓሪ ፡ ወመስተሣህል ፤ ርሑቀ ፡ መዐት ፡ ወብዙኀ ፡ ምሕረት ፡ ወጻድቅ ።"),
    (85, 16, "ነጽር ፡ ላዕሌየ ፡ ወተሣሀለኒ ፤ ሀቦ ፡ ኀይለ ፡ ለገብርከ ፡ ወአድኅኖ ፡ ለወልደ ፡ አመትከ ።"),
    (85, 17, "ግበር ፡ ምስሌነ ፡ ትእምርተ ፡ ለሠናይ ፤ ወይርአዩ ፡ ጸላእትነ ፡ ወይትኀፈሩ ፡ ከመ ፡ አንተ ፡ እግዚኦ ፡ ረዳእከነ ፡ ወአስተፈሣሕከነ ።"),
    (86, 1, "ዘደቂቀ ፡ ቆሬ ፡ መዝሙር ፡ ማኅሌት ።"),
    (86, 2, "መሰረታቲሃ ፡ ውስተ ፡ አድባር ፡ ቅዱሳን ። ያበድሮን ፡ እግዚአብሔር ፡ ለአንቅጸ ፡ ጽዮን ፤ እምኵሉ ፡ ተዓይኒሁ ፡ ለያዕቆብ ።"),
    (86, 3, "ነኪር ፡ ነገሩ ፡ በእንቲአኪ ፡ ሀገረ ፡ እግዚአብሔር ።"),
    (86, 4, "እዜክሮን ፡ ለራአብ ፡ ወለባቢሎን ፡ እለ ፡ ያአምራኒ ፤ ወናሁ ፡ አሎፍሊ ፡ ወጢሮስ ፡ ወሕዝበ ፡ ኢትዮጵያ ፤ እለ ፡ ተወልዱ ፡ በህየ ።"),
    (86, 5, "እምነ ፡ ጽዮን ፡ ይብል ፡ ሰብእ ፡ ወብእሲ ፡ ተወልደ ፡ በውስቴታ ፤ ወወእቱ ፡ ልዑል ፡ ሳረራ ።"),
    (86, 6, "እግዚአብሔር ፡ ይነግሮሙ ፡ ለሕዝቡ ፡ በመጽሐፍ ፤ ወለመላእክቲሁኒ ፡ እለ ፡ ተወልዱ ፡ በውስቴታ ።"),
    (86, 7, "ከመ ፡ ፍሡሓን ፡ ኵሎሙ ፡ እለ ፡ ይነብሩ ፡ ውስቴትኪ ።"),
    (87, 1, "ምኅሌት ፡ መዝሙር ፡ ዘደቂቀ ፡ ቆሬ ፡ ፍጻሜ ፡ ዘአመ ፡ መጽአ ፡ ዘበኣእምሮ ፡ ኤማን ፡ እስራኤላዊ ።"),
    (87, 2, "እግዚአብሔር ፡ አምላከ ፡ መድኀኒትየ ፤ ዕለትየ ፡ ጸራኅኩ ፡ ኀቤከ ፡ ወሌሊትየኒ ፡ ቅድሜከ ።"),
    (87, 3, "ለትባእ ፡ ጸሎትየ ፡ ቅድሜከ ፤ አፅምእ ፡ እዝነከ ፡ ኀበ ፡ ስእለትየ ።"),
    (87, 4, "እስመ ፡ ጸግበት ፡ ነፍስየ ፡ ሕማመ ፤ ወአልጸቀት ፡ ለሞት ፡ ሕይወትየ ።"),
    (87, 5, "ወተኈለቁ ፡ ምስለ ፡ እለ ፡ ይወርዱ ፡ ውስተ ፡ ዐዘቅት ፤ ወኮንኩ ፡ ከመ ፡ ብእሲ ፡ ዘአልቦ ፡ ረዳኤ ። ግዑዘ ፡ ውስተ ፡ ምዉታን ፤"),
    (87, 6, "ከመ ፡ ቅቱላን ፡ ወግዱፋን ፡ እለ ፡ ይሰክቡ ፡ ውስተ ፡ መቃብር ፡ እለ ፡ ኢዘከርኮሙ ፡ ለግሙራ ፤ እስመ ፡ እሙንቱሂ ፡ ርሕቁ ፡ እምእዴከ ።"),
    (87, 7, "ወአንበሩኒ ፡ ውስተ ፡ ዐዘቅት ፡ ታሕተ ፤ ውስተ ፡ ጽልመት ፡ ወጽላሎተ ፡ ሞት ።"),
    (87, 8, "ላዕሌየ ፡ ጸንዐ ፡ መዐትከ ፤ ወኵሎ ፡ መቅሠፍተከ ፡ አምጻእከ ፡ ላዕሌየ ።"),
    (87, 9, "አርሐቀ ፡ እምኔየ ፡ እለ ፡ ያአምሩኒ ፤ ወረሰይከኒ ፡ ርኩሰ ፡ በኀቤሆሙ ፡ አኀዙኒ ፡ ወአልብየ ፡ ሙፃአ ።"),
    (87, 10, "አዕይንትየኒ ፡ ደክማ ፡ በተጽናስ ፤ ወጸራኅኩ ፡ ኀቤከ ፡ እግዚኦ ፡ ኵሎ ፡ አሚረ ፤ ኣንሥእ ፡ እደውየ ፡ ኀቤከ ።"),
    (87, 11, "ቦኑ ፡ ለምዉታን ፡ ትገብር ፡ መንክረከ ፤ ወዐቀብተ ፡ ሥራይኑ ፡ ያነሥኡ ።"),
    (87, 12, "ወይነግሩኒ ፡ እለ ፡ ውስተ ፡ መቃብር ፡ ሣህለከ ፤ ወጽድቀከኒ ፡ ውስተ ፡ ሞትኑ ።"),
    (87, 13, "ወይትዐወቅኑ ፡ ውስተ ፡ ጽልመት ፡ መንክርከ ፤ ወርትዕከኒ ፡ በምድርኑ ፡ ተረስዐ ።"),
    (87, 14, "ወአነሂ ፡ እግዚኦ ፡ ኀቤከ ፡ ጸራኅኩ ፤ በጽባሕ ፡ ትብጻሕ ፡ ጸሎትየ ፡ ቅድሜከ ።"),
    (87, 15, "ለምንት ፡ እግዚኦ ፡ ትገድፍ ፡ ጸሎትየ ፤ ወትመይጥ ፡ ገጸከ ፡ እምኔየ ።"),
    (87, 16, "ነዳይ ፡ አነ ፡ ወሰራሕኩ ፡ እምንእስየ ፤ ተልዒልየ ፡ ተተሐትኩ ፡ ወተመነንኩ ።"),
    (87, 17, "ላዕሌየ ፡ ኀለፈ ፡ መቅሠፍትከ ፤ ወግርማከ ፡ አደንገፀኒ ።"),
    (87, 18, "ዐገቱኒ ፡ ኵሎ ፡ አሚረ ፡ ከመ ፡ ማይ ፤ ወአኀዙኒ ፡ ኅቡረ ።"),
    (87, 19, "አርሐቀ ፡ እምኔየ ፡ አዕርክትየ ፡ ወቢጽየ ፤ ወአዝማድየ ፡ እምተጽናስየ ።"),
    (88, 1, "ዘበኣእምሮ ፡ ኤታን ፡ እስራኤላዊ ።"),
    (88, 2, "ምሕረተከ ፡ እሴብሕ ፡ እግዚኦ ፡ ለዓለም ፤ ወእዜኑ ፡ ጽድቀከ ፡ በአፉየ ፡ ለትውልደ ፡ ትውልድ ።"),
    (88, 3, "እስመ ፡ ትቤ ፡ ለዓለም ፡ አሐንጽ ፡ ምሕረተ ፤ በሰማይ ፡ ጸንዐ ፡ ጽድቅከ ።"),
    (88, 4, "ኪዳነ ፡ ተካየድኩ ፡ ምስለ ፡ ኅሩያንየ ፤ ወመሐልኩ ፡ ለዳዊት ፡ ገብርየ ።"),
    (88, 5, "ለዓለም ፡ አስተዴሉ ፡ ዘርዐከ ፤ ወአሐንጽ ፡ ለትውልደ ፡ ትውልድ ፡ መንበረከ ።"),
    (88, 6, "ይገንያ ፡ ሰማያት ፡ ለስብሐቲከ ፡ እግዚኦ ፤ ወጽድቅከኒ ፡ በማኅበረ ፡ ቅዱሳን ።"),
    (88, 7, "መኑ ፡ ይትዔረዮ ፡ ለእግዚአብሔር ፡ በደመናት ፤ ወመኑ ፡ ይመስሎ ፡ ለእግዚአብሔር ፡ እምደቂቀ ፡ አማልክት ።"),
    (88, 8, "እግዚአብሔር ፡ ስቡሕ ፡ በምክረ ፡ ቅዱሳን ፤ ዐቢይ ፡ ወግሩም ፡ ዲበ ፡ ኵሎሙ ፡ እለ ፡ ዐውዱ ።"),
    (88, 9, "እግዚኦ ፡ አምላከ ፡ ኀያለን ፡ መኑ ፡ ከማከ ፤ ኀያል ፡ እንተ ፡ እግዚኦ ፡ ወጽድቅ ፡ የዐውደከ ።"),
    (88, 10, "አንተ ፡ ትኴንን ፡ ኀይለ ፡ ባሕር ፤ ወአንተ ፡ ታረሞ ፡ ለድምፀ ፡ ማዕበላ ።"),
    (88, 11, "አንተ ፡ አኅሰርኮ ፡ ለዕቡይ ፡ ከመ ፡ ቅቱል ፤ ወበመዝራዕተ ፡ ኀይልከ ፡ ዘረውኮሙ ፡ ለፀርከ ።"),
    (88, 12, "ዚአከ ፡ ውእቱ ፡ ሰማያት ፡ ወእንቲአከ ፡ ይእቲ ፡ ምድር ፤ ወዓለመኒ ፡ በምልኡ ፡ አንተ ፡ ሳረርከ ።"),
    (88, 13, "ባሕረ ፡ ወመስዐ ፡ አንተ ፡ ፈጠርከ ። ታቦር ፡ ወአርሞንኤም ፡ በስመ ፡ ዚአከ ፡ ይትፌሥሑ ፡ ወይሴብሑ ፡ ለስምከ ።"),
    (88, 14, "መዝራዕትከ ፡ ምስለ ፡ ኀይል ፤ ጸንዐት ፡ እዴከ ፡ ወተለዐለት ፡ የማንከ ።"),
    (88, 15, "ፍትሕ ፡ ወርትዕ ፡ ተድላ ፡ መንበርከ ፤ ሣህል ፡ ወጽድቅ ፡ የሐውር ፡ ቅድመ ፡ ገጽከ ።"),
    (88, 16, "ብፁዕ ፡ ሕዝብ ፡ ዘያአምር ፡ የብቦ ። እግዚኦ ፡ በብርሃበ ፡ ገጽከ ፡ የሐውሩ ፤"),
    (88, 17, "ወበስምከ ፡ ይትፌሥሑ ፡ ኵሎ ፡ አሚረ ፤ ወበጽድቅከ ፡ ይትሌዐሉ ።"),
    (88, 18, "እስመ ፡ ምክሐ ፡ ኀይሎሙ ፡ እንተ ፤ ወበሣህልከ ፡ ይትሌዐል ፡ ቀርንነ ።"),
    (88, 19, "እስመ ፡ ዘእግዚአብሔር ፡ ረድኤትነ ፤ ወቅዱሰ ፡ እስራኤል ፡ ንጉሥነ ።"),
    (88, 20, "ውእቱ ፡ አሚረ ፡ ተናገርኮሙ ፡ በራእይ ፡ ለደቂቅከ ፤ ወትቤ ፡ እሬሲ ፡ ረድኤተ ፡ በላዕለ ፡ ኀይል ፡ ወአልዐልኩ ፡ ኅሩየ ፡ እምሕዝብየ ።"),
    (88, 21, "ወረከብክዎ ፡ ለዳዊት ፡ ገብርየ ፤ ወቀባእክዎ ፡ ቅብአ ፡ ቅዱሰ ።"),
    (88, 22, "እስመ ፡ እዴየ ፡ ትረድኦ ፤ ወመዝራዕትየ ፡ ታጸንዖ ።"),
    (88, 23, "ኢይብቍዕ ፡ ጸላኢ ፡ በላዕሌሁ ፤ ወውሉድ ፡ ዐመፃ ፡ ኢይደግም ፡ አሕምሞቶ ።"),
    (88, 24, "ወእምትሮሙ ፡ ለፀሩ ፡ እምቅድመ ፡ ገጹ ፤ ወኣኅስሮሙ ፡ ለጸላእቱ ።"),
    (88, 25, "ወሣህልየሰ ፡ ወጽድቅየ ፡ ምስሌሁ ፤ ወበስምየ ፡ ይትሌዐል ፡ ቀርኑ ።"),
    (88, 26, "ወእሠይም ፡ ውስተ ፡ ባሕር ፡ እዴሁ ፤ ወውስተ ፡ አፍላግ ፡ የማኖ ።"),
    (88, 27, "ውእቱ ፡ ይብለኒ ፡ አቡየ ፡ አንተ ፤ አምላኪየ ፡ ወረዳእየ ፡ ወመድኀንየ ።"),
    (88, 28, "ወአነሂ ፡ በኵርየ ፡ እሬስዮ ፤ ወልዑል ፡ እምነገሥተ ፡ ምድር ።"),
    (88, 29, "ወለዓለም ፡ አዐቅብ ፡ ሎቱ ፡ ሣህልየ ፤ ወምእመን ፡ ውእቱ ፡ ለኪዳንየ ።"),
    (88, 30, "ወእሬሲ ፡ ዘርዖ ፡ ለዓለመ ፡ ዓለም ፤ ወመንበሮሂ ፡ ከመ ፡ መዋዕለ ፡ ሰማይ ።"),
    (88, 31, "ወእመሰ ፡ ኀደጉ ፡ ደቂቁ ፡ ሕግየ ፤ ወኢሖሩ ፡ በኵነኔየ ።"),
    (88, 32, "ወእመሂ ፡ አርኰሱ ፡ ሥርዐትየ ፤ ወኢዐቀቡ ፡ ትእዛዝየ ።"),
    (88, 33, "እዋሕያ ፡ በበትር ፡ ለኀጢአቶሙ ፤ ወበመቅሠፍት ፡ ለአበሳሆሙ ።"),
    (88, 34, "ወሣህልየሰ ፡ ኢይበልእ ፡ እምኔሆሙ ፤ ወኢይዔምፅ ፡ በጸድቅየ ።"),
    (88, 35, "ወኢያረኵስ ፡ ኪዳንየ ፤ ወኢይሔሱ ፡ ዘወፅአ ፡ እምአፉየ ።"),
    (88, 36, "ምዕረ ፡ መሐልኩ ፡ በቅዱስየ ፤ ከመ ፡ ለዳዊት ፡ ኢይሔስዎ ።"),
    (88, 37, "ወዘርዑሂ ፡ ለዓለም ፡ ይሄሉ ፤ ወመንበሩሂ ፡ ከመ ፡ ፀሐይ ፡ በቅድሜየ ።"),
    (88, 38, "ወሥሩዕ ፡ ከመ ፡ ወርኅ ፡ ለዓለም ፤ ወስምዑሂ ፡ ምእመን ፡ በሰማይ ።"),
    (88, 39, "ወአንተሰ ፡ መነንኮ ፡ ወገደፍኮ ፤ ወአናሕሰይኮ ፡ ለመሲሕከ ።"),
    (88, 40, "ወሜጥከ ፡ ሥርዐቶ ፡ ለገብርከ ፤ ወአርኰስከ ፡ ውስተ ፡ ምድር ፡ መቅደሶ ።"),
    (88, 41, "ወነሠትከ ፡ ኵሎ ፡ ጥቅሞ ፤ ወረሰይከ ፡ አጽዋኒሁ ፡ መፍርሀ ።"),
    (88, 42, "ወተማሰጦ ፡ ኵሉ ፡ ኀላፌ ፡ ፍኖት ፤ ወኮነ ፡ ጽእለተ ፡ ለጎሩ ።"),
    (88, 43, "ወአልዐልከ ፡ የማነ ፡ ፀሩ ፤ ወአስተፈሣሕከ ፡ ኵሎ ፡ ጸላእቱ ።"),
    (88, 44, "ወሜጥከ ፡ ረድኤተ ፡ ኲናቱ ፤ ወኢተወከፍኮ ፡ በውስተ ፡ ፀብእ ።"),
    (88, 45, "ወሰዐርኮ ፡ እምንጽሑ ፤ ወነፃሕከ ፡ ውስተ ፡ ምድር ፡ መንበሮ ።"),
    (88, 46, "ወአውኀድከ ፡ መዋዕለ ፡ መንበሩ ፤ ወሶጥከ ፡ ላዕሌሁ ፡ ኀፍረተ ።"),
    (88, 47, "እስከ ፡ ማእዜኑ ፡ እግዚኦ ፡ ትትመየጥ ፡ ለግሙራ ፤ ወይነድድ ፡ ከመ ፡ እሳት ፡ መዐትከ ።"),
    (88, 48, "ተዘከር ፡ ምንት ፡ ውእቱ ፡ ኀይልየ ፤ ቦኑ ፡ ለከንቱ ፡ ፈጠርኮ ፡ ለኵሉ ፡ እጓለ ፡ እመሕያው ።"),
    (88, 49, "መኑ ፡ ሰብእ ፡ ዘየሐዩ ፡ ወኢይሬእዮ ፡ ለሞት ፤ ወመኑ ፡ ዘያድኅና ፡ ለነፍሱ ፡ እምእደ ፡ ሲኦል ።"),
    (88, 50, "አይቴ ፡ ውእቱ ፡ ዘትካት ፡ ሣህልከ ፡ እግዚኦ ፤ ዘመሐልከ ፡ ለዳዊት ፡ ገብርከ ፡ በጽድቅ ።"),
    (88, 51, "ተዘከር ፡ እግዚኦ ፡ ዘጸአልዎሙ ፡ ለአግብርቲከ ፤ ዘተወከፍኩ ፡ በሕፅንየ ፡ ብዙኀ ፡ አሕዛብ ።"),
    (88, 52, "ዘጸአሉ ፡ ጸላእትከ ፡ እግዚኦ ፤ ወጸአሉ ፡ እብሬተ ፡ መሲሕከ ።"),
    (88, 53, "ይትባረክ ፡ እግዚአብሔር ፡ ለዓለም ፤ ለይኩን ፡ ለይኩን ።"),
    (89, 1, "ጸሎት ፡ ዘሙሴ ፡ ዘብእሴ ፡ እግዚአብሔር ። እግዚኦ ፡ ጸወነ ፡ ኮንከነ ፡ ለትውልደ ፡ ትውልድ ።"),
    (89, 2, "ዘእንበለ ፡ ይቁም ፡ አድባር ፡ ወይትፈጠር ፡ ዓለም ፡ ወምድር ፤ እምቅድመ ፡ ዓለም ፡ ወእስከ ፡ ለዓለም ፡ አንተ ፡ ክመ ።"),
    (89, 3, "ኢትሚጦ ፡ ለሰብእ ፡ ለኀሳር ፤ ወትቤ ፡ ተመየጡ ፡ ደቂቀ ፡ እጓለ ፡ እመሕያው ።"),
    (89, 4, "እስመ ፡ ዐሠርቱ ፡ ምእት ፡ ዐመት ፡ በቅድሜከ ፡ ከመ ፡ ዕለት ፡ እንተ ፡ ትማልም ፡ ኀለፈት ፤ ወሰዓተ ፡ ሌሊት ።"),
    (89, 5, "ምኑን ፡ ዐመታት ፡ በቅድሜሆሙ ፤ በጽባሕ ፡ ከመ ፡ ሣዕር ፡ የኀልፍ ።"),
    (89, 6, "በጽባሕ ፡ ይሠርጽ ፡ ወየኀልፍ ፤ ወሰርከሰ ፡ ይወድቅ ፡ የቢሶ ፡ ወአንፂዎ ።"),
    (89, 7, "እስመ ፡ ኀለቅነ ፡ በመዐትከ ፤ ወደንገፅነ ፡ በመቅሠፍትከ ።"),
    (89, 8, "ወሤምከ ፡ ኀጢአተነ ፡ ቅድሜከ ፤ ወዓለምነሂ ፡ ውስተ ፡ ብርሃነ ፡ ገጽከ ።"),
    (89, 9, "እስመ ፡ ኀልቃ ፡ ኵሎን ፡ መዋዕሊነ ፡ ወኀለቅነ ፡ በመቅሠፍትከ ።"),
    (
        89,
        10,
        "ወዐመቲነኒ ፡ ከመ ፡ ሳሬት ፡ ይከውና ። ወመዋዕለ ፡ ዐመቲነ ፡ ሰብዓ ፡ ክራማት ፡ ወእመሰ ፡ በዝኃ ፡ ሰማንያ ፡ ዓም ፤ ወፈድፋድንሰ ፡ እምእላ ፡ ጻማ ፡ ወሕማም ። እስመ ፡ ኀለፈት ፡ የዋሃት ፡ እምኔነ ፡ ወተገሠጽነ ።",
    ),
    (89, 11, "መኑ ፡ ያአምር ፡ ኀይለ ፡ መቅሠፍትከ ፤ ወእምግርማ ፡ መዐትከ ፡ ኀልቁ ።"),
    (89, 12, "ከመዝ ፡ አርኢ ፡ የማነከ ፤ ለምሁራን ፡ ልብ ፡ በጥበብ ።"),
    (89, 13, "ተመየጥ ፡ እግዚኦ ፡ እስከ ፡ ማእዜኑ ፤ ወተናበብ ፡ በእንተ ፡ አግብርቲከ ።"),
    (89, 14, "እስመ ፡ ጸገብነ ፡ በጽባሕ ፡ ምሕረተከ ፤ ወተፈሣሕነ ፡ ወተሐሠይነ ፡ በኵሉ ፡ መዋዕሊነ ፤"),
    (89, 15, "ወተፈሣሕነ ፡ ህየንተ ፡ መዋዕል ፡ ዘኣሕመምከነ ፤ ወህየንተ ፡ ዐመት ፡ እንተ ፡ ርኢናሃ ፡ ለእኪት ።"),
    (89, 16, "ርኢ ፡ ላዕለ ፡ አግብርቲከ ፡ ወላዕለ ፡ ተግባርከ ፡ እግዚኦ ፤ ወምርሖሙ ፡ ለደቂቆሙ ።"),
    (89, 17, "ለይኩን ፡ ብርሃኑ ፡ ለእግዚአብሔር ፡ አምላክነ ፡ ላዕሌነ ፤ [ወይሠርሕ ፡ ለነ ፡ ተግባረ ፡ እደዊነ ፡] ወይሠርሕ ፡ ተግባረ ፡ እደዊነ ።"),
    (90, 1, "ስብሐት ፡ ማኅሌት ፡ ዘዳዊት ። ዘየኀድር ፡ በረድኤተ ፡ ልዑል ፤ ወይነብር ፡ ውስተ ፡ ጽላሎቱ ፡ ለአምላከ ፡ ሰማይ ።"),
    (90, 2, "ይብሎ ፡ ለእግዚአብሔር ፡ ምስካይየ ፡ ወጸወንየ ፡ አንተ ፤ አምላኪየ ፡ ወረዳእየ ፡ ወእትዌከል ፡ ቦቱ ።"),
    (90, 3, "እስመ ፡ ውእቱ ፡ ይባልሐኒ ፡ እመሥገርት ፡ ነዓዊት ፤ ወእምነገር ፡ መደንግፅ ።"),
    (90, 4, "ይጼልለከ ፡ በገበዋቲሁ ፡ ወትትዌከል ፡ በታሕተ ፡ ክነፊሁ ፤ ጽድቅ ፡ በወልታ ፡ የዐውደከ ።"),
    (90, 5, "ወኢትፈርህ ፡ እምግርማ ፡ ሌሊት ፤ እምሐጽ ፡ ዘይሠርር ፡ በመዐልት ።"),
    (90, 6, "እምግብር ፡ ዘየሐውር ፡ በጽልመት ፤ እምጽድቅ ፡ ወእምጋኔነ ፡ ቀትር ።"),
    (90, 7, "ይወድቁ ፡ በገቦከ ፡ ዐሠርቱ ፡ ምእት ፡ ወኣእላፍ ፡ በየማንከ ፤ ወኀቤከሰ ፡ ኢይቀርቡ ።"),
    (90, 8, "ወባሕቱ ፡ ትሬኢ ፡ በኣዕይንቲከ ፤ ወትሬኢ ፡ ፍዳሆሙ ፡ ለኃጥኣን ።"),
    (90, 9, "እስመ ፡ አንተ ፡ እግዚኦ ፡ ተስፋየ ፤ ልዑል ፡ ረሰይከ ፡ ጸወነከ ።"),
    (90, 10, "ኢይቀርብ ፡ እኩይ ፡ ኀቤከ ፤ ወኢይበውእ ፡ መቅሠፍት ፡ ቤተከ ።"),
    (90, 11, "እስመ ፡ ለመላእክቲሁ ፡ ይኤዝዞሙ ፡ በእንቲአከ ፤ ከመ ፡ ይዕቀቡከ ፡ በኵሉ ፡ ፍናዊከ ።"),
    (90, 12, "ወበእደው ፡ ያነሥኡከ ፤ ከመ ፡ ኢትትዐቀፍ ፡ በእብን ፡ እግረከ ።"),
    (90, 13, "ላዕለ ፡ ተኵላ ፡ ወከይሲ ፡ ትጼዐን ፤ ወትከይድ ፡ አንበሳ ፡ ወከይሴ ።"),
    (90, 14, "እስመ ፡ ብየ ፡ ተወከለ ፡ ወኣድኅኖ ፤ ወእከድኖ ፡ እስመ ፡ ኣእመረ ፡ ስምየ ።"),
    (90, 15, "ይጼውዐኒ ፡ ወእሰጠዎ ፡ ሀሎኩ ፡ ምስሌሁ ፡ አመ ፡ ምንዳቤሁ ፤ ኣድኅኖ ፡ ወእሰብሖ ።"),
    (90, 16, "ለነዋኅ ፡ መዋዕል ፡ ኣጸግቦ ፤ ወኣርእዮ ፡ አድኅኖትየ ።"),
    (91, 1, "መዝሙር ፡ ማኅሌት ፡ በዓለተ ፡ ሰንበት ።"),
    (91, 2, "ይኄይስ ፡ ተአምኖ ፡ በእግዚአብሔር ፤ ወዘምሮ ፡ ለስምከ ፡ ልዑል ።"),
    (91, 3, "ወነጊረ ፡ በጽባሕ ፡ ምሕረትከ ፤ ወጽድቅከኒ ፡ በሌሊት ።"),
    (91, 4, "በዘዐሠርቱ ፡ አውታሪሁ ፡ መዝሙረ ፡ ማኅሌት ፡ ወመሰንቆ ።"),
    (91, 5, "እስመ ፡ አስተፈሣሕከኒ ፡ እግዚኦ ፡ በምግባሪከ ፤ ወእትሐሠይ ፡ በግብረ ፡ እደዊከ ።"),
    (91, 6, "ጥቀ ፡ ዐቢይ ፡ ግብርከ ፡ እግዚኦ ፤ ወፈድፋደ ፡ ዕሙቅ ፡ ሕሊናከ ።"),
    (91, 7, "ብእሲ ፡ አብድ ፡ ኢያአምር ፤ ወዘአልቦ ፡ ልበ ፡ ኢይሌብዎ ፡ ለዝንቱ ፡፡"),
    (91, 8, "ሶበ ፡ ይበቍሉ ፡ ኃጥኣን ፡ ከመ ፡ ሣዕር ፡ ወይሠርጹ ፡ ኵሎሙ ፡ ገበርተ ፡ ዐመፃ ፤ ከመ ፡ ይሠረዉ ፡ ለዓለመ ፡ ዓለም ፤"),
    (91, 9, "ወአንተሰ ፡ ልዑል ፡ ለዓለም ፡ እግዚኦ ።"),
    (91, 10, "እስመ ፡ ናሁ ፡ ጸላእትከ ፡ ይትሐጐሉ ፤ ወይዘረዉ ፡ ኵሎሙ ፡ ገበርተ ፡ ዐመፃ ።"),
    (91, 11, "ወይትሌዐል ፡ ቀርንየ ፡ ከመ ፡ ዘአሐዱ ፡ ቀርኑ ፤ ወይጠልል ፡ በቅብእ ፡ ሲበትየ ።"),
    (91, 12, "ወርእየት ፡ ዐይንየ ፡ በጸላእትየ ፡ ወሰምዐት ፡ እዝንየ ፡ ዲቤሆሙ ፡ ለእኩያን ፡ እለ ፡ ቆሙ ፡ ላዕሌየ ።"),
    (91, 13, "ጻድቅከ ፡ ከመ ፡ በቀልት ፡ ይፈሪ ፤ ወይበዝኅ ፡ ከመ ፡ ዘግባ ፡ ዘሊባኖስ ።"),
    (91, 14, "ትኩላን ፡ እሙንቱ ፡ ውስተ ፡ ቤተ ፡ እግዚአብሔር ፤ ወይበቍሉ ፡ ውስተ ፡ ዐጸዱ ፡ ለአምላክነ ።"),
    (91, 15, "ውእቱ ፡ አሚረ ፡ ይበዝኁ ፡ በርሥኣን ፡ ጥሉል ፤ ወይከውኑ ፡ ዕሩፋነ ።"),
    (91, 16, "ወይነግሩ ፡ ከመ ፡ ጽድቅ ፡ እግዚአብሔር ፡ አምላክነ ፤ ወአልቦ ፡ ዐመፃ ፡ በኀቤሁ ።"),
    (
        92,
        1,
        "በዕለተ ፡ ሰንበት ፡ አመ ፡ ኅድረተ ፡ ምድር ፤ ሰብሐተ ፡ ማኅሌት ፡ ዘዳዊት ። እግዚአብሔር ፡ ነግሠ ፡ ስብሐቲሁ ፡ ለብሰ ፤ ለብሰ፡ እግዚአብሔር ፡ ኀይሎ ፡ ወቀነተ ፤ ወአጽንዓ ፡ ለዓለም ፡ ከመ ፡ ኢታንቀልቅል ።",
    ),
    (92, 2, "ድልው ፡ መንበርከ ፡ እግዚኦ ፡ እምትካት ፤ ወእስከ ፡ ለዓለም ፡ አንተ ፡ ክመ ።"),
    (92, 3, "አልዐሉ ፡ አፍላግ ፡ እግዚኦ ፤ አልዐሉ ፡ አፍላግ ፡ ቃላቲሆሙ ።"),
    (92, 4, "[ያሌዕሉ ፡ አፍላግ ፡ ድምፆሙ ።] እምቃለ ፡ ማያት ፡ ብዙኅ ፡ መንክር ፡ ተላህያ ፡ ለባሕር ፤ መንክርሰ ፡ እግዚአብሔር ፡ በአርያሙ ።"),
    (92, 5, "ስምዐ ፡ ዚአከ ፡ እሙን ፡ ፈድፋደ ፤ ለቤትከ ፡ ይደሉ ፡ ስብሐት ፤ እግዚኦ ፡ ለነዋኅ ፡ መዋዕል ።"),
    (93, 1, "መዝሙር ፡ ዘዳዊት ፡ ዘበረቡዕ ሰንበት ። እግዚአብሔር ፡ እግዚእ ፡ መስተበቅል ፤ እግዚአብሔር ፡ መስተበቅል ፡ ገሀደ ።"),
    (93, 2, "ተለዐለ ፡ ዘይኴንና ፡ ለምድር ፤ ፍድዮሙ ፡ ፍዳሆሙ ፡ ለዕቡያን ።"),
    (93, 3, "እስከ ፡ ማእዜኑ ፡ ኃጥኣን ፡ እግዚኦ ፤ እስከ ፡ ማእዜኑ ፡ ይዜሀሩ ፡ ኃጥኣን ።"),
    (93, 4, "ይትዋሥኡ ፡ ወይነቡ ፡ ዐመፃ ፤ ወይነቡ ፡ ኵሎሙ ፡ ገበርተ ፡ ዐመፃ ።"),
    (93, 5, "ወአኅሰሩ ፡ ሕዝበከ ፡ እግዚኦ ፤ ወሣቀዩ ፡ ርስተከ ።"),
    (93, 6, "ወቀተሉ ፡ እቤረ ፡ ወእጓለ ፡ ማውታ ፤ ወቀተሉ ፡ ፈላሴ ።"),
    (93, 7, "ወይቤሉ ፡ ኢይሬኢ ፡ እግዚአብሔር ፤ ወኢያአምር ፡ አምላከ ፡ ያዕቆብ ።"),
    (93, 8, "ለብዉ ፡ አብዳነ ፡ ሕዝብ ፤ አብዳንኬ ፡ ማእዜኑ ፡ ይጠቡ ።"),
    (93, 9, "ወተከላሁ ፡ ለእዝን ፡ ኢይሰምዕኑ ፤ ወዘፈጠራሁ ፡ ለዐይን ፡ ኢይሬኢኑ ።"),
    (93, 10, "ዘይጌሥጾሙ ፡ ለአሕዛብ ፡ ኢይዛለፍኑ ፤ ዘይሜህሮሙ ፡ ለሰብእ ፡ ጥበበ ።"),
    (93, 11, "እግዚአብሔር ፡ ያአምር ፡ ሕሊናሆሙ ፡ ለጠቢባን ፡ ከመ ፡ ከንቱ ፡ ውእቱ ።"),
    (93, 12, "ብፁዕ ፡ ብእሲ ፡ ዘአንተ ፡ ገሠጽኮ ፡ እግዚኦ ፤ ወዘመሀርኮ ፡ ሕገከ ።"),
    (93, 13, "ከመ ፡ ይትገሐስ ፡ እምዋዕል ፡ እኩያት ፤ እስከ ፡ ይትከረይ ፡ ግብ ፡ ለኃጥኣን ።"),
    (93, 14, "እስመ ፡ ኢይገድፎሙ ፡ እግዚአብሔር ፡ ለሕዝቡ ፤ ወኢየኀድጎሙ ፡ ለርስቱ ።"),
    (93, 15, "እስከ ፡ ይገብእ ፡ ፍትሕ ፡ ለዘ ፡ ይጸድቅ ፤ ወኵሎሙ ፡ ርቱዓነ ፡ ልብ ፡ እለ ፡ ኪያሃ ፡ ቦሙ ።"),
    (93, 16, "መኑ ፡ ይትናሥአኒ ፡ በእንተ ፡ እኩያን ፤ ወመኑ ፡ ይትቃወመኒ ፡ በእንተ ፡ ገበርተ ፡ ዐመፃ ።"),
    (93, 17, "ሶበ ፡ አኮ ፡ እግዚአብሔር ፡ ዘረድአኒ ፤ ሕቀ ፡ ከመ ፡ ዘእምኀደረት ፡ ነፍስየ ፡ ውስተ ፡ ሲኦል ።"),
    (93, 18, "ወሶበ ፡ እቤ ፡ ድኅፃ ፡ እገርየ ፤ ምሕረትከ ፡ እግዚኦ ፡ ረድአኒ ።"),
    (93, 19, "እግዚኦ ፡ በከመ ፡ ብዙኀ ፡ ሕማማ ፡ ለልብየ ፤ ናዝዞትከ ፡ አስተፈሥሓ ፡ ለነፍስየ ።"),
    (93, 20, "ወኢይትቃወመከ ፡ መንበረ ፡ ዐመፃ ፤ ዘይፈጥር ፡ ጻማ ፡ ዲበ ፡ ትእዛዝ ።"),
    (93, 21, "ወይንዕውዋ ፡ ለነፍሰ ፡ ጻድቅ ፤ ወይኴንኑ ፡ ደመ ፡ ንጹሕ ።"),
    (93, 22, "ወኮነኒ ፡ እግዚአብሔር ፡ ጸወንየ ፤ አምላኪየ ፡ ወረድኤተ ፡ ተስፋየ ።"),
    (93, 23, "ወይፈድዮሙ ፡ እግዚአብሔር ፡ በከመ ፡ እከዮሙ ፤ ወያጠፍኦሙ ፡ እግዚአብሔር ፡ አምላክነ ።"),
    (94, 1, "ስብሐተ ፡ ማኅሌት ፡ ዘዳዊት ። ንዑ ፡ ንትፈሣሕ ፡ በእግዚአብሔር ፤ ወንየብብ ፡ ለአምላክነ ፡ ወመድኀኒነ ።"),
    (94, 2, "ወንብጻሕ ፡ ቅድመ ፡ ገጹ ፡ በአሚን ፤ ወበመዝሙር ፡ ንየብብ ፡ ሎቱ ።"),
    (
        94,
        3,
        "እስመ ፡ ዐቢይ ፡ ውእቱ ፡ እግዚአብሔር ፡ አምላክነ ፤ ወንጉሥ ፡ ዐቢይ ፡ ውእቱ ፡ ላዕለ ፡ ኵሉ ፡ አማልክት ። እስመ ፡ ኢይገድፎሙ ፡ እግዚአብሔር ፡ ለሕዝቡ ።",
    ),
    (94, 4, "እስመ ፡ ውስተ ፡ እዴሁ ፡ አጽናፈ ፡ ምድር ፤ ወአድባር ፡ ነዋኃት ፡ ዚአሁ ፡ ውእቱ ።"),
    (94, 5, "እስመ ፡ እንቲአሁ ፡ ይእቲ ፡ ባሕር ፡ ወውእቱ ፡ ፈጠራ ፤ ወለየብሰኒ ፡ እደዊሁ ፡ ገብራ ።"),
    (94, 6, "ንዑ ፡ ንስግድ ፡ ወንግነይ ፡ ሎቱ ፤ ወንብኪ ፡ ቅድመ ፡ እግዚአብሔር ፡ ዘውእቱ ፡ ፈጠረነ ።"),
    (94, 7, "እስመ ፡ ውእቱ ፡ አምላክነ ፤ ወንሕነሰ ፡ ሕዝቡ ፡ አባግዐ ፡ መርዔቱ ፤ ዮም ፡ ለእመ ፡ ሰማዕክሙ ፡ ቃሎ ።"),
    (94, 8, "ኢታጽንዑ ፡ ልበክሙ ፡ ከመ ፡ አመ ፡ አምረርዎ ፡ በገዳም ፡ ወአመ ፡ አመከርዎ ።"),
    (94, 9, "ዘአመከሩኒ ፡ አበዊክሙ ፤ ፈተኑኒ ፡ ወርእዩ ፡ መግባርየ ።"),
    (94, 10, "ወአርብዓ ፡ ዓመተ ፡ ተቈጣዕክዋ ፡ ለይእቲ ፡ ትውልድ ፡ ወእቤ ፡ ዘልፈ ፡ ይስሕት ፡ ልቦሙ ፤ ወእሙንቱሰ ፡ ኢያእመሩ ፡ ፍናውየ ።"),
    (94, 11, "በከመ ፡ መሐልኩ ፡ በመዐትየ ፤ ከመ ፡ ኢይበውኡ ፡ ውስተ ፡ ዕረፍትየ ።"),
    (
        95,
        1,
        "ዘአመ ፡ ተሐንጸ ፡ ቤት ፡ ዘእምድኅረ ፡ ፂዋዌ ፤ ማኅሌት ፡ ዘዳዊት ። ሰብሕዎ ፡ ለእግዚአብሔር ፡ ስብሐተ ፡ ሐዲሰ ፤ ሰብሕዎ ፡ ለእግዚአብሔር ፡ ኵላ ፡ ምድር ።",
    ),
    (95, 2, "ሰብሕዎ ፡ ለእግዚአብሔር ፡ ወባርኩ ፡ ለስሙ ፤ ወተዘያነዉ ፡ እምዕለት ፡ ዕለተ ፡ አድኅኖቶ ።"),
    (95, 3, "ወንግርዎሙ ፡ ለአሕዛብ ፡ ስብሐቲሁ ፤ ወለኵሎሙ ፡ አሕዛብ ፡ ተኣምሪሁ ።"),
    (95, 4, "እስመ ፡ ዐቢይ ፡ እግዚአብሔር ፡ ወብዙኅ ፡ አኰቴቱ ፤ ወግሩም ፡ ውእቱ ፡ ላዕለ ፡ ኵሉ ፡ አማልክት ።"),
    (95, 5, "እስመ ፡ አማልክተ ፡ አሕዛብ ፡ አጋንንት ፤ ወእግዚአብሔርሰ ፡ ሰማያተ ፡ ገብረ ።"),
    (95, 6, "አሚን ፡ ወሠናይት ፡ ቅድሜሁ ፤ ቅድሳት ፡ ወዕበየ ፡ ስብሐት ፡ ውስተ ፡ መቅደሱ ።"),
    (95, 7, "አምጽኡ ፡ ለእግዚአብሔር ፡ በሓውርተ ፡ አሕዛብ ፤ አምጽኡ ፡ ለእግዚአብሔር ፡ ክብረ ፡ ወስብሓተ ።"),
    (95, 8, "አምጽኡ ፡ ለእግዚአብሔር ፡ ስብሐተ ፡ ለስሙ ፤ ንሥኡ ፡ መሥዋዕተ ፡ ወባኡ ፡ ውስተ ፡ አዕጻዲሁ ።"),
    (95, 9, "ስግዱ ፡ ለእግዚአብሔር ፡ በዐጸደ ፡ መቅደሱ ፤ ታድለቀልቅ ፡ እምቅድመ ፡ ገጹ ፡ ኵላ ፡ ምድር ።"),
    (95, 10, "በልዎሙ ፡ ለኣሕዛብ ፡ ከመ ፡ እግዚአብሔር ፡ ነግሠ ፡ ወአጽንዓ ፡ ለዓለም ፡ ከመ ፡ ኢታንቀልቅል ፤ ወይኴንኖሙ ፡ ለአሕዛብ ፡ በርትዕ ።"),
    (95, 11, "ይትፌሥሓ ፡ ሰማያት ፡ ወትትሐሠይ ፡ ምድር ፤ ወትትከወስ ፡ ባሕር ፡ በምልኣ ።"),
    (95, 12, "ትትሐሠይ ፡ ገዳም ፡ ወኵሉ ፡ ዘውስቴታ ፤ ውእቱ ፡ አሚረ ፡ ይትፌሥሑ ፡ ኵሉ ፡ ዕፀወ ፡ ገዳም ።"),
    (95, 13, "እምቅድመ ፡ ገጹ ፡ ለእግዚአብሔር ፡ እስመ ፡ ይመጽእ ፡ ወይመጽእ ፡ ወይኴንና ፡ ለምድር ፤ ወይኴንና ፡ ለዓለም ፡ በጽድቅ ፡ ወለአሕዛብኒ ፡ በርትዕ ።"),
    (96, 1, "ዘዳዊት ፡ ዘአመ ፡ ገብአ ፡ ምድሩ ። እግዚአብሔር ፡ ነግሠ ፡ ትትሐሠር ፡ ምድር ፤ ወይትሐሥያ ፡ ደሰያት ፡ ብዙኃት ።"),
    (96, 2, "ደመና ፡ ወቆባር ፡ ዐውዶ ፤ ፍትሕ ፡ ወርትዕ ፡ ተድላ ፡ መንበሩ ።"),
    (96, 3, "እሳት ፡ ይሐውር ፡ ቅድሜሁ ፤ ወነድ ፡ የዐግቶሙ ፡ ለጸላእቱ ።"),
    (96, 4, "አስተርአየ ፡ መባርቅቲሁ ፡ ለዓለም ፤ ርእየት ፡ ወአድለቅለቀት ፡ ምድር ።"),
    (96, 5, "ወአድባርኒ ፡ ተመሰዉ ፡ ከመ ፡ ስምዕ ፡ እምቅድመ ፡ ገጹ ፡ ለእግዚአብሔር ፤ እምቅድመ ፡ ገጹ ፡ ለእግዚአብሔር ፡ ኵላ ፡ ምድር ።"),
    (96, 6, "ይነግራ ፡ ሰማያት ፡ ጽድቀ ፡ ዚአሁ ፤ ወኵሎሙ ፡ አሕዛብ ፡ ርእዩ ፡ ስብሐቲሁ ።"),
    (96, 7, "ይትኀፈሩ ፡ ኵሎሙ ፡ እለ ፡ ይሰግዱ ፡ ለግልፎ ፤ እለ ፡ ይትሜክሑ ፡ በአማልክቲሆሙ ፤ ወይስግዱ ፡ ሎቱ ፡ ኵሎሙ ፡ መላእክቲሁ ።"),
    (96, 8, "ሰምዐት ፡ ወተፈሥሐት ፡ ጽዮን ፡ ወተሐሥያ ፡ አዋልደ ፡ ይሁዳ ፤ በእንተ ፡ ፍትሕከ ፡ እግዚኦ ።"),
    (96, 9, "እስመ ፡ አንተ ፡ እግዚአብሔር ፡ ልዑል ፡ በኵሉ ፡ ምድር ፤ ፈድፋደ ፡ ተለዐልከ ፡ እምኵሉ ፡ አማልክት ።"),
    (96, 10, "እለ ፡ ታፈቅርዎ ፡ ለእግዚአብሔር ፡ ጽልእዋ ፡ ለእኪት ፤ የዐቅብ ፡ እግዚአብሔር ፡ ነፍሰ ፡ ጻድቃኑ ፡ ወያድኅኖሙ ፡ እምእደ ፡ ኃጥኣን ።"),
    (96, 11, "በርህ ፡ ሠረቀ ፡ ለጻድቃን ፤ ወለርቱዓነ ፡ ልብ ፡ ትፍሥሕት ።"),
    (96, 12, "ይትፌሥሑ ፡ ጻድቃን ፡ በእግዚአብሔር ፤ ወይገንዩ ፡ ለዝክረ ፡ ቅድሳቱ ።"),
    (97, 1, "መዝሙር ፡ ዘዳዊት ። ሰብሕዎ ፡ ለእግዚአብሔር ፡ ስብሐተ ፡ ሐዲሰ ፤ እስመ ፡ መንክረ ፡ ገብረ ፡ እግዚአብሔር ፡ ወአድኅኖተ ፡ የማኑ ፡ ወመዝራዕቲሂ ፡ ቅዱስ ።"),
    (97, 2, "አርአየ ፡ እግዚአብሔር ፡ አድኅኖቶ ፤ ወበቅድመ ፡ አሕዛብ ፡ ከሠተ ፡ ኪዳኖ ።"),
    (97, 3, "ወተዘከረ ፡ ሣህሎ ፡ ለያዕቆብ ፡ ወጽድቀሂ ፡ ለቤተ ፡ እስራኤል ፤"),
    (97, 4, "ርእዩ ፡ ኵልክሙ ፡ አጽናፈ ፡ ምድር ፡ አድኅኖቶ ፡ ለአምላክነ ።"),
    (97, 5, "የብቡ ፡ ለእግዚአብሔር ፡ በኵሉ ፡ ምድር ፤ ሰብሑ ፡ ተፈሥሑ ፡ ወዘምሩ ።"),
    (97, 6, "ዘምሩ ፡ ለእግዚአብሔር ፡ በመሰንቆ ፤ በመሰንቆ፡ ወበቃለ ፡ መዝሙር ። በቀርነ ፡ ዝብጦ ፡ ወበቃለ ፡ ቀርን ፤ የብቡ ፡ በቅድመ ፡ እግዚአብሔር ፡ ንጉሥ ።"),
    (97, 7, "ወትትከወስ ፡ ባሕር ፡ በምልኣ ፤ ዓለምኒ ፡ ወኵሎሙ ፡ እለ ፡ ይነብሩ ፡ ውስቴታ ።"),
    (97, 8, "ወአፍላግኒ ፡ ይጠፍሑ ፡ እደ ፡ ኅቡረ ፤ አድባርኒ ፡ ይትሐሠዩ ።"),
    (97, 9, "እስመ ፡ በህየ ፡ ይኴንና ፡ ለምድር ፤ ወይኴንና ፡ ለዓለም ፡ በጽድቅ ፡ ወለአሕዛብኒ ፡ በርትዕ ።"),
    (98, 1, "መዝሙር ፡ ዘዳዊት ። እግዚአብሔር ፡ ነግሠ ፡ ደንገፁ ፡ አሕዛብ ፤ ዘይነብር ፡ ዲበ ፡ ኪሩቤል ፡ አድለቅለቃ ፡ ለምድር ።"),
    (98, 2, "እግዚአብሔር ፡ ዐቢይ ፡ በጽዮን ፤ ወልዑል ፡ ውእቱ ፡ ላዕለ ፡ ኵሉ ፡ አሕዛብ ።"),
    (98, 3, "ኵሉ ፡ ይገኒ ፡ ለስምከ ፡ ዐቢይ ፤ እስመ ፡ ግሩም ፡ ወቅዱስ ፡ ውእቱ ።"),
    (98, 4, "ክቡር ፡ ንጉሥ ፡ ፍትሐ ፡ ያፈቅር ፤ አንተ ፡ አጽናዕካ ፡ ለጽድቅ ፡ ፍትሐ ፡ ወጽድቀ ፡ ለያዕቆብ ፡ አንተ ፡ ገበርከ ።"),
    (98, 5, "ተለዐለ ፡ እግዚአብሔር ፡ ፈጣሪነ ፡ ወይሰግዱ ፡ ሎቱ ፡ ታሕተ ፡ መከየደ ፡ እገሪሁ ፤ እስመ ፡ ቅዱሳን ፡ እሙንቱ ።"),
    (98, 6, "ሙሴ ፡ ወአሮን ፡ በክህነቶሙ ፡ ወሳሙኤልኒ ፡ ምስለ ፡ እለ ፡ ይጼውዑ ፡ ስሞ ፤ ይጼውዕዎ ፡ ለእግዚአብሔር ፡ ወውእቱኒ ፡ ይሰጠዎሙ ።"),
    (98, 7, "ወይትናገሮሙ ፡ በዐምደ ፡ ደመና ፤ ወየዐቅቡ ፡ ስምዖ ፡ ወትእዛዞሂ ፡ ዘወሀቦሙ ።"),
    (98, 8, "እግዚኦ ፡ አምላክነ ፡ አንተ ፡ ሰማዕኮሙ ፤ እግዚኦ ፡ አንተ ፡ ተሣህልኮሙ ፡ ወትትቤቀል ፡ በኵሉ ፡ ምግባሮሙ ።"),
    (98, 9, "ተለዐለ ፡ እግዚአብሔር ፡ አምላክነ ፡ ወይሰግዱ ፡ ሎቱ ፡ ውስተ ፡ ደብረ ፡ መቅደሱ ፤ እስመ ፡ ቅዱስ ፡ ውእቱ ፡ እግዚአብሔር ፡ አምላክነ ።"),
    (99, 1, "መዝሙር ፡ ዘተጋንዮ ። የብቡ ፡ ለእግዚአብሔር ፡ በኵሉ ፡ ምድር ።"),
    (99, 2, "ተቀንዩ ፡ ለእግዚአብሔር ፡ በትፍሥሕት ፤ ወባኡ ፡ ቅድሜሁ ፡ በሐሤት ።"),
    (99, 3, "ኣእምሩ ፡ ከመ ፡ እግዚአብሔር ፡ ውእቱ ፡ አምላክነ ፤ ወውእቱ ፡ ፈጠረነ ፡ ወአኮ ፡ ንሕነ ፡ ወንሕነሰ ፡ ሕዝቡ ፡ ወአባግዐ ፡ መርዔቱ ።"),
    (99, 4, "ባኡ ፡ ውስተ ፡ አናቅጺሁ ፡ በተጋንዮ ፡ ወውስተ ፡ አዕጻዲሁ ፡ በስብሐት ፤ እመንዎ ፡ ወሰብሑ ፡ ለስሙ ።"),
    (99, 5, "እስመ ፡ ኄር ፡ እግዚአብሔር ፡ እስመ ፡ ለዓለም ፡ ምሕረቱ ፤ ወለትውልደ ፡ ትውልድ ፡ ጽድቁ ።"),
    (100, 1, "መዝሙር ፡ ዘዳዊት ። ምሕረተ ፡ ወፍትሕ ፡ አኀሊ ፡ ለከ ።"),
    (100, 2, "እዜምር ፡ ወእሌቡ ፡ ፍኖተ ፡ ንጹሕ ፤ ማእዜ ፡ ትመጽእ ፡ ኀቤየ ። ወአሐውር ፡ በየዋሃተ ፡ ልብየ ፡ በማእከለ ፡ ቤትየ ።"),
    (100, 3, "ወኢረሰይኩ ፡ ቅድመ ፡ አዕይንትየ ፡ ግብረ ፡ እኩየ ፤ ጸላእኩ ፡ ገበርተ ፡ ዐመፃ ፡"),
    (100, 4, "ወኢተለወኒ ፡ ልብ ፡ ጠዋይ ። ሶበ ፡ ተግሕሠ ፡ እኩይ ፡ እምኔየ ፡ ኢያእመርኩ ።"),
    (100, 5, "ዘየሐሚ ፡ ቢጾ ፡ በጽሚት ፡ ኪያሁ ፡ ሰደድኩ ፤ ዕቡየ ፡ ዐይን ፡ ወሥሡዐ ፡ ልብ ፡ ኢይትሀወል ፡ ምስሌየ ።"),
    (100, 6, "አዕይንትየሰ ፡ ኀበ ፡ መሀይምናነ ፡ ምድር ፡ ከመ ፡ ኣንብሮሙ ፡ ምስሌየ ፤ ዘየሐውር ፡ በፍኖት ፡ ንጹሕ ፡ ውእቱ ፡ ይትለአከኒ ።"),
    (100, 7, "ወኢይነብር ፡ ማእከለ ፡ ቤትየ ፡ ዘይገብር ፡ ትዕቢተ ፤ ወኢያረትዕ ፡ ቅድሜየ ፡ ዘይነብብ ፡ ዐመፃ ።"),
    (100, 8, "በጽባሕ ፡ እቀትሎሙ ፡ ለኵሎሙ ፡ ኃጥኣነ ፡ ምድር ፤ ከመ ፡ እሠርዎሙ ፡ እምሀገረ ፡ እግዚአብሔር ፡ ለኵሎሙ ፡ ገበርተ ፡ ዐመፃ ።"),
    (101, 1, "ጸሎት ፡ ባሕታዊ ፡ ሶበ ፡ ይቴክዝ ፤ ወይክዑ ፡ ቅድመ ፡ እግዚአብሔር ፡ ኵሎ ፡ ስእለቶ ።"),
    (101, 3, "ስምዐኒ ፡ እግዚኦ ፡ ጸሎትየ ፤ ወይብጻሕ ፡ ቅድሜከ ፡ ገዐርየ ።"),
    (101, 3, "ወኢትሚጥ ፡ ገጸከ ፡ እምኔየ ፡ በዕለተ ፡ መንዳቤየ ፤ አፅምእ ፡ እዝነከ ፡ ኀቤየ ፡ አመ ፡ ዕለተ ፡ እጼውዐከ ፡ ፍጡነ ፡ ስምዐኒ ።"),
    (101, 4, "እስመ ፡ ኀልቀ ፡ ከመ ፡ ጢስ ፡ መዋዕልየ ፤ ወነቅጸ ፡ ከመ ፡ ሣዕር ፡ አዕጽምትየ ።"),
    (101, 5, "ተቀሠፍኩ ፡ ወየብሰ ፡ ከመ ፡ ሣዕር ፡ ልብየ ፤ እስመ ፡ ተረስዐኒ ፡ በሊዐ ፡ እክል ።"),
    (101, 6, "እምቃለ ፡ ገዐርየ ፡ ጠግዐ ፡ ሥጋየ ፡ ዲበ ፡ አዕጽምትየ ።"),
    (101, 7, "ወኮንኩ ፡ ከመ ፡ አዱገ ፡ መረብ ፡ ዘገዳም ፤ ወኮንኩ ፡ ከመ ፡ ጉጓ ፡ ውስተ ፡ ቤት ፡ ሌሊተ ።"),
    (101, 8, "ተጋህኩ ፡ ወኮንኩ ፡ ከመ ፡ ዖፍ ፡ ባሕታዊ ፡ ውስተ ፡ ናሕስ ።"),
    (101, 9, "ኵሎ ፡ አሚረ ፡ ይጼእሉኒ ፡ ጸላእትየ ፤ ወእለኒ ፡ ይሰዱኒ ፡ ይሰካትዩ ፡ ላዕሌየ ።"),
    (101, 10, "እስመ ፡ ሐመደ ፡ ከመ ፡ እክል ፡ ቀማሕኩ ፤ ወስቴየኒ ፡ ምስለ ፡ አንብዕየ ፡ ሰተይኩ ።"),
    (101, 11, "እምገጸ ፡ መቅሠፍተ ፡ መዐትከ ፤ እስመ ፡ አንሣእከኒ ፡ ወነፃኅከኒ ።"),
    (101, 12, "ወመዋዕልየኒ ፡ ከመ ፡ ጽላሎት ፡ ኀለፈ ፤ ወአነሂ ፡ ከመ ፡ ሣዕር ፡ የበስኩ ።"),
    (101, 13, "ወአንተሰ ፡ እግዚኦ ፡ ለዓለም ፡ ትነብር ፤ ወዝክርከኒ ፡ ለትውልደ ፡ ትውልድ ።"),
    (101, 14, "ተንሥእ ፡ እግዚኦ ፡ ወተሣሀለ ፡ ለጽዮን ፤ እስመ ፡ ጊዜሃ ፡ ውእቱ ፡ ከመ ፡ ተሣሀላ ፡ ወበጽሐ ፡ ዕድሜሃ ።"),
    (101, 15, "እስመ ፡ ሠምሩ ፡ አግብርቲከ ፡ እበኒሃ ፤ ወአክበርዎ ፡ ለመሬታ ።"),
    (101, 16, "ወይፍርሁ ፡ አሕዛብ ፡ ስመከ ፡ እግዚኦ ፤ ወኵሎሙ ፡ ነገሥት ፡ ለስብሐቲከ ።"),
    (101, 17, "እስመ ፡ የሐንጻ ፡ እግዚአብሔር ፡ ለጽዮን ፤ ወያስተርኢ ፡ በስብሐቲሁ ።"),
    (101, 18, "ወነጸረ ፡ ላዕለ ፡ ጸሎተ ፡ ነዳይ ፤ ወኢተቈጥዐ ፡ ስእለቶሙ ።"),
    (101, 19, "ወተጽሕፈት ፡ ዛቲ ፡ ለካልእ ፡ ትውልድ ፤ ወሕዝብ ፡ ዘይትፈጠር ፡ ይሴብሖ ፡ ለእግዚአብሔር ።"),
    (101, 20, "እስመ ፡ ሐወጸ ፡ እምሰማየ ፡ መቅደሱ ፤ እግዚአብሔር ፡ ሐወጸ ፡ እምሰማይ ፡ ዲበ ፡ ምድር ።"),
    (101, 21, "ከመ ፡ ይስማዕ ፡ ገዐሮሙ ፡ ለሙቁሓን ፤ ወከመ ፡ ያሕይዎሙ ፡ ለደቂቀ ፡ ቅቱላን ።"),
    (101, 22, "ከመ ፡ ይንግሩ ፡ በጽዮን ፡ ስመ ፡ እግዚአብሔር ፤ ወስብሐቲሁኒ ፡ በኢየሩሳሌም ።"),
    (101, 23, "ሶበ ፡ ተጋብኡ ፡ አሕዛብ ፡ ኅቡረ ፤ ወነገሥትኒ ፡ ከመ ፡ ይትቀነዩ ፡ ለእግዚአብሔር ።"),
    (101, 24, "ወተሠጥዎሙ ፡ በፍኖተ ፡ ኀይሉ ፤ ንግረኒ ፡ ውሕዶን ፡ ለመዋዕልየ ።"),
    (101, 25, "ወኢትሰደኒ ፡ በመንፈቀ ፡ ዐመትየ ። ለትውልደ ፡ ትውልድ ፡ ዐመቲከ ።"),
    (101, 26, "አንተ ፡ እግዚኦ ፡ አቅደምከ ፡ ሳርሮታ ፡ ለምድር ፤ ወግብረ ፡ እደዊከ ፡ እማንቱ ፡ ሰማያት ።"),
    (101, 27, "እማንቱሰ ፡ ይትሐጐላ ፡ ወአንተሰ ፡ ትሄሉ ፤ ወኵሉ ፡ ከመ ፡ ልብስ ፡ ይበሊ ፤ ወከመ ፡ ሞጣሕት ፡ ትዌልጦሙ ፡ ወይትዌለጡ ።"),
    (101, 28, "ወአንተሰ ፡ አንተ ፡ ክመ ፤ ወዐመቲከኒ ፡ ዘኢየኀልቅ ።"),
    (101, 29, "ወደቂቀ ፡ አግብርቲከ ፡ ይነብርዋ ፤ ወዘርዖሙኒ ፡ ለዓለም ፡ ይጸንዕ ።"),
    (102, 1, "ዘዳዊት ። ተባርኮ ፡ ነፍስየ ፡ ለእግዚአብሔር ፤ ወኵሉ ፡ አዕጽምትየ ፡ ለስሙ ፡ ቅዱስ ።"),
    (102, 2, "ተባርኮ ፡ ነፍስየ ፡ ለእግዚአብሔር ፤ ወኢትርሳዕ ፡ ኵሎ ፡ ሰብሐቲሁ ።"),
    (102, 3, "ዘይሰሪ ፡ ለከ ፡ ኵሎ ፡ ኃጢአትከ ፤ ዘይፌውሰከ ፡ እምኵሉ ፡ ደዌከ ።"),
    (102, 4, "ዘያድኅና ፡ እሙስና ፡ ለሕይወትከ ፤ ዘይኬልለከ ፡ በሣህሉ ፡ ወበምሕረቱ ።"),
    (102, 5, "ዘያጸግባ ፡ እምበረከቱ ፡ ለፍትወትከ ፤ ዘይሔድሳ ፡ ከመ ፡ ንስር ፡ ለውርዙትከ ።"),
    (102, 6, "ገባሬ ፡ ሣህል ፡ እግዚአብሔር ፤ ወይፈትሕ ፡ ለኵሉ ፡ ግፉዓን ።"),
    (102, 7, "አርአየ ፡ ፍናዊሁ ፡ ለሙሴ ፤ ወለደቂቀ ፡ እስራኤል ፡ ሥምረቶ ።"),
    (102, 8, "መሓሪ ፡ ወመስተሣህል ፡ እግዚአብሔር ፤ ርሑቀ ፡ መዐት ፡ ወብዙኀ ፡ ምሕረት ፡ ወጻድቅ ።"),
    (102, 9, "ኢይቀሥፍ ፡ ወትረ ፡ ወኢይትመዓዕ ፡ ዘልፈ ።"),
    (102, 10, "አኮ ፡ በከመ ፡ ኀጢአትነ ፡ ዘገብረ ፡ ለነ ፤ ወኢፈደየነ ፡ በከመ ፡ አበሳነ ።"),
    (102, 11, "ወበከመ ፡ ልዑል ፡ ሰማይ ፡ እምድር ፤ አጽንዐ ፡ ምሕረቶ ፡ እግዚአብሔር ፡ ላዕለ ፡ እለ ፡ ይፈርህዎ ።"),
    (102, 12, "ወበከመ ፡ ይርሕቅ ፡ ሠርቅ ፡ እምዐረብ ፤ አርሐቀ ፡ እምኔነ ፡ ኀጢአተነ ።"),
    (102, 13, "ወበከመ ፡ ይምሕር ፡ አብ ፡ ውሉደ ፤ ከማሁ ፡ ይምሕሮሙ ፡ እግዚአብሔር ፡ ለእለ ፡ ይፈርህዎ ።"),
    (102, 14, "እስመ ፡ ውእቱ ፡ ያአመር ፡ ፍጥረተነ ፤ ተዘከር ፡ እግዚኦ ፡ ከመ ፡ መሬት ፡ ንሕነ ።"),
    (102, 15, "ወሰብእሰ ፡ ከመ ፡ ሣዕር ፡ መዋዕሊሁ ፤ ወከመ ፡ ጽጌ ፡ ገዳም ፡ ከማሁ ፡ ይፈሪ ።"),
    (102, 16, "እስመ ፡ መንፈስ ፡ ይወፅእ ፡ እምኔሁ ፡ ወኢይሄሉ ፡ እንከ ፤ ወኢያአምር ፡ እንከ ፡ መካኖ ።"),
    (102, 17, "ወሣህሉሰ ፡ ለእግዚአብሔር ፡ እምዓለም ፡ ወእስከ ፡ ለዓለም ፡ ዲበ ፡ እለ ፡ ይፈርህዎ ፤ ወጽድቁኒ ፡ ዲበ ፡ ትውልደ ፡ ትውልድ ።"),
    (102, 18, "ለእለ ፡ የዐቅቡ ፡ ሕጎ ፤ ወይዜከሩ ፡ ትእዛዞ ፡ ከመ ፡ ይግበሩ ።"),
    (102, 19, "እግዚአብሔር ፡ አስተዳለወ ፡ መንበሮ ፡ በሰማያት ፤ ወኵሎ ፡ ይኴንን ፡ በመንግሥቱ ።"),
    (102, 20, "ባርክዎ ፡ ለእግዚአብሔር ፡ ኵልክሙ ፡ መላእክቲሁ ፤ ጽኑዓን ፡ ወኀያላን ፡ እለ ፡ ትገብሩ ፡ ቃሎ ፡ ወእለ ፡ ትሰምዑ ፡ ቃለ ፡ ነገሩ ።"),
    (102, 21, "ባርክዎ ፡ ለእግዚአብሔር ፡ ኵሉ ፡ ኀይሉ ፤ ላእካኑ ፡ እለ ፡ ይገብሩ ፡ ፈቃዶ ።"),
    (102, 22, "ባርክዎ ፡ ለእግዚአብሔር ፡ ኵሉ ፡ ተግባሩ ፤ ውስተ ፡ ኵሉ ፡ በሐውርተ ፡ መለኮቱ ፤ ትባርኮ ፡ ነፍስየ ፡ ለእግዚአብሔር ።"),
    (103, 1, "ዘዳዊት ። ትባርኮ ፡ ነፍስየ ፡ ለእግዚአብሔር ። እግዚኦ ፡ አምላኪየ ፡ ጥቀ ፡ ዐበይከ ፡ ፈድፋደ ፤ አሚነ ፡ ወዕበየ ፡ ስብሐት ፡ ለበስከ ።"),
    (103, 2, "ወለበስከ ፡ ብርሃነ ፡ ከመ ፡ ልብስ ፤ ወረበብኮ ፡ ለሰማይ ፡ ከመ ፡ ሠቅ ።"),
    (103, 3, "ዘይጠፍር ፡ በማይ ፡ ጽርሖ ፡ ወረሰየ ፡ ደመና ፡ መከየዶ ፤ ዘየሐውር ፡ በክነፈ ፡ ነፋስ ።"),
    (103, 4, "ዘይሬስዮሙ ፡ ለመላእክቲሁ ፡ መንፈሰ ፤ ወለእለ ፡ ይትለአክዎ ፡ ነደ ፡ እሳት ።"),
    (103, 5, "ሳረራ ፡ ለምድር ፡ ወአጽንዓ ፤ ከመ ፡ ኢታንቀልቅል ፡ ለዓለመ ፡ ዓለም ።"),
    (103, 6, "ወቀላይኒ ፡ ከመ ፡ ልብስ ፡ ዐጽፋ ፤ ውስተ ፡ አድባር ፡ ይቀውሙ ፡ ማያት ።"),
    (103, 7, "ወእምተግሣጽከ ፡ ይጐዩ ፤ ወእምድምፀ ፡ ነጐድጓድከ ፡ ይደነግፁ ።"),
    (103, 8, "የዐርጉ ፡ አድባረ ፡ ወይወርዱ ፡ ገዳመ ፤ ውስተ ፡ ብሔር ፡ ኀበ ፡ ሳረርኮሙ ።"),
    (103, 9, "ወሠራዕኮሙ ፡ ወሰኖሙ ፡ እምኀበ ፡ ኢየኀልፉ ፤ ከመ ፡ ኢይትመየጡ ፡ ወኢይክድንዋ ፡ ለምድር ።"),
    (103, 10, "ዘይፌኑ ፡ አንቅዕተ ፡ ውስተ ፡ ቈላት ፤ ማእከለ ፡ አድባር ፡ የኀልፉ ፡ ማየት ።"),
    (103, 11, "ወያሰትዩ ፡ ለኵሉ ፡ አርዌ ፡ ገዳም ፤ ወይትወክፉ ፡ ሐለስትዮታት ፡ ለጽምኦሙ ።"),
    (103, 12, "ወያጸሉ ፡ ህየ ፡ አዕዋፈ ፡ ሰማይ ፤ ወይነቅዉ ፡ በማእከለ ፡ ጾላዓት ።"),
    (103, 13, "ዘይሰቅዮሙ ፡ ለአድባር ፡ እምውሳጥያቲሆሙ ፤ እምፍሬ ፡ ተግባርከ ፡ ትጸግብ ፡ ምድር ።"),
    (103, 14, "ዘያበቍል ፡ ሣዕረ ፡ ለእንስሳ ፡ ወኀመልማለ ፡ ለቅኔ ፡ እጓለ ፡ እመሕያው ፤ ከመ ፡ ያውፅእ ፡ እክለ ፡ እምድር ።"),
    (103, 15, "ወወይን ፡ ያስተፌሥሕ ፡ ልበ ፡ ሰብእ ፡ ወቅብእ ፡ ለአብርሆ ፡ ገጽ ፤ ወእክል ፡ ያጸንዕ ፡ ኀይለ ፡ ሰብእ ።"),
    (103, 16, "ወይጸግቡ ፡ ዕፀወ ፡ ገዳም ፤ አርዘ ፡ ሊባኖስ ፡ ዘተከልከ ።"),
    (103, 17, "ወበህየ ፡ ይትዋለዳ ፡ አዕዋፍ ፤ ወይትጋወሮን ፡ ቤተ ፡ ሄርድያኖስ ።"),
    (103, 18, "አድባር ፡ ነዋኃት ፡ ለሀየላት ። ወጾላዓት ፡ ምጕያዮን ፡ ለግሔያት ።"),
    (103, 19, "ወገበርከ ፡ ወርኀ ፡ በዕድሜሁ ፤ ፀሐይኒ ፡ አእመረ ፡ ምዕራቢሁ ።"),
    (103, 20, "ታመጽእ ፡ ጽልመተ ፡ ወይከውን ፡ ሌሊተ ፤ ወይወፅኡ ፡ ቦቱ ፡ ኵሉ ፡ አርዌ ፡ ገዳም ።"),
    (103, 21, "እጕለ ፡ አናብስት ፡ ይጥሕሩ ፡ ወይመስጡ ፤ ወይስእሉ ፡ ኀበ ፡ እግዚአብሔር ፡ ሲሳዮሙ ።"),
    (103, 22, "ወእምከመ ፡ ሠረቀ ፡ ፀሐይ ፡ የአትዉ ፤ ወይውዕሉ ፡ ውስተ ፡ ግበቢሆሙ ።"),
    (103, 23, "ወይወፍር ፡ ሰብእ ፡ ውስተ ፡ ተግባሩ ፤ ወይውዕል ፡ ወይትቀነይ ፡ እስከ ፡ ይመሲ ።"),
    (103, 24, "ጥቀ ፡ ዐቢይ ፡ ግብርከ ፡ እግዚኦ ፡ ወኵሎ ፡ በጥበብ ፡ ገበርከ ፤ መልአ ፡ ምድር ፡ ዘፈጠርከ ።"),
    (103, 25, "ዛቲ ፡ ባሕር ፡ ዐባይ ፡ ወረሓብ ፤ ህየ ፡ ዘይትሐወስ ፡ ዘአልቦ ፡ ኈልቁ ፡ እንስሳ ፡ ዐበይተ ፡ ምስለ ፡ ደቃቅ ።"),
    (103, 26, "ህየ ፡ ይሐውራ ፡ አሕማር ፤ ከይሲ ፡ ዘፈጠርከ ፡ ይሳለቅ ፡ ላዕሌሆሙ ።"),
    (103, 27, "ወኵሉ ፡ ይሴፎ ፡ ኀቤከ ፤ አንተ ፡ ትሁቦሙ ፡ ሲሳዮሙ ፡ በበጊዜሁ ።"),
    (103, 28, "ወእምከመ ፡ ወሀብኮሙ ፡ ያስተጋብኡ ፤ ወፈቲሕከ ፡ እዴከ ፡ ታጸግብ ፡ ለኵሉ ፡ እምሕረትከ ።"),
    (103, 29, "ወእመሰ ፡ ሜጥከ ፡ ገጸከ ፡ ይደነግፁ ፤ ታወፅእ ፡ መንፈሶሙ ፡ ወየኀልቁ ፡ ወይገብኡ ፡ ውስተ ፡ መሬቶሙ ።"),
    (103, 30, "ወትፌኑ ፡ መንፈሰከ ፡ ወይትፈጠሩ ፤ ወትሔድስ ፡ ገጻ ፡ ለምድር ።"),
    (103, 31, "ለይኩን ፡ ስብሐቲሁ ፡ ለእግዚአብሔር ፡ ለዓለም ፤ ይትፌሣሕ ፡ እግዚአብሔር ፡ በተግባሩ ።"),
    (103, 32, "ዘይኔጽራ ፡ ለምድር ፡ ወይሬስያ ፡ ከመ ፡ ትርዐድ ፤ ዘይገሶሙ ፡ ለአድባር ፡ ወይጠይሱ ።"),
    (103, 33, "እሴብሖ ፡ ለእግዚአብሔር ፡ በሕይወትየ ፤ ወእዜምር ፡ ለአምላኪየ ፡ በአምጣነ ፡ ሀሎኩ ።"),
    (103, 34, "ወኣሠምሮ ፡ በቃልየ ፤ ወአንሰ ፡ እትፌሣሕ ፡ በእግዚአብሔር ።"),
    (103, 35, "ወየኀልቁ ፡ ኃጥኣን ፡ እምድር ፡ ወአማፅያንሂ ፡ ኢይሄልዉ ፡ እንከ ፤ ትባርኮ ፡ ነፍስየ ፡ ለእግዚአብሔር ።"),
    (104, 1, "ሀሌሉያ ። ግኔዩ ፡ ለእግዚአብሔር ፡ ወጸውዑ ፡ ስሞ ፤ ወንግርዎሙ ፡ ለአሕዛብ ፡ ምግባሮ ።"),
    (104, 2, "ሰብሕዎ ፡ ወዘምሩ ፡ ሎቱ ፤ ወንግሩ ፡ ኵሎ ፡ መንክሮ ።"),
    (104, 3, "ወትከብሩ ፡ በስሙ ፡ ቅዱስ ፤ ለይትፌሣሕ ፡ ልብ ፡ ዘየኀሦ ፡ ለእግዚአብሔር ።"),
    (104, 4, "ኅሥዎ ፡ ለእግዚአብሔር ፡ ወትጸንዑ ፤ ወኅሡ ፡ ገጾ ፡ በኵሉ ፡ ጊዜ ።"),
    (104, 5, "ወተዘከሩ ፡ መንክሮ ፡ ዘገብረ ፤ ተኣምሪሁ ፡ ወኵነኔ ፡ አፉሁ ።"),
    (104, 6, "ዘርዐ ፡ አብርሃም ፡ አግብርቲሁ ፤ ወደቂቀ ፡ ያዕቆብ ፡ ኅሩያኒሁ ።"),
    (104, 7, "ውእቱ ፡ እግዚአብሔር ፡ አምላክነ ፤ ውስተ ፡ ኵሉ ፡ ምድር ፡ ኵነኔሁ ።"),
    (104, 8, "ወተዘከረ ፡ ሥርዐቶ ፡ ዘለዓለም ፤ ቃሎ ፡ ዘአዘዘ ፡ ለዐሠርቱ ፡ ምእት ፡ ትውልድ ።"),
    (104, 9, "ዘሠርዐ ፡ ለአብርሃም ፤ ወመሐለ ፡ ለይስሐቅ ።"),
    (104, 10, "ወአቀመ ፡ ስምዐ ፡ ለያዕቆብ ፤ ወለእስራኤል ፡ ኪዳኖ ፡ ዘለዓለም ።"),
    (104, 11, "ወይቤሎ ፤ ለከ ፡ እሁበከ ፡ ምድረ ፡ ከናዐን ፤ ትኩንክሙ ፡ ሐብለ ፡ ርስትክሙ ።"),
    (104, 12, "እንዘ ፡ ውኁዳን ፡ ጥቀ ፡ እሙንቱ ፤ ወፈላስያን ፡ ውስቴታ ።"),
    (104, 13, "ወኀለፉ ፡ እምሕዝብ ፡ ውስተ ፡ ሕዝብ ፤ ወእምነገሥት ፡ ውስተ ፡ ካልእ ፡ ሕዝብ ።"),
    (104, 14, "ወኢኀደገ ፡ ይስሐጦሙ ፡ ሰብእ ፤ ወገሠጸ ፡ ነገሥተ ፡ በእንቲአሆሙ ።"),
    (104, 15, "ኢትግስሱ ፡ መሲሓንየ ፤ ወኢታሕሥሙ ፡ ዲበ ፡ ነቢያትየ ።"),
    (104, 16, "ወአምጽአ ፡ ረኃበ ፡ ለብሔር ፤ ወአጥፍአ ፡ ኵሎ ፡ ኀይለ ፡ እክል ።"),
    (104, 17, "ፈነወ ፡ ብእሴ ፡ ቅድሜሆሙ ፤ ወተሰይጠ ፡ ዮሴፍ ፡ ወኮነ ፡ ገብረ ።"),
    (104, 18, "ወሐማ ፡ እገሪሁ ፡ በመዋቅሕት ፤ ወአምሰጠት ፡ ነፍሱ ፡ እምኀጺን ።"),
    (104, 19, "ዘእንበለ ፡ ይብጻሕ ፡ ቃሉ ፤ ቃለ ፡ እግዚአብሔር ፡ እመከሮ ።"),
    (104, 20, "ወፈነወ ፡ ንጉሥ ፡ ወፈትሖ ፤ ወሤሞ ፡ መልአከ ፡ አሕዛብ ።"),
    (104, 21, "ወረሰዮ ፡ እግዚአ ፡ ለቤቱ ፤ ወአኰነኖ ፡ ላዕለ ፡ ኵሉ ፡ ጥሪቱ ።"),
    (104, 22, "ከመ ፡ ይገሥጾሙ ፡ ለመላእክቲሁ ፡ ከማሁ ፤ ወከመ ፡ ያጥብቦሙ ፡ ለሊቃውንቲሁ ፡ ከማሁ ።"),
    (104, 23, "ወቦአ ፡ እስራኤል ፡ ብሔረ ፡ ግብጽ ፤ ወያዕቆብኒ ፡ ኀደረ ፡ ምድረ ፡ ካም ።"),
    (104, 24, "ወአብዝኆሙ ፡ ለሕዝቡ ፡ ፈድፋደ ፤ ወአጽንዖሙ ፡ እምፀሮሙ ።"),
    (104, 25, "ወሜጠ ፡ ልቦሙ ፡ ከመ ፡ ይጽልኡ ፡ ሕዝቦ ፤ ወከመ ፡ ይሐብልይዎሙ ፡ ለአግብርቲሁ ።"),
    (104, 26, "ወፈነወ ፡ ሙሴሃ ፡ ገብሮ ፤ ወአሮንሃ ፡ ኅሩዮ ።"),
    (104, 27, "ወሤመ ፡ ቃለ ፡ ትእምርት ፡ ላዕሌሆሙ ፤ ወመንክሮሂ ፡ በምድረ ፡ ካም ።"),
    (104, 28, "ወፈነወ ፡ ጽልመተ ፡ ወአጽለሞሙ ፤ ወአምረርዎ ፡ ለቃሉ ።"),
    (104, 29, "ወረሰየ ፡ ማዮሙ ፡ ደመ ፤ ወቀተለ ፡ ዐሣቲሆሙ ።"),
    (104, 30, "ወአውፅአት ፡ ምድሮሙ ፡ ቈርነነዓተ ፤ ውስተ ፡ አብያተ ፡ ነገሥቶሙ ።"),
    (104, 31, "ይቤ ፡ ወመጽአ ፡ አኮት ፤ ወትንንያ ፡ ውስተ ፡ ኵሉ ፡ ምድሮሙ ።"),
    (104, 32, "ወረሰየ ፡ ዝናሞሙ ፡ በረደ ፤ ወነደ ፡ እሳት ፡ ውስተ ፡ ምድሮሙ ።"),
    (104, 33, "ወቀተለ ፡ ወይኖሙ ፡ ወበለሶሙ ፤ ወቀጥቀጠ ፡ ኵሎ ፡ ዕፀወ ፡ ብሔሮሙ ።"),
    (104, 34, "ይቤ ፡ ወመጽአ ፡ አንበጣ ፤ ወደጎብያ ፡ ዘአልቦ ፡ ኈልቈ ።"),
    (104, 35, "[ወበልዐ ፡ ኵሎ ፡ ሣዕረ ፡ ብሔሮሙ ፤] ወበልዐ ፡ ኵሎ ፡ ፍሬ ፡ ምድሮሙ ።"),
    (104, 36, "ወቀተለ ፡ ኵሎ ፡ በኵረ ፡ ብሔሮሙ ፤ ወቀዳሜ ፡ ኵሉ ፡ ተግባሮሙ ።"),
    (104, 37, "ወአውፅኦሙ ፡ በወርቅ ፡ ወበብሩር ፤ ወአልቦ ፡ ደዌ ፡ ውስተ ፡ ሕዝቦሙ ።"),
    (104, 38, "ወተፈሥሑ ፡ ግብጽ ፡ በፀአቶሙ ፤ እስመ ፡ ፈርሀዎሙ ።"),
    (104, 39, "ወአንጦልዐ ፡ ደመና ፡ ወሰወሮሙ ፤ ወእሳትኒ ፡ ከመ ፡ ያብርህ ፡ ሎሙ ፡ በሌሊት ።"),
    (104, 40, "ወሰአሉ ፡ ወመጽአ ፡ ፍርፍርት ፤ ወአጽገቦሙ ፡ ኅብስተ ፡ ሰማይ ።"),
    (104, 41, "ወአንቅዐ ፡ ኰኵሐ ፡ ወአውሐዘ ፡ ማየ ፤ ወሖሩ ፡ አፍላግ ፡ ውስተ ፡ በድው ።"),
    (104, 42, "እስመ ፡ ተዘከረ ፡ ቃሎ ፡ ቅዱሰ ፤ ዘኀበ ፡ አብርሃም ፡ ገብሩ ።"),
    (104, 43, "ወአውፅኦሙ ፡ ለሕዝብ ፡ በትፍሥሕት ፤ ወለኅሩያኒሁ ፡ በሐሤት ።"),
    (104, 44, "ወወሀቦሙ ፡ በሐውርተ ፡ አሕዛብ ፤ ወወረሱ ፡ ጻማ ፡ ባዕድ ።"),
    (104, 45, "ከመ ፡ ይዕቀቡ ፡ ሕጎ ፤ ወይኅሥሡ ፡ ሥርዐቶ ።"),
    (105, 1, "ሀሌሉያ ። ግኔዩ ፡ ለእግዚአብሔር ፡ እስመ ፡ ኄር ፤ እስመ ፡ ለዓለም ፡ ምሕረቱ ።"),
    (105, 2, "መኑ ፡ ይነግር ፡ ኀይለ ፡ እግዚአብሔር ፤ ወይገብር ፡ ከመ ፡ ይስማዕ ፡ ኵሎ ፡ ስብሐቲሁ ።"),
    (105, 3, "ብፁዓን ፡ እለ ፡ የዐቅቡ ፡ ፍትሐ ፤ ወይገብሩ ፡ ጽድቀ ፡ በኵሉ ፡ ጊዜ ።"),
    (105, 4, "ተዘከረነ ፡ እግዚኦ ፡ ብሣህልከ ፡ ሕዝበከ ፤ ወተሣሀለነ ፡ በአድኅኖትከ ።"),
    (105, 5, "ከመ ፡ ንርአይ ፡ ሠናይቶሙ ፡ ለኅሩያኒከ ፤ ወከመ ፡ ንትፈሣሕ ፡ በፍሥሓ ፡ ሕዝብከ ፤ ወከመ ፡ ንክበር ፡ ምስለ ፡ ርስትከ ።"),
    (105, 6, "አበስነ ፡ ምስለ ፡ አበዊነ ፤ ዐመፅነ ፡ ወጌገይነ ።"),
    (105, 7, "ወአበዊነሂ ፡ በብሔረ ፡ ግብጽ ፡ ኢያእመሩ ፡ መንክረከ ፤ ወኢተዘከሩ ፡ ብዝኀ ፡ ምሕረትከ ፤ ወአምረሩከ ፡ አመ ፡ የዐርጉ ፡ ባሕረ ፡ ኤርትራ ።"),
    (105, 8, "ወአድኀኖሙ ፡ በእንተ ፡ ስሙ ፤ ከመ ፡ ያርእዮሙ ፡ ኀይሎ ።"),
    (105, 9, "ወገሠጻ ፡ ለባሕረ ፡ ኤርትራ ፡ ወየብሰት ፤ ወመርሖሙ ፡ በቀላይ ፡ ከመ ፡ ዘበገዳም ።"),
    (105, 10, "ወአድኀኖሙ ፡ እምእደ ፡ ጸላእቶሙ ፤ ወአንገፎሙ ፡ እምእደ ፡ ፀሮሙ ።"),
    (105, 11, "ወደፈኖሙ ፡ ማይ ፡ ለእለ ፡ ሮድዎሙ ፤ ወኢተርፈ ፡ አሐዱ ፡ እምውስቴቶሙ ።"),
    (105, 12, "ወተአመኑ ፡ በቃሉ ፤ ወሰብሕዎ ፡ በስብሐቲሁ ።"),
    (105, 13, "ወአፍጠኑ ፡ ረሲዐ ፡ ምግባሩ ፤ ወኢተዐገሡ ፡ በምክሩ ።"),
    (105, 14, "ወፈተዉ ፡ ፍትወተ ፡ በገዳም ፤ ወአምረርዎ ፡ ለእግዚአብሔር ፡ በበድው ።"),
    (105, 15, "ወወሀቦሙ ፡ ዘሰአሉ ፤ ወገነወ ፡ ጽጋበ ፡ ለነፍሶሙ ።"),
    (105, 16, "ወአምዕዕዎ ፡ ለሙሴ ፡ በትዕይንት ፤ ወለአሮን ፡ ቅዱሰ ፡ እግዚአብሔር ።"),
    (105, 17, "ወአብቀወት ፡ ምድር ፡ ወውኅጠቶ ፡ ለዳታን ፤ ወደፈነቶሙ ፡ ለተዓይነ ፡ አቤሮን ።"),
    (105, 18, "ወነደ ፡ እሳት ፡ ውስተ ፡ ተዓይንቲሆሙ ፤ ወአውዐዮሙ ፡ ነበልባል ፡ ለኃጥኣን ።"),
    (105, 19, "ወገብሩ ፡ ላህመ ፡ በኮሬብ ፤ ወሰገዱ ፡ ለግልፎ ።"),
    (105, 20, "ወወለጡ ፡ ክብሮሙ ፤ በአምሳለ ፡ ላህም ፡ ዘይትረዐይ ፡ ሣዕረ ።"),
    (105, 21, "ወረስዕዎ ፡ ለእግዚአብሔር ፡ ዘአድኅኖሙ ፤ ዘገብረ ፡ ዐቢያተ ፡ በግብጽ ።"),
    (105, 22, "ወመንክረ ፡ በምድረ ፡ ካም ፤ ወግሩመ ፡ በባሕረ ፡ ኤርትራ ።"),
    (
        105,
        23,
        "ወይቤ ፡ ከመ ፡ ይሠርዎሙ ፤ ሶበ ፡ አኮ ፡ ሙሴ ፡ ኅሩዮ ፡ ቆመ ፡ ቅድሜሁ ፡ አመ ፡ ብድብድ ፡ ከመ ፡ ይሚጥ ፡ መቅሠፍተ ፡ መዐቱ ፡ ወከመ ፡ ኢይሠርዎሙ ።",
    ),
    (105, 24, "ወመነኑ ፡ ምድረ ፡ መፍትወ ፤ ወኢተአመኑ ፡ በቃሉ ።"),
    (105, 25, "ወአንጐርጐሩ ፡ በውስተ ፡ ተዓይኒሆሙ ፤ ወኢሰምዑ ፡ ቃለ ፡ እግዚአብሔር ።"),
    (105, 26, "ወአንሥአ ፡ እዴሁ ፡ ላዕሌሆሙ ፤ ከመ ፡ ይንፅኆሙ ፡ በገዳም ።"),
    (105, 27, "ወከመ ፡ ይንፃኅ ፡ ዘርዖሙ ፡ ውስተ ፡ አሕዛብ ፤ ወከመ ፡ ይዝርዎሙ ፡ ውስተ ፡ በሓውርት ።"),
    (105, 28, "ወተፈጸሙ ፡ በብዔል ፡ ፌጎር ፤ ወበልዑ ፡ መሥዋዕተ ፡ ምዉተ ።"),
    (105, 29, "ወወሐክዎ ፡ በምግባሪሆሙ ፤ ወበዝኀ ፡ ብድብድ ፡ ላዕሌሆሙ ።"),
    (105, 30, "ወተንሥአ ፡ ፊንሐስ ፡ ወአድኀኖሙ ፤ ወኀደገ ፡ ብድብድ ።"),
    (105, 31, "ወተኈለቀ ፡ ጽድቅ ፤ ልትውልደ ፡ ትውልድ ፡ ወእስከ ፡ ለዓለም ።"),
    (105, 32, "ወአምዕዕዎ ፡ በኀበ ፡ ማየ ፡ ቅሥት ፤ ወሐመ ፡ ሙሴ ፡ በእንቲአሆሙ ።"),
    (105, 33, "እስመ ፡ አምረርዋ ፡ ለነፍሱ ፤ ወአዘዘ ፡ በከናፍሪሁ ።"),
    (105, 34, "ወኢሠረዉ ፡ አሕዛበ ፡ ዘይቤሎሙ ፡ እግዚአብሔር ።"),
    (105, 35, "ወተደመሩ ፡ ምስለ ፡ አሕዛብ ፤ ወተመሀሩ ፡ ምግባሮሙ ።"),
    (105, 36, "ወተቀንዩ ፡ ለግልፎሆሙ ፤ ወኮኖሙ ፡ ጌጋየ ።"),
    (105, 37, "ወዘብሑ ፡ ደቂቆሙ ፡ ወአዋልዲሆሙ ፡ ለአጋንንት ።"),
    (105, 38, "ወከዐዉ ፡ ደመ ፡ ንጹሐ ፡ ደመ ፡ ደቂቆሙ ፡ ወአዋልዲሆሙ ፤ ወሦዑ ፡ ለግልፎ ፡ ከናዐን ፤ ወተቀትለት ፡ ምድር ፡ በደም ።"),
    (105, 39, "ወረኵሰት ፡ ምድር ፡ በምግባሪሆሙ ፤ ወዘመዉ ፡ በጣዖቶሙ ።"),
    (105, 40, "ወተምዕዐ ፡ እግዚአብሔር ፡ መዐተ ፡ ላዕለ ፡ ሕዝቡ ፤ ወአስቆረሮሙ ፡ ለርስቱ ።"),
    (105, 41, "ወአግብኦሙ ፡ ውስተ ፡ እደ ፡ ፀሮሙ ፤ ወቀነይዎሙ ፡ ጸላእቶሙ ።"),
    (105, 42, "ወአሕመምዎሙ ፡ ፀሮሙ ፤ ወኀስሩ ፡ በታሕተ ፡ እደዊሆሙ ።"),
    (105, 43, "ወዘልፈ ፡ ያድኅኖሙ ፤ ወእሙንቱሰ ፡ አምረርዎ ፡ በምክሮሙ ፡ ወሐሙ ፡ በኀጢአቶሙ ።"),
    (105, 44, "ወርእዮሙ ፡ ከመ ፡ ተመንደቡ ፤ ወሰምዖሙ ፡ ጸሎቶሙ ።"),
    (105, 45, "ወተዘከረ ፡ ኪዳኖ ፤ ወነስሐ ፡ በከመ ፡ ብዙኀ ፡ ምሕረቱ ።"),
    (105, 46, "ወወሀቦሙ ፡ ሣህሎ ፤ በቅድመ ፡ ኵሎሙ ፡ እለ ፡ ፀወውዎሙ ።"),
    (105, 47, "አድኅነነ ፡ እግዚኦ ፡ አምላክነ ፡ ወአስተጋብአነ ፡ እምአሕዛብ ፤ ከመ ፡ ንግበይ ፡ ለስምከ ፡ ቅዱስ ፡ ወከመ ፡ ንትመካሕ ፡ በስብሐቲከ ።"),
    (105, 48, "ይትባረክ ፡ እግዚአብሔር ፡ አምላከ ፡ እስራኤል ፤ እምቅድመ ፡ ዓለም ፡ ወእስከ ፡ ለዓለም ፤ ወይበል ፡ ኵሉ ፡ ሕዝብ ፡ ለይኩን ፡ ለይኩን ።"),
    (106, 1, "ሀሌሉያ ። ግነዩ ፡ ለእግዚአብሔር ፡ እስመ ፡ ኄር ፤ እስመ ፡ ለዓለም ፡ ምሕረቱ ።"),
    (106, 2, "ለይበሉ ፡ እለ ፡ አድኀኖሙ ፡ እግዚአብሔር ፤ እለ ፡ አድኀኖሙ ፡ እምእደ ፡ ፀሮሙ ።"),
    (106, 3, "ወአስተጋብኦሙ ፡ እምበሓውርት ፤ እምጽባሕ ፡ ወእምዐረብ ፡ ወመስዕ ፡ ወባሕር ።"),
    (106, 4, "ወሳኰዩ ፡ ውስተ ፡ በድው ፡ ዘአልቦ ፡ ማየ ፤ ወኢረከቡ ፡ ፍኖተ ፡ ሀገረ ፡ ብሔሮሙ ።"),
    (106, 5, "ጸምኡ ፡ ወርኅቡ ፤ ወኀልቀት ፡ ነፍሶሙ ፡ በላዕሌሆሙ ።"),
    (106, 6, "ወዐውየዉ ፡ ኀበ ፡ እግዚአብሔር ፡ ሶበ ፡ ተመንደቡ ፤ ወአድኀኖሙ ፡ እምንዳቤሆሙ ።"),
    (106, 7, "ወመርሖሙ ፡ ፍኖተ ፡ ርቱዐ ፤ ከመ ፡ ይሖሩ ፡ ፍኖተ ፡ ሀገሮሙ ።"),
    (106, 8, "ንግሩ ፡ ለእግዚአብሔር ፡ ምሕረቶ ፤ ወመንክሮሂ ፡ ለእጓለ ፡ እመሕያው ።"),
    (106, 9, "እስመ ፡ አጽገበ ፡ ነፍሰ ፡ ርኅብተ ፤ ወመልአ ፡ ነፍሰ ፡ ዕራቃ ፡ በረከተ ።"),
    (106, 10, "ለእለ ፡ ይነብሩ ፡ ውስተ ፡ ጽልመት ፡ ወጽላሎተ ፡ ሞት ፤ ወመቁሓን ፡ በንዴት ፡ ወበኀጺን ።"),
    (106, 11, "እስመ ፡ አምረሩ ፡ ቃለ ፡ እግዚአብሔር ፤ ወአምዕዑ ፡ ምክረ ፡ ልዑል ።"),
    (106, 12, "ወሰርሐ ፡ በሕማም ፡ ልቦሙ ፤ ደወዩ ፡ ወኀጥኡ ፡ ዘይቀብሮሙ ።"),
    (106, 13, "ወዐውየዉ ፡ ኀበ ፡ እግዚአብሔር ፡ ሶበ ፡ ተመንደቡ ፤ ወአድኀኖሙ ፡ እምንዳቤሆሙ ።"),
    (106, 14, "ወአውፅኦሙ ፡ እምጽልመት ፡ ወጽላሎተ ፡ ሞት ፤ ወሰበረ ፡ መዋቅሕቲሆሙ ።"),
    (106, 15, "ንግሩ ፡ ለእግዚአብሔር ፡ ምሕረቶ ፤ ወመንክሮሂ ፡ ለእጓለ ፡ እመሕያው ።"),
    (106, 16, "እስመ ፡ ሰበረ ፡ ኆኃተ ፡ ብርት ፤ ወቀጥቀጠ ፡ መናስግተ ፡ ኀጺን ።"),
    (106, 17, "ወተወክፎሙ ፡ እምፍኖተ ፡ ጌጋዮሙ ፤ እስመ ፡ ሐሙ ፡ በኃጢአቶሙ ።"),
    (106, 18, "ወኵሎ ፡ መብልዐ ፡ አስቆረረት ፡ ነፍሶሙ ፤ ወቀርቡ ፡ ኀበ ፡ አናቅጸ ፡ ሞት ።"),
    (106, 19, "ወዐውየዉ ፡ ኀበ ፡ እግዚአብሔር ፡ ሶበ ፡ ተመንደቡ ፤ ወአድኀኖሙ ፡ እምንዳቤሆሙ ።"),
    (106, 20, "ወፈነወ ፡ ቃሎ ፡ ወአሕየዎሙ ፤ ወአድኀኖሙ ፡ እሞቶሙ ።"),
    (106, 21, "ንግሩ ፡ ለእግዚአብሔር ፡ ምሕረቶ ፤ ወመንክሮሂ ፡ ለእጓለ ፡ እመሕያው ።"),
    (106, 22, "ወይሡዑ ፡ ሎቱ ፡ መሥዋዕተ ፡ ስብሐት ፤ ወይንግሩ ፡ ግብሮ ፡ በትፍሥሕት ።"),
    (106, 23, "እለ ፡ ይወርዱ ፡ ውስተ ፡ ባሕር ፡ በአሕማር ፤ ወይትጌበሩ ፡ ተግባሮሙ ፡ ውስተ ፡ ማይ ፡ ብዙኅ ።"),
    (106, 24, "እሙንቱሰ ፡ ያአምሩ ፡ ግብረ ፡ እግዚአብሔር ፤ ወመንክሮሂ ፡ በውስተ ፡ ልጐት ።"),
    (106, 25, "ይቤ ፡ ወመጽአ ፡ መንፈሰ ፡ ዐውሎ ፤ ወተለዐለ ፡ ማዕበል ።"),
    (106, 26, "የዐርጉ ፡ እስከ ፡ ሰማይ ፡ ወይወርዱ ፡ እስከ ፡ ቀላይ ፤ ወተመስወት ፡ ነፍሶሙ ፡ በሕማም ።"),
    (106, 27, "ደንገፁ ፡ ወተሀውኩ ፡ ከመ ፡ ስኩር ፤ ወተሰጥመ ፡ ኵሉ ፡ ጥበቦሙ ።"),
    (106, 28, "ወዐውየዉ ፡ ኀበ ፡ እግዚአብሔር ፡ ሶበ ፡ ተመንደቡ ፤ ወአድኀኖሙ ፡ እምንዳቤሆሙ ።"),
    (106, 29, "ወአጥፍኦ ፡ ለዐውሎ ፡ ወአርመመ ፡ ባሕር ፤ ወአርመመ ፡ ማዕበል ።"),
    (106, 30, "ወተፈሥሑ ፡ እስመ ፡ አዕረፉ ፤ ወመርሖሙ ፡ ውስተ ፡ መርሶ ፡ ኀበ ፡ ፈቀዱ ።"),
    (106, 31, "ንግሩ ፡ ለእግዚአብሔር ፡ ምሕረቶ ፤ ወመንክሮሂ ፡ ለእጓለ ፡ እመሕያው ።"),
    (106, 32, "ወያዐብይዎ ፡ በማኅበረ ፡ አሕዛብ ፤ ወይሴብሕዎ ፡ በመንበረ ፡ ሊቃውንት ።"),
    (106, 33, "ወረሰዮሙ ፡ ለአፍላግ ፡ በድወ ፤ ወረሰየ ፡ ምጽማአ ፡ ሙሓዘ ፡ ማይ ።"),
    (106, 34, "ወረሰየ ፡ ጼወ ፡ ለምድር ፡ እንተ ፡ ትፈሪ ፤ በእከዮሙ ፡ ለእለ ፡ ይነብርዋ ።"),
    (106, 35, "ወረሰዩ ፡ ለበድው ፡ ሙሓዘ ፡ ማይ ፤ ወለምድረ ፡ በድው ፡ ቀላያተ ፡ ማያት ።"),
    (106, 36, "ወአንበረ ፡ ህየ ፡ ርኁባነ ፤ ወሐነጹ ፡ አህጉረ ፡ ኀበ ፡ ይነብርዋ ።"),
    (106, 37, "ወዘርዑ ፡ ገራውሀ ፡ ወተከሉ ፡ ወይነ ፤ ወገብሩ ፡ ማእረረ ፡ እክል ።"),
    (106, 38, "ወባረኮሙ ፡ ወበዝኁ ፡ ፈድፋደ ፤ ወኢያውኀደ ፡ ሎሙ ፡ እንስሳሆሙ ።"),
    (106, 39, "ወደወዩ ፡ ወውኅዱ ፤ በሕማም ፡ እኩይ ፡ ወበጻዕር ።"),
    (106, 40, "ወተክዕወ ፡ ኀሳር ፡ ዲበ ፡ መላእክት ፤ ወአስሐቶሙ ፡ ውስተ ፡ በድው ፡ ዘኢኮነ ፡ ፍኖተ ።"),
    (106, 41, "ወረድኦ ፡ ለነዳይ ፡ በተጽናሱ ፤ ወረሰዮ ፡ ከመ ፡ አባግዐ ፡ ብሔር ።"),
    (106, 42, "ይርአዩ ፡ ራትዓን ፡ ወይትፌሥሑ ፤ ወትትፈፀም ፡ አፉሃ ፡ ኵላ ፡ ዐመፃ ።"),
    (106, 43, "መኑ ፡ ጠቢብ ፡ ዘየዐቅቦ ፡ ለዝ ፤ ወያአምር ፡ ከመ ፡ መሓሪ ፡ እግዚአብሔር ።"),
    (107, 1, "ማኅኬት ፡ መዝሙር ፡ ዘዳዊት ።"),
    (107, 2, "ጥቡዕ ፡ ልብየ ፡ እግዚኦ ፡ ጥቡዕ ፡ ልብየ ፤ እሴብሕ ፡ ወእዜምር ፡ ወይትነሣእ ፡ ክብርየ ።"),
    (107, 3, "ወእትነሣእ ፡ በመዝሙር ፡ ወበመሰንቆ ፤ ወእትነሣእ ፡ በጽባሕ ።"),
    (107, 4, "እገኒ ፡ ለከ ፡ በውስተ ፡ አሕዛብ ፡ እግዚኦ ፤ ወእዜምር ፡ ለከ ፡ በውስተ ፡ ሕዝብ ።"),
    (107, 5, "እስመ ፡ ዐብየት ፡ እስከ ፡ ሰማያት ፡ ምሕረትከ ፤ ወእስከ ፡ ደመናት ፡ ጽድቅከ ።"),
    (107, 6, "ተለዐለ ፡ እግዚአብሔር ፡ መልዕልተ ፡ ሰማያት ፤ ወበኵሉ ፡ ምድር ፡ ስብሐቲሁ ።"),
    (107, 7, "ከመ ፡ ይድኀኑ ፡ ፍቁራኒከ ፤ አድኅን ፡ በየማንከ ፡ ወስምዐኒ ።"),
    (107, 8, "እግዚአብሔር ፡ ነበበ ፡ በመቅደሱ ፡ እትሐሠይ ፡ ወእትካፈል ፡ ሰቂማ ፤ ወእሳፈር ፡ አዕጻዳተ ፡ ቈላት ።"),
    (107, 9, "ዚአየ ፡ ውእቱ ፡ ገላዐድ ፡ ወዚአየ ፡ ምናሴ ፡ ወኤፍሬም ፡ ስዋቀ ፡ ርእስየ ፤ ወይሁዳ ፡ ንጉሥየ ።"),
    (107, 10, "ወሞአብ ፡ ካህን ፡ ተስፋየ ፤ ዲበ ፡ ኢዶምያስ ፡ እሰፍሕ ፡ መካይድየ ፤ ሊተ ፡ ይገንዩ ፡ አሎፍሊ ።"),
    (107, 11, "መኑ ፡ ይወስደኒ ፡ ሀገረ ፡ ጥቅም ፤ ወመኑ ፡ ይመርሐኒ ፡ እስከ ፡ ኢዶምያስ ።"),
    (107, 12, "አኮኑ ፡ አንተ ፡ ዘገዳፍከነ ፡ እግዚኦ ፤ ወኢትወፅእ ፡ አምላክነ ፡ ምስለ ፡ ኀይልነ ።"),
    (107, 13, "ሀበነ ፡ ረድኤተ ፡ በምብዳቤነ ፤ ወከንቱ ፡ ተአምኖ ፡ በሰብእ ።"),
    (107, 14, "በእግዚአብሔር ፡ ንገብር ፡ ኀይለ ፤ ወወእቱ ፡ ያኀስሮሙ ፡ ለእለ ፡ ይሣቅዩነ ።"),
    (108, 1, "ፍጻሜ ፡ መዝሙር ፡ ዘዳዊት ። እግዚኦ ፡ ኢትጸመመኒ ፡ ስእለትየ ።"),
    (108, 2, "እስመ ፡ አፈ ፡ ዐመፃ ፡ ወአፈ ፡ ኃጥእ ፡ አብቀወ ፡ ላዕሌየ ፤ ወነበቡ ፡ ላዕሌየ ፡ በልሳነ ፡ ዐመፃ ።"),
    (108, 3, "ወዐገቱኒ ፡ በጽልእ ፤ ወፀብኡኒ ፡ በከንቱ ።"),
    (108, 4, "ወዘእምአፍቀሩኒ ፡ አስተዋደዩኒ ፤ ወአንሰ ፡ እጼሊ ።"),
    (108, 5, "ገደዩኒ ፡ እኪተ ፡ ህየንተ ፡ ሠናይት ፤ ወጸልኡኒ ፡ ህየንተ ፡ ዘአፍቀርክዎሙ ።"),
    (108, 6, "ሢም ፡ ላዕሌሁ ፡ ኃጥአ ፤ ወሰይጣን ፡ ይቁም ፡ በየማኑ ።"),
    (108, 7, "ወሶበሂ ፡ ይትዋቀሥ ፡ ይፃእ ፡ ተመዊኦ ፤ ወጸሎቱሂ ፡ ትኩኖ ፡ ጌጋየ ።"),
    (108, 8, "ወይኩና ፡ መዋዕሊሁ ፡ ኅዳጠ ፤ ወሢመቶሂ ፡ ይንሣእ ፡ ባዕድ ።"),
    (108, 9, "ወይኩኑ ፡ ደቂቁ ፡ እጓለ ፡ ማውታ ፤ ወብእሲቱሂ ፡ ትኩን ፡ መበለተ ።"),
    (108, 10, "ወይትሀውኩ ፡ ደቂቁ ፡ ወይፍልሱ ፡ ወያስተፍእሙ ፤ ወይስድድዎሙ ፡ እምአብያቲሆሙ ።"),
    (108, 11, "ወይበርበሮ ፡ ባዕለ ፡ ዕዳ ፡ ኵሎ ፡ ንዋዮ ፤ ወይሐብልዩ ፡ ነቢር ፡ ኵሎ ፡ ተግባሮ ።"),
    (108, 12, "ወኢይርከብ ፡ ዘይረድኦ ፤ ወኢይምሐርዎሙ ፡ ለእጓለ ፡ ማውታሁ ።"),
    (108, 13, "ወይሠረዉ ፡ ደቂቁ ፤ በአሕቲ ፡ ትውልድ ፡ ትደምሰስ ፡ ስሙ ።"),
    (108, 14, "ወትዘከር ፡ ኅጢአተ ፡ አቡሁ ፡ በቅድመ ፡ እግዚአብሔር ፤ ወኢይደምሰስ ፡ ጌጋያ ፡ ለእሙ ።"),
    (108, 15, "ወየሀሉ ፡ ቅድመ ፡ እግዚአብሔር ፡ በኵሉ ፡ ጊዜ ፤ ወይጥፋእ ፡ እምድር ፡ ዝክሩ ።"),
    (108, 16, "እስመ ፡ ኢተዘከረ ፡ ይግበር ፡ ምጽዋተ ፤ ወሰደደ ፡ ብእሴ ፡ ነዳየ ፡ ወምስኪነ ፡ ወጥቡዕ ፡ ልቡ ፡ ለቀቲል ።"),
    (108, 17, "ወአብደረ ፡ መርገመ ፡ ወትመጽኦ ፤ ወአበያ ፡ ለበረከት ፡ ወትርሕቅ ፡ አምኔሁ ።"),
    (108, 18, "ወለብሳ ፡ ለመርገም ፡ ከመ ፡ ልብስ ፤ ወቦአት ፡ ከመ ፡ ማይ ፡ ውስተ ፡ አማዑቱ ፤ ወከመ ፡ ቅብእ ፡ ውስተ ፡ አዕጽምቲሁ ።"),
    (108, 19, "ወትኩኖ ፡ ከመ ፡ ልብስ ፡ ዘይትዐጸፍ ፤ ወከመ ፡ ቅናት ፡ ዘይቀንት ፡ ዘልፈ ።"),
    (108, 20, "ዝግብር ፡ ለእለ ፡ ያስተዋድዩኒ ፡ ኀበ ፡ እግዚአብሔር ፤ ወለእለ ፡ ይነቡ ፡ እኩየ ፡ ላዕለ ፡ ነፍስየ ።"),
    (108, 21, "ወአንተሰ ፡ እግዚኦ ፡ እግዚእየ ፡ ግበር ፡ ሣህለከ ፡ ላዕሌየ ፡ በእንተ ፡ ስምከ ፤ እስመ ፡ ሠናይ ፡ ምሕረትከ ፡ አድኅነኒ ።"),
    (108, 22, "እስመ ፡ ነዳይ ፡ ወምስኪን ፡ አነ ፤ ልብየኒ ፡ ደንገፀኒ ፡ በውስጥየ ።"),
    (108, 23, "ወኀለቁ ፡ ከመ ፡ ጽላሎት ፡ ዘኀለፈ ፤ ወተነገፍኩ ፡ ከመ ፡ አንበጣ ።"),
    (108, 24, "ወደክመኒ ፡ ብረክየ ፡ በጾም ፤ ወስሕከ ፡ ሥጋየ ፡ በኀጢአ ፡ ቅብእ ።"),
    (108, 25, "ወአንሰ ፡ ተጸአልኩ ፡ በኀቤሆሙ ፤ ሶበ ፡ ይሬእዩኒ ፡ የሐውሱ ፡ ርእሶሙ ።"),
    (108, 26, "ርድአኒ ፡ እግዚኦ ፡ አምላኪየ ፤ ወአድኅነኒ ፡ በእንተ ፡ ምሕረትከ ።"),
    (108, 27, "ወያእምሩ ፡ ከመ ፡ እዴከ ፡ ይእቲ ፡ ዛቲ ፤ ወአንተ ፡ እግዚኦ ፡ ገበርከ ።"),
    (108, 28, "እሙንቱሰ ፡ ይረግሙ ፡ ወአንተ ፡ ባርክ ፤ ይትኀፈሩ ፡ እለ ፡ ይትነሥኡ ፡ ላዕሌየ ፡ ወገብርከሰ ፡ ይትፌሣሕ ።"),
    (108, 29, "ለይልበሱ ፡ ኀፍረተ ፡ እለ ፡ ያስተዋድዩኒ ፤ ወይትዐጸፍዋ ፡ ከመ ፡ ዐጽፍ ፡ ለኃጢአቶሙ ።"),
    (108, 30, "እገኒ ፡ በአፉየ ፡ ለእግዚአብሔር ፡ ፈድፋደ ፤ ወእሴብሖ ፡ በማእከለ ፡ ብዙኃን ።"),
    (108, 31, "እስመ ፡ ቆመ ፡ በየማነ ፡ ነዳይ ፤ ከመ ፡ ያድኅና ፡ ለነፍስየ ፡ እምእለ ፡ ሮድዋ ።"),
    (109, 1, "መዝሙር ፡ ዘዳዊት ። ይቤሎ ፡ እግዚእ ፡ ለእግዚእየ ፡ ንበር ፡ በየማንየ ፤ እስከ ፡ ኣገብኦሙ ፡ ለጸላእትከ ፡ ታሕተ ፡ መከየደ ፡ እገሪከ ።"),
    (109, 2, "በትረ ፡ ኀይል ፡ ይፈኑ ፡ ለከ ፡ እግዚአብሔር ፡ እምጽዮን ፤ ወትኴንን ፡ በማእከለ ፡ ጸላእትከ ።"),
    (109, 3, "ምስሌከ ፡ ቀዳማዊ ፡ በዕለተ ፡ ኀይል ። ወብርሃኖሙ ፡ ለቅዱሳን ፡ ወለድኩከ ፡ እምከርሥ ፡ እምቅድመ ፡ ኮከበ ፡ ጽባሕ ።"),
    (109, 4, "መሐለ ፡ እግዚአብሔር ፡ ወኢይኔስሕ ፤ አንተ ፡ ካህኑ ፡ ለዓለም ፤ በከመ ፡ ሢመቱ ፡ ለመልከ ፡ ጼዴቅ ።"),
    (109, 5, "እግዚአብሔር ፡ በየማንከ ፤ ይቀጠቅጦሙ ፡ ለነገሥት ፡ በዕለተ ፡ መዐቱ ።"),
    (109, 6, "ወይኴንኖሙ ፡ ለአሕዛብ ፡ ወያበዝኅ ፡ አብድንተ ፤ ወይሰብር ፡ አርእስተ ፡ ብዙኃን ፡ በዲበ ፡ ምድር ።"),
    (109, 7, "እምውሒዝ ፡ ሰትዩ ፡ ማየ ፡ በፍኖት ፤ ወበእንተዝ ፡ ይትሌዐል ፡ ርእስ ።"),
    (110, 1, "ሀሌሉያ ። እገኒ ፡ ለከ ፡ እግዚኦ ፡ በኵሉ ፡ ልብየ ፤ በምክረ ፡ ራትዓን ፡ ወበማኅበር ።"),
    (110, 2, "ዐቢይ ፡ ግብረ ፡ እግዚአብሔር ፤ ወትትኀሠሥ ፡ ውስተ ፡ ኵሉ ፡ ፈቃዱ ።"),
    (110, 3, "አሚን ፡ ወዕበየ ፡ ስብሐት ፡ ምግባሩ ፤ ወጽድቁኒ ፡ ይነብር ፡ ለዓለም ።"),
    (110, 4, "ተዝካረ ፡ ገብረ ፡ ለስብሐቲሁ ፤ መሓሪ ፡ ወመስተሣህል ፡ እግዚአብሔር ።"),
    (110, 5, "ወወሀቦሙ ፡ ሲሳዮሙ ፡ ለእለ ፡ ይፈርህዎ ፤ ወተዘከረ ፡ ኪዳኖ ፡ ዘለዓለም ።"),
    (110, 6, "ወአርአዮሙ ፡ ለሕዝቡ ፡ ኀይለ ፡ ምግባሩ ፤ ከመ ፡ የሀቦሙ ፡ ርስተ ፡ ዘአሕዛብ ።"),
    (110, 7, "ግብረ ፡ እደዊሁ ፡ ጽድቅ ፡ ወርትዕ ፤ ወእሙን ፡ ኵሉ ፡ ትእዛዙ ።"),
    (110, 8, "ወጽኑዕ ፡ ለዓለመ ፡ ዓለም ፤ ወግቡር ፡ በጽድቅ ፡ ወበርትዕ ።"),
    (110, 9, "መድኀኒተ ፡ ፈነወ ፡ እግዚአብሔር ፡ ለሕዝቡ ፡ ወአዘዘ ፡ ሥርዐቶ ፡ ዘለዓለም ፤ ቅዱስ ፡ ወግሩም ፡ ስመ ፡ ዚአሁ ።"),
    (110, 10, "ቀዳሚሃ ፡ ለጥበብ ፡ ፈሪሀ ፡ እግዚአብሔር ፡ ወምክር ፡ ሠናይት ፡ ለኵሉ ፡ ዘይገብራ ፤ ወስብሐቲሁኒ ፡ ይነብር ፡ ለዓለም ።"),
    (111, 1, "ሀሌሉያ ። ብፁዕ ፡ ብእሲ ፡ ዘይፈርሆ ፡ ለእግዚአብሔር ፤ ወዘይፈቅድ ፡ ትእዛዞ ፡ ፈድፋደ ።"),
    (111, 2, "ወይከውን ፡ ጽኑዐ ፡ ዘርዑ ፡ ውስተ ፡ ምድር ፤ ትውልደ ፡ ጻድቃን ፡ ይትባረኩ ።"),
    (111, 3, "ክብር ፡ ወብዕል ፡ ውስተ ፡ ቤቱ ፤ ወጽድቁኒ ፡ ይነብር ፡ ለዓለመ ፡ ዓለም ።"),
    (111, 4, "ሠረቀ ፡ ብርሃን ፡ ለራትዓን ፡ በውስተ ፡ ጽልመት ፤ መሓሪ ፡ ወመስተሣህል ፡ እግዚአብሔር ፡ ወጻድቅ ፡ አምላክነ ።"),
    (111, 5, "ብእሲ ፡ መሓሪ ፡ መስተሣህል ፡ ወኄር ፤ ወይዔቅም ፡ ቃሎ ፡ በውስተ ፡ ፍትሕ ።"),
    (111, 6, "ወኢይትሀወክ ፡ ለዓለም ፤ ዝክረ ፡ ጻድቅ ፡ ለዓለም ፡ ይሄሉ ።"),
    (111, 7, "ወኢይፈርህ ፡ እምነገር ፡ እኩይ ፤ ጥቡዕ ፡ ልቡ ፡ ለተወክሎ ፡ በእግዚአብሔር ።"),
    (111, 8, "ጽኑዕ ፡ ልቡ ፡ ወኢይትሀወክ ፡ ለዓለም ፤ እስከ ፡ ይሬኢ ፡ በጸላእቱ ።"),
    (111, 9, "ዘረወ ፡ ወወሀበ ፡ ለነዳይ ፡ ወጽድቁኒ ፡ ይነብር ፡ ለዓለመ ፡ ዓለም ፤ ወይትሌዐል ፡ ቀርኑ ፡ በክብር ።"),
    (111, 10, "ይሬኢ ፡ ኃጥእ ፡ ወይትመዓዕ ፡ ወይሐቂ ፡ ስነኒሁ ፡ ወይትመሰው ፤ ወተኀልቅ ፡ ፍትወቶሙ ፡ ለኃጥኣን ፡፡"),
    (112, 1, "ሀሌሉያ ። ሰብሕዎ ፡ አግብርቲሁ ፡ ለእግዚአብሔር ፤ ወሰብሑ ፡ ለስመ ፡ እግዚአብሔር ።"),
    (112, 2, "ወይኩን ፡ ብሩከ ፡ ስሙ ፡ ለእግዚአብሔር ፤ እምይእዜ ፡ ወእስከ ፡ ለዓለም ።"),
    (112, 3, "እምሥራቀ ፡ ፀሐይ ፡ ወእስከነ ፡ ዐርብ ፤ ይትአኰት ፡ ስሙ ፡ ለእግዚአብሔር ።"),
    (112, 4, "ልዑል ፡ እግዚአብሔር ፡ መልዕልተ ፡ ኵሉ ፡ አሕዛብ ፤ ወውስተ ፡ ሰማያት ፡ ስብሐቲሁ ።"),
    (112, 5, "መኑ ፡ ከመ ፡ እግዚአብሔር ፡ አምላክነ ፤ ዘይነብር ፡ ውስተ ፡ አርያም ።"),
    (112, 6, "ወይሬኢ ፡ ዘበታሕቱ ፤ በሰማይኒ ፡ ወበምድርኒ ።"),
    (112, 7, "ዘያነሥኦ ፡ ለነዳይ ፡ እምድር ፤ ወያሌዕሎ ፡ እመሬት ፡ ለምስኪን ።"),
    (112, 8, "ከመ ፡ ያንብሮ ፡ ምስለ ፡ መላእክቲሁ ፤ ወምስለ ፡ መላእክተ ፡ ሕዝቡ ።"),
    (112, 9, "ዘያነብራ ፡ ለመካን ፡ ውስተ ፡ ቤቱ ፤ ወያስትፌሥሓ ፡ ለእመ ፡ ውሉድ ።"),
    (113, 1, "ሀሌሉያ ። አመ ፡ ይወፅኡ ፡ እስራኤል ፡ እምግብጽ ፤ ወቤተ ፡ ያዕቆብ ፡ እምሕዝበ ፡ ፀር ።"),
    (113, 2, "ወኮነ ፡ ይሁዳ ፡ መቅደሶ ፤ ወእስራኤልኒ ፡ ምኵናኖ ።"),
    (113, 3, "ባሕርኒ ፡ ርእየት ፡ ወጐየት ፤ ወዮርዳኖስኒ ፡ ገብአ ፡ ድኅሬሁ ።"),
    (113, 4, "ወአድባር ፡ አንፈርዐጹ ፡ ከመ ፡ ሐራጊት ፤ ወአውግርኒ ፡ ከመ ፡ መሓስአ ፡ አባግዕ ፤"),
    (113, 5, "ምንተ ፡ ኮንኪ ፡ ባሕር ፡ ዘጐየይኪ ፤ ወአንተኒ ፡ ዮርዳኖስ ፡ ዘገባእከ ፡ ድኅሬከ ።"),
    (113, 6, "ወአድባር ፡ ዘአንፈርዐጽክሙ ፡ ከመ ፡ ሐራጊት ፤ ወአውግርኒ ፡ ከመ ፡ መሓስአ ፡ አባግዕ ፤"),
    (113, 7, "እምቅድመ ፡ ገጹ ፡ ለእግዚአብሔር ፡ አድለቅለቀት ፡ ምድር ፤ እምቅድመ ፡ ገጹ ፡ ለአምላከ ፡ ያዕቆብ ።"),
    (113, 8, "ዘይሬስያ ፡ ለኰኵሕ ፡ አንቅዕተ ፡ ማያት ፤ ወለእዝኅ ፡ ዐዘቃተ ፡ ማያት ።"),
    (113, 9, "አኮ ፡ ለነ ፡ እግዚኦ ፡ አኮ ፡ ለነ ፤ ለስመ ፡ ዚአከ ፡ ሀብ ፡ ስብሐተ ፤"),
    (113, 10, "በምሕረትከ ፡ ወበጽድቅከ ። ከመ ፡ ኢይበሉነ ፡ አሕዛብ ፤ አይቴ ፡ ውእቱ ፡ አምላኮሙ ።"),
    (113, 11, "አምላክነሰ ፡ ውስተ ፡ ሰማይ ፡ ላዕለ ፤ በሰማይኒ ፡ ወበምድርኒ ፡ ኵሎ ፡ ዘፈቀደ ፡ ገብረ ፡ እግዚአብሔር ።"),
    (113, 12, "አማልክቲሆሙ ፡ ለአሕዛብ ፡ ዘወርቅ ፡ ወብሩር ፤ ግብረ ፡ እደ ፡ እጓለ ፡ እመሕያው ።"),
    (113, 13, "አፈ ፡ ቦሙ ፡ ወኢይነቡ ፤ ዐይነ ፡ ቦሙ ፡ ወኢይሬእዩ ።"),
    (113, 14, "እዝነ ፡ ቦሙ ፡ ወኢይሰምዑ ፤ አንፈ ፡ ቦሙ ፡ ወኢያጼንዉ ።"),
    (113, 15, "እደ ፡ ቦሙ ፡ ወኢይገሱ ፤ እግረ ፡ ቦሙ ፡ ወኢየሐውሩ ፤ ወኢይነቡ ፡ በጐራዒቶሙ ። ወአልቦሙ ፡ መንፈሰ ፡ ውስተ ፡ አፉሆሙ ።"),
    (113, 16, "ከማሆሙ ፡ ለይኩኑ ፡ ኵሎሙ ፡ እለ ፡ ገብርዎሙ ፤ ወኵሎሙ ፡ እለ ፡ ይትዌከሉ ፡ ቦሙ ።"),
    (113, 17, "ቤተ ፡ እስራኤል ፡ ተወከሉ ፡ በእግዚአብሔር ፤ ረዳኢሆሙ ፡ ውእቱ ፡ ወምእመኖሙ ።"),
    (113, 18, "ቤተ ፡ አሮን ፡ ተወከሉ ፡ በእግዚአብሔር ፤ ረዳኢሆሙ ፡ ውእቱ ፡ ወምእመኖሙ ።"),
    (113, 19, "እለ ፡ ትፈርህዎ ፡ ለእግዚአብሔር ፡ ተወከሉ ፡ በእግዚአብሔር ፤ ረዳኢሆሙ ፡ ውእቱ ፡ ወምእመኖሙ ።"),
    (113, 20, "እግዚአብሔር ፡ ተዘከረነ ፡ ወባረከነ ፤ ባርክ ፡ ቤተ ፡ እስራኤል ፤ ወባርክ ፡ ቤተ ፡ አሮን ።"),
    (113, 21, "ባርኮሙ ፡ ለኵሎሙ ፡ እለ ፡ ይፈርህዎ ፡ ለእግዚአብሔር ፤ ለንኡሶሙ ፡ ወለዐቢዮሙ ።"),
    (113, 22, "ይዌስክ ፡ እግዚአብሔር ፡ ላዕሌክሙ ፤ ላዕሌክሙ፡ ወላዕለ ፡ ውሉድክሙ ።"),
    (113, 23, "ብሩካን ፡ አንትሙ ፡ ለእግዚአብሔር ፤ ዘገብረ ፡ ሰማየ ፡ ወምድረ ።"),
    (113, 24, "ሰማየ ፡ ሰማያት ፡ ለእግዚአብሔር ፤ ወምድረሰ ፡ ወሀበ ፡ ለእጓለ ፡ እመሕያው ።"),
    (113, 25, "ዘአኮ ፡ ምዉታን ፡ ይሴብሑከ ፡ እግዚኦ ፤ ወኢኵሎሙ ፡ እለ ፡ ይወርዱ ፡ ውስተ ፡ ሲኦል ።"),
    (113, 26, "ንሕነ ፡ ሐያዋን ፡ ንባርኮ ፡ ለእግዚአብሔር ፤ እምይእዜ ፡ ወእስከ ፡ ለዓለም ።"),
    (114, 1, "ሀሌሉያ ። አፍቀርኩ ፡ እስመ ፡ ሰምዐኒ ፡ እግዚአብሔር ፡ ቃለ ፡ ስእለትየ ።"),
    (114, 2, "ወአፅምአ ፡ እዝኖ ፡ ኀቤየ ፤ ወጸዋዕክዎ ፡ በመዋዕልየ ።"),
    (114, 3, "አኀዘኒ ፡ ጻዕረ ፡ ሞት ፡ ወረከበኒ ፡ ሕማመ ፡ ሲኦል ፤ ሕማም ፡ ወምንዳቤ ፡ ረከበኒ ።"),
    (114, 4, "ወጸዋዕኩ ፡ ስመ ፡ እግዚአብሔር ፤ እግዚኦ ፡ ባልሓ ፡ ለነፍስየ ።"),
    (114, 5, "መሓሪ ፡ እግዚአብሔር ፡ ወጻድቅ ፤ ወአምላክነሂ ፡ መስተሣህል ።"),
    (114, 6, "የዐቅብ ፡ ሕፃናተ ፡ እግዚአብሔር ፤ ተመንደብኩሂ ፡ ወአድኀነኒ ።"),
    (114, 7, "ግብኢ ፡ ነፍስየ ፡ ውስተ ፡ ዕረፍትኪ ፤ እስመ ፡ እግዚአብሔር ፡ ረዳኢኪ ።"),
    (114, 8, "እስመ ፡ አድኀና ፡ ለነፍስየ ፡ እሞት ፤ ወለአዕይንትየኒ ፡ እምአንብዕ ፡ ወለእገርየኒ ፡ እምዳኅፅ ።"),
    (114, 9, "ከመ ፡ አሥምሮ ፡ ለእግዚአብሔር ፡ በብሔረ ፡ ሕያዋን ።"),
    (115, 1, "ሀሌሉያ ። አመንኩ ፡ በዘነበብኩ ፤ ወአንሰ ፡ ብዙኀ ፡ ሐመምኩ ።"),
    (115, 2, "አንሰ ፡ አቤ ፡ እምግዕዝየ ፤ ኵሉ ፡ ሰብእ ፡ ሐሳዊ ፡ ውእቱ ።"),
    (115, 3, "ምንተኑ ፡ አዐስዮ ፡ ለእግዚአብሔር ፤ በእንተ ፡ ኵሉ ፡ ዘገብረ ፡ ሊተ ።"),
    (115, 4, "ጽዋዐ ፡ ሕይወት ፡ እትሜጦ ፤ ወስመ ፡ እግዚአብሔር ፡ እጼውዕ ።"),
    (115, 5, "[ወእሁብ ፡ ብፅአትየ ፡ ለእግዚአብሔር ፤ በቅድመ ፡ ኵሉ ፡ ሕዝቡ ።]"),
    (115, 6, "ክብር ፡ ሞቱ ፡ ለጻድቅ ፡ በቅድመ ፡ እግዚአብሔር ።"),
    (115, 7, "እግዚኦ ፡ አነ ፡ ገብርከ ፤ ገብርከ ፡ ወልደ ፡ አመትከ ፤ ወሰበርከ ፡ መዋቅሕትየ ።"),
    (115, 8, "ለከ ፡ እሠውዕ ፡ መሥዋዕተ ፡ ስብሓት ፤ [ወስመ ፡ እግዚአብሔር ፡ እጼውዕ ፡]"),
    (115, 9, "ወእሁብ ፡ ብፅአትየ ፡ ለእግዚአብሔር ፤ በቅድመ ፡ ኵሉ ፡ ሕዝቡ ።"),
    (115, 9, "በዐጸደ ፡ ቤተ ፡ እግዚአብሔር ፤ ወበማእከሌኪ ፡ ኢየሩሳሌም ።"),
    (116, 1, "ሀሌሉያ ። ሰብሕዎ ፡ ለእግዚአብሔር ፡ ኵልክሙ ፡ አሕዛብ ፤ ወይሴብሕዎ ፡ ኵሎሙ ፡ ሕዝብ ።"),
    (116, 2, "እስመ ፡ ጸንዐት ፡ ምሕረቱ ፡ ላዕሌነ ፤ ወጽድቁሰ ፡ ለእግዚአብሔር ፡ ይሄሉ ፡ ለዓለም ።"),
    (117, 1, "ሀሌሉያ ። ግነዩ ፡ ለእግዚአብሔር ፡ እስመ ፡ ኄር ፤ እስመ ፡ ለዓለም ፡ ምሕረቱ ።"),
    (117, 2, "ንግሩ ፡ ቤተ ፡ እስራኤል ፡ ከመ ፡ ኄር ፤ ከመ ፡ ለዓለም ፡ ምሕረቱ ።"),
    (117, 3, "ንግሩ ፡ ቤተ ፡ አሮን ፡ ከመ ፡ ኄር ፤ ከመ ፡ ለዓለም ፡ ምሕረቱ ።"),
    (117, 4, "ንግሩ ፡ ኵልክሙ ፡ እለ ፡ ትፈርህዎ፡ ለእግዚአብሔር ፡ ከመ ፡ ኄር ፤ ከመ ፡ ለዓለም ፡ ምሕረቱ ።"),
    (117, 5, "ሶበ ፡ ተመንደብኩ ፡ ጸዋዕክዎ ፡ ለእግዚአብሔር ፤ ወሰምዐኒ ፡ ወአርሐበ ፡ ሊተ ።"),
    (117, 6, "እግዚአብሔር ፡ ይረድአኒ ፡ ኢይፈርህ ፤ እጓለ ፡ እመሕያው፡ ምንተ ፡ ይሬስየኒ ።"),
    (117, 7, "እግዚአብሔር ፡ ይረድአኒ ፤ ወአነ ፡ እሬእዮሙ ፡ ለጸላእትየ ።"),
    (117, 8, "ይኄይስ ፡ ተአምኖ ፡ በእግዚአብሔር ፤ እምተአምኖ ፡ በእጓለ ፡ እመሕያው ።"),
    (117, 9, "ይኄይስ ፡ ተአምኖ ፡ በእግዚአብሔር ፤ እምተሰፍዎ ፡ በመላእክት ።"),
    (117, 10, "ኵሎሙ ፡ አሕዛብ ፡ ዐገቱኒ ፤ ወበስመ ፡ እግዚአብሔር ፡ ሞአክዎሙ ።"),
    (117, 11, "ዐጊተሰ ፡ ዐገቱኒ ፤ ወበስመ ፡ እግዚአብሔር ፡ ሞአክዎሙ ።"),
    (117, 12, "ዐገቱኒ ፡ ከመ ፡ ንህብ ፡ መዓረ ፡ ወነዱ ፡ ከመ ፡ እሳት ፡ ውስተ ፡ አስዋክ ፤ ወበስመ ፡ እግዚአብሔር ፡ ሞአክዎሙ ።"),
    (117, 13, "ተንተንኩ ፡ ለወዲቅ ፤ ወእግዚአብሔር ፡ አንሥአኒ ።"),
    (117, 14, "ኀይልየኒ ፡ ወዝክርየኒ ፡ እግዚአብሔር ፤ ወውእቱ ፡ ኮነኒ ፡ መድኀንየ ።"),
    (117, 15, "ቃለ ፡ ትፍሥሕት ፡ ውስተ ፡ አብያቲሆሙ ፡ ለጻድቃን ፤"),
    (117, 16, "የማነ ፡ እግዚአብሔር ፡ ገብረት ፡ ኀይለ ። የማነ ፡ እግዚአብሔር ፡ አልዐለተኒ ፤ የማነ ፡ እግዚአብሔር ፡ ገብረት ፡ ኀይለ ።"),
    (117, 17, "ኢይመውት ፡ ዘእንበለ ፡ ዘአሐዩ ፤ ወእነግር ፡ ግብሮ ፡ ለእግዚአብሔር ።"),
    (117, 18, "ገሥጾሰ ፡ ገሠጸኒ ፡ እግዚአብሔር ፤ ወለሞትሰ ፡ ባሕቱ ፡ ኢመጠወኒ ።"),
    (117, 19, "አርኅዉ ፡ ሊተ ፡ አናቅጸ ፡ ጽድቅ ፤ እባእ ፡ ውስቴቶን ፡ ወእግነየ ፡ ለእግዚአብሔር ።"),
    (117, 20, "ዝአንቀጽ ፡ እንተ ፡ እግዚአብሔር ፤ ጻድቃን ፡ ይበውኡ ፡ ውስቴታ ።"),
    (117, 21, "እገኒ ፡ ለከ ፡ እግዚኦ ፡ እስመ ፡ ሰማዕከኒ ፤ ወኮንከኒ ፡ መድኀንየ ።"),
    (117, 22, "እብን ፡ ዘመነንዋ ፡ ነደቅት ፤ ይእቲ ፡ ኮነት ፡ ውስተ ፡ ርእሰ ፡ ማዕዘንት ።"),
    (117, 23, "እምኀበ ፡ እግዚአብሔር ፡ ኮነት ፡ ዛቲ ፤ ወነካር ፡ ይእቲ ፡ ለአዕይንቲነ ።"),
    (117, 24, "ዛቲ ፡ ዕለት ፡ እንተ ፡ ገብረ ፡ እግዚአብሔር ፤ ንትፈሣሕ ፡ ወንትሐሠይ ፡ ባቲ ።"),
    (117, 25, "ኦእግዚኦ ፡ አድኅንሶ ፤ ኦእግዚኦ ፡ ሠርሐሶ ።"),
    (117, 26, "ቡሩክ ፡ ዘይመጽእ ፡ በስመ ፡ እግዚአብሔር ፤ በረክናክሙ ፡ እምቤተ ፡ እግዚአብሔር ።"),
    (117, 27, "እግዚአብሔር ፡ እግዚእ ፡ ወአስተርአየ ፡ ለነ ፤ ግበሩ ፡ በዓለ ፡ በትፍሥሕት ፡ በኀበ ፡ እለ ፡ ያስተሓምምዎ ፡ እስከ ፡ አቅርንቲሁ ፡ ለምሥዋዕ ።"),
    (117, 28, "አምላኪየ ፡ አንተ ፡ ወእገኒ ፡ ለከ ፤ አምላኪየ ፡ አንተ ፡ ወኣሌዕለከ ። እገኒ ፡ ለከ ፡ እግዚኦ ፡ እስመ ፡ ሰማዕከኒ ፡ ወኮንከኒ ፡ መድኀንየ ።"),
    (117, 29, "ግነዩ ፡ ለእግዚአብሔር ፡ እስመ ፡ ኄር ፤ እስመ ፡ ለዓለም፡ ምሕረቱ ።"),
    (118, 1, "ሀሌሉያ ። ፩ ፤ አሌፍ ። ብፁአን ፡ እለ ፡ ንጹሓን ፡ በፍኖቶሙ ፤ እለ ፡ ይሐውሩ ፡ በሕገ ፡ እግዚአብሔር ።"),
    (118, 2, "ብፁዓን ፡ እለ ፡ ይኀሡ ፡ ስምዖ ፤ ወበኵሉ ፡ ልቦሙ ፡ ይኀሥዎ ።"),
    (118, 3, "ወእለሰ ፡ ይገብሩ ፡ ዐመፃ ፤ ፍኖተ ፡ ዚአሁ ፡ ኢሖሩ ።"),
    (118, 4, "አንተ ፡ አዘዝከ ፡ ይዕቀቡ ፡ ትእዛዘከ ፡ ፈድፋደ ።"),
    (118, 5, "ይረትዕሰ ፡ ይርታዕ ፡ ፍኖትየ ፤ ከመ ፡ እዕቀብ ፡ ኵነኔከ ።"),
    (118, 6, "ውእቱ ፡ ጊዜ ፡ ኢይትኀፈር ፤ በርእየ ፡ ኵሉ ፡ ትእዛዝከ ።"),
    (118, 7, "እገኒ ፡ ለከ ፡ እግዚኦ ፡ በልብ ፡ ርቱዕ ፤ ሶበ ፡ ተመሀርኩ ፡ ኵነኔ ፡ ጽድቅከ ።"),
    (118, 8, "ወአዐቅብ ፡ ኵነኔከ ፤ ወኢትግድፈኒ ፡ ለዝሉፉ ።"),
    (118, 9, "፪ ፤ ቤት ። በምንተ ፡ ያረትዕ ፡ ወሬዛ ፡ ፍኖቶ ፤ በዐቂበ ፡ ነቢብከ ።"),
    (118, 10, "በኵሉ ፡ ልብየ ፡ ኀሠሥኩከ ፤ ኢታርሕቀኒ ፡ እምትእዛዝከ ።"),
    (118, 11, "ውስተ ፡ ክብየ ፡ ኀባእኩ ፡ ነቢበከ ፤ ከመ ፡ ኢየአብስ ፡ ለከ ።"),
    (118, 12, "ብሩክ ፡ አንተ ፡ እግዚኦ ፡ ወምህረኒ ፡ ኵነኔከ ።"),
    (118, 13, "በከናፍርየ ፡ ነገርኩ ፡ ኵሎ ፡ ኰነኔ ፡ አፉከ ።"),
    (118, 14, "በፍኖተ ፡ ስመዕከ ፡ ተፈሣሕኩ ፤ ከመ ፡ ዘበኵሉ ፡ ብዕል ።"),
    (118, 15, "ወእዛዋዕ ፡ በትእዛዝከ ፤ ወአኀሥሥ ፡ ፍናዊከ ።"),
    (118, 16, "ወኣነብብ ፡ ትእዛዛቲከ ፤ ወኢይረስዕ ፡ ቃለከ ።"),
    (118, 17, "፫ ፤ ጋሜል ። ዕስዮ ፡ ለገብርከ ፡ ከመ ፡ እሕዮ ፤ ወእዕቀብ ፡ ነቢበከ ።"),
    (118, 18, "ክሥቶን ፡ ለአዕይንትየ ፡ ወእርአይ ፤ መድምመከ ፡ እምሕግከ ።"),
    (118, 19, "ፈላሲ ፡ አነ ፡ ውስተ ፡ ምድር ፤ ኢትኅባእ ፡ እምኔየ ፡ ትእዛዘከ ።"),
    (118, 20, "አፍቀረት ፡ ነፍስየ ፡ ወፈተወት ፡ ኵነኔከ ፡ በኵሉ ፡ ጊዜ ።"),
    (118, 21, "ገሠጽኮሙ ፡ ለዕቡያን ፤ ርጉማን ፡ እለ ፡ ይትገሐሡ ፡ እምትእዛዝከ ።"),
    (118, 22, "ኣእትት ፡ እምኔየ ፡ ጽእለተ ፡ ወኀሳረ ፤ እስመ ፡ ትእዛዘከ ፡ ኀሠሥኩ ።"),
    (118, 23, "እስመ ፡ ነበሩ ፡ መላእክት ፡ ወኪያየ ፡ ሐመዩ ፤ ወገብርከሰ ፡ ይዛዋዕ ፡ በኵነኔከ ።"),
    (118, 24, "እስመ ፡ ስምዕከ ፡ ተመሀርየ ፡ ውእቱ ፤ ወምክርየኒ ፡ ኵነኔ ፡ ዚአከ ።"),
    (118, 25, "፬ ፤ ዳሌጥ ። ጠግዐት ፡ ነፍስየ ፡ በምድር ፤ ኣሕይወኒ ፡ በከመ ፡ ነቢብከ ።"),
    (118, 26, "ነገርኩ ፡ ፍናዊከ ፡ ወሰማዕከኒ ፤ ወምህረኒ ፡ ኵነኔከ ።"),
    (118, 27, "ፍኖተ ፡ ጽድቅከ ፡ አለብወኒ ፤ ወእዛዋዕ ፡ በመንክርከ ።"),
    (118, 28, "ደቀሰት ፡ ነፍስየ ፡ እምሐዘን ፤ አጽንዐኒ ፡ በነቢብከ ።"),
    (118, 29, "ፍኖተ ፡ ዐመፃ ፡ አርሕቅ ፡ እምኔየ ፤ ወበሕግከ ፡ ተሣሀለኒ ።"),
    (118, 30, "ፍኖተ ፡ ጽድቅከ ፡ አብደርኩ ፤ ወኵነኔከሰ ፡ ኢረሳዕኩ ።"),
    (118, 31, "ተለውኩ ፡ ስምዐከ ፤ እግዚኦ ፡ ኢታስተኀፍረኒ ።"),
    (118, 32, "ፍኖተ ፡ ትእዛዝከ ፡ ሮጽኩ ፤ ሶበ ፡ አርሐብኮ ፡ ለልብየ ።"),
    (118, 33, "፭ ፤ ሄ ። ምህረኒ ፡ እግዚኦ ፡ ፍኖተ ፡ ጽድቅከ ፤ ወእኅሥሣ ፡ በኵሉ ፡ ጊዜ ።"),
    (118, 34, "አለብወኒ ፡ ወእኅሥሥ ፡ ሕገከ ፤ ወእዕቀቦ ፡ በኵሉ ፡ ልብየ ።"),
    (118, 35, "ምርሐኒ ፡ ፍኖተ ፡ ትእዛዝከ ፤ እስመ ፡ ኪያሃ ፡ ፈቀድኩ ።"),
    (118, 36, "ሚጥ ፡ ልብየ ፡ ውስተ ፡ ስምዕከ ፤ ወአኮ ፡ ውስተ ፡ ትዕግልት ።"),
    (118, 37, "ሚጦን ፡ ለአዕይንትየ ፡ ከመ ፡ ኢይርአያ ፡ ከንቶ ፤ ወኣሕይወኒ ፡ በፍኖትከ ።"),
    (118, 38, "አቅም ፡ ለገብርከ ፡ ዘነበብከ ፡ ውስተ ፡ ነቢብከ ።"),
    (118, 39, "ኣእትት ፡ እምኔየ ፡ ጽእለተ ፡ ዘተሐዘብኩ ፤ እስመ ፡ ሠናይ ፡ ኵነኔከ ።"),
    (118, 40, "ናሁ ፡ ፈተውኩ ፡ ትእዛዘከ ፤ ወኣሕይወኒ ፡ በጽድቅከ ።"),
    (118, 41, "፮ ፤ ዋው ። ወይምጻእ ፡ ላዕሌየ ፡ ምሕረትከ ፡ እግዚኦ ፤ እግዚኦ ፡ አድኅኖትከ ፡ በከመ ፡ ነቢብከ ።"),
    (118, 42, "አውሥኦሙ ፡ ቃለ ፡ ለእለ ፡ ይጼእሉኒ ፤ እስመ ፡ ተወከልኩ ፡ በቃልከ ።"),
    (118, 43, "ወኢታእትት ፡ ቃለ ፡ ጽድቅ ፡ እምአፉየ ፡ ለግሙራ ፤ እስመ ፡ ተወከልኩ ፡ በኵነኔከ ።"),
    (118, 44, "ወአዐቅብ ፡ ሕገከ ፡ በኵሉ ፡ ጊዜ ፤ ለዓለም ፡ ወለዓለመ ፡ ዓለም ።"),
    (118, 45, "ወአሐውር ፡ ስፉሕ ፤ እስመ ፡ ትእዛዘከ ፡ ኀሠሥኩ ።"),
    (118, 46, "ወእነግር ፡ ስምዐከ ፡ በቅድመ ፡ ነገሥተ ፤ ወኢይትኀፈር ።"),
    (118, 47, "ወኣነብብ ፡ ትእዛዘከ ፤ ዘአፍቀርኩ ፡ ጥቀ ።"),
    (118, 48, "ወኣነሥእ ፡ እደውየ ፡ ኀበ ፡ ትእዛዝከ ፡ ዘአፍቀርኩ ፤ ወእዛዋዕ ፡ በትእዛዝከ ።"),
    (118, 49, "፯ ፤ ዛይ ። ተዘከር ፡ ቃለከ ፡ ዘአሰፈውኮ ፡ ለገብርከ ።"),
    (118, 50, "ወይእቲ ፡ አስተፈሥሐተኒ ፡ በሕማምየ ፤ እስመ ፡ ቃልከ ፡ ኣሕየወኒ ።"),
    (118, 51, "ዕቡያን ፡ ዐመፃ ፡ ፈድፋደ ፤ ወእምሕግከሰ ፡ ኢተገሐሥኩ ።"),
    (118, 52, "ወተዘከርኩ ፡ ፍትሐከ ፡ ዘእምዓለም ፤ ወተፈሣሕኩ ፡ እግዚኦ ።"),
    (118, 53, "ሐዘን ፡ አኀዘኒ ፡ እምኃጥኣን ፤ እለ ፡ ኀደጉ ፡ ሕገከ ።"),
    (118, 54, "መዝሙር ፡ ኮነኒ ፡ ኵነኔከ ፤ በብሔር ፡ ኀበ ፡ ፈለስኩ ።"),
    (118, 55, "ተዘከርኩ ፡ በሌሊት ፡ ስመከ ፡ እግዚኦ ፤ ወዐቀብኩ ፡ ሕገከ ።"),
    (118, 56, "ወይእቲ ፡ ኮነተኒ ፤ እስመ ፡ ኵነኔከ ፡ ኀሠሥኩ ።"),
    (118, 57, "፰ ፤ ሔት ። ክፍልየ ፡ እግዚአብሔር ፤ ወእቤ ፡ ይዕቀቡ ፡ ሕገከ ።"),
    (118, 58, "ሰአልኩ ፡ ገጸከ ፡ እግዚኦ ፡ በኵሉ ፡ ልብየ ፤ ተሣሀለኒ ፡ በከመ ፡ ነቢብከ ።"),
    (118, 59, "ወሐለይኩ ፡ በእንተ ፡ ፍናዊከ ፤ ወሜጥኩ ፡ እግርየ ፡ ውስተ ፡ ስምዕከ ።"),
    (118, 60, "አጥባዕኩ ፡ ወኢናፈቁ ፤ ለዐቂበ ፡ ትእዛዝከ ።"),
    (118, 61, "አሕባለ ፡ ኃጥኣን ፡ ተፀፍራ ፡ ላዕሌየ ፤ ወሕገከሰ ፡ ኢረሳዕኩ ።"),
    (118, 62, "መንፍቀ ፡ ሌሊት ፡ እትነሣእ ፡ ከመ ፡ እግነይ ፡ ለከ ፤ በእንተ ፡ ኵነኔ ፡ ጽድቅከ ።"),
    (118, 63, "ከማሆሙ ፡ አነ ፡ ለኵሎሙ ፡ እለ ፡ ይፈርሁከ ፤ ወለእለ ፡ የዐቅቡ ፡ ትእዛዘከ ።"),
    (118, 64, "ሣህልከ ፡ እግዚኦ ፡ መልአ ፡ ምድረ ፤ ወምህረኒ ፡ ኵነኔከ ።"),
    (118, 65, "፱ ፤ ጤት ። ሠናይተ ፡ ገበርከ ፡ ላዕለ ፡ ገብርከ ፤ እግዚኦ ፡ በከመ ፡ ቃልከ ።"),
    (118, 66, "ሠናይተ ፡ ምክር ፡ ወጥበበ ፡ ምህረኒ ፤ እስመ ፡ ተአመንኩ ፡ በትእዛዝከ ።"),
