    (118, 69, "በዝኀ ፡ ላዕሌየ ፡ ዐመፃሆሙ ፡ ለዕቡያን ፤ ወአንሰ ፡ በኵሉ ፡ ልብየ ፡ ኀሠሥኩ ፡ ትእዛዘከ ።"),
    (118, 70, "ረግዐ ፡ ከመ ፡ ሐሊብ ፡ ልቦሙ ፤ ወአንሰ ፡ ኣነብብ ፡ በሕግከ ።"),
    (118, 71, "ደለወኒ ፡ ዘኣሕመምከኒ ፤ ከመ ፡ አእምር ፡ ኵነኔከ ።"),
    (118, 72, "ይኄይሰኒ ፡ ሕገ ፡ አፉከ ፤ እምኣእላፍ ፡ ወርቅ ፡ ወብሩር ።"),
    (118, 73, "፲ ፤ ዮድ ። እደዊከ ፡ ገብራኒ ፡ ወለሐኳኒ ፤ ኣለብወኒ ፡ ወእትመሀር ፡ ትእዛዘከ ።"),
    (118, 74, "እለ ፡ ይፈርሁከ ፡ ይርእዩኒ ፡ ወይትፌሥሑ ፤ እስመ ፡ ተወከልኩ ፡ በነቢብከ ።"),
    (118, 75, "ኣእመርኩ ፡ እግዚኦ ፡ ከመ ፡ ጽድቅ ፡ ኵነኔከ ፤ ወበርቱዕ ፡ ኣሕመምከኒ ።"),
    (118, 76, "ይኩነኒ ፡ ምሕረትከ ፡ ከመ ፡ ያስተፈሥሐኒ ፤ ወበከመ ፡ ነቢብከ ፡ ይኩኖ ፡ ለገብርከ ።"),
    (118, 77, "ይምጽአኒ ፡ ሣህልከ ፡ ወእሕየው ፤ እስመ ፡ ተመሀርየ ፡ ውእቱ ፡ ሕግከ ።"),
    (118, 78, "ይትኀፈሩ ፡ ዕቡያን ፡ እስመ ፡ ዐመፃ ፡ መከሩ ፡ ላዕሌየ ፤ ወአንሰ ፡ እዛዋዕ ፡ በትእዛዝከ ።"),
    (118, 79, "ይግብኡኒ ፡ እለ ፡ ይፈርሁከ ፤ ወእለ ፡ ያአምሩ ፡ ስምዐከ ።"),
    (118, 80, "ለይኩን ፡ ልብየ ፡ ንጹሐ ፡ በኵነኔከ ፤ ከመ ፡ ኢይተኀፈር ።"),
    (118, 81, "፲፩ ፤ ካፍ ። ኀለፈት ፡ ነፍስየ ፡ ውስተ ፡ አድኅኖትከ ፤ ወተወከልኩ ፡ በቃልከ ።"),
    (118, 82, "ደክማ ፡ አዕይንትየ ፡ ለመድኀኒትከ ፤ እንዘ ፡ ይብላ ፡ ማእዜ ፡ ታስተፌሥሐኒ ።"),
    (118, 83, "እስመ ፡ ኮንኩ ፡ ከመ ፡ ዝቅ ፡ ውስተ ፡ አስሐትያ ፤ ወኵነኔከሰ ፡ ኢረሳዕኩ ።"),
    (118, 84, "ሚመጠን ፡ እማንቱ ፡ መዋዕሊሁ ፡ ለገብርከ ፤ ወማእዜ ፡ ትፈትሕ ፡ ሊተ ፡ እምእለ ፡ ይሰዱኒ ።"),
    (118, 85, "ነገሩኒ ፡ ኃጥኣን ፡ ዘውዐ ፤ ወአኮሰ ፡ ከመ ፡ ሕግከ ፡ እግዚኦ ።"),
    (118, 86, "ኵሉ ፡ ትእዛዝከ ፡ ጽድቅ ፤ በዐመፃ ፡ ሰደዱኒ ፡ ርድአኒ ።"),
    (118, 87, "ሕቀ ፡ ከመ ፡ ዘእምደምሰሱኒ ፡ ውስተ ፡ ምድር ፤ ወአንሰ ፡ ኢኀደጉ ፡ ትእዛዘከ ።"),
    (118, 88, "በከመ ፡ ምሕረትከ ፡ ኣሕይወኒ ፤ ወእዕቀብ ፡ ስምዐ ፡ አፉከ ።"),
    (118, 89, "፲፪ ፤ ላሜድ ። እግዚኦ ፡ ለዓለም ፡ ይነብር ፡ ቃልከ ፡ ውስተ ፡ ሰማይ ።"),
    (118, 90, "ወለትውልደ ፡ ትውልድ ፡ ጽድቅከ ፤ ሳረርካ ፡ ለምድር ፡ ወትነብር ።"),
    (118, 91, "ወበትእዛዝከ ፡ ይቀውም ፡ ዕለት ፤ እስመ ፡ ኵሎ ፡ ቀነይከ ።"),
    (118, 92, "ሶበ ፡ አኮ ፡ ሕግከ ፡ ተመሀርየ ፡ ውእቱ ፤ ትካት ፡ እምተሐጐልኩ ፡ በኀሳርየ ።"),
    (118, 93, "ለዓለም ፡ ኢይረስዕ ፡ ኵነኔከ ፤ እስመ ፡ ቦቱ ፡ አሕየውከኒ ።"),
    (118, 94, "ዘዚአከ ፡ አነ ፡ አድኅነኒ ፤ እስመ ፡ ኵነኔከ ፡ ኀሠሥኩ ።"),
    (118, 95, "ኪያየ ፡ ይጸንሑ ፡ ኃጥኣን ፡ ይቅትሉኒ ፤ እስመ ፡ ስምዐከ ፡ ለበውኩ ።"),
    (118, 96, "ለኵሉ ፡ ግብር ፡ ርኢኩ ፡ ማኅለቅቶ ፤ ወትእዛዝከሰ ፡ ርሒብ ፡ ፈድፋደ ።"),
    (118, 97, "፲፫ ፤ ሜም ። ጥቀ ፡ አፍቀርኩ ፡ ሕገከ ፡ እግዚኦ ፤ ኵሎ ፡ አሚረ ፡ ተምሀርየ ፡ ውእቱ ።"),
    (118, 98, "እምጸላእትየ ፡ አጥበበኒ ፡ ትእዛዝከ ፤ እስመ ፡ ለዓለም ፡ ሊተ ፡ ውእቱ ።"),
    (118, 99, "እምኵሎሙ ፡ እለ ፡ መሀሩኒ ፡ ጠበብኩ ፤ እስመ ፡ ተመሀርየ ፡ ውእቱ ፡ ትእዛዝከ ።"),
    (118, 100, "ወእምአእሩግኒ ፡ ጠበብኩ ፤ እስመ ፡ ትእዛዘከ ፡ ኀሠሥኩ ።"),
    (118, 101, "እምኵሉ ፡ ፍኖተ ፡ ዐመፃ ፡ ከላእኩ ፡ እግርየ ፤ ከመ ፡ እዕቀብ ፡ ነቢበከ ።"),
    (118, 102, "ወኢተገሐስኩ ፡ እምኵነኔከ ፤ እስመ ፡ አንተ ፡ መሀርከኒ ።"),
    (118, 103, "ጥዑም ፡ ለጕርዔየ ፡ ነቢብከ ፤ እምዓር ፡ ወሶከር ፡ ጥዕመኒ ፡ ለአፉየ ።"),
    (118, 104, "እምትእዛዝከ ፡ ለበውኩ ፤ በእንተዝ ፡ ኵሎ ፡ ፍኖተ ፡ ዐመፃ ፡ ጸላእኩ ።"),
    (118, 105, "፲፬ ፤ ኖን ። ማሕቶት ፡ ለእግርየ ፡ ሕግከ ፤ ብርሃን ፡ ለፍኖትየ ።"),
    (118, 106, "መሐልኩ ፡ ወአጥባዕኩ ፤ ከመ ፡ እዕቀብ ፡ ኵነኔ ፡ ጽድቅከ ።"),
    (118, 107, "ሐመምኩ ፡ ፈድፋደ ፤ እግዚኦ ፡ ኣሕይወኒ ፡ በከመ ፡ ነቢብከ ።"),
    (118, 108, "ሥመር ፡ እግዚኦ ፡ ቃለ ፡ አፉየ ፤ ወምህረኒ ፡ ኵነኔከ ።"),
    (118, 109, "ነፍስየ ፡ ውስተ ፡ እዴከ ፡ በኵሉ ፡ ጊዜ ፤ ወኢረሳዕኩ ፡ ሕገከ ።"),
    (118, 110, "ሠርዑ ፡ ሊተ ፡ ኃጥኣን ፡ መሥገርተ ፤ ወኢስሕትኩ ፡ እምትእዛዝከ ።"),
    (118, 111, "ወረስኩ ፡ ስምዐከ ፡ ለዓለም ፤ እስመ ፡ ሐሤቱ ፡ ለልብየ ፡ ውእቱ ።"),
    (118, 112, "ሜጥኩ ፡ ልብየ ፡ ከመ ፡ እግበር ፡ ትእዛዘከ ፤ ለዓለም ፡ ዘእንበለ ፡ ሒስ ።"),
    (118, 113, "፲፭ ፤ ሳምኬት ። ዐማፂያነ ፡ ጻላእኩ ፤ ወሕገከሰ ፡ አፍቀርኩ ።"),
